INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ae6c85af', 't-mm-01-001', 'html', '<table><tbody><tr><td>1st Generation</td><td>Mode</td><td>Endometrial preparation</td><td>Cavity length<br/>> 10cm</td><td>Cervical dilation required</td><td>Sub-mucus fibroids resection</td></tr><tr><td>TCRE<br/>Biopsy can be taken<br/>Longest recovery time.<br/>Highest complication</td><td>Mono/bipolar 3mm loop</td><td>Optional</td><td>yes</td><td>9mm</td><td>Yes</td></tr><tr><td>RBA<br/>Repeat ablation can be undertaken</td><td>Mono / Bipolar</td><td>Optional</td><td>Yes</td><td>>9mm</td><td>yes</td></tr><tr><td>ELA<br/>Costly<br/>Saline is used</td><td>Nd-yag</td><td>Required</td><td>Yes</td><td>7mm</td><td>No</td></tr><tr><td>2nd Generation</td><td>Mode</td><td>Endo prep</td><td>Maximum Cavity length</td><td>Cervix dilation required</td><td>Sub-mucus fibroids resection</td></tr><tr><td>1. Therma choice III<br/>10-12min<br/>C/I:<br/>i. Classical c/s<br/>ii. myomectomy</td><td>Fluid filled thermal balloon</td><td>No</td><td>11mm</td><td>5mm</td><td><3cm</td></tr><tr><td>2. Novas sure<br/>90 – 120sec<br/>50ohm</td><td>Bipolar radio frequency</td><td>No</td><td>11mm</td><td>8mm</td><td><3cm</td></tr><tr><td>3. Hydrothermal ablators<br/>10min</td><td>Heated Saline</td><td>Yes</td><td>6 - 10.5cm</td><td>8mm</td><td><4cm</td></tr></tbody></table>', 312) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
