INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-deb9e903', 't-mm-01-002', 'html', '<table><tbody><tr><td>ESGE</td><td>FIGO</td></tr><tr><td>Type 0:<br/>No myometrium involvement<br/>Pedunculated entirely intra Cavity<br/>Type 1: <50% myometrium invasion.<br/><90% angle of myoma surface to the uterine wall.<br/>> sessile<br/>Type 2:<br/>> 50% invasion<br/>> 90%angle of myoma surface to uterine wall</td><td>Type 0:<br/>pedunculated<br/>Type 1:                submucosal<br/><50%<br/>I/mural<br/>Type 2: more<br/>50% intramural<br/>Type 3:<br/>Contact<br/>Endometrium    intramural<br/>Type 4:  less<br/>Then 50%I/m<br/>Type 5:<br/>> 50% I/m<br/>Type 6:                 sub-serosal<br/><50% I/m<br/>Type 7:<br/>pedunculated<br/>Type 8: Others-Broad ligament, cervical</td></tr><tr><td>Symptoms:<br/>1. Pain: Dyspnea, dragging pain, dysmenorrhea.<br/>2. Pressure symptoms over bladder and bowel<br/>3.HMB</td></tr></tbody></table>', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
