INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-447e0ecd', 't-mm-01-006', 'text', '1st line: Alendronate if T score is < 2.5.it inhibits osteoporosis', 90) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
