INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d0a512cd', 't-mm-01-006', 'text', '3rd line: Strontium Ranelate (2g/day Hs) & Raloxifene if T - score is - 2.5 - 4 or Age > 54.', 92) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2bcc680d', 't-mm-01-006', 'text', '4th line: teriparatide', 93) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
