INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b07c26b0', 't-mm-01-007', 'text', 'For 100,000 HRT users/year:', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
