INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ea56d239', 't-mm-01-007', 'text', 'POF=> Contraception or HRT up to age of Menopause', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
