INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-01-020', 'chap-mm-01-01', '19. DYSMENORRHEA', 'Detailed medical reference and study guide on 19. DYSMENORRHEA.', 20, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1cd748b3', 't-mm-01-020', 'html', '<table><tbody><tr><td></td><td>Primary Dysmenorrhea<br/>No underlying pathology</td><td>Secondary Dysmenorrhea<br/>Pain manifests underlying pathology</td></tr><tr><td>Age<br/>Onset<br/>Duration<br/>Nature</td><td>16-25<br/>Menarche<br/>8-72 hrs.<br/>Cramping pain<br/>+ vomiting<br/>Radiates to back<br/>Or upper legs</td><td>30 – 45<br/>After menarche<br/>Prior to onset & throughout cycles<br/>Variable number of days<br/>Non cyclic/ cyclical episodes</td></tr><tr><td>Comorbidity</td><td>No</td><td>HMB, vaginal discharge, IMB, PCB, CPP, Bowel or urological symptoms</td></tr><tr><td>Response to NSAIDS</td><td>Yes</td><td>Yes, but may require further t/m</td></tr><tr><td>Examination</td><td>Normal</td><td>Fixed R/V Uterus<br/>Thickened Uterosacral ligaments<br/>Endometriotic nodules<br/>Adnexal mass<br/>Enlarge tender uterus.</td></tr><tr><td>Investigation</td><td>normal USG</td><td>USG:<br/>Adenomyosis<br/>Fibroids<br/>Endometriosis<br/>Swabs:<br/>PiD</td></tr></tbody></table>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
