INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4f9957e4', 't-mm-01-021', 'text', 'Primary due to sexual problems and ascending infection', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-560d85c5', 't-mm-01-021', 'text', 'Viral infections:', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f488a32e', 't-mm-01-021', 'text', 'Hep B, C, HIV', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-81e99fb6', 't-mm-01-021', 'text', 'Obstetric complications:', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-43d77025', 't-mm-01-021', 'text', 'PPH', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-acbe25af', 't-mm-01-021', 'text', 'Prolong labor – C/section', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ba6684fa', 't-mm-01-021', 'text', 'Genital trauma', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-25d8892a', 't-mm-01-021', 'text', 'ENND', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b2e0d768', 't-mm-01-021', 'text', 'Still birth', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a796e228', 't-mm-01-021', 'text', 'Need for resuscitation.', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b47c69f1', 't-mm-01-021', 'text', 'FEMALE GENITAL MUTATION ACT:', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8a3acfb5', 't-mm-01-021', 'text', 'FGM is illegal unless done until.', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5d12a044', 't-mm-01-021', 'text', '(1). For physical/Mental health of women.', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-08c9da38', 't-mm-01-021', 'text', '(2). Purpose of labor/Birth.', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7081e67e', 't-mm-01-021', 'text', 'FGM – arranging, facilitation and Assistance is illegal.', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b5c610aa', 't-mm-01-021', 'text', 'Offence for those with parental responsibility to fail to protect a girl from risk of FGM.', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-588ea2b0', 't-mm-01-021', 'text', 'FGM in <18 years’ girl Report to police within 1 month.', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-acf5129f', 't-mm-01-021', 'text', 'Female Genital cosmetic surgery FGCS (including tightening)', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a613bb02', 't-mm-01-021', 'text', 'Prohibited unless for physical/mental health.', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-095ad23e', 't-mm-01-021', 'text', 'Surgeons should make sure compliance with FGM act.', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f6494ebc', 't-mm-01-021', 'text', 'Infibulation is illegal – No justification.', 80) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fc827e64', 't-mm-01-021', 'text', 'Legal and regulatory responsibilities of health professionals:', 81) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5e5a9f02', 't-mm-01-021', 'text', 'Data recording:', 82) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5aeccf2c', 't-mm-01-021', 'text', 'Data recording is mandatory for all women identified as having FGM.', 83) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e523d9bf', 't-mm-01-021', 'text', 'Document FGM diagnosis in medical records (even if the FGM is not the reason for presentation).', 84) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e1f53f10', 't-mm-01-021', 'text', 'If genital examination is performed and type of FGM is identifies, record FGM type (WHO classification).', 85) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3b122d12', 't-mm-01-021', 'text', 'Document further details in accordance with the HSCIC FGM Enhanced Dataset.', 86) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b01fcfcc', 't-mm-01-021', 'text', 'Explain to the woman that her personal data will be transmitted to the HSCIC for the purpose of FGM prevalence monitoring and that the data will not be anonymized.', 87) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6bbd22f8', 't-mm-01-021', 'text', 'Reporting to police and/or social services in the event of risk to a child:', 88) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f645cb14', 't-mm-01-021', 'text', 'Children under 18:', 89) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-efc0f84e', 't-mm-01-021', 'text', 'If FGM is confirmed (on examination or if the patient or parent says it has been done). Refer as a matter of urgency to the police and this should be done within 1 month of confirmation.', 90) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b32563c7', 't-mm-01-021', 'text', 'If FGM is suspected (but not confirmed) or the girl is at risk (but has not had FGM), refer to social services or the police. The urgency of the referral depends on the degree of risk.', 91) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e8b4603b', 't-mm-01-021', 'text', 'Non pregnant women with FGM: no requirement to report unless a related child is at risk.', 92) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d7aff6b1', 't-mm-01-021', 'text', 'Pregnant women:', 93) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b76794de', 't-mm-01-021', 'text', 'A member of the clinical team) midwife or obstetrician) must make an individual risk assessment using an FGM safeguarding risk assessment tool ad if the unborn child, or any other child in the family, is considered to be at risk of FGM then reporting to social services or the police must occur Document maternal history of FGM in the personal child health record (‘Red book’) prior to postnatal discharge.', 94) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b8dc3982', 't-mm-01-021', 'text', 'If delivery of a baby girl, notify the designated child protection midwife, who should inform the GP and health visitor.', 95) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c6853b61', 't-mm-01-021', 'text', '>>>Genital piercing should be classified as type 4 FGM in accordance with the WHO FGM classification.', 96) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8fa3391d', 't-mm-01-021', 'text', 'Clinical management of adult women with FGM in obstetric and gynecological practice', 97) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b6e05ac6', 't-mm-01-021', 'text', 'All acute trusts/health boards should have a designated consultant and midwife responsible for the care of women with FGM.', 98) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f766428f', 't-mm-01-021', 'text', 'All women in obstetric and gynecological practice.', 99) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3fe0b282', 't-mm-01-021', 'text', 'Explain law on FGM, documenting the discussion and referring her to information provided', 100) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3e580a31', 't-mm-01-021', 'text', 'Provide interpreter if required (not a family member).', 101) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ac30cc3a', 't-mm-01-021', 'text', 'Offer referral for psychological assessment and treatment.', 102) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-316145d1', 't-mm-01-021', 'text', 'Offer specialist referral as appropriate, e.g. sexual health, urology.', 103) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-59d48939', 't-mm-01-021', 'text', 'Make a clinical assessment of FGM (symptoms, examination) and need for de-infibulation.', 104) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3856a75a', 't-mm-01-021', 'text', 'Record data in accordance with the HSCIC FGM Enhanced Dataset. These include age at FGM, country where FGM was performed, date of entry to UK (if applicable) and past history of de-infibulation and/or re-infibulation.', 105) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c678b7af', 't-mm-01-021', 'text', 'If de infibulation is indicated, offer before pregnancy it can usually be performed on an outpatient basis.', 106) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e46b8b7c', 't-mm-01-021', 'text', 'ideally before 1st intercourse', 107) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c268ee83', 't-mm-01-021', 'text', 'Reporting to social services or the police is only required if a related child is considered to be at risk.', 108) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-459550ae', 't-mm-01-021', 'text', 'Additional management in pregnant women.', 109) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-50d0a7a4', 't-mm-01-021', 'text', 'Refer to designated consultant obstetrician or specialist midwife with responsibility for women with FGM.', 110) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ff7e1852', 't-mm-01-021', 'text', 'Local protocols will determine which elements of care (child safeguarding risk assessment, data recording, clinical management) should be undertaken by the designated midwife or obstetrician and which may be undertaken by other appropriately trained midwives or obstetricians.', 111) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b4f6c508', 't-mm-01-021', 'text', 'Discuss and clearly document a plan of care, preformatted Performa’s may be used.', 112) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-34d8e7b7', 't-mm-01-021', 'text', 'Make an individual risk assessment using an FGM safeguarding risk assessment tool (an example of such a tool. If the unborn child or any related child is considered to be at risk then reporting to social services or the police must occur.', 113) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aee5dc7a', 't-mm-01-021', 'text', 'All women  with FGM are offered psychological assessment is t/m.', 114) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3016bf36', 't-mm-01-021', 'text', 'Offer screening for hepatitis C in addition to routine screening for hepatitis B, HIV and syphilis.', 115) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9fdf1dab', 't-mm-01-021', 'text', 'If de-infibulation is indicated, discuss, agree and document the timing (antenatal or intrapartum). Inform the woman that re-infibulation after delivery will not be performed under any circumstances.', 116) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4ea5dcc6', 't-mm-01-021', 'text', 'Manage as high obstetric risk (increased risk of hemorrhage, perineal trauma and caesarean section), except for women who have had previous pregnancies with uncomplicated vaginal deliveries and no history of post-delivery re-infibulation.', 117) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ef6cde2a', 't-mm-01-021', 'text', 'Document maternal history of FGM in the personal child health record (''Red Book'') prior to postnatal discharge.', 118) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b8a2efa6', 't-mm-01-021', 'text', 'If delivery of a baby girl, notify the designated child protection midwife, who should inform the GP and health visitor.', 119) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b011a751', 't-mm-01-021', 'text', 'Offer postnatal follow-up if de-infibulation performed intrapartum or if planned de-infibulation did not occur because of delivery by caesarean section.', 120) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9b7cf56e', 't-mm-01-021', 'text', 'Indications for De-Infibulation:', 121) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eaff98db', 't-mm-01-021', 'text', 'Too tight introits to allow menstrual flow, vaginal examination, normal urination or comfortable sexual intercourse & safe vaginal delivery.', 122) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eb600ae3', 't-mm-01-021', 'text', 'Before gynecological surgery, TOP, Cervix Smear, Sexual health screening.', 123) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bd5da6eb', 't-mm-01-021', 'text', 'Type III.', 124) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-da9dec4f', 't-mm-01-021', 'text', 'Plan of care for women with FGM in pregnancy:', 125) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ee266858', 't-mm-01-021', 'text', '-  Document maternal history of FGM in personal child health record (Red Book'').-  If delivery of baby girl, notify safeguarding midwife who should inform the GP and health visitor.-  Offer postnatal follow-up if de infibulation performed intrapartum er if planned de-infibulation did not occur because of delivery by caesarean section-  Ensure all data required for HSCIC Enhanced Dataset have been recorded.-  Document maternal history of FGM in personal child health record (Red Book'').-  If delivery of baby girl, notify safeguarding midwife who should inform the GP and health visitor.-  Offer postnatal follow-up if de infibulation performed intrapartum er if planned de-infibulation did not occur because of delivery by caesarean section-  Ensure all data required for HSCIC Enhanced Dataset have been recorded.-  Generally, manage as high risk for caesarean section, hemorrhage and perineal trauma-  Some women may be considered low risk and suitable for midwifery-led care if history of previous uncomplicated vaginal delivery-  If de-infibulation is required, ensure that the midwife and obstetrician caring for the woman have received appropriate training-  Perineal tears in women with FGM should be managed in the same manner as in women without FGM.-  Generally, manage as high risk for caesarean section, hemorrhage and perineal trauma-  Some women may be considered low risk and suitable for midwifery-led care if history of previous uncomplicated vaginal delivery-  If de-infibulation is required, ensure that the midwife and obstetrician caring for the woman have received appropriate training-  Perineal tears in women with FGM should be managed in the same manner as in women without FGM.-  Use professional interpreter if required (not family member) and explain law on FGM.-  Offer referral for psychological assessment and screening for hepatitis in addition to routine antenatal screening.-  Make clinical assessment of FGM. If de infibulation is required, agree timing and explain that re-infibulation will not be performed.-  Assess other obstetric risk factors and action appropriately.-  Agree and Document plan for antenatal, intrapartum and postpartum care.-  Use professional interpreter if required (not family member) and explain law on FGM.-  Offer referral for psychological assessment and screening for hepatitis in addition to routine antenatal screening.-  Make clinical assessment of FGM. If de infibulation is required, agree timing and explain that re-infibulation will not be performed.-  Assess other obstetric risk factors and action appropriately.-  Agree and Document plan for antenatal, intrapartum and postpartum care.postpartumpostpartumintrapartumintrapartumantenatalantenatalClinical management plan:-  Ensure clear documentation.-  Preformatted proformas may be used.Clinical management plan:-  Ensure clear documentation.-  Preformatted proformas may be used.Woman with FGM in pregnancy:Referral to designated midwife and/or obstetrician with responsibility for FGM Consultant-led careWoman with FGM in pregnancy:Referral to designated midwife and/or obstetrician with responsibility for FGM Consultant-led careData recording:-  Ensure compliance with HSCIC Enhanced Dataset.-  Document FGM diagnosis, including FGM type (WHO classification).Data recording:-  Ensure compliance with HSCIC Enhanced Dataset.-  Document FGM diagnosis, including FGM type (WHO classification).Child safeguarding risk assessment by midwife or obstetrician:-  Use risk assessment tool-  Explain law on FGM-   Report to social services or the police if unborn child or related child at risk.Child safeguarding risk assessment by midwife or obstetrician:-  Use risk assessment tool-  Explain law on FGM-   Report to social services or the police if unborn child or related child at risk.', 126) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-46ab3025', 't-mm-01-021', 'text', 'De-infibulation can be done:', 127) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b76cd079', 't-mm-01-021', 'text', 'antenatally', 128) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aa37063d', 't-mm-01-021', 'text', '1st stage of labour', 129) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fc31462d', 't-mm-01-021', 'text', '@ the time of delivery', 130) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d0dedae4', 't-mm-01-021', 'text', 'Before or after C/S', 131) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
