INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-27f3cee8', 't-mm-01-022', 'text', '5 - 15%', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-de3b84dd', 't-mm-01-022', 'text', 'Can be Idiopathic - no underlying endocrine disorder', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3256c148', 't-mm-01-022', 'text', 'Pathophysiology:', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
