INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3111c70', 't-mm-01-024', 'text', '1:5000 – 1:10000', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
