INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-18316376', 't-mm-01-024', 'text', 'Development of SSC before age 8', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-21e17286', 't-mm-01-024', 'text', 'Development of breast or Pubic hair before age 7 in white girls and before age 6 in black girls.', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
