INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb9d3bd5', 't-mm-01-024', 'text', 'Puberty can be:', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-789e0222', 't-mm-01-024', 'text', 'Consonant – if it follows normal sequence.', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96f011a9', 't-mm-01-024', 'text', 'Disconsonant – if it is abnormal.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dfd6b993', 't-mm-01-024', 'text', 'Puberty consists of physical changes.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-035f4040', 't-mm-01-024', 'text', 'Adolescence consists of psychological and social changes.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-45b4597d', 't-mm-01-024', 'text', 'Puberty comes form 10 years onwards and usually takes 3 – 4 years with passage from one stage to another stage approximately every year.', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-98ad4d39', 't-mm-01-024', 'text', 'Thelarche: usually 1st sign of Puberty.', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-43e875fe', 't-mm-01-024', 'text', 'Development of breast bud – tanner stage (2).', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2d30fa8a', 't-mm-01-024', 'text', 'Pubertal growth spurt occurs with breast budding, with peak velocity at mid puberty.', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d8762fd4', 't-mm-01-024', 'text', 'Menarche occurs within 2 – 3years of thelarche median age for menarche 13 years.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f019fa4d', 't-mm-01-024', 'text', 'Pubarche: development of pubic hair followed by axillary hair. Pubarche follows thelarche.', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-68bb1d5c', 't-mm-01-024', 'text', 'Types of precocious Puberty:', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-927d2bb2', 't-mm-01-024', 'text', 'Central precocious puberty CPP', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b3cc98fb', 't-mm-01-024', 'text', 'Peripheral precocious puberty PPP', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7ca775d0', 't-mm-01-024', 'text', 'Isolated variants', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-45277007', 't-mm-01-024', 'html', '<table><tbody><tr><td></td><td>CPP</td><td>PPP</td></tr><tr><td>HPO Axis</td><td>Pre – mature activation</td><td>Not involved</td></tr><tr><td>SSC</td><td>Isosexual</td><td>Isosexual or can be contra sexual</td></tr><tr><td>Pathology</td><td>CNS pathology:<br/>Tumors<br/>Trauma<br/>Infections.<br/>Chemotherapy<br/>Radiotherapy<br/>Congenital lesions<br/>Secondary to PPP<br/>Idiopathic 74%</td><td>1. Ovarian causes:<br/>EST<br/>Androgen secreting tumors (can cause contra sexual puberty).<br/>Functional ovarian cyst.<br/>2. Adrenal causes:<br/>CAH (Contra sexual)<br/>Cushing syndrome (contra sexual)<br/>Neoplasm (iso or contra)<br/>3. Exogenous hormones:<br/>COCP<br/>Skin creams<br/>Anabolic steroids.<br/>McCune – Albright syndrome.<br/>Severe long-standing hypothyroidism.</td></tr><tr><td>Investigations:<br/>Bone age</td><td>Advanced > 2 years</td><td>Usually advance except in hypothyroidism</td></tr><tr><td>Estradiol</td><td>Variable</td><td>Very high (EST).</td></tr><tr><td>GnRH stimulation test<br/>Normally in pre – pubertal children FSH exceeds LH.<br/>In pubertal children LH exceeds FSH.<br/>Isolated thelarche FSH exceeds.</td><td>Gold standard Test<br/>LH: FSH ratio > 1</td><td>Flat response.</td></tr><tr><td>Prolactin levels</td><td>Not elevated routinely<br/>When observed can be due to compression tumors</td><td>Can be elevated in McCune-Albright Syndrome (MAS) and chronic Hypothyroidism.</td></tr><tr><td>TFT’S</td><td></td><td>T4,     TSH</td></tr><tr><td>Androgens<br/>DHEA, Androstenedione DHEA sulphate, 17α hydroxy progesterone.</td><td></td><td>Increase in androgen secreting tumors.<br/>Urinary 17 – ketosteroid very high in adrenal tumors.</td></tr><tr><td>Pelvic USG + Abdominal USG.</td><td>Endometrial thickening + uterine volume > 2ml or length > 34mm and pear-shaped uterus is associated with progressive CPP</td><td>Functional cysts.<br/>Ovarian tumors.<br/>Adrenal tumors.</td></tr><tr><td>CT cranium</td><td>Tumors of head</td><td>normal</td></tr><tr><td>CT Adrenals</td><td>-</td><td>Tumors of adrenals</td></tr><tr><td>Skeletal Survey Bone scan</td><td>-</td><td>Polyostotic<br/>Fibrous dysplasia</td></tr></tbody></table>', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
