INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-77a29598', 't-mm-02-012', 'text', 'Infertility due to tubal factors 17%', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-91d0c214', 't-mm-02-012', 'text', '1 in 6 couples', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-02b08241', 't-mm-02-012', 'html', '<table><tbody><tr><td>Test and operating time</td><td>Key Points</td><td>Effectiveness</td><td>Safety</td></tr><tr><td>Laparoscopy<br/>30 min time</td><td></td><td>Unknown</td><td>Bowell/vascular injury 0.13%<br/>Bladder injury</td></tr><tr><td>HSG<br/>10min</td><td>Sensitivity 53% - D 7 – 12 of cycle<br/>Specificity 87%<br/>- oil based: oil embolism & granulomas formation<br/>- water base: Superior image Quality</td><td>unknown</td><td>Anaphylaxis<br/>PiD 3.1%<br/>Radiation exposure 2G</td></tr><tr><td>Saline – Sono hysteroscopy<br/>12min</td><td>- saline infusion sonography (sis) for cavity.<br/>- hystero salpingo foam sonography for tubes.<br/>- catchers 5F, 7F.</td><td>unknown</td><td>PiD</td></tr><tr><td>SSTC<br/>15min</td><td>- Selective salpingography & tubal catheterization.<br/>- measures tubal perfusion pressure directly which has good prognostic value.</td><td>- Reduces false positive results due to tubal spasm.<br/>- Pregnancy rate 30%.<br/>- catheterization rate 62 – 90%.</td><td>Tubal perforation 2%<br/>Ectopic 3%</td></tr><tr><td>THL<br/>Transvaginal hydro laparoscopy<br/>15 min<br/>Mini laparoscopy:<br/>Under Local anesthesia</td><td>Insertion of needle in POD & insufflation of 0.4 – 0.6%lit of fluid followed by small diameter rigid angle endoscopy & visualization of Adnexa, pouch and tubes with dye test.</td><td>unknown</td><td>Bowel Injury, rectal 0.61%</td></tr><tr><td>Salpingoscopy<br/>45%</td><td>fimbrial end of tube via THL or laparoscopy.</td><td>unknown</td><td>Same as laparoscopy or THL.</td></tr><tr><td>falloposcopy</td><td>Visualization of interstitial portion of tube via hysteroscopy</td><td>Unknown<br/>pregnancy rate 27.6%<br/>11.5% mild dx<br/>O% severe dx</td><td>Tubal perforation 5.1%</td></tr><tr><td>fertiloscopy</td><td>Sensitivity 86%<br/>Specificity 100%</td><td>unknown</td><td>Rectal injury 0.61%<br/>Uterine perforation.</td></tr><tr><td>CAT<br/>Chlamydia Ab Test</td><td>Specificity 21 – 90%<br/>Single largest cause of tubal factor infertility.</td><td>Microimmunofluorescense is test used to detect antibodies against chlamydia<br/>High sensitivity = to detect tubal disease.<br/>High specificity = to rule out tubal disease.</td><td></td></tr></tbody></table>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-44a527da', 't-mm-02-012', 'text', 'Table 5. TUBAL TEST', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
