INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-58ea9bef', 't-mm-02-012', 'text', 'Cause of tubal infertility, repair is done by 4 – 0 prolineCause of tubal infertility, repair is done by 4 – 0 prolineProximal disease 15%', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
