INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-71f32c86', 't-mm-02-012', 'html', '<table><tbody><tr><td>surgery</td><td>Indication</td><td>Term pregnancy</td><td>ectopic</td></tr><tr><td>Salpingectomy by laparoscopy</td><td>Hydrosalpinx before IVF</td><td>25%</td><td>1 – 2%</td></tr><tr><td>Resection anastomosis</td><td>SIN (proximal disease 15%)</td><td>44%</td><td>7%</td></tr><tr><td>Salpingo ovariolysis</td><td>Periadenexal Adhesions</td><td>50%</td><td>5%</td></tr><tr><td>Fimbrioplasty</td><td>Fimbrial Phimosis</td><td>50%</td><td>7%</td></tr><tr><td>salpingostomy</td><td>Hydrosalpinx if Mucosal length is normal up to 50% or well informed Patient</td><td>30%</td><td>9%</td></tr><tr><td>Reversal of BTL<br/>1% request for reversal<br/>5% regret<br/>Isthmic – isthmic anastomosis is most successful method of sterilization reversal</td><td>Residual tube >4cm<br/>Age <35 years<br/>Tubal sterilization</td><td>52%</td><td>5%</td></tr></tbody></table>', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
