INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ce3cbacc', 't-mm-03-009', 'html', '<table><tbody><tr><td>SATGE I:</td><td></td><td>MANAGEMENT</td><td>5 YEARS<br/>SURVIVAL</td><td>1 YEAR</td></tr><tr><td>A<br/>B<br/>C</td><td>Limited to 1 ovary capsule intact =></td><td>Fertility sparing can be consisted in young:</td><td>90%<br/>80%</td><td>98%</td></tr><tr><td></td><td>Limited to both ovaries capsule intact</td><td>Stating Laparotomy:<br/>TAH + BSO<br/>Evaluation of all peritoneal surfaces<br/>Washings for cytology<br/>Multiple peritoneal biopsies.<br/>Omentectomy.<br/>Pelvic/para – aortic LN biopsies.<br/>Hepatic/ diaphragmatic cytology.<br/>Cytoreductive surgery: Residual disease<br/>< 1cm.<br/>Chemotherapy: carboplatin + paclitaxel = 6 cycles.<br/>Main stay of treatment: surgery + chemo except stage 1A,1B, low grade</td><td></td><td></td></tr><tr><td></td><td>1: 1A/1B with surgical spill<br/>2: 1A/1B with ruptured capsule before surgery or tumor on surface.<br/>3: 1A/1B but malignant cells in ascites or peritoneal washings.</td><td></td><td></td><td></td></tr><tr><td>STAGE II:</td><td></td><td></td><td></td></tr><tr><td>A<br/>B<br/>C</td><td>Implants on surface of uterus, tubes, ovary.</td><td>Surgery: + Adjuvant therapy according to MDT decision.<br/>Surgery: + Neoadjuvant or adjuvant therapy according to MDT decision.</td><td>70%</td><td>89%</td></tr><tr><td></td><td>Other pelvic organs Bladder, rectum.</td><td></td><td></td><td></td></tr><tr><td></td><td>IIA, IIB with ascites or peritoneal washings positive</td><td></td><td></td><td></td></tr><tr><td>STAGE III:</td><td></td><td></td><td></td></tr><tr><td>A1<br/>A2<br/>B<br/>C</td><td>Positive Retroperitoneal Lymph nodes<br/>IIIA1a: <10mm Mets<br/>IIIA1b: > 10mm Mets – peritoneal Mets</td><td></td><td>40%</td><td>73%</td></tr><tr><td></td><td>Microscopic extra pelvic peritoneal invasion + positive retroperitoneal Lymph nodes.</td><td></td><td></td><td></td></tr><tr><td></td><td>Macroscopic < 2cm extra pelvic peritoneal Mets + positive retroperitoneal Lymph nodes.</td><td></td><td></td><td></td></tr><tr><td></td><td>Extra pelvic peritoneal Mets >2cm Macroscopic, positive retroperitoneal L nodes.</td><td></td><td></td><td></td></tr><tr><td></td><td>Extension to liver/spleen capsule abdominal organs – No parenchymal involvement.</td><td></td><td></td><td></td></tr><tr><td>STAGE: IV</td><td></td><td></td><td></td></tr><tr><td>A<br/>B</td><td>Plural effusion with + ive cytology.</td><td>Neoadjuvant followed by surgery according to MDT decision</td><td>20%</td><td>53%<br/>Un stage – 67%.<br/>Unknown stage = 53%.</td></tr><tr><td></td><td>Hepatic, splenic parenchymal Mets.<br/>Mets to extra abdominal organs.<br/>inguinal L nodes.</td><td></td><td></td><td></td></tr></tbody></table>', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
