INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aabb3529', 't-mm-03-011', 'text', '28/100,000.', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-502f7ce6', 't-mm-03-011', 'text', 'Life style and other factors = 34%.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
