INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-32806d5b', 't-mm-03-011', 'html', '<table><tbody><tr><td>FIGO - STAGE</td><td>TREATMENT</td><td>5 YEARS SURVIVAL</td><td>1 YEAR</td></tr><tr><td>Stage 1</td><td>A: < 50% myometrium invasion, non-aggressive type</td><td>TAH + BSO<br/>By General Gynaecologist.</td><td>72%<br/>Role of sentinel node biopsy</td><td>99%</td></tr><tr><td></td><td>B: > 50% invasion, non-aggressive type<br/>C: aggressive type limited to endometrium</td><td></td><td></td><td></td></tr><tr><td>Stage 2<br/>Any type + local or vaginal spread.</td><td>A: cervical stoma, non – aggressive.</td><td>Radical TAH + Adjuvant therapy.</td><td>56%</td><td>95%</td></tr><tr><td></td><td>B: Lymph vascular space invasion + Non aggressive type.</td><td></td><td></td><td></td></tr><tr><td></td><td>C: Aggressive with Myometrial involvement.</td><td></td><td></td><td></td></tr><tr><td>Stage 3</td><td>A: serosal or Adnexal involvement with any type.</td><td>Non-Operable:<br/>Palliative surgery if fit for anesthesia<br/>palliative<br/>surgery</td><td>30%</td><td>83%</td></tr><tr><td></td><td>B: Vagina, Parametria pelvic peritoneum.</td><td></td><td></td><td></td></tr><tr><td></td><td>C: LN<br/>C1 – pelvic<br/>C2 – para – aortic up to renal vessels</td><td></td><td></td><td></td></tr><tr><td>Stage 4</td><td>A: Bladder, Bowel mucosa</td><td></td><td>10%</td><td>46%</td></tr><tr><td></td><td>B: Abdominal, Peritoneal metastasis beyond pelvis<br/>C: Distant metastasis L.N beyond renal vessels brain, bone.</td><td></td><td></td><td></td></tr></tbody></table>', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7c09d3be', 't-mm-03-011', 'text', 'Table 8. CA ENDOMETRIUM', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
