INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2f42e626', 't-mm-03-011', 'html', '<table><tbody><tr><td>TYPE 1 low Grade</td><td>TYPE 2 High Grade</td></tr><tr><td>E dependent<br/>Pre/peri menopausal women<br/>Endometrial hyperplasia<br/>Minimal invasion<br/>Endometroid type<br/>Low Grade<br/>Good prognosis<br/>KRAS gene</td><td>Non-E dependent<br/>Post-menopausal women<br/>Atrophic Endometrium<br/>Poorly differentiated.<br/>Serous/clear cell carcinoma.<br/>High grade<br/>poor prognosis<br/>P53 gene</td></tr></tbody></table>', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
