INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fdc51670', 't-mm-03-012', 'html', '<table><tbody><tr><td>1A<br/>micro invasive</td><td></td><td>MANAGEMENT</td><td>LND</td><td>5 YEARS<br/>SURVIVAL</td><td>1 YEAR survival</td></tr><tr><td></td><td>1A1: up to 3mm</td><td>Cone biopsy/ simple trachelectomy/ simple hysterectomy</td><td>_</td><td>79%</td><td>96%</td></tr><tr><td></td><td>1A2: 3.1 – 5mm.</td><td>Cone biopsy/simple trachelectomy / simple hysterectomy</td><td>+</td><td></td><td></td></tr><tr><td></td><td>A1 + A2 + Lymph vascular space invasion</td><td>Cone biopsy simple trachelectomy simple hysterectomy. Fertility sparing surgery can be done up to low volume B1.</td><td>+</td><td></td><td></td></tr><tr><td>1B<br/>Macro invasive</td><td>1B1: >5mm – 20mm</td><td>B1 – low volume simple trachelectomy/simple hysterectomy</td><td>+</td><td></td><td>79%</td></tr><tr><td></td><td></td><td>Radical trachelectomy /Radical hysterectomy</td><td>+</td><td></td><td></td></tr><tr><td></td><td>1B2 >2cm – <4cm</td><td>Radical hysterectomy even fertility wishes</td><td>+</td><td></td><td></td></tr><tr><td></td><td>1B3: > 4cm</td><td>Chemo Radiation/ Radical hysterectomy</td><td></td><td></td><td></td></tr><tr><td>STAGE II: BEYOND CERVIX</td><td></td><td></td><td></td></tr><tr><td>2A<br/>Upper 3rd vagina</td><td>2A1: up to 4cm</td><td>Chemo Radiation/ Radical hysterectomy</td><td>49%</td><td>92%</td></tr><tr><td></td><td>2A2: > 4cm in dimension</td><td></td><td></td><td></td></tr><tr><td>2B involving parametria but not up to the pelvic wall</td><td>Chemo Radiation/ palliative surgery</td><td></td><td></td></tr><tr><td>STAGE III:</td><td></td><td></td><td></td></tr><tr><td>A<br/>B<br/>C</td><td>Lower 1/3rd of vagina but not pelvic side wall</td><td>Chemo Radiation/ palliative surgery</td><td>22%</td><td>75%</td></tr><tr><td></td><td>Pelvic side wall Hydronephrosis or non-functional kidney</td><td></td><td></td><td></td></tr><tr><td></td><td>IC1 – pelvic nodes involvement</td><td></td><td></td><td></td></tr><tr><td></td><td>IC2 – paraaortic node metastasis</td><td></td><td></td><td></td></tr><tr><td>STAGE: IV</td><td></td><td></td><td></td></tr><tr><td>A<br/>B</td><td>Adjacent organs</td><td>Chemo Radiation + palliative Radio</td><td>7%</td><td>50%</td></tr><tr><td></td><td>Distant Metastasis</td><td></td><td></td><td></td></tr></tbody></table>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
