INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a6b21f4d', 't-mm-03-013', 'text', 'Benign vulva lesions:', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-84f92082', 't-mm-03-013', 'html', '<table><tbody><tr><td>lesion</td><td>Features</td><td>Treatment and follow up</td></tr><tr><td>Lichen sclerosis<br/>SCC= <5%</td><td>Autoimmune HLA DQ – 7.<br/>Cigarette paper, white shiny appearance<br/>Tissue paper, figure of 8 appearance<br/>Histopathology: hyalinization, no vaginal involvement<br/>Auto antibodies against Extra cellular matrix protein.</td><td>Ultra potent steroid.<br/>Daily for 1m0.<br/>Alternate days for nesxt2ndm0.<br/>Twice weekly for next3rd m0.<br/>F/U – at 3m0 then at 1year at vulval clinic. Afterwards yearly lifelong with GP</td></tr><tr><td>Lichen planus<br/>Erosive – most common<br/>MDT: vulval clinic SSC – 3%.</td><td>Autoimmune in erosive type.<br/>5Ps for characteristic lesions:<br/>Polygonal, purple, pruritic, plaque, planner<br/>Wickham stria<br/>T – cell immunity<br/>Involvement of vaginal/oral mucosa.<br/>H/P: saw tooth Appearance acanthosis, band like dermal infiltrates.</td><td>Ultra-potent steroids.<br/>Vaginal steroid<br/>hydrocortisone with applicators at sensitive areas and mild disease.</td></tr><tr><td>Lichen Simplex</td><td>Thickened pale, scaly, leathery skin.<br/>Involvement of thigh, pubic hair often lost @ site of itching.<br/>H/P: Epithelial thickening, mitosis in Basel and prickle layers.</td><td>Emollient soap.<br/>Topical steroids.</td></tr><tr><td>Paget’s disease.</td><td>Red, pink, crusty, white cake icing effect, strawberry cream effect, velvety texture, islands of keratosis.<br/>H/P: rounded, atypical cells with oval nuclei, pale cytoplasm.</td><td>Wide load excision.<br/>2 weeks referral pathway<br/>Examination of breast, Anus.<br/>F/U: Anal, vulva extension and breast examination 3m0 for 2 years then annually.</td></tr><tr><td>Vulval Crohn’s</td><td>Swollen, edematous, granules, abscesses and draining sinuses.</td><td></td></tr><tr><td>Bechet’s Disease.</td><td>Recurrent oral, genital ulcers painful with scaring</td><td></td></tr><tr><td>Pemphigoid</td><td>Older women, subdermal blisters.<br/>Healing with scaring.<br/>Immunofluorescence:<br/>Antibodies deposits at dermo-epidermal junction.</td><td></td></tr><tr><td>Pemphigus</td><td>Younger women<br/>Intradermal blisters.<br/>Healing without scaring.<br/>Immunofluorescence:<br/>Antibodies deposits @ intra dermal layer of epidermis.</td><td></td></tr><tr><td>Vulvodynia</td><td>Generalized<br/>Localized<br/>Vestibulodynia<br/>Clitorodynia<br/>Hemivulodynia.<br/>Provoked or unprovoked<br/>Provoked with intercourse, Tampon use, light touch.</td><td>Education.<br/>Rule out organic cause<br/>Rule out psychological trauma like sexual abuse<br/>Vulval care<br/>2 or 5% lidocaine 30 min before intercourse<br/>Iintra lesion therapy<br/>Botox injection<br/>TCA – SSRI – SNRI.<br/>Antipsycotics.<br/>Psychological counselling<br/>Psychosexual counselling</td></tr></tbody></table>', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
