INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-61049f50', 't-mm-03-014', 'html', '<table><tbody><tr><td>SATGE I:</td><td></td><td>MANAGEMENT</td><td>5 YEARS<br/>SURVIVAL</td><td>1 YEAR</td></tr><tr><td>A<br/>B</td><td>Lesion < 2cm no node involvement invasion < 1mm.</td><td>Wide local excision.</td><td>95%</td><td>96%</td></tr><tr><td></td><td>> 2cm (2.1cm) invasion 1.1mm, no node involvement</td><td>Ipsilateral: Radical vulvectomy + ipsilateral L node dissection.<br/>Central or lesion lateral > 4cm Radical vulvectomy + Bilateral lymph node dissection.</td><td></td><td></td></tr><tr><td>STAGE II:</td><td></td><td></td><td></td></tr><tr><td>Lower 1/3rd of urethra or vagina or Anus.</td><td>Radiotherapy</td><td>85%</td><td>89%</td></tr><tr><td>STAGE III:</td><td></td><td></td><td></td></tr><tr><td>A<br/>B<br/>C</td><td>1. LN > 5mm A1<br/>2. LN < 5mm A2</td><td>Radiotherapy</td><td>75%</td><td>78%</td></tr><tr><td></td><td>> 2 LN > 5mm OR<br/>> 3 LN <5mm.</td><td></td><td></td><td></td></tr><tr><td></td><td>Positive LN with extra capsular spread.</td><td></td><td></td><td></td></tr><tr><td>STAGE IV:</td><td></td><td></td><td></td></tr><tr><td>A<br/>B</td><td>- upper 3rd of urethra.<br/>- vagina, Bladder/ Rectum, mucosa<br/>- mucous, fixed o pelvic bone or fixed/ ulcerated inguinal L.N.</td><td>Radio</td><td>30%</td><td>43%</td></tr><tr><td></td><td>Distant Mets * pelvic N.</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td>Unknown stage 81%.</td></tr></tbody></table>', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
