INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ceb3e55d', 't-mm-04-015', 'html', '<table><tbody><tr><td>Aa<br/>Descent of fixed point on anterior wall</td><td>Ba<br/>The Lowest part of upper anterior vaginal wall</td><td>Cc<br/>The Lowest part of cervix</td></tr><tr><td>GH<br/>Genital Hiatus</td><td>PB<br/>perineal Body</td><td>TVC<br/>Total Vaginal Length</td></tr><tr><td>AP<br/>Descend of fixed point on posterior wall</td><td>BP<br/>The Lowest part of the upper posterior vaginal wall.</td><td>D<br/>Vault or insertion of uterosacral</td></tr></tbody></table>', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
