INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-93a7d971', 't-mm-04-015', 'html', '<table><tbody><tr><td>Stage 0</td><td>No prolapse<br/>Aa, Ba, BP, AP = - 3cm.<br/>C or D < TVL – 2cm.</td></tr><tr><td>Stage 1</td><td>Leading edge - 1cm.</td></tr><tr><td>Stage 2</td><td>Leading edge > - 1cm but < + 1cm.</td></tr><tr><td>Stage 3</td><td>Leading edge > + 1cm but < + (TVL – 2cm).</td></tr><tr><td>Stage 4</td><td>Leading edge > + (TVL – 2).</td></tr></tbody></table>', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
