INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-05-002', 'chap-mm-05-01', '2.GENITAL INFECTIONS AND THEIR MANAGEMENTS', 'Detailed medical reference and study guide on 2.GENITAL INFECTIONS AND THEIR MANAGEMENTS.', 2, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-769387a7', 't-mm-05-002', 'html', '<table><tbody><tr><td>Infection</td><td>%ages</td><td>Diagnosis</td><td>T/m</td><td>Alternative</td><td>Recurrent</td><td>TOC</td><td>Partner screening</td><td>Special note</td></tr><tr><td>Bacterial vaginosis:<br/>- Common cause of discharge<br/>- 20-40 years of age<br/>- fishy odor after intercourse because semen is alkaline.</td><td>5-50%<br/>TOP 30%<br/>Pregnancy 12%</td><td>Hay Ison<br/>Amsel’s<br/>G staining</td><td>*metronidazole 400mg, B.D, 5-7days, P/O  or 0.75% IV, 5day<br/>* clindamycin= 2% P/V for 7D</td><td>Tinidazole 2g<br/>OR<br/>Clinda 30mg P/O x 7days</td><td>Metronidazole 0.75 I/V x OD for 16D</td><td>Not recommended</td><td>Not recommended</td><td>*HIV – same t/m<br/>*TOP – same t/m<br/>*Pregnancy – I/V<br/>*Lactation – I/V<br/>Avoid oral</td></tr><tr><td>Trichomonas<br/>*Sexually transmitted<br/>*frothy discharge 20-40yrs of age</td><td>Asymptomatic 10-15%<br/>- Discharge 70%<br/>- Frothy 30%<br/>- Strawberry cervix 2%<br/>- urethral dx 20%</td><td>Microscopy – initial HVS, VVS<br/>Culture high sensitivity<br/>NAAT gold std<br/>- VVS<br/>- HVS<br/>- Urine samples</td><td>Metronidazole<br/>400mg BD 5-7days<br/>OR<br/>2g Stat P/O or P/R</td><td>Tinidazole 2g stat</td><td>Tinidazole<br/>- expensive<br/>- Long t/2<br/>- Remain in tissues<br/>- more tissue penetration<br/>Non Responders<br/>- repeat regimen<br/>- High dose<br/>- Metronidazole 2g 0D for<br/>5 – 7D or 800TDS 7D<br/>- Tinidazole 1g TDS 14D, 2G B.D 14days</td><td>Recommended If<br/>- symptoms after t/m or<br/>- Recurrence.</td><td>Any partner within 4weeks tested for STI.</td><td>HIV: B.D regimen for 7days<br/>2g dose not effective<br/>Pregnancy – I/V<br/>Tind C/I in 1st<br/>Lactation 12 weeks<br/>Avoid lactation</td></tr><tr><td>VVC<br/>- 20-40yrs<br/>Low immunity<br/>=>vulval + under Breast = candiasis<br/>=>vulval + intra Breast pargets</td><td>90-90% candida Albicans<br/>*75% women @ least single episode<br/>*45%@ least (2) episode<br/>20% asymptomatic with colonization<br/>(absence of neutrophils on microscopy)</td><td>Microscopy wet film<br/>HVS<br/>No pseudohyphea in candida Glabrata<br/>Neutrophils – candida albicans<br/>Blastophores – Candida Albicans<br/>Psendo hyphae – Candida Albicans<br/>Culture<br/>Sabouraud media</td><td>*Fluconazole 150 P/O or *clotrimazole 500mg p/v<br/>*Severe Fluconazole D1 & D4 or clotrimazole 500 D1 & D4</td><td>Clotrimazole cream 5g stat or clotrimazole pessary 200mg 3 nights.</td><td>*Fluconazole daily for 72 hours then weekly for 6m0 or *clotrimazole or topical imidazole daily 7 – 14days till response then 6m0 *or clotrimazole 500 weekly or * 50 – 100/day.</td><td>Not recommended</td><td>Not recommended</td><td>Pregnancy<br/>- topical or I/V<br/>- longer course clotrimazole 500 for 7ays</td></tr><tr><td></td><td></td><td></td><td>Non Albicans<br/>Nystatin 100000 p/v 12-14nights.<br/>Boric acid or amphotericin B or flucytosine cream</td><td></td><td></td><td></td><td></td></tr></tbody></table>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cb2f1a59', 't-mm-05-002', 'text', 'Table 12. 2.GENITAL INFECTIONS AND THEIR MANAGEMENTS', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b8b247a6', 't-mm-05-002', 'html', '<table><tbody><tr><td>Infection</td><td>%ages</td><td>Diagnosis</td><td>T/m</td><td>Alternative</td><td>Recurrence</td><td>TOC</td><td>Partner screening</td><td>Special note</td></tr><tr><td>Neisseria Gonorrhea<br/>- mucopurulent dx<br/>- Major cause of testicular system.<br/>- Affecting urethra<br/>- Urinary symptoms.</td><td>- 50% asymptomatic.<br/>- 90% symptoms in male<br/>- 19% with NG has CT +ve</td><td>- Microscopy in symptomatic pts:<br/>- Urethral/ meatal swab/ Rectal<br/>- Phalangeal swabs NR<br/>NAAT ideal.<br/>- 1st pass urine<br/>- Swabs (Rectal, Phalangeal, VVS)<br/>Culture all pts<br/>- purpose to check susceptibility</td><td>- Ceftriaxone 1g I/M stat if susceptibility unknown or<br/>- Cipro 500mg p/o x stat if susceptibility known (36% are resistant to Cipro).</td><td>*Cefixime 400mg + azthro 2g stat or<br/>*Gentamycin 240mg I/M + azthro 2g p/o stet<br/>or<br/>*Spectinomycin I/M + Azthro 2g p/o</td><td></td><td>*All pts *culture after 72 hours of completion of t/m.</td><td>Recommended<br/>- Asymptomatic +ve NG or infection of other sites.<br/>3m0 all partners.<br/>- Symptomatic urethral NG<br/>All partners within 2 weeks</td><td>*Conjunctivitis – 1g ceftriaxone<br/>*Disseminated 1g I/M, I/V ceftriaxone 24 hourly.<br/>Or<br/>Cefotaxime 1g -8 hourly I/V. or<br/>Cipro500mg I/V, B.D<br/>Spectinomycin 2g I/M B.D<br/>*Pregnancy Cipro avoid<br/>*HIV same t/m<br/>*NG + CT if azthro taken before then only NG t/m.</td></tr><tr><td>chlamydia Trachomatis<br/>20 – 40age.<br/>- No Urinary symptoms.<br/>-Neonatal conjunctivitis >5days.<br/>- Acute cervicitis.</td><td>15 – 19y = 1.5 – 4.3%<br/>50% resolve spontaneously over 12m0.<br/>Rectal 3 – 50% in MSM 70% in heterosexual.<br/>Phalangeal 0.5 – 2.3% MSM<br/>SARA 1%<br/>PID 16%<br/>Subfertility 1 – 20% after PID<br/>Periportal Adhesions<br/>5 – 10%.<br/>Co – infections with Mycoplasma 3 – 15%.<br/>- 54% resolve spontaneously after 1yr.</td><td>NAAT<br/>- VVS in women.<br/>- FCU in men.<br/>- Rectal swab.<br/>- LG V Testing<br/>- All pts with proctitis.<br/>- HIV + MSM without proctitis but positive CT.</td><td>Uncomplicated<br/>Doxycycline 100mg B.D – 7D.<br/>Or<br/>Azthro 2g stat<br/>Rectal<br/>Doxycycline</td><td>Genital<br/>Erythromycin 500 BD for 10 – 14D<br/>Or<br/>Ofloxacin 200mg BD<br/>Or<br/>Ofloxacin 400 OD<br/>Rectal Azithromycin.</td><td>*2 – 5m0 after previous infection * so repeat testing 3m0 after t/m.</td><td>NR = Routinely *recommended<br/>*Pregnancy 6 weeks.<br/>*Symptoms persists<br/>Swabs and PCR<br/>CT Persists for 3 – 5weeks so TOC NR routinely.</td><td>ALL</td><td>*HIV +ve<br/>Genital & pharyngeal CT same as HIV –ve.<br/>*HIV +ve<br/>Rectal CT<br/>Test LGV<br/>Not doneNot done<br/>Not done<br/>Not done<br/>+ve<br/>Doxi 3 wks<br/>*Pregnancy<br/>Azthro, Erythro Ampicillin<br/>NG + CT<br/>ceftriaxone 500 I/M + Azthro 1g.<br/>NG + Rectel CT – ceftriaxone + Doxi + Azthro.<br/>Neonatal CT<br/>5-12D oral Erythro</td></tr></tbody></table>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
