INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-97e2e241', 't-mm-05-004', 'html', '<table><tbody><tr><td>Condition</td><td>Causative Agent</td><td>Clinical features</td><td>Diagnosis</td><td>Treatment</td><td>Partner tracing and Treatment</td><td>TOC</td><td>Follow up</td></tr><tr><td>Donovanosis<br/>20 – 40years<br/>More in India<br/>Ing over all</td><td>Klebsiella<br/>Granulomatous</td><td>- Papules<br/>- S/C nodules that ulcerate.</td><td>Direct Microscopy<br/>Rapid Giemsa<br/>Histology<br/>Donnovan bodies<br/>PCR</td><td>- Azithro 1g weekly<br/>- Co – trimoxazole<br/>- Doxi<br/>- Erythromycin<br/>Children Azithromycin<br/>Pregnancy Erythromycin</td><td>All in 6m0</td><td></td><td>Till lesions heals</td></tr><tr><td>Lymphogranuloma<br/>venereum<br/>LGV</td><td>CT L1 – L3<br/>L2 commonest</td><td>- 95% Asymptomatic.<br/>- Painless papules, pustules, shallow ulcers.<br/>- Hemorrhagic proctitis<br/>- pharyngeal LGV.<br/>- Painful lymphadenopathy, lymphadenitis (painful + Tender unilateral)</td><td>NAAT:<br/>- Ulcer base<br/>- Rectal swabs.<br/>- Urethral swab</td><td>Doxi Erythro</td><td>Within weeks? Before onset of symptoms</td><td>Not required routinely</td><td></td></tr><tr><td>Chancroid</td><td>H Ducreyi</td><td>Painful ulcers<br/>Bubo formations<br/>Painful lymphadenopathy</td><td>NAAT<br/>Ulcer base</td><td>Azithromycin<br/>Ceftriaxone<br/>Ciprofloxacin</td><td>All partners within 10 days before symptoms</td><td>Not required</td><td></td></tr><tr><td>Syphilis</td><td></td><td>Painless ulcers<br/>Painless lymphadenopathy</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
