INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-81a9e03c', 't-mm-05-005', 'text', 'Abnormal placentation.', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f79a6910', 't-mm-05-005', 'text', 'Use of anti-coagulants', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6d6f8485', 't-mm-05-005', 'text', 'Severe cardiopulmonary disease.', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-49f72c69', 't-mm-05-005', 'text', 'Very high BMI', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8e8b50bf', 't-mm-05-005', 'text', 'Distorted uterine cavity by fibroids or any other anomaly.', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-104ecee5', 't-mm-05-005', 'text', 'Previous cervical surgery.', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8f26bea3', 't-mm-05-005', 'text', 'Type 3 FGM.', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-80b652c3', 't-mm-05-005', 'text', 'These cases need extra care like use of special instruments, type of Anaesthesia, ultrasound and guidance.', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-934e2db4', 't-mm-05-005', 'text', 'Table 14. Medical Abortion Dosage:', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-264bedac', 't-mm-05-005', 'html', '<table><tbody><tr><td>Gestation</td><td>Mifepristone</td><td>Misoprostol</td><td>Repeat Misoprostol</td><td>Until</td></tr><tr><td>Before 12 weeks can be performed at home</td><td>200mg stat 24 – 48 hours before miso P/O</td><td>800mg P/V, S/C or buccal stat</td><td>400ug P/V, S/L, buccal if abortion don’t happen in 4 hours</td><td>----</td></tr><tr><td></td><td>Not available</td><td>800ug P/V, S/L or buccal stat</td><td>400ug p/v, s/c buccal every 3 hours</td><td>expulsion</td></tr><tr><td>After 12 weeks under taken at hospital setting</td><td>200ug stat p/o 24 – 48 hours before miso</td><td>800ug p/v, s/L or buccal stet</td><td>400ug p/v, s/L buccal every 3 hours</td><td>expulsion</td></tr><tr><td></td><td>Not available</td><td>800ug p/v, s/L or buccal stet</td><td>400ug p/v, s/L buccal every 3 hours</td><td>Expulsion</td></tr></tbody></table>', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-de5077c6', 't-mm-05-005', 'text', 'Pain Management for Medical Abortion:', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cc3bc874', 't-mm-05-005', 'text', 'Should be given always', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cbf07922', 't-mm-05-005', 'text', 'NSAIDS – either prophylactic or at time of cramping.', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0e1aecc7', 't-mm-05-005', 'text', 'Non – pharmacological – hot water, heat pads.', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-06c45b31', 't-mm-05-005', 'text', 'Narcotic analgesics if pain is more especially in higher gestation.', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dad1c2b8', 't-mm-05-005', 'text', 'Surgical Abortion:', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-56e6a2fe', 't-mm-05-005', 'text', 'Before 14 weeks:', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-abb5b783', 't-mm-05-005', 'text', 'Vacuum aspiration either', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-60dc834f', 't-mm-05-005', 'text', 'Electric vacuum aspiration EVA', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bb1b253d', 't-mm-05-005', 'text', 'Manual vacuum aspiration MVA', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a7b3c4ef', 't-mm-05-005', 'text', 'MVA accommodate 4 – 12mm cannula.', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6e0f2a7e', 't-mm-05-005', 'text', 'All products should be inspected after evacuation.', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cf84d277', 't-mm-05-005', 'text', '12 – 14 weeks:', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-83dd7e1c', 't-mm-05-005', 'text', 'Dilatation and evacuation D & E.', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-86608643', 't-mm-05-005', 'text', 'D & E require cervical preparation using dilators or pharmacological agents, skilled, experienced care provider.', 80) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cbc2fd93', 't-mm-05-005', 'text', 'Vacuum aspiration can be done up till 16 weeks using large cannula 16mm.', 81) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5e92f679', 't-mm-05-005', 'text', 'D & C (dilation and curettage) is an obsolete method.', 82) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-243b7363', 't-mm-05-005', 'text', 'Cervical preparation before surgical Abortion:', 83) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d3f2b9cd', 't-mm-05-005', 'text', 'Cervix preparation reduces risk of incomplete abortion.', 84) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d7c6ecca', 't-mm-05-005', 'html', '<table><tbody><tr><td>Gestation</td><td>Methods of preparation</td></tr><tr><td>Before 12 weeks</td><td>Mifepristone<br/>Or miso<br/>Or miso</td><td>200mg<br/>400mg<br/>400mg</td><td>P/O<br/>S/L<br/>P/V, buccal</td><td>24 – 48hours before<br/>1 – 2 hours before<br/>2 – 3 hours before</td></tr><tr><td>12 – 18+6weeks</td><td>Combination of MISO and mifepristone as Above or<br/>Osmotic dilators plus<br/>Either Mifepristone or MISO<br/>Or both using above regimen.</td></tr><tr><td>19 – 24weeks</td><td>Osmotic dilators plus<br/>Either mifepristone or MISO<br/>Or both.</td></tr></tbody></table>', 85) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bf9940e5', 't-mm-05-005', 'text', 'Table 15. Cervical preparation before surgical Abortion', 86) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7261235b', 't-mm-05-005', 'text', 'Pain Management for Surgical TOP:', 87) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8f98b848', 't-mm-05-005', 'text', 'Analgesia should always be offered:', 88) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b73f776b', 't-mm-05-005', 'text', 'Most of the times:', 89) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2006a862', 't-mm-05-005', 'text', 'NSAIDS', 90) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fc59d425', 't-mm-05-005', 'text', 'Local anesthesia+ Verbal reassurance', 91) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d55a36d1', 't-mm-05-005', 'text', 'Conscious sedation', 92) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-23ad250c', 't-mm-05-005', 'text', 'General Anesthesia:', 93) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-781420db', 't-mm-05-005', 'text', 'Not recommended routinely, if considered then use I/V propofol and fentanyl rather inhalational agents.', 94) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e880cb31', 't-mm-05-005', 'text', 'Local anesthesia:', 95) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c8eb6647', 't-mm-05-005', 'text', 'Lidocaine as Para cervical block can be used to alleviate discomfort from cervical dilatation and uterine evacuation.', 96) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-de0e97bf', 't-mm-05-005', 'text', 'Conscious Sedation:', 97) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-051c6f5c', 't-mm-05-005', 'text', 'Should be offered with local anesthesia if available.', 98) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aeec11e1', 't-mm-05-005', 'text', 'Medical Management of Incomplete Abortion:', 99) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-735d1e97', 't-mm-05-005', 'text', 'No evidence of Infection', 100) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3b530197', 't-mm-05-005', 'text', 'Uterine size < 14 weeksuterine size > 14 weeks', 101) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f6e7d969', 't-mm-05-005', 'text', 'MISO 400ug s/L buccal1. 14 – 24 weeks – MISO 400ug S/L,', 102) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-58850fe5', 't-mm-05-005', 'text', 'MISO 600ug orallybuccal, P/V.', 103) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66a8396d', 't-mm-05-005', 'text', 'Evacuation by vacuum aspiration repeat 3 hourly', 104) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d85600e0', 't-mm-05-005', 'text', '2. up to 16 weeks’ vacuum aspiration', 105) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6cb3317f', 't-mm-05-005', 'text', '3. after 16 weeks’ dilatation and evacuation', 106) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c997feb7', 't-mm-05-005', 'text', 'Incomplete Abortion + Infection:', 107) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-89df74e9', 't-mm-05-005', 'text', 'Broad spectrum antibiotics, I/V if infection is severe.', 108) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c54c86ac', 't-mm-05-005', 'text', 'Surgical evacuation urgently.', 109) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e5ce9d40', 't-mm-05-005', 'text', 'Refer to facility where expertise available', 110) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8309a958', 't-mm-05-005', 'text', 'Septic Shock', 111) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5ae8f08a', 't-mm-05-005', 'text', 'I/V antibiotics immediately.', 112) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f39d4244', 't-mm-05-005', 'text', 'Referral to HDU', 113) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-81a0b121', 't-mm-05-005', 'text', 'Immediately', 114) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-166219bc', 't-mm-05-005', 'text', 'Ampicillin 0.5 – 1g every 6 hours.', 115) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9f466dd6', 't-mm-05-005', 'text', 'Metronidazole 500mg every 8 hours.', 116) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d38b6287', 't-mm-05-005', 'text', 'Gentamicin 12mg daily with monitoring.', 117) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5806b9db', 't-mm-05-005', 'text', 'Contraception after abortion:', 118) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a74617d5', 't-mm-05-005', 'text', 'Access to C/C on same day.', 119) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-79ba82f3', 't-mm-05-005', 'text', 'Implants:', 120) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-312a04c4', 't-mm-05-005', 'text', 'Day of surgical abortion or day of mifepristone.', 121) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e2f4440a', 't-mm-05-005', 'text', 'IUD:', 122) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1c11ce38', 't-mm-05-005', 'text', '@ time of surgical TOP or after expulsion of pregnancy.', 123) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7fba2b4c', 't-mm-05-005', 'text', 'DMPA:', 124) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-afa37cf4', 't-mm-05-005', 'text', '@ time of mifepristone.', 125) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a7e104d9', 't-mm-05-005', 'text', 'Risk of ongoing pregnancy.', 126) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fcef3e4f', 't-mm-05-005', 'text', 'Tubal Ligation:', 127) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-438d6b54', 't-mm-05-005', 'text', 'Should be done after some time to avoid regret and failure', 128) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-32bfba6b', 't-mm-05-005', 'text', 'All methods except IUD can be stated on the time of mifepristone.', 129) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8f08ecef', 't-mm-05-005', 'text', 'IUD can be initiated after surgical procedure', 130) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96b99788', 't-mm-05-005', 'text', 'Additional contraception is not required if contraception initiated immediately or with 5 days of abortion.', 131) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-05-006', 'chap-mm-05-01', '7. ABORTION CLAUSES', 'Detailed medical reference and study guide on 7. ABORTION CLAUSES.', 6, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-10e58b83', 't-mm-05-006', 'html', '<table><tbody><tr><td>Clause</td><td>Definition</td><td>Example</td><td>Additional Points</td></tr><tr><td>A</td><td>Continuation of pregnancy would involve risk to life of the women > Than if TOP done.</td><td>PE @ 34 week</td><td>Elective Termination<br/>2 practioners involved<br/>In decision</td></tr><tr><td>B</td><td>Continuation of pregnancy can cause Grave injury to physical and mental health > than if TOP done</td><td></td><td>Elective Termination<br/>2 practioners involved</td></tr><tr><td>C</td><td>Social Reasons < 24 weeks<br/>Injury to physical/ Mental health of women</td><td>Gender, Rape</td><td>Elective Termination<br/>2 practioners involved</td></tr><tr><td>D</td><td>Existing child health < 24 weeks<br/>Continuation more harm to physical/ Mental health of existing child than TOP</td><td>Down @ home now requesting TOP that she can’t handle Down and newborn</td><td>Elective Termination<br/>2 practioners involved</td></tr><tr><td>E</td><td>Risk of being handicapped if born anomalous fetus</td><td>Gross anomalies, Edwards Down with associated severe Anomalies<br/>Cleft, lip, Missing limp => don’t Abort</td><td>Elective Termination<br/>2 practioners involved</td></tr><tr><td>F</td><td>To save life of women</td><td>Eclampsia</td><td>Emergency termination<br/>1 practioner involved</td></tr><tr><td>G</td><td>Prevent permanent Injury to physical/ mental health of women</td><td>SCH</td><td>Emergency termination<br/>1 practioner involved</td></tr></tbody></table>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-df5c82a2', 't-mm-05-006', 'text', 'Table 16. ABORTION CLAUSES', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0a31603f', 't-mm-05-006', 'text', 'C, D => <24 weeks', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9bfd2e1d', 't-mm-05-006', 'text', 'A, B, F, G => No limit of gestations', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-05-007', 'chap-mm-05-01', '8. UK MEDICAL ELIGIBILITY CRITERIA (UKMEC)', 'Detailed medical reference and study guide on 8. UK MEDICAL ELIGIBILITY CRITERIA (UKMEC).', 7, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6e40ff86', 't-mm-05-007', 'text', 'Definition of UKMEC categories', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-89abbf08', 't-mm-05-007', 'html', '<table><tbody><tr><td>UKMEC</td><td>Definition of category</td></tr><tr><td>Category 1</td><td>A condition for which there is no restriction for the use of the method</td></tr><tr><td>Category 2</td><td>A condition where the advantages of using the method generally outweigh the theoretical or proven risks</td></tr><tr><td>Category 3</td><td>A condition where the theoretical or proven risks usually outweigh the advantages of using the method. The provision of a method requires expert clinical judgement and/or referral to a specialist contraceptive provider, since use of the method is not usually recommended unless other more appropriate methods are not available or not acceptable</td></tr><tr><td>Category 4</td><td>A condition which represents an unacceptable health risk if the method is used</td></tr></tbody></table>', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
