INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9bedbdc2', 't-mm-05-007', 'html', '<table><tbody><tr><td>Current and history of ischemic heart disease</td><td>1</td><td>I</td><td>C</td><td>I</td><td>C</td><td>3</td><td>I</td><td>C</td><td>4</td></tr><tr><td></td><td></td><td>2</td><td>3</td><td>2</td><td>3</td><td></td><td>2</td><td>3</td><td></td></tr><tr><td>Stroke (history of cerebrovascular accident, including TIA)</td><td>1</td><td>I</td><td>C</td><td>I</td><td>C</td><td>3</td><td>I</td><td>C</td><td>4</td></tr><tr><td></td><td></td><td>2</td><td>3</td><td>2</td><td>3</td><td></td><td>2</td><td>3</td><td></td></tr><tr><td>Known dyslipidemias</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td></tr><tr><td>Venous thromboembolism (VTE)</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>a) History of VTE</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td>b) Current VTE (on anticoagulants)</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td>c) Family history of VTE</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>(1) First-degree relative age <45 years</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>3</td></tr><tr><td>(2) First-degree relative age ≥ 245 years</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>d) Major surgery</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>(1) With prolonged immobilization</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td>(ii) Without prolonged immobilization</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>e) Minor surgery without immobilization</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>f) Immobility (unrelated to surgery) (e.g wheelchair use, debilitating illness)</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>3</td></tr><tr><td>Superficial venous thrombosis</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>a) Varicose veins</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>b) Superficial venous thrombosis</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>Known thrombogenic mutations e.g factor V Leiden, prothrombin mutation, protein s. protein C and the antithrombin deficiencies</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td>Valvular and congenital heart disease</td></tr><tr><td>a) Uncomplicated</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>b) Complicated (e.g. pulmonary hypertension, history of subacute bacterial endocarditis)</td><td>2</td><td>2</td><td>1</td><td>1</td><td>1</td><td>4</td></tr><tr><td>Cardiomyopathy</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>a) Normal cardiac function</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>b) Impaired cardiac function</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td>Cardiac arrhythmias</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>a) Atrial fibrillation</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td>b) Known long QT syndrome</td><td>I</td><td>C</td><td>I</td><td>3</td><td>1</td><td>2</td><td>1</td><td>2</td></tr><tr><td></td><td>3</td><td>1</td><td>3</td><td>1</td><td></td><td></td><td></td><td></td></tr><tr><td>NEUROLOGICAL CONDITIONS:</td></tr><tr><td>HEADACHES</td></tr><tr><td>a) Non-migraines (mild or severe)</td><td>1</td><td>1</td><td>1</td><td>1</td><td>I</td><td>C</td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>I</td><td>2</td></tr><tr><td>b) Migraine without aura, at any age</td><td></td><td></td><td></td><td>I</td><td>C</td><td>I</td><td>C</td></tr><tr><td></td><td></td><td></td><td></td><td>1</td><td>2</td><td>2</td><td>3</td></tr><tr><td>c) Migraine with aura,