INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-36687a38', 't-mm-05-007', 'html', '<table><tbody><tr><td>HIV INFECTION</td><td></td></tr><tr><td>HIV infection</td><td></td></tr><tr><td>a) High risk of HIV infection</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>b) HIV infected</td><td></td></tr><tr><td>(i) CD4 count ≥200 cells/mm³</td><td>2</td><td>2</td><td>1</td><td>1<br/>1</td><td>1</td></tr><tr><td>(ii) CD4 count <200 cells/mm²</td><td>I</td><td>C</td><td>I</td><td>C</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td></td><td>3</td><td>2</td><td>3</td><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>c) Taking antiretroviral (ARV) drugs</td><td>Certain ARV drugs have the potential to affect the bioavailability of steroid hormones in hormonal contraception.<br/>For up-to-date information on the potential drug interactions between hormonal contraception and ARV drugs, please refer to the online HIV drugs interaction checker<br/>(www.hiv-druginteractions.org/Interactions.aspx).</td></tr><tr><td>OTHER INFECTIONS</td><td></td></tr><tr><td>Tuberculosis</td><td></td></tr></tbody></table>', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
