INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-33705378', 't-mm-05-007', 'html', '<table><tbody><tr><td>Diabetes</td><td></td></tr><tr><td>a) History of gestational disease</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>b) Non-vascular disease</td><td></td></tr><tr><td>(i) Non-insulin dependent</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td></tr><tr><td>(ii) Insulin dependent</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td></tr><tr><td>c) Nephropathy/retinopathy/neuropathy</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>3</td></tr><tr><td>d) Other vascular disease</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>3</td></tr></tbody></table>', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
