INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e8faff5d', 't-mm-05-007', 'html', '<table><tbody><tr><td>Thyroid disorders</td><td></td></tr><tr><td>a) Simple goitre</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>b) Hyperthyroid</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>c) Hypothyroid</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>GASTROINTESTINAL CONDITIONS</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Gallbladder disease</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>a) Symptomatic</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>(i) Treated by cholecystectomy</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td></tr><tr><td>(ii) Medically treated</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>3</td></tr><tr><td>(iii) Current</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>3</td></tr><tr><td>b) Asymptomatic</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td></tr><tr><td>History of cholestasis</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>a) Pregnancy related</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>b) Past COC related</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>3</td></tr><tr><td>Viral hepatitis</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>a) Acute or flare</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>I</td><td>C</td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td>3</td><td>2</td></tr></tbody></table>', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8edcf076', 't-mm-05-007', 'html', '<table><tbody><tr><td>b) Carrier</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>c) Chronic</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>Cirrhosis</td><td></td></tr><tr><td>a) Mild (compensated without complications)</td><td>4</td><td>4</td><td>4</td><td>4</td><td>4</td><td>4</td></tr><tr><td>b) Severe (decompensated)</td><td>1</td><td>3</td><td>3</td><td>3</td><td>3</td><td>4</td></tr><tr><td>Inflammatory bowel disease (including Crohn''s disease and ulcerative colitis)</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td></tr><tr><td>ANAEMIAS</td><td></td></tr><tr><td>Thalassemia</td><td>2</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>Sickle cell disease</td><td>2</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td></tr><tr><td>Iron deficiency anemia</td><td>2</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>RHEUMATIC DISEASES</td><td></td></tr><tr><td>Rheumatoid arthritis</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td></tr><tr><td>Systemic lupus erythematosus (SLE)</td><td></td></tr><tr><td>a) No antiphospholipid antibodies</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td></tr><tr><td>b) Positive antiphospholipid antibodies</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr><tr><td>Positive antiphospholipid antibodies</td><td>1</td><td>2</td><td>2</td><td>2</td><td>2</td><td>4</td></tr></tbody></table>', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-05-008', 'chap-mm-05-01', '9. COMBINED HORMONAL CONTRACEPTION', 'Detailed medical reference and study guide on 9. COMBINED HORMONAL CONTRACEPTION.', 8, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8255a8a4', 't-mm-05-008', 'heading', '10. PROGESTERONE ONLY PILLS', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3e2d0699', 't-mm-05-008', 'heading', '11. PROGESTERONE ONLY INJECTABLE CONTRACEPTION', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-15557c49', 't-mm-05-008', 'heading', '12. PROGESTERONE ONLY IMPLANT', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e7cdc2e9', 't-mm-05-008', 'text', '1/3’d UK women aged 16—44 years had used oral contraception', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4f291ea1', 't-mm-05-008', 'text', 'CHC -estrogen and a progestogen', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-df409388', 't-mm-05-008', 'text', 'A pill (COC)', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f4e5ede1', 't-mm-05-008', 'text', 'Transdermal Patch CTP', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-38b22cef', 't-mm-05-008', 'text', 'Vaginal ring CVR', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9217b771', 't-mm-05-008', 'text', 'PERFECT USE VS TYPICAL USE', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4e5f779a', 't-mm-05-008', 'text', 'Many contraceptive methods are affected by human error such as forgetting to take your pill. They may be very effective with "perfect use" but the effectiveness of certain methods as "typically used" is likely to be lower.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2cc98aac', 't-mm-05-008', 'text', 'Perfect use: of a contraceptive method is when it is used correctly all the time.', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-45e9b8fc', 't-mm-05-008', 'text', 'Typical use: is what generally happens in real life. It takes into account human error.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5802ed22', 't-mm-05-008', 'text', '✓ Effectiveness could also be affected by drug interactions (all CHC methods) and malabsorption (COC only). ✓ Effectiveness could also be affected by drug interactions (all CHC methods) and malabsorption (COC only). CONTRACEPTIVE EFFECTIVENESS:', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3f66fbb', 't-mm-05-008', 'text', 'CHC is highly user-dependent:', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ba4f2a90', 't-mm-05-008', 'text', '✓CTP could be less effective in women weighing >90 kg✓CTP could be less effective in women weighing >90 kg Perfect use = contraceptiveTypical use it is estimated that', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5f2b94eb', 't-mm-05-008', 'text', 'failure is low (<1%).9% of women have unplanned', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bdda106d', 't-mm-05-008', 'text', 'pregnancies in the first year of CHC use.', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c9a192d8', 't-mm-05-008', 'text', 'Health risks:', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5d543e7b', 't-mm-05-008', 'text', 'VTE: CHC is associated with increased risk of VTE;', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e929dc8e', 't-mm-05-008', 'text', 'dependent on progestogen type and estrogen dose', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ee1f3a45', 't-mm-05-008', 'html', '<table><tbody><tr><td>Type of CHC used</td><td>Risk of developing a VTE in a year (incidence in 10 000 women)</td></tr><tr><td>Women not using combined hormonal pill/patch/ring and not pregnant</td><td>~2</td></tr><tr><td>Women using CHC containing levonorgestrel, norethisterone or norgestimate</td><td>-5-7</td></tr><tr><td>Women using CHC containing etonogestrel or norelgestromin</td><td>~6-12</td></tr><tr><td>Women using CHC containing drospirenone, gestodene or desogestrel</td><td>~9-12</td></tr></tbody></table>', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9513f4c6', 't-mm-05-008', 'text', 'Arterial thromboembolic disease:', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a2efdf09', 't-mm-05-008', 'text', 'Myocardial information (MI) and ischemic stroke', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-becf9688', 't-mm-05-008', 'text', 'Breast cancer: small increased risk of breast cancer which reduces with time after stopping CHC.', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f0860fd8', 't-mm-05-008', 'text', 'Cervical cancer: current use of CHC for > 5 years has a small increased risk of cervical cancer risk reduces over time after stopping CHC and is no longer increased by about 10 years after stopping.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5aa9aadc', 't-mm-05-008', 'text', 'Hormone free interval HFI can be associated with these defects including mood chance headache and unscheduled bleeding.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f3fa9bdb', 't-mm-05-008', 'text', 'Concomitant use of other drugs:', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c56cff79', 't-mm-05-008', 'text', 'Hepatic enzyme-inducing drugs could reduce the contraceptive effectiveness of all CHC methods. It can affect serum levels of drugs such as lamotrigine with potential significant clinical effects', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0ed5235d', 't-mm-05-008', 'text', 'Choice of contraceptive method:', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-84328878', 't-mm-05-008', 'text', 'A COC containing < 30 ug EE in combination with LNG or NET is a reasonable first-line option to minimize (VTE) risk.', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-465a70d5', 't-mm-05-008', 'text', 'CHC, formulation and regimen:', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-758a84d9', 't-mm-05-008', 'text', 'Estrogens: In the UK, the majority of COC as well as the CTP and CVR, contain between 20 µg and 35 µg of the synthetic estrogen, EE.', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8921423f', 't-mm-05-008', 'text', 'Progestogens:', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0fe1315e', 't-mm-05-008', 'text', 'First: norethisterone (NET)', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1d1ac49f', 't-mm-05-008', 'text', 'Second: levonorgestrel (LNG)', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-86709169', 't-mm-05-008', 'text', 'Third: Desogestrel, gestagens, norgestimate', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1b543395', 't-mm-05-008', 'text', 'Newer/Formulations:', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96d5c3d0', 't-mm-05-008', 'text', 'Co-cyprindiol (containing 35 µg EE with cyproterone acetate, an anti-androgen) is indicated for management of moderate to severe acne and hirsutism. Women using co-cyprindiol for these indications do not require additional contraception.', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7b0a7ee9', 't-mm-05-008', 'text', 'Standard and tailored regimens for use of combined hormonal contraception (CHC)', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f5a62b30', 't-mm-05-008', 'html', '<table><tbody><tr><td>Type of regimen</td><td>Period of CHC use</td><td>HFI</td></tr><tr><td>Standard use</td><td>21 days (21 active pills or 1 ring, or 3 patches)</td><td>7 days</td></tr><tr><td>Tailored use</td><td></td><td></td></tr><tr><td>Shortened hormone-free interval (HFI)</td><td>21 days (21 active pills or 1 ring, or 3 patches)</td><td>4 days</td></tr><tr><td>Extended use (tricycling)</td><td>9 weeks 3 x 21 active pills or 3 rings, or 9 patches used consecutively)</td><td>4 or 7 days</td></tr><tr><td>Flexible extended use</td><td>Continuous use (>221 days) of active pills, patches or rings until breakthrough bleeding occurs for 3-4 days</td><td>4 days</td></tr><tr><td>Continuous use</td><td>Continuous use of active pills, patches or rings</td><td>None</td></tr></tbody></table>', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0314dab2', 't-mm-05-008', 'text', 'Studies revealed that suppression of ovarian activity with low-dose COCs with 7-day HFIs is suboptimal. Loss of ovarian suppression during 7-day HFIs is commonly associated with follicular development, and', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b005bfd5', 't-mm-05-008', 'text', 'most dominant follicles appear during this period. By contrast, increased ovarian suppression was noted in regimens that shortened or eliminated the HFI, or that substituted low-dose ethinyl estradiol for the HFI.', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-81e48ac5', 't-mm-05-008', 'text', 'Extended regimens with modified HFIs may provide greater ovarian suppression with the potential for increased contraceptive effectiveness.', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3e485d18', 't-mm-05-008', 'text', 'Non-contraceptive health benefits:', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dfd71621', 't-mm-05-008', 'text', 'Reduce HMB', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c8f61261', 't-mm-05-008', 'text', 'menstrual pain', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-176378c0', 't-mm-05-008', 'text', 'improve acne.', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e236a0b7', 't-mm-05-008', 'text', 'Premenstrual syndrome symptoms.', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a7f27978', 't-mm-05-008', 'text', 'Reduce risk of recurrence of endometriosis after surgical management.', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f0806266', 't-mm-05-008', 'text', 'CHC can be used for management of pcos.', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1d45d3f5', 't-mm-05-008', 'text', 'Significant reduction in risk of endometrial and ovarian cancer that increases with duration of chc use and persists for many years after stopping chc', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8ef92660', 't-mm-05-008', 'text', 'Reduced risk of colorectal cancer', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-27b8f699', 't-mm-05-008', 'text', 'Table 18. Starting combined hormonal contraception and requirement for additional contraceptive precautions', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3ff32a24', 't-mm-05-008', 'html', '<table><tbody><tr><td>Circumstance</td><td>When to start</td><td>Requirement for 7 days additional contraceptive precautions (9 days for estradiol valerate/dienogest COC)</td><td>Requirement for HSUPT 21 days after last UPSI</td></tr><tr><td>Women having natural menstrual cycles</td><td>Up to and including Day 5</td><td>No</td><td>No</td></tr><tr><td></td><td>At any other time if it is reasonably certain she is not pregnant or a HSUPT is negative</td><td>Yes</td><td>Consider</td></tr><tr><td>Women who are amenorrhoeic</td><td>At any time if it is reasonably she is not pregnant and/or a HSUPT is negative</td><td>Yes</td><td>Consider</td></tr><tr><td>After LNG-EC</td><td>Immediately</td><td>Yes</td><td>Yes</td></tr><tr><td>After UPA-EC</td><td>5 days after taking UPA-EC</td><td>Yes</td><td>Yes</td></tr><tr><td>After child birth (breastfeeding)</td><td>From 6 childbirth weeks following</td><td>Yes</td><td>Consider</td></tr><tr><td>After childbirth (not breastfeeding)</td><td>Without additional risk factors for VTE: from 3 weeks following childbirth</td><td>Yes</td><td>Consider</td></tr><tr><td></td><td>With additional risk factors for VTE: from 6 weeks following childbirth</td><td>Yes</td><td>Consider</td></tr><tr><td>†After abortion. Miscarriage.<br/>ectopic pregnancy or gestational trophoblastic disease</td><td>Up to and including Day 5 following treatment</td><td>No</td><td>Follow-up pregnancy testing as per local protocol after these pregnancies</td></tr><tr><td></td><td>After Day 5" if it is reasonably certain she is not pregnant</td><td>Yes</td><td></td></tr></tbody></table>', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-07705c48', 't-mm-05-008', 'text', 'Table 19. Switching from hormonal contraceptive method to combined hormonal contraception', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-47b9a529', 't-mm-05-008', 'html', '<table><tbody><tr><td></td><td>Switch from</td><td>Switch to</td><td>When to start</td><td>Requirements for additional contraceptive Precaution</td><td>Notes</td></tr><tr><td></td><td>CHC</td><td>Another CHC</td><td>Start on day after last No active COC. CVR or CTP</td><td>No</td><td>a hormone-free interval (HF1) is taken the need for additional emergency should precautions be and contraception assessed on an individual basis, taking account of correct use before the HPI. See also Table 7.</td></tr><tr><td></td><td>Traditional POP</td><td>CHC</td><td>Can be Immediately. started the POP has been used consistently and<br/>Correctly</td><td>Yes (7 days")</td><td>The primary mode of action Is not inhibition of ovulation and therefore additional precautions are required in case ovulation occurs before contraceptive efficacy of CHC has been established. The cervical mucus effect may be maintained but there is no evidence to prove adequate contraceptive protection.</td></tr><tr><td></td><td>Progestogen-only anovulatory methods<br/>Desogestrel-only pill<br/>Desogestrel-only pill<br/>Injectable</td><td>CHC</td><td>Start on day after last Desogestrel<br/>Start on day after last Desogestrel up to when the repeat injection is due<br/>Start at any time up to when the Implant is due for removal</td><td>No</td><td>The primary mode of action of these methods is inhibition of ovulation CHC suppresses ovulation by the time the inhibitory effect of the previous method is lost.</td></tr><tr><td></td><td>LNG-IUS (within licensed duration of use)</td><td>CHC</td><td>Start at any time</td><td>Yes (7 days"<br/>if there has been UPSI in the last 7 days, the LNG-IUS should be retained for 7 days</td><td></td></tr></tbody></table>', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-93c52929', 't-mm-05-008', 'text', 'Table 20.Switching from non-hormonal contraceptive method to combined hormonal contraception', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aa903639', 't-mm-05-008', 'html', '<table><tbody><tr><td>Switch from</td><td>Switch to</td><td>When to start</td><td>Requirement for additional contraceptive precaution</td><td>Notes</td></tr><tr><td>Cu-IUD</td><td>CHC</td><td>Up to Day 5 of menstrual cycle (Day 1 estradiol COC)</td><td>No</td><td>Cu-IUD can be removed at that time.</td></tr><tr><td></td><td></td><td>At any other time during the menstrual cycle or if amenorrhoeic</td><td>Yes (7 days)"</td><td>Additional precautions are required unless CHC was started 7 days prior to Cu-IUD removal. Cu-IUD could be left in situ until CHC becomes effective.</td></tr><tr><td>Non-hormonal method (other than a Cu-IUD)</td><td>CHC</td><td>Up to and including Day 5 of menstrual cycle (Day 1 estradiol COC)</td><td>No</td><td></td></tr><tr><td></td><td></td><td>At any other time</td><td>Yes (7 days")</td><td>Consider follow-up pregnancy test.<br/>If amenorrhoeic, a negative HSUPT should be obtained before starting CHC.</td></tr></tbody></table>', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9998ce7a', 't-mm-05-008', 'text', 'Percentage of women experiencing an unintended pregnancy within the first year of use with typical use and perfect use', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2ef9a457', 't-mm-05-008', 'html', '<table><tbody><tr><td>Method</td><td>Typical use (%) (estimated)</td><td>Perfect use (%)</td></tr><tr><td>No method</td><td>85</td><td>85</td></tr><tr><td>Fertility awareness-based methods</td><td>24</td><td>0.4-5</td></tr><tr><td>Female diaphragm</td><td>12</td><td>6</td></tr><tr><td>Male condom</td><td>18</td><td>2</td></tr><tr><td>Combined hormonal contraception"</td><td>9</td><td>0.3</td></tr><tr><td>Progestogen-only pill</td><td>9</td><td>0.3</td></tr><tr><td>Progestogen-only injectable</td><td>6</td><td>0.2</td></tr><tr><td>Copper intrauterine device</td><td>0.8</td><td>0.6</td></tr><tr><td>Levonorgestrel intrauterine system</td><td>0.2</td><td>0.2</td></tr><tr><td>Progestogen-only implant</td><td>0.05</td><td>0.05</td></tr><tr><td>Female sterilization</td><td>0.5</td><td>0.5</td></tr><tr><td>Vasectomy</td><td>0.15</td><td>0.1</td></tr></tbody></table>', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-75c3118c', 't-mm-05-008', 'text', 'Women using combined hormonal contraception: key indications for medical review', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d88c40a0', 't-mm-05-008', 'text', 'Key symptoms that should prompt women to seek urgent medical review', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
