INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b00d7032', 't-mm-05-008', 'text', 'Chest pain and/or breathlessness and/or coughing up blood', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-26a1c679', 't-mm-05-008', 'text', 'Loss of motor or sensory function', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-edad3064', 't-mm-05-008', 'text', 'Key symptoms that should prompt women to seek medical review', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-04924fbf', 't-mm-05-008', 'text', 'Breast lump, unilateral nipple discharge, new nipple inversion, change in breast skin', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-adaaabca', 't-mm-05-008', 'text', 'New onset migraine', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eab4956c', 't-mm-05-008', 'text', 'New onset sensory or motor symptoms in the hour preceding onset of migraine', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2a8eff5b', 't-mm-05-008', 'text', 'Persistent unscheduled vaginal bleeding', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6e97e9cf', 't-mm-05-008', 'text', 'New medical diagnoses that should prompt women to seek advice from their contraceptive provider (and review of the suitability of CHC)', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c861f89e', 't-mm-05-008', 'text', 'High blood pressure', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb86cf07', 't-mm-05-008', 'text', 'High body mass index (>35 kg/m²)', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-61da3051', 't-mm-05-008', 'text', 'Migraine or migraine with aura', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d7406ecc', 't-mm-05-008', 'text', 'Deep vein thrombosis or pulmonary embolism', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-89b2f846', 't-mm-05-008', 'text', 'Blood clotting abnormality', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9b6aa08c', 't-mm-05-008', 'text', 'Antiphospholipid antibodies', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eee7a1e4', 't-mm-05-008', 'text', 'Angina, heart attack, stroke or peripheral vascular disease', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-39dd610a', 't-mm-05-008', 'text', 'Atrial fibrillation', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c44bee74', 't-mm-05-008', 'text', 'Cardiomyopathy', 80) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-52489f71', 't-mm-05-008', 'text', 'Breast cancer or breast cancer gene mutation', 81) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-53a4f787', 't-mm-05-008', 'text', 'Liver tumor', 82) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-57819403', 't-mm-05-008', 'text', 'Symptomatic gallstones', 83) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d6b6b45a', 't-mm-05-008', 'text', 'If two or more Pills have been missed (> 72 hours since last pill is current packet of > 48 hours late starting first pill in new packet)If two or more Pills have been missed (> 72 hours since last pill is current packet of > 48 hours late starting first pill in new packet)Missed pill Guidelines:IF ONE pills been missed (48-72 hours since last pill in current packet or 24-48 hours late starting first pill in new packetIF ONE pills been missed (48-72 hours since last pill in current packet or 24-48 hours late starting first pill in new packet', 84) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0b36048d', 't-mm-05-008', 'text', 'Continuing contraceptive coverThe most recent missed pill should be taken as soon as possibleThe remaining pills should be continued at the usual timeCondoms should be used or sex avoided until seven consecutive active pills have been taken. This advice may be overcautious in the second and third weeks, but the advice is a backup in the event that further pills are missed.Continuing contraceptive coverThe most recent missed pill should be taken as soon as possibleThe remaining pills should be continued at the usual timeCondoms should be used or sex avoided until seven consecutive active pills have been taken. This advice may be overcautious in the second and third weeks, but the advice is a backup in the event that further pills are missed.Continuing contraceptive cover:The missed pill should be taken as soon as remembered. The remaining pills should be continued at the usual time.Continuing contraceptive cover:The missed pill should be taken as soon as remembered. The remaining pills should be continued at the usual time.', 85) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d3c42c98', 't-mm-05-008', 'text', 'Minimizing risk of pregnancyEmergency contraception not usually required but may need to be considered if pills have to missed earlier in the packet or in the last week of the previous packet.Minimizing risk of pregnancyEmergency contraception not usually required but may need to be considered if pills have to missed earlier in the packet or in the last week of the previous packet.', 86) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d4792291', 't-mm-05-008', 'text', 'Minimizing The risk of pregnancyIf pills are missed in the first week (Pills 1-7)EC should be considered if unprotected sex occurred in the pill – free interval or in the first week of pill taking.if pills are missed the second week (pills 8 – 14)No indication for the EC if the pills in the proceeding 7 days have been consistently and correctly (assuming the pills thereafter 7 days correct lying the pills thereafter are taken correctly and additional contraceptive precautions are used. if pills are missed in the third week (pills 15 – 21)OMIT THE PILL FREE INTERVAL by finishing the pills in the correct pack (or discarding any placebo tablets) and starting a new pack the next day.Minimizing The risk of pregnancyIf pills are missed in the first week (Pills 1-7)EC should be considered if unprotected sex occurred in the pill – free interval or in the first week of pill taking.if pills are missed the second week (pills 8 – 14)No indication for the EC if the pills in the proceeding 7 days have been consistently and correctly (assuming the pills thereafter 7 days correct lying the pills thereafter are taken correctly and additional contraceptive precautions are used. if pills are missed in the third week (pills 15 – 21)OMIT THE PILL FREE INTERVAL by finishing the pills in the correct pack (or discarding any placebo tablets) and starting a new pack the next day.', 87) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ce6cce93', 't-mm-05-008', 'text', '1st week missed - EC + additional precautions', 88) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bcb03513', 't-mm-05-008', 'text', '2nd week only additional precautions', 89) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6ffc90fc', 't-mm-05-008', 'text', '3rd week – skip pill free interval', 90) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-05-009', 'chap-mm-05-01', '11.PROGESTOGEN-ONLY PILL', 'Detailed medical reference and study guide on 11.PROGESTOGEN-ONLY PILL.', 9, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0e578ba8', 't-mm-05-009', 'text', 'This guideline will consider POPs available in the UK. namely Desogestrel (DSG) 75 kg, Drosperinone (DRSP) 4 mg (soon to be available in the UK) and the ‘traditional’ POPs levonorgestrel| (LNG) 30 pg and norethisterone (NET) 350 ug', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3cbad315', 't-mm-05-009', 'text', 'MOA: DSG and DRSP POPs: inhibition of ovulation', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-31181219', 't-mm-05-009', 'text', 'LNG and NET POPs: changes on cervical mucus, endometrium and tubal motility', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a940d008', 't-mm-05-009', 'text', 'A 12-month supply of traditional, DSG or DRSP POP can be provided with an annual review.', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9699975c', 't-mm-05-009', 'text', 'Specific approved brands of DSG POP can now be bought from a pharmacy, without a prescription, under the supervision of a pharmacist.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3161c279', 't-mm-05-009', 'text', 'LNG, NET and DSG POPs are taken continuously at 24-hour intervals without an HFI.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f61879f4', 't-mm-05-009', 'text', 'The new DRSP POP is taken in a regimen of 24 daily active pills followed by four hormone-free placebo pills (to establish a more predictable bleeding pattern)', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fa66ecd6', 't-mm-05-009', 'text', 'Use of all POPs taken between menarche and age 55 years.', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b2fa42ec', 't-mm-05-009', 'text', 'DRSP POP should also generally be avoided in:', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-567f967b', 't-mm-05-009', 'text', 'Severe renal insufficiency or acute renal failure.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-90cda7e7', 't-mm-05-009', 'text', 'Individuals with known hyperkaliemia or untreated hyperaldosteronism (e.g., Addison''s disease).', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cd8e1694', 't-mm-05-009', 'text', 'Individuals currently using potassium-sparing diuretics, aldosterone antagonists or potassium supplements.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d8aaaea0', 't-mm-05-009', 'text', 'DRSP POP used with caution by individuals with mild/moderate renal impairment or treated hyperaldosteronism (e.g., treated Addison''s disease)', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fe190a81', 't-mm-05-009', 'text', 'Individuals with significant risk factors for chronic kidney disease: measurement of urea & electrolytes (U&E) and blood pressure considered prior to prescription of the DRSP POP, particularly if age over 50 years', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a7956f19', 't-mm-05-009', 'text', 'Side effects: Change in bleeding pattern over a 3-month period ending at about 12 months of use (at around 6—9 months of use with DRSP POP)', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66154b37', 't-mm-05-009', 'text', 'Interactions: contraceptive effectiveness of all POPs could be reduced during use of the enzyme-inducer and for 28 days after stopping the enzyme-inducer.', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f493be10', 't-mm-05-009', 'text', 'Ability of UPA-EC as an EC can be reduced if a POP has been taken in the preceding 7 days or within 5 days of taking the UPA. Offer them DMPA. the Cu-lUD or the LNG-IUS', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9f417020', 't-mm-05-009', 'text', 'Interactions between DRSP POP and drugs such as ACEi and ARBs could also potentially increase risk of hyperkaliemia', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8f54c3be', 't-mm-05-009', 'text', 'Non-contraceptive benefits:', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0dd35203', 't-mm-05-009', 'text', 'DSG and DRSP POP could reduce dysmenorrhea for some users', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0389222e', 't-mm-05-009', 'text', 'DRSP POP might theoretically offer benefit for acne or hirsutism', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c8feaa3e', 't-mm-05-009', 'text', 'Induction of withdrawal bleeding is not required in individuals with PCOS during use of a POP even if they are amenorrhea.', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-843ced91', 't-mm-05-009', 'text', 'AC: additional contraception like barrier or abstinence', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aafffcc2', 't-mm-05-009', 'text', 'DRSP POP is started on day 1 of a natural menstrual cycle, day 1 after abortion or by day 21 after childbirth. If started at any other time, quick start+ AC for 7 days+ consider EC and follow-up pregnancy test', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-627dec7c', 't-mm-05-009', 'text', 'LNG, NET and DSG POPs can be started on days 1—5 of a natural menstrual cycle, by day 5 after abortion or by day 21 after childbirth. At any other time. quick start +AC for 2 days+ consider EC and follow-up pregnancy test if required.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-64126f88', 't-mm-05-009', 'text', '(UPSI from the time that the first pill was missed until correct pill taking had resumed for 48 hours)', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8e24ec2d', 't-mm-05-009', 'text', 'DRSP POP if taken 24hrs late recent pill + next pill at usual time+ AC for 7days+ consider EC', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c5d1717b', 't-mm-05-009', 'text', '(OMIT THE HFI (PLACEBO PILLS) IF ANY OF THE LAST 7 ACTIVE PILLS ARE MISSED)', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-86a6a0cb', 't-mm-05-009', 'text', 'Vomiting after the progestogen-only pill is taken', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d0ef3dbb', 't-mm-05-009', 'html', '<table><tbody><tr><td>Type of POP</td><td>Manufacturer-recommended time after pill-taking until unaffected by<br/>vomiting</td></tr><tr><td>DRSP POP</td><td>3-4 hours</td></tr><tr><td>LNG traditional POP</td><td>2 hours</td></tr><tr><td>NET traditional POP</td><td>Not stated. GDG su est 2 hours as above</td></tr><tr><td>DSG POP</td><td>hours</td></tr></tbody></table>', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5ab0e4e2', 't-mm-05-009', 'text', 'POPs are taken daily with no pill-free interval.', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2bb5d97f', 't-mm-05-009', 'text', 'taken at or around the same POPs currently available in the UK contain either NET 350 pg (Micronor, Noriday), LNG 30 pg (Norgeston@) or DSG 75 pg (Cerazetto)', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-405899dd', 't-mm-05-009', 'text', 'Mode of action:', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6f290e10', 't-mm-05-009', 'text', 'POPs increase volume & viscosity of cervical mucus preventing sperm penetration into upper reproductive tract. Can also act to suppress ovulation.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4f6e174f', 't-mm-05-009', 'text', 'Efficacy:', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4d241fae', 't-mm-05-009', 'text', 'If used consistently and correctly, POPs are more than 99% effective.', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4b732a4a', 't-mm-05-009', 'text', 'Drug interactions:', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1840e09b', 't-mm-05-009', 'text', 'POP users taking enzyme-inducing drugs should be advised to switch to the progestogen-only injectable or intrauterine contraception.', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-54054196', 't-mm-05-009', 'text', 'For short durations of enzyme-inducing treatment (<2 months) women can continue the POP providing they use additional precautions', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e245d649', 't-mm-05-009', 'text', 'Women wishing to start the POP after stopping enzyme-inducing drugs should be advised dafter the last dose of enzyme-inducing drug.', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cba213a3', 't-mm-05-009', 'text', 'Missed Pill Guideline:', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-02615c63', 't-mm-05-009', 'text', 'TRADITIONAL POPS                     DESOGESTREL POPS', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-440477ed', 't-mm-05-009', 'text', '> 3 hours late >12 hours late', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a2b7acff', 't-mm-05-009', 'text', '(>27 hours since the last pill was taken) (>36 hours since the last pill was taken)', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d24259df', 't-mm-05-009', 'text', 'The missed pill should be taken as soon as remembered. If more than one pill has been missed, only one pill should be taken.', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-107a768e', 't-mm-05-009', 'text', 'The next pill should be taken at the usual time. This may mean that two pills are taken in 1 day.', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4de4827b', 't-mm-05-009', 'text', 'Additional contraceptive precautions (condoms or avoidance of sex) are advised for 2 days (48 hours) after restarting the POP.', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fa6e24c6', 't-mm-05-009', 'text', 'Emergency contraception is indicated if unprotected sexual intercourse occurred after the missed pill and within 48 hours of restarting the POP.', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c526a36f', 't-mm-05-009', 'text', 'Raised BMI and POP:', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1db1feb6', 't-mm-05-009', 'text', 'NO increased risk of pregnancy in POP users with a heavier body weight or a higher BMI and insufficient evidence to support a dose of more than one pill per day in women who are heavy or overweight.', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5770ff6d', 't-mm-05-009', 'text', 'Non-contraceptive benefits:', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-40aebbcc', 't-mm-05-009', 'text', 'Dysmenorrhea: DSG', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7a1a45aa', 't-mm-05-009', 'text', 'Ectopic pregnancy: While the overall risk of pregnancy is reduced with use of traditional POPs, around 1 in 10 pregnancies that do occur may be ectopic.', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4761c568', 't-mm-05-009', 'text', 'Headaches and Ovarian cysts/persistent ovarian follicles: No good evidence was identified.', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-54db2d74', 't-mm-05-009', 'text', 'Return of fertility: There is no evidence suggesting a delay in return of fertility following discontinuation of a POP; therefore, if pregnancy is not desired, other contraceptive methods should be used immediately following discontinuation of the POP.', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d408bde3', 't-mm-05-009', 'text', 'Side effects:', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-64a92ed4', 't-mm-05-009', 'text', 'Bleeding: Changes in bleeding patterns associated with the POP are common.', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7b43e27f', 't-mm-05-009', 'text', 'Libido: Effects of POP on libido are lacking and therefore a possible effect cannot be excluded.', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8ba8e1ed', 't-mm-05-009', 'text', 'Weight change: Evidence does not support a casual association between POP use and weight change.', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1d3c7135', 't-mm-05-009', 'text', 'Women may be given up to a 12-month supply of POPs at their first and follow-up visits and advised to return at any time if problems arise.', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cff269c0', 't-mm-05-009', 'text', 'The POP can be used until the age of 55 years when natural loss of fertility can be assumed for most women.', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-801d4a1e', 't-mm-05-009', 'text', 'If they are aged > 50 years and amenorrhea they can continue using a POP and have FSH concentrations tested on two occasions 6 weeks apart. If both FSH measurements are >30 IU/I this is', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-284dff62', 't-mm-05-009', 'text', 'suggestive of ovarian failure and they should continue with a POP or barrier method for one further year.''', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a24fef10', 't-mm-05-009', 'text', 'Recommendations following incorrect progestogen-only pill use', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a913b31d', 't-mm-05-009', 'html', '<table><tbody><tr><td></td><td>Traditional POP</td><td>DSG POP</td><td>DRSP POP</td></tr><tr><td>When is a pill missed?</td><td>A pill is missed if taken 3 hours late (27 hours after last pill taken)</td><td>A pill is missed if taken 12 hours last (36 hours after les pill</td><td>A pill is missed if taken 24 hours late 48 hours after last pill was taken or 24 hours after a new packet should have been started after an HFI</td></tr><tr><td>Action if pill(s) missed</td><td>Take the most recent missed pill as soon as possible<br/>Take the next pill at the usual time (this may mean taking two pills in 1 day)<br/>Use additional contraceptive precautions (eg, condoms) for 48 hours after correct pill-taking has restarted<br/>Consider EC</td><td></td><td>Take the most recent missed pill as soon as possible<br/>Take the next bill at the usual time (this may mean taking two pills in 1 day)<br/>Use additional contraceptive precautions (eg, condoms) for 7 days after correct pill-taking has restarted<br/>Consider EC<br/>OMIT THE HFI (PLACEBO PILLS) IF ANY OF THE LAST 7 ACTIVE PILLS ARE MISSED</td></tr><tr><td>Is EC required?</td><td>EC should be considered if there was UPSI from the site that the first pill was missed until correct pill taking had resumed for 48 hours</td><td></td><td>EC should be considered if<br/>Any active pill(s) were missed and there was UPSI from the time that the first pill was missed until correct pill-taking had resumed for 7 days<br/>Pills were missed on days 1-7 of the packet and there was UPSI during the HFI or week 1</td></tr><tr><td>Follow-up</td><td>Consider pregnancy test 21 days after last UPSI</td><td></td><td></td></tr></tbody></table>', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c335ea26', 't-mm-05-009', 'text', 'Table 21. Recommendations following incorrect progestogen-only pill use', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-05-010', 'chap-mm-05-01', '11. PROGESTOGEN-ONLY INJECTABLE CONTRACEPTION', 'Detailed medical reference and study guide on 11. PROGESTOGEN-ONLY INJECTABLE CONTRACEPTION.', 10, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6fa5f634', 't-mm-05-010', 'text', '▪ Long-acting reversible contraceptives (LARCs) are those that are administered less frequently than once a month.', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ecab8395', 't-mm-05-010', 'text', 'DMPA (Depot Medroxyprogesterone Acetate) and NET-EN (Norethisterone Enanthate) are long-acting progestogens.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-34a4ef8d', 't-mm-05-010', 'text', 'DMPA:', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5cbb0242', 't-mm-05-010', 'text', 'Administered via intramuscular (IM) injection:', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6448630a', 't-mm-05-010', 'text', 'Depo-Provera: 150 mg medroxyprogesterone acetate in 1 ml.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cd7dc2c4', 't-mm-05-010', 'text', 'Also available as a subcutaneous (SC) injection:', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4cec4dbe', 't-mm-05-010', 'text', 'Sayana Press: 104 mg MPA in 0.65 ml', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5dc01d34', 't-mm-05-010', 'text', 'NET-EN:', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7edd980a', 't-mm-05-010', 'text', 'Less commonly used in the UK.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ba4ba408', 't-mm-05-010', 'text', 'Given as Noristerat®: 200 mg in 1 ml via IM injection.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-681c869e', 't-mm-05-010', 'text', 'Licensed for short-term use, such as:', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fda21d43', 't-mm-05-010', 'text', 'When a partner has undergone vasectomy (until successful vasectomy is confirmed).', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c60e23ac', 't-mm-05-010', 'text', 'After rubella immunization.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e9d277e2', 't-mm-05-010', 'text', 'The combined contraceptive injectable is not available in the UK.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66bbd51d', 't-mm-05-010', 'text', 'Mode of action: Progestogen-only injectable contraception works primarily by inhibiting ovulation. There is also an effect on cervical mucus, resulting in poor cervical mucus scores and limited sperm penetration.', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8a5892a8', 't-mm-05-010', 'text', 'Failure rate: When administered at the recommended dosing interval the failure rate of progestogen-only injectable contraception is approximately 0.2% in the first year of use.', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d5e61759', 't-mm-05-010', 'text', 'With typical use the failure rate is approximately 6%.', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9619e496', 't-mm-05-010', 'text', 'Non-contraceptive benefits:', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-31f8b7b0', 't-mm-05-010', 'text', 'Bleeding and dysmenorrhea:Amenorrhea or reduced bleeding is common in progestogen-only injectable users and may benefit women with menstrual problems. DMPA use may reduce pain associated with endometriosis. Women should be advised about changes in bleeding patterns.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-11de1e93', 't-mm-05-010', 'text', 'Ovarian and endometrial cancers:Use of DMPA is not associated with an increased risk of ovarian or endometrial cancer and may offer some protection.', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-09d7da0d', 't-mm-05-010', 'text', 'Sickle cell disease:DMPA is a contraceptive option for women with sickle cell disease and may reduce the severity of sickle crisis pain.', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5f875686', 't-mm-05-010', 'text', 'Health concerns', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4a726c01', 't-mm-05-010', 'text', 'Bone mineral density (BMD):Progestogen-only injectable use is associated with a small loss of BMD, which is usually recovered after discontinuation.', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-247c8c78', 't-mm-05-010', 'text', 'In women aged under 18 years, progestogen-only injectable contraception can be used after consideration of alternative methods.', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-633b1a01', 't-mm-05-010', 'text', 'Women are generally advised to switch to another method at age 50 years.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dabf355b', 't-mm-05-010', 'text', 'No DMPA before 18years and after 50 years', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-52ff4d7c', 't-mm-05-010', 'text', 'Breast cancer: There is a weak association between current use of DMPA and breast cancer. Any increased risk is likely to be small and reduce with time after stopping', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5a25c679', 't-mm-05-010', 'text', 'Cardiovascular health: A causal association between DMPA and venous thrombosis has not been demonstrated.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8300569c', 't-mm-05-010', 'text', 'Cervical cancer: There is a weak association between cervical cancer and use of DMPA for 5 years or longer. Any increased risk appears to reduce with time after stopping and could be due to confounding factors.', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b3df4827', 't-mm-05-010', 'text', 'Side effects:', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-79da17e2', 't-mm-05-010', 'text', 'Altered bleeding patterns and Weight gain: Use of DMPA appears to be associated with weight gain, particularly in women under 18 years of age with a BMI >30kg/m2.', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c217949b', 't-mm-05-010', 'text', 'Injection site reactions: Injection site reactions appear to be more common with use of SC DMPA than with use of IM DMPA.', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1bd6285f', 't-mm-05-010', 'text', 'Others Effects: Diffuse hair loss (alopecia), Headache, Mood change, Vasomotor symptoms,   Libido and sexual function,', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6f392ed8', 't-mm-05-010', 'text', 'Vaginitis: Whilst there is little evidence available to demonstrate causation, a number of possible side effects such as acne, decreased libido, mood swings, headache, hot flushes and vaginitis have been reported with use of DMPA.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-703709c6', 't-mm-05-010', 'text', 'Site of injection and period:', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7a66cd8b', 't-mm-05-010', 'text', 'The gluteal muscle is the preferred site for IM DMPA administration but it can be administered into the deltoid muscle of SC DMPA should be injected into the abdomen or anterior thigh.', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0adbd602', 't-mm-05-010', 'text', 'Women should be advised to return fora repeat injection of IM or SC DMPA (outside the product license for IM DMPA). An injection of DMPA can be administered up to 7 days late (up to 14 weeks after the last injection) without the need for additional contraceptive', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5a0732fb', 't-mm-05-010', 'text', 'precautions (outside the product license for IM DMPA).', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ee512a76', 't-mm-05-010', 'text', 'The efficacy of DMPA is not reduced with concurrent use of enzyme-inducing drugs.', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bb8e4f0b', 't-mm-05-010', 'text', 'No increased risk of pregnancy has been demonstrated in progestogen-only injectable users with higher body weight, although data are limited in women with a BMI >40 kg/m².', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6bf80530', 't-mm-05-010', 'text', 'Return of fertility:Women who discontinue their progestogen-only injectable and who do not wish to conceive should be advised to start another contraceptive method before or at the time of their next scheduled injection even if amenorrhoeic.', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b9fa9f2c', 't-mm-05-010', 'text', 'Women should be informed that there can be a delay of up to 1 year in the return of fertility after discontinuation of IM or SC DMPA.', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0b8c95e0', 't-mm-05-010', 'text', 'Sexually transmitted infections and testing:The consistent and correct use of condoms (male or female) can reduce the risk of STI transmission and should therefore be recommended as a risk-reduction strategy.', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9cb15369', 't-mm-05-010', 'text', 'Problematic bleeding:', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f4ee5aa5', 't-mm-05-010', 'text', 'Women who experience unscheduled bleeding during use of a progestogen-only injectable and who are medically eligible can be offered a COC for 3 months.', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-68a90a6c', 't-mm-05-010', 'text', 'Women with unscheduled bleeding during use of a progestogen-only injectable contraceptive can be offered 500 mg mefenamic acid up to three times daily for 5 days.', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-05-011', 'chap-mm-05-01', '12. PROGESTOGEN-ONLY IMPLANT', 'Detailed medical reference and study guide on 12. PROGESTOGEN-ONLY IMPLANT.', 11, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-196e4be9', 't-mm-05-011', 'text', 'The ENG-IMP is currently the only progestogen-only contraceptive subdermal implant available in the UK.', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e92faccb', 't-mm-05-011', 'text', 'The ENG-IMP is a highly effective long-acting reversible method of contraception.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7a1d8b09', 't-mm-05-011', 'text', 'Licensed for 3 years of use for contraception.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a86d2c6c', 't-mm-05-011', 'text', 'Effectiveness:', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d595481e', 't-mm-05-011', 'text', 'The first-year contraceptive failure rate for the ENG-IMP has been estimated at 0.05%.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb8d7618', 't-mm-05-011', 'text', 'Routine use of the ENG-IMP for longer than 3 years is not currently recommended.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ab0e0654', 't-mm-05-011', 'text', 'Drugs Interactions:', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-83d4337f', 't-mm-05-011', 'text', 'Women using enzyme-inducing drugs should be informed that the contraceptive effectiveness of the ENG-IMP could be reduced during use of the enzyme-inducer and for 28 days after stopping the enzyme-inducer.', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9f045d1c', 't-mm-05-011', 'text', 'Women using enzyme-inducing drugs should be offered a reliable contraceptive method that is unaffected by enzyme-inducers.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-41706bab', 't-mm-05-011', 'text', 'Weight/BMI', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-990b2195', 't-mm-05-011', 'text', 'The available evidence suggests that contraceptive effectiveness of ENG is not affected by body weight or BMI', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ba037e6d', 't-mm-05-011', 'text', 'Ulipristal acetate (UPA):', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4f773c93', 't-mm-05-011', 'text', 'The ability of UPA-EC to delay ovulation could be reduced if an ENG-IMP is inserted within 5 days of taking the UPA.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5b82ff02', 't-mm-05-011', 'text', 'The ability of UPA-EC to delay ovulation could theoretically be reduced if a woman has an ENG-IMP in situ (even if it has been in situ for longer than 3 years).', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3db18cb5', 't-mm-05-011', 'text', 'Individuals should be advised to wait 5 days after taking UPA-EC before insertion of the ENG-IMP.', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-effbfa1d', 't-mm-05-011', 'text', 'They should be made aware that they must use condoms reliably or abstain from sex during the 5 days waiting and then for 7 days after implant insertion.', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4d14c40d', 't-mm-05-011', 'text', 'Suitability of the etonogestrel implant:', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dd2e05e3', 't-mm-05-011', 'text', 'Breast cancer, arterial thromboembolism, decompensated cirrhosis, hepatocellular tumors and unexplained vaginal bleeding are UKMEC 3 or 4', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-60f69a82', 't-mm-05-011', 'text', 'Medical conditions that are UKMEC3 or UKMEC4 for use of the etonogestrel subdermal implant', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb29d78b', 't-mm-05-011', 'html', '<table><tbody><tr><td>Condition</td><td>UKMEC category for use of etonogestrel subdermal implant</td></tr><tr><td>Current and history of ischemic heart disease</td><td>UKMEC3 for continuation (UKMEC2 for initiation)</td></tr><tr><td>History of stroke</td><td>UKMEC3 for continuation (UKMEC2 for initiation)</td></tr><tr><td>Unexplained vaginal bleeding (before evaluation)</td><td>UKMEC3</td></tr><tr><td>Current breast cancer</td><td>UKMEC4</td></tr><tr><td>Past breast cancer</td><td>UKMEC3</td></tr><tr><td>Severe (decompensated) cirrhosis</td><td>UKMEC3</td></tr><tr><td>Hepatocellular adenoma or carcinoma</td><td>UKMEC3</td></tr></tbody></table>', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c9c66437', 't-mm-05-011', 'text', 'Dysmenorrhea', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8ff322b5', 't-mm-05-011', 'text', 'Heavy menstrual bleeding', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-94b65d21', 't-mm-05-011', 'text', 'Endometriosis: Limited available evidence suggests that use of the ENG-IMP could be associated with improvement in endometriosis- associated pain', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7b32dfa8', 't-mm-05-011', 'text', 'Endometrial protection in polycystic ovary syndrome: Induction of withdrawal bleeding is not required in ENG-IMP users with polycystic', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fa43fa50', 't-mm-05-011', 'text', 'ovary syndrome who are amenorrhoeic during the licensed duration of use of the ENG-IMP', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-33a46166', 't-mm-05-011', 'text', 'Risk of adverse health events', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-51a442bd', 't-mm-05-011', 'text', 'Venous and arterial thromboembolism:Evidence suggests no significant increase in risk of venous or arterial thromboembolic events associated with current use of the ENG-IMP.', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-08d26cca', 't-mm-05-011', 'text', 'Osteoporosis:Evidence is too limited to confirm or exclude an association between ENG-IMP use and reduction in bone mineral density (BMD).', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f93b8c04', 't-mm-05-011', 'text', 'Breast cancer:No significant increase in risk of breast cancer associated with ENG-IMP use but is too limited to completely exclude an association.', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b315ff33', 't-mm-05-011', 'text', 'Gynecological cancer:The available evidence is too limited to inform whether an association exists between use of the ENG-IMP and risk of ovarian, endometrial, or cervical cancer.', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dba5a647', 't-mm-05-011', 'text', 'Ectopic pregnancy:Risk of ectopic pregnancy during use of the ENG-IMP is extremely small.', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a9a5f964', 't-mm-05-011', 'text', 'Side Effects', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-39b4d322', 't-mm-05-011', 'text', 'Irregular, unpredictable bleeding is common during use of the ENG-IMP.', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c5a0c19d', 't-mm-05-011', 'text', 'Bleeding pattern may change at any time during use of an ENG-IMP.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-710e4fa5', 't-mm-05-011', 'text', 'Individuals with ‘unfavorable’ bleeding patterns in the first few months after ENG-IMP insertion may have about a 50% chance that bleeding will improve over time.', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0b5094bc', 't-mm-05-011', 'text', 'Endometrial protection in polycystic ovary syndrome:Induction of withdrawal bleeding is not required in ENG-IMP users with polycystic ovary syndrome who are amenorrhoeic during licensed duration of use of ENG-IMP.', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ae5d1ea2', 't-mm-05-011', 'note', 'Note:After exclusion of other causes of bleeding, ENG-IMP users with problematic bleeding who are medically eligible can be offered a 3-', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-58eedae1', 't-mm-05-011', 'text', 'month trial of additional use of COC or a 5-day course of mefenamic acid.', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4f608766', 't-mm-05-011', 'text', 'Side Effects', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a492677f', 't-mm-05-011', 'text', 'Headache: Headache is commonly reported during ENG-IMP use; but limited evidence.', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-98796f9f', 't-mm-05-011', 'text', 'Acne: Observational studies suggest that during ENG-IMP use a minority of users experience new onset acne or worsening of existing acne while others have improvement in existing acne.', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-952bc0f9', 't-mm-05-011', 'text', 'Depression: The available evidence is too limited to confirm or exclude a causative association between ENG-IMP use and depression.', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3f913a27', 't-mm-05-011', 'text', 'Weight change: The available evidence is too limited to confirm or exclude a causal association between ENG-IMP use and weight gain.', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2e0b9664', 't-mm-05-011', 'text', 'Other side effects: Mastalgia (10.2% of women), abdominal pain (5.2%), dizziness (4.9%), emotional lability (5.7%), nervousness (3.5%) and nausea (2.5%).', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-01e4f666', 't-mm-05-011', 'text', 'Risk of adverse health events', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a16041c0', 't-mm-05-011', 'text', 'Venous and arterial thromboembolism: evidence suggests no significant increase in risk of venous or arterial thromboembolic events associated with current use of the ENG-IMP.', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-416babb1', 't-mm-05-011', 'text', 'Osteoporosis: evidence is too limited to confirm or exclude an association between ENG-IMP use and reduction in BMD.', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-82160baf', 't-mm-05-011', 'text', 'Breast cancer: no significant increase in risk of breast cancer associated with ENG-IMP use but is too limited to completely exclude an association.', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-369625d9', 't-mm-05-011', 'text', 'Gynecological cancer: The available evidence is too limited to inform whether an association between use of the ENG-IMP and risk of ovarian, endometrial or cervical cancer.', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1fe22dd3', 't-mm-05-011', 'text', 'Ectopic pregnancy: risk of ectopic pregnancy during use of the ENG-IMP is extremely small.', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ec6c60e6', 't-mm-05-011', 'text', 'Points to cover in the clinical history from an etonogestrel implant user who presents with problematic bleeding', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a101e157', 't-mm-05-011', 'text', 'Clinical history taking should include assessment of:', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b7de8086', 't-mm-05-011', 'text', 'The individual''s own concerns (a particular bleeding pattern may be acceptable to one user, but not to another)', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a5b77678', 't-mm-05-011', 'text', 'Duration of use of the etonogestrel implant (ENG-IMP)', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ba1e9697', 't-mm-05-011', 'text', 'Use of any medications (including over-the-counter preparations) which may interact with the ENG-IMP', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d064db3f', 't-mm-05-011', 'text', 'Cervical screening history', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fbcc06e2', 't-mm-05-011', 'text', 'Risk of sexually transmitted infections (highest risk in those aged <25 years, or at any age with a new partner, or more than one partner in the last year, but consider testing for all those with problematic bleeding)', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6d47b662', 't-mm-05-011', 'text', 'Bleeding pattern before starting hormonal contraception, since starting and currently', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0eab0635', 't-mm-05-011', 'text', 'Other symptoms suggestive of an underlying cause (for example, abdominal or pelvic pain, postcoital bleeding, dyspareunia, heavy menstrual bleeding)', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cf6c1061', 't-mm-05-011', 'text', 'Possibility of pregnancy.', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-845d63ac', 't-mm-05-011', 'text', 'Time of Insertion:', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4b0989b6', 't-mm-05-011', 'text', 'The ENG-IMP can be inserted on days 1–5 of a natural menstrual cycle, by day 5 after abortion, or by day 21 after childbirth without requirement for additional contraceptive precautions.', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f5d5b1cf', 't-mm-05-011', 'text', 'Endometrial protection in polycystic ovary syndrome:Induction of withdrawal bleeding is not required in ENG-IMP users with polycystic ovary syndrome who are amenorrhoeic during licensed duration of use of ENG-IMP.', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d825261f', 't-mm-05-011', 'note', 'Note:After exclusion of other causes of bleeding, ENG-IMP users with problematic bleeding who are medically eligible can be offered a 3-month trial of additional use of COC or a 5-day course of mefenamic acid.', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9f144b86', 't-mm-05-011', 'text', 'Side Effects', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9133888c', 't-mm-05-011', 'text', 'Headache: Headache is commonly reported during ENG-IMP use; but limited evidence.', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c1de5aa8', 't-mm-05-011', 'text', 'Acne: Observational studies suggest that during ENG-IMP use a minority of users experience new onset acne or worsening of existing acne while others have improvement in existing acne.', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2dbc1430', 't-mm-05-011', 'text', 'Depression: The available evidence is too limited to confirm or exclude a causative association between ENG-IMP use and depression.', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-368c0ce7', 't-mm-05-011', 'text', 'Weight change: The available evidence is too limited to confirm or exclude a causal association between ENG-IMP use and weight gain.', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f973f0cb', 't-mm-05-011', 'text', 'Other side effects: Mastalgia (10.2% of women), abdominal pain (5.2%), dizziness (4.9%), emotional lability (5.7%), nervousness (3.5%) and nausea (2.5%).', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6fb87157', 't-mm-05-011', 'text', 'Risk of adverse health events', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bea36412', 't-mm-05-011', 'text', 'Venous and arterial thromboembolism: evidence suggests no significant increase in risk of venous or arterial thromboembolic events associated with current use of the ENG-IMP.', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-45fb44ed', 't-mm-05-011', 'text', 'Osteoporosis: evidence is too limited to confirm or exclude an association between ENG-IMP use and reduction in BMD.', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-76cb49db', 't-mm-05-011', 'text', 'Breast cancer: no significant increase in risk of breast cancer associated with ENG-IMP use but is too limited to completely exclude an association.', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-84b98975', 't-mm-05-011', 'text', 'Gynecological cancer: The available evidence is too limited to inform whether an association between use of the ENG-IMP and risk of ovarian, endometrial or cervical cancer.', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-75648021', 't-mm-05-011', 'text', 'Ectopic pregnancy: risk of ectopic pregnancy during use of the ENG-IMP is extremely small.', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fd7a864b', 't-mm-05-011', 'text', 'Points to cover in the clinical history from an etonogestrel implant user who presents with problematic bleeding', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-578d91ed', 't-mm-05-011', 'text', 'Clinical history taking should include assessment of:', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5955b3c0', 't-mm-05-011', 'text', 'The individual''s own concerns (a particular bleeding pattern may be acceptable to one user, but not to another)', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8eb2dd3b', 't-mm-05-011', 'text', 'Duration of use of the etonogestrel implant (ENG-IMP)', 80) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3cf9edcb', 't-mm-05-011', 'text', 'Use of any medications (including over-the-counter preparations) which may interact with the ENG-IMP', 81) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-42493005', 't-mm-05-011', 'text', 'Cervical screening history', 82) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3e70136b', 't-mm-05-011', 'text', 'Risk of sexually transmitted infections (highest risk in those aged <25 years, or at any age with a new partner, or more than one partner in the last year, but consider testing for all those with problematic bleeding)', 83) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6b13f7f9', 't-mm-05-011', 'text', 'Bleeding pattern before starting hormonal contraception, since starting and currently', 84) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3827d1f0', 't-mm-05-011', 'text', 'Other symptoms suggestive of an underlying cause (for example, abdominal or pelvic pain, postcoital bleeding, dyspareunia, heavy menstrual bleeding)', 85) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f97d551a', 't-mm-05-011', 'text', 'Possibility of pregnancy.', 86) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-97bee296', 't-mm-05-011', 'text', 'Time of Insertion:', 87) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5d5b0e1d', 't-mm-05-011', 'text', 'The ENG-IMP can be inserted on days 1–5 of a natural menstrual cycle, by day 5 after abortion, or by day 21 after childbirth without requirement for additional contraceptive precautions.', 88) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-22f7b7a1', 't-mm-05-011', 'text', 'At any other time, the ENG-IMP can be quick started according to Quick Starting Guidance, with advice to use additional contraceptive precautions for 7 days and to take a follow-up pregnancy test (if required).', 89) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-05-012', 'chap-mm-05-01', '13. EMERGENCY CONTRACEPTION', 'Detailed medical reference and study guide on 13. EMERGENCY CONTRACEPTION.', 12, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-796c9213', 't-mm-05-012', 'heading', '14. DRUG INTERACTION WITH HORMONAL CONTRACEPTION', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1cf5a49f', 't-mm-05-012', 'text', 'Indication: Women who do not wish to conceive should be offered EC after UPSI that has taken place on any day of a natural menstrual cycle.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-25dc8c0f', 't-mm-05-012', 'text', 'After pregnancy: Women who do not wish to conceive should be offered EC after:', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-88bcdf4a', 't-mm-05-012', 'text', 'UPSI from Day 21 after childbirth', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3265bdf2', 't-mm-05-012', 'text', 'UPSI from Day 5 after abortion, miscarriage, ectopic pregnancy or uterine evacuation for gestational trophoblastic disease (GTD).', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2f3ebf84', 't-mm-05-012', 'text', 'Hormonal contraception incorrectly: Women who do not wish to conceive should be offered EC after UPSI if their regular contraception has been compromised or has been used incorrectly', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cc74b333', 't-mm-05-012', 'text', 'There are 3 methods of EC:', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b37f426f', 't-mm-05-012', 'text', 'CU – IUD', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb930478', 't-mm-05-012', 'text', 'UPA – EC', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2ac8426c', 't-mm-05-012', 'text', 'LNG – ECG', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a2cf2d74', 't-mm-05-012', 'text', 'Mode of action:', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5f572966', 't-mm-05-012', 'text', 'Sperm are viable in the female genital tract for about 5 days after UPSI. If ovulation occurs within those 5 days, fertilization could take place and a woman is at risk of pregnancy.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-70f91927', 't-mm-05-012', 'text', 'Cu-lUD: Inhibition of fertilization by its toxic effect on sperm and ova. Copper has been shown to adversely affect the motility and viability of sperm and the viability and transport of ova. It is the most effective method of EC', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ce640e4a', 't-mm-05-012', 'text', 'UPA: UPA 30 mg – a selective progesterone receptor modulator – acts by delaying ovulation for at least 5 days, until sperm from the UPSI for which EC was taken are no longer viable.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-03c1b4c9', 't-mm-05-012', 'text', 'LNG: LNG-EC inhibits ovulation, delaying or preventing follicular rupture and causing luteal dysfunction.', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-546bdcb9', 't-mm-05-012', 'text', 'Oral EC', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-35580dac', 't-mm-05-012', 'text', 'EC providers should advise women that UPA-EC has been demonstrated to be effective for EC up to 120 hours of UPSI', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-569ca8d0', 't-mm-05-012', 'text', 'LNG-EC is licensed for EC up to 72 hours after UPSI. The evidence suggests that LNG-EC is ineffective if taken more than 96 hours after UPSI.', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-993b9ea5', 't-mm-05-012', 'text', 'UPA-EC has been demonstrated to be more effective than LNG-EC.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5fcc6036', 't-mm-05-012', 'text', 'Oral EC administered after ovulation is ineffective', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b48f315b', 't-mm-05-012', 'text', 'Effect of Weight/BMI:', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e07311cb', 't-mm-05-012', 'text', 'Cu-IUD: Effectiveness of the Cu-IUD is not known to be affected by weight or BMI.', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-99c5617b', 't-mm-05-012', 'text', 'Oral EC: It is possible that higher weight or BMI could reduce the effectiveness of oral EC, particularly LNG-EC.', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-34e2bd6e', 't-mm-05-012', 'text', 'Table 22. Methods of emergency contraception in UK:', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4e639de6', 't-mm-05-012', 'html', '<table><tbody><tr><td>Method</td><td>Class</td><td>Recommended dose/use</td><td>Indications</td></tr><tr><td>Copper intrauterine device (Cu-IUD)</td><td>Intrauterine contraceptive method</td><td>IUD retained until pregnancy excluded (e.g., onset of next menstrual period) or can be kept for ongoing contraception</td><td>Within 5 days (120 hours) after the first UPSI in a cycle or within 5 days after the earliest estimated date of ovulation</td></tr><tr><td>Levonorgestrel EC (LNG-EC)</td><td>Progestogen</td><td>1.5 mg single oral dose*</td><td>Licensed for use within 72 hours after UPSI or contraceptive failure</td></tr><tr><td>Ulipristal acetate EC (UPA-EC)</td><td>Progesterone receptor modulator</td><td>30 mg single oral dose</td><td>Licensed for use within 5 days (120 hours) after UPSI or contraceptive failure</td></tr></tbody></table>', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96f6891e', 't-mm-05-012', 'text', 'Consideration before offering EC:', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2847c1d7', 't-mm-05-012', 'text', 'Hours passed from UPSI', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-55e6e842', 't-mm-05-012', 'text', 'Date of M/C', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fbc062a3', 't-mm-05-012', 'text', 'R/O Contraindications of EC', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c7a03a51', 't-mm-05-012', 'text', 'If LNG, double check indications of Double Dose (3 mg vs 1.5 mg)', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3a514f85', 't-mm-05-012', 'text', 'Double dose of LNG – EC is given in:', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-951c6892', 't-mm-05-012', 'text', 'Wt >70 kg', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-19de7c9c', 't-mm-05-012', 'text', 'BMI >26', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-61315724', 't-mm-05-012', 'text', 'Taking enzyme inducing drugs', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a40a3a32', 't-mm-05-012', 'text', 'Inducers of hepatic CYP450 enzymes:', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-71db8039', 't-mm-05-012', 'text', 'EC providers should advise women using enzyme-inducing drugs that the effectiveness of UPA-EC and LNG-EC could be reduced.', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-db818c60', 't-mm-05-012', 'text', 'Women requiring EC who are using enzyme-inducing drugs should be offered a Cu-IUD if appropriate.A 3 mg dose of LNG can be considered but women should be informed that the effectiveness of this regimen is unknown.', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-49b8e035', 't-mm-05-012', 'text', 'A double-dose of UPA-EC is not recommended', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-da8a7953', 't-mm-05-012', 'text', '▪ Progestogens: EC providers should be aware that the effectiveness of UPA-EC could be reduced.', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9d206905', 't-mm-05-012', 'text', '▪ If a woman takes progestogen in the 5 days after taking UPA-EC, EC providers should be aware that the effectiveness of UPA-EC could theoretically be reduced if a woman has taken progestogen prior to taking UPA-EC.', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e10735d6', 't-mm-05-012', 'text', 'Contraindications/Restrictions to Use of EC:', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-20173160', 't-mm-05-012', 'text', 'Cu-IUD: EC providers should be aware that the contraindications to insertion of a Cu-IUD for EC are the same as those for routine IUD insertion.', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b808d54a', 't-mm-05-012', 'text', 'UPA-EC: EC providers should be aware that UPA-EC is not suitable for use by women who have severe asthma controlled by oral glucocorticoids.', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-033198c0', 't-mm-05-012', 'text', 'Breastfeeding and Require EC:', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-954e617b', 't-mm-05-012', 'text', 'Cu-IUD: Breastfeeding women have a higher relative risk of uterine perforation during insertion of intrauterine contraception than non-breastfeeding women. However, absolute risk of perforation is low.', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fd351058', 't-mm-05-012', 'text', 'UPA-EC: Breastfeeding women should be advised not to breastfeed and to express & discard milk for a week after they have taken UPA-EC.', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6807a1cc', 't-mm-05-012', 'text', 'LNG-EC: Women who breastfeed should be informed that available limited evidence indicates that LNG-EC has no adverse effects on breastfeeding or on their infants.', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7089df20', 't-mm-05-012', 'text', 'Method of EC:', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4187384a', 't-mm-05-012', 'text', 'All women requiring EC should be offered a Cu-lUD if appropriate as', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cb6c9091', 't-mm-05-012', 'text', 'it is the most effective method of EC. Cu-IUD can be inserted up to 5 days after the first UPSI in a natural menstrual cycle, or up to 5 days after the earliest likely date of ovulation (whichever is later).', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b3b50c0d', 't-mm-05-012', 'text', 'a Cu-IUD is not appropriate or not acceptable; women should be advised that oral EC should be taken as soon as possible if there has been UPSI within the last 5 days', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e9569f45', 't-mm-05-012', 'text', 'EC providers should consider! UPA-EC as the first-line oral EC for a woman who has had UPSI 96-120 hours ago (even if she has also had UPSI within the last 96 hours).', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9953c469', 't-mm-05-012', 'text', 'Sexual assault: Women requiring EC after sexual assault should be offered all methods of EC including the Cu-IUD.', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f62eaf9f', 't-mm-05-012', 'text', 'offer a woman UPA-EC or LNG-EC if she has had UPSI earlier in the same cycle as well as within the last 5 days, as evidence suggests that UPA- EC and LNG-EC do not disrupt an existing pregnancy and are not associated with fetal abnormality.', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-77a03814', 't-mm-05-012', 'text', 'If vomiting occurs within 3 hours of taking oral EC, a repeat dose should be given', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a6ac09b1', 't-mm-05-012', 'text', 'Time to contraceptive effectiveness when starting 120 hours after ulipristal acetate emergency contraception (UPA-EC)', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-228f922e', 't-mm-05-012', 'html', '<table><tbody><tr><td>Contraceptive method</td><td>Requirement for additional contraception after starting method</td></tr><tr><td>Combined oral contraceptive pill except Qlaira</td><td>7 days</td></tr><tr><td>Combined vaginal ring/transdermal patch</td><td>7 days</td></tr><tr><td>Progestogen-only pill (traditional/Desogestrel)</td><td>2 days</td></tr><tr><td>Progestogen-only implant or injectable</td><td>7 days</td></tr><tr><td>Qlaira</td><td>9 days</td></tr></tbody></table>', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-02e749a3', 't-mm-05-012', 'text', '🔹 Choosing between UPA-EC and LNG-EC', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-df0a5019', 't-mm-05-012', 'text', 'Ulipristal acetate EC (UPA-EC) has been demonstrated to be more effective than levonorgestrel.', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c57254e8', 't-mm-05-012', 'text', 'EC (LNG-EC) from 0–120 hours after UPSI. The evidence suggests that both UPA-EC and LNG-EC are ineffective if taken after ovulation.', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-527b8a1b', 't-mm-05-012', 'text', 'METHODS OF EC IN UK', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-466e73ca', 't-mm-05-012', 'text', 'Women requiring EC who are using enzyme-inducing drugs should be offered a Cu-IUD if appropriate.', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-996c4e79', 't-mm-05-012', 'text', 'A 3 mg dose of LNG can be considered but women should be informed that the effectiveness of this regimen is unknown. A double-dose of UPA-EC is NOT recommended.', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fd779c37', 't-mm-05-012', 'text', 'METHODS OF EC IN UK', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-30a82016', 't-mm-05-012', 'text', 'The effectiveness of UPA-EC could be reduced if a woman takes progestogen in the 5 days after taking UPA-EC.', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e9b76bf4', 't-mm-05-012', 'text', 'Effectiveness of UPA-EC could theoretically be reduced if a woman has taken progestogen in the 7 days prior to taking UPA-EC.', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-27a614c4', 't-mm-05-012', 'text', 'Avoid progestogen 7 days before and 5 days after taking UPA-EC.', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7b00bd2a', 't-mm-05-012', 'text', 'EMERGENCY CONTRACEPTION', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-02f4fcce', 't-mm-05-012', 'text', '✅ Adolescents who need EC should be offered all methods of EC including the Cu-IUD.', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-98cca620', 't-mm-05-012', 'text', '✅ Women requiring EC after sexual assault should be offered all methods of EC including the Cu-IUD.', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a6776f8f', 't-mm-05-012', 'text', 'Effectiveness of EC – methods:', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5d4bf77e', 't-mm-05-012', 'text', 'UPA ➜ 98% if taken within 120 hours', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-10a0b35e', 't-mm-05-012', 'text', 'LNG ➜ 85% in 72 hours then decreases to 56% in next 12 hours', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2b5c99d1', 't-mm-05-012', 'text', 'IUCD ➜ 99% effective', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-be9a725d', 't-mm-05-012', 'text', 'IMPORTANT tips before selection of EC', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-87dc6546', 't-mm-05-012', 'text', 'after day 19 ➜ use of IUCD if ovulation delayed', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-35d9af95', 't-mm-05-012', 'text', 'within day 14 ➜ prefer oral pills', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6e9573a6', 't-mm-05-012', 'text', 'LNG – UPSI → 72 hrs. (before midcycle)', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-af3486ac', 't-mm-05-012', 'text', 'UPA – UPSI → 120 hrs. (before midcycle <19 days)', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2514ee41', 't-mm-05-012', 'text', 'IUCD – UPSI → 120 hrs. (after midcycle even before midcycle)', 80) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c54e194d', 't-mm-05-012', 'text', 'always keep in mind contra-indications of each EC', 81) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-05-013', 'chap-mm-05-01', '14.DRUG INTERACTIONS WITH HORMONAL CONTRACEPTION', 'Detailed medical reference and study guide on 14.DRUG INTERACTIONS WITH HORMONAL CONTRACEPTION.', 13, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6859fb84', 't-mm-05-013', 'text', 'Enzyme inducers which may DECREASE contraceptive efficacy', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-584df9aa', 't-mm-05-013', 'text', 'Antiepileptics(e.g. carbamazepine, eslicarbazepine, fosphenytoin, oxcarbazepine, phenobarbital, phenytoin, primidone, rufinamide, topiramate)', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cd53baee', 't-mm-05-013', 'text', 'Antibacterials(e.g. rifabutin, rifampicin)', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-07ab4ccc', 't-mm-05-013', 'note', 'Antiretrovirals(e.g. efavirenz, nevirapine)Note: Ritonavir reduces the bioavailability of estrogen and may reduce the bioavailability of progestogens by inducing glucuronidation.', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5d1b352b', 't-mm-05-013', 'text', 'Antidepressants(e.g. St John’s wort – a herbal preparation)', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ebf53f3f', 't-mm-05-013', 'text', 'Others(e.g. modafinil, bosentan, aprepitant, lumacaftor)', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6a7fe113', 't-mm-05-013', 'text', 'Enzyme inhibiting drugs that may INCREASE hormone levels:', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aafcf7a5', 't-mm-05-013', 'text', 'Antibacterials (e.g. erythromycin)', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9c52e025', 't-mm-05-013', 'text', 'Antifungals (e.g. fluconazole, itraconazole, ketoconazole, posaconazole, voriconazole)', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a06b8fb3', 't-mm-05-013', 'text', 'Antiretrovirals (e.g. atazanavir)', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5e3dd5c0', 't-mm-05-013', 'text', 'Immunosuppressants (e.g. tacrolimus)', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bb479e00', 't-mm-05-013', 'text', 'Non-steroidal anti-inflammatories (NSAIDs) (e.g. etoricoxib)', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0737f5d0', 't-mm-05-013', 'text', 'Statins (e.g. atorvastatin, rosuvastatin)', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-99eea2da', 't-mm-05-013', 'text', 'Vasodilators (e.g. sitaxentan sodium)', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-75e1cef2', 't-mm-05-013', 'note', 'Note:', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0f97596b', 't-mm-05-013', 'text', 'Lamotrigine (antiepileptic) and griseofulvin (antifungal) are not thought to be enzyme-inducing drugs; however, contraceptive efficacy may still be reduced by concurrent use.The clinical significance of this effect is unknown', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d7324a7d', 't-mm-05-013', 'heading', 'Effects of contraceptive hormones on other drugs', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-20672572', 't-mm-05-013', 'text', 'Antiepileptics', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ad04da55', 't-mm-05-013', 'text', 'Combined hormonal contraception (CHC) moderately reduces lamotrigine exposure.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d0bee41d', 't-mm-05-013', 'text', 'This can lead to decreased seizure control during the hormone phase and increased lamotrigine exposure and toxicity risk in the hormone-free week.', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f5b84f8d', 't-mm-05-013', 'text', 'Desogestrel', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-339a479c', 't-mm-05-013', 'text', 'Might increase lamotrigine levels and adverse effects.', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6d370d7f', 't-mm-05-013', 'text', 'Ethinylestradiol (EE) may modestly reduce sodium valproate levels.', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aebae894', 't-mm-05-013', 'text', 'Progestogen receptor modulators', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-850a9e88', 't-mm-05-013', 'text', 'Quick starting hormonal contraception after ulipristal acetate (UPA) for emergency contraception (EC) may reduce EC effectiveness.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-260e4a16', 't-mm-05-013', 'text', 'Possible adverse effects and/or consider some monitoring', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-79e2b5a2', 't-mm-05-013', 'html', '<table><tbody><tr><td>Drug Class</td><td>Interaction</td></tr><tr><td>Antihypertensives</td><td>Estrogens may increase BP and antagonize antihypertensive efficacy.</td></tr><tr><td>Antidiabetics</td><td>Estrogens may antagonize the hypoglycemic effect of antidiabetics.</td></tr><tr><td>Anxiolytics & hypnotics</td><td>Estrogens and progestogens may reduce plasma concentrations of lorazepam, oxazepam, and temazepam.</td></tr><tr><td>Thyroid hormones</td><td>Estrogens may increase the requirements for thyroid hormones in hypothyroidism.</td></tr></tbody></table>', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-13d058a7', 't-mm-05-013', 'heading', 'Increased levels or adverse effects', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6f618f79', 't-mm-05-013', 'html', '<table><tbody><tr><td>Drug Class</td><td>Interaction Details</td></tr><tr><td>✅ Immunosuppressants</td><td>EE (Ethinylestradiol) might increase tacrolimus concentrations — should be monitored by a specialist. Ciclosporin levels may be increased by estrogens and progestogens.</td></tr><tr><td>✅ UPA (Ulipristal Acetate)</td><td>Predicted to increase everolimus and sirolimus concentrations.</td></tr><tr><td>✅ Dopaminergic</td><td>Selegiline levels may increase due to estrogens/progestogens → toxicity risk. EE reduces ropinirole clearance by ~one-third. Manufacturers advise avoiding concurrent use.</td></tr></tbody></table>', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6a5acb9d', 't-mm-05-013', 'heading', 'Possible adverse effects and/or consider some monitoring', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4e1ac774', 't-mm-05-013', 'html', '<table><tbody><tr><td>Drug Class</td><td>Interaction</td></tr><tr><td>Antifungals</td><td>Estrogens and progestogens may increase levels of voriconazole.</td></tr><tr><td>Anxiolytics & hypnotics</td><td>Estrogens and progestogens may increase plasma concentrations of chlordiazepoxide, diazepam, and clorazepate.</td></tr><tr><td>Bronchodilators</td><td>Estrogens slightly reduce the clearance of theophylline, leading to increased plasma concentrations. Reducing dosage is recommended if adverse effects occur.</td></tr><tr><td>Muscle relaxants</td><td>Estrogens and progestogens may increase tizanidine levels and its adverse effects.</td></tr></tbody></table>', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a2921201', 't-mm-05-013', 'heading', 'Possible adverse effects and/or consider some monitoring', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e98e9943', 't-mm-05-013', 'html', '<table><tbody><tr><td>Drug Class</td><td>Interaction</td></tr><tr><td>✅ Potassium-sparing diuretics and aldosterone antagonists</td><td>Additive hyperkaliemia or hypotension might occur with Drosperinone and potassium-sparing diuretics.</td></tr><tr><td>✅ Retinoids</td><td>Adverse effects of oral contraceptives on lipids may add to those of isotretinoin. As retinoids are teratogenic, highly effective contraception (e.g., IUDs or progestogen-only implants) is recommended.</td></tr><tr><td>✅ Triptans</td><td>COCs (Combined Oral Contraceptives) appear to slightly raise levels of frovatriptan, naratriptan, and zolmitriptan, though not clinically significant.</td></tr></tbody></table>', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9943f353', 't-mm-05-013', 'heading', 'Effect of Enzyme Inducers (during use and for 4 weeks after)', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-12a74f3c', 't-mm-05-013', 'html', '<table><tbody><tr><td>Drug Type</td><td>Impact of Enzyme Inducers</td><td>Action</td></tr><tr><td>CHC (Combined Hormonal Contraception)</td><td>❌ Known clinical interaction</td><td>Avoid use; advise alternative method</td></tr><tr><td>POP (Progestogen-only pill)</td><td>❓ Potential interaction</td><td>Caution required</td></tr><tr><td>IMP (Progestogen-only implant)</td><td>✅ No clinical interaction</td><td>Method suitable</td></tr><tr><td>DMPA (Depot medroxyprogesterone acetate)</td><td>✅ No clinical interaction</td><td>Method suitable</td></tr><tr><td>LNG-IUS (Levonorgestrel IUD)</td><td>✅ No clinical interaction</td><td>Method suitable</td></tr><tr><td>Cu-IUD (EC)</td><td>✅ No clinical interaction</td><td>Method suitable</td></tr><tr><td>LNG-EC (Levonorgestrel Emergency Contraception)</td><td>❓ Potential interaction</td><td>Caution required</td></tr><tr><td>UPA-EC (Ulipristal Acetate EC)</td><td>❌ Known clinical interaction</td><td>Avoid use; advise alternative method</td></tr><tr><td>Drug Type</td><td>CHC</td><td>POP</td><td>IMP</td><td>DMPA</td><td>LNG-IUS</td><td>Cu-IUD (EC)</td><td>LNG-EC</td><td>UPA-EC</td></tr><tr><td>Lamotrigine (non-enzyme inducer)</td><td>❓</td><td>❓</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Griseofulvin (non-enzyme inducer)</td><td>❌</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>❓</td></tr><tr><td>Drugs that alter gastric pH</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Drugs causing severe diarrhea/vomiting</td><td>❓</td><td>❓</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td>❓</td><td>❓</td></tr><tr><td>Progestogen receptor modulators (e.g., UPA)</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table>', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-05-014', 'chap-mm-05-01', '15. PROBLEMATIC BLEEDING WITH HORMONAL CONTRACEPTION', 'Detailed medical reference and study guide on 15. PROBLEMATIC BLEEDING WITH HORMONAL CONTRACEPTION.', 14, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dacb9a1d', 't-mm-05-014', 'heading', '16. BARRIER METHOD OF CONTRACEPTION', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d5c7a541', 't-mm-05-014', 'text', 'The management of women who present with problematic bleeding while using hormonal contraception is challenging.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f550b1d8', 't-mm-05-014', 'text', 'Before starting hormonal contraception, women should be advised about the bleeding patterns expected both initially and in the longer term.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6624c97d', 't-mm-05-014', 'text', 'A pregnancy test is indicated for sexually active women using hormonal contraception who have problematic bleeding', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e4251829', 't-mm-05-014', 'text', 'Clinically important bleeding patterns in women aged 15-44 years Scheduled bleedingMenstruation or regular withdrawal bleeding with combined hormonal contraception (CHC)Other bleeding patterns Frequent bleeding Infrequent bleeding Prolonged bleeding Spotting Breakthrough bleeding Amenorrhea More than five bleeding episodes within a reference periodFewer than three bleeding episodes within a reference periodBleeding episode lasting 14 days or moreVaginal discharge containing blood, that may not require the use of sanitary protectionUnscheduled bleeding in women using CHCNo bleeding or spotting days throughout the 90-day reference periodBleeding episode: one or more consecutive days of bleeding, bounded by bleed-free days. Reference period: a 90-day period of time during use of a hormonal contraceptive methodClinically important bleeding patterns in women aged 15-44 years Scheduled bleedingMenstruation or regular withdrawal bleeding with combined hormonal contraception (CHC)Other bleeding patterns Frequent bleeding Infrequent bleeding Prolonged bleeding Spotting Breakthrough bleeding Amenorrhea More than five bleeding episodes within a reference periodFewer than three bleeding episodes within a reference periodBleeding episode lasting 14 days or moreVaginal discharge containing blood, that may not require the use of sanitary protectionUnscheduled bleeding in women using CHCNo bleeding or spotting days throughout the 90-day reference periodBleeding episode: one or more consecutive days of bleeding, bounded by bleed-free days. Reference period: a 90-day period of time during use of a hormonal contraceptive method', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-452d027f', 't-mm-05-014', 'text', 'Points to cover in the clinical history from a woman using hormonal contraception who presents with problematic bleeding Clinical history taking should include an assessment of a woman''s Own concerns Current method of contraception and duration of use" Current method of contraception and duration of use" Compliance with the current contraceptive method Use of any medications (including over the counter preparations) which may interact with the contraceptive method illness/condition that may affect absorption of orally administered hormones Cervical screening history Risk of sexually transmitted infections (le. those aged <25 years, or at any age with a new partner, or more than one partner in the last year) Bleeding pattern before starting hormonal contraception, since starting and currently Other symptoms suggestive of an underlying cause (eg. abdominal or pelvic pain, postcoital bleeding, and dyspareunia. heavy menstrual bleeding) Possibility of pregnancy compliance with the current contraceptive method Points to cover in the clinical history from a woman using hormonal contraception who presents with problematic bleeding Clinical history taking should include an assessment of a woman''s Own concerns Current method of contraception and duration of use" Current method of contraception and duration of use" Compliance with the current contraceptive method Use of any medications (including over the counter preparations) which may interact with the contraceptive method illness/condition that may affect absorption of orally administered hormones Cervical screening history Risk of sexually transmitted infections (le. those aged <25 years, or at any age with a new partner, or more than one partner in the last year) Bleeding pattern before starting hormonal contraception, since starting and currently Other symptoms suggestive of an underlying cause (eg. abdominal or pelvic pain, postcoital bleeding, and dyspareunia. heavy menstrual bleeding) Possibility of pregnancy compliance with the current contraceptive method', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9273cdde', 't-mm-05-014', 'text', 'Table 23. Expected bleeding patterns after commencing hormonal contraception and in the longer term', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0cae2767', 't-mm-05-014', 'html', '<table><tbody><tr><td></td><td>Contraceptive method</td><td>Bleeding patterns in women in the first 3 months</td><td>Bleeding patterns in women in the longer term</td></tr><tr><td></td><td>Combined hormonal contraception (pill. patch or ring)</td><td>Up to 20% of COC users have irregular bleeding</td><td>Irregular bleeding usually settles<br/>No significant differences in bleeding between pill and patch use<br/>The combined vaginal ring may afford better cycle control (less unscheduled bleeding) when compared to the pill<br/>Users of estradiol COC have reported shorter, lighter bleeds and a higher rate of absent withdrawal bleeds than women using an EE-containing COC"</td></tr><tr><td></td><td>Progestogen-only pill</td><td>Bleeding is unpredictable<br/>With traditional POP one-third of women have a change in bleeding<br/>A comparative study of DSG ING POP reported that frequent bleeding, prolonged bleeding and infrequent bleeding were more common in DSG users than ING users in the first reference period of 90 days</td><td>Bleeding may not settle with time<br/>Traditional POP users can be advised that frequent and irregular bleeding are common, while prolonged bleeding and amenorrhea are less likely<br/>As a guide, women considering DSG-only POP can be advised that after 12 months of use over a 3-month period approximately:<br/>5 in 10 women can expect to be amenorrhoeic or have infrequent bleeding<br/>4 in 10 women can expect to have 3-5 bleeding spotting/episodes (regular)<br/>1 in 10 women can expect 26 bleeding/spotting episodes (frequent bleeding)<br/>2 in 10 women will experience bleeding/spotting episodes fasting for more than 14 days (prolonged</td></tr><tr><td></td><td>Progestogen-only injectable (IM and SC</td><td>Bleeding disturbances (spotting light, heavy or prolonged bleeding) are common. Around 1 in 10 women may be amenorrhoeic in the first 3 months of use</td><td>Rates of amenorrhea increase with duration of use and are similar form and SC DMPA, around 50% or more are amenorrheic at 12 months</td></tr><tr><td></td><td>Progestogen-only implant</td><td>Bleeding disturbances are common. The bleeding pattern in the first 3 months is broadly predictive of future bleeding patterns for many women</td><td>As a guide, around:<br/>2 in 10 women are amenorrhoeic<br/>3 in 10 women have infrequent bleeding<br/>Fewer than 1 in 10 women have frequent bleeding<br/>2 in 10 women have prolonged bleeding<br/>in 75% of reference periods bleeding spotting days are fewer than or comparable to those observed during the natural cycle, but they occur at unpredictable intervals</td></tr><tr><td></td><td>Levonorgestrel releasing intrauterine system (LNG-IUS) 52 mg (Mirena)</td><td>Frequent bleeding / spotting is common in the first how months after insertion</td><td>There is a decrease over time in the number of bleeding and spotting days with all dioses of LNG JUS<br/>A 90% reduction in menstrual blood loss has been demonstrated over 12 months of 52 mg LNG-IUS Use<br/>At 1-year, infrequent bleeding is usual with the LNG-IUS and some women will be amenorrhoeic 24% of 52 mg LNG-IUS users are amenorrhoeic at 3 years</td></tr><tr><td></td><td>LNG-IUS 13.5 mg (Jaydess)</td><td>Frequent bleeding / spotting is common in the first few months after insertion</td><td>There is a decrease over time in the number of bleeding and spotting days with all doses of ING-HUS<br/>Users of the 13.5 mg LNG-IUS report more spotting days than bleeding days over the duration of licensed use<br/>Fewer women (10% of 3 years) will experience amenorrhea with this dose of LNG-IUS compared to the 52 mg LNG-IUS</td></tr></tbody></table>', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
