INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0c3bc7c9', 't-mm-05-014', 'text', 'FOR ALL WOMEN USING HORMONAL CONTRACEPTION WITH PROBLEMATIC BLEEDING Take a clinical history to assess The woman''s concerns Correct use of method (e.g. pill taking, patch use), use of interacting medication, illness altering absorption of orally administered hormonesOther symptoms (e.g. pain, dyspareunia, abnormal vaginal discharge, heavy bleeding. postcoital bleeding) Exclude sexually transmitted infections Check cervical screening history Consider the need for a pregnancy test FOR ALL WOMEN USING HORMONAL CONTRACEPTION WITH PROBLEMATIC BLEEDING Take a clinical history to assess The woman''s concerns Correct use of method (e.g. pill taking, patch use), use of interacting medication, illness altering absorption of orally administered hormonesOther symptoms (e.g. pain, dyspareunia, abnormal vaginal discharge, heavy bleeding. postcoital bleeding) Exclude sexually transmitted infections Check cervical screening history Consider the need for a pregnancy test', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
