INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-59345310', 't-mm-06-001', 'text', 'Consent: Is a pt’s agreement for a health professional to provide care.', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1d956226', 't-mm-06-001', 'text', 'Type:', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-358f06fe', 't-mm-06-001', 'text', 'Non – verbal like presenting arm to check B.P.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-22fc572e', 't-mm-06-001', 'text', 'Verbal.', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b12667f1', 't-mm-06-001', 'text', 'Written.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9338f0c6', 't-mm-06-001', 'text', 'For a valid consent:', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0c451ee6', 't-mm-06-001', 'text', 'Be competent to make the particular decision', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8ceba76d', 't-mm-06-001', 'text', 'Have received sufficient information to make decision', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-764b04ae', 't-mm-06-001', 'text', 'Not be acting under stress.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9d95b470', 't-mm-06-001', 'text', 'Competent or having capacity:', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a4ee3fd9', 't-mm-06-001', 'text', 'Capacity consists of following:', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2707ce58', 't-mm-06-001', 'text', 'Ability to comprehend & retain information', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-53367928', 't-mm-06-001', 'text', 'A belief in information given', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d92091f0', 't-mm-06-001', 'text', 'Ability to use information given to arrive @ a decision.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a28be8cb', 't-mm-06-001', 'text', 'A Pt may have the capacity to Consent to some decision but not others. A Pt’s capacity may vary with factors such as confusion, Panic, Shock, Fatigue pain/ Medication. But such factors may not automatically render a pt incapable of Consent.', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-753af8bd', 't-mm-06-001', 'text', 'Adults with Incapacity:', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aaedb92b', 't-mm-06-001', 'text', 'Before making decision, you must:', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0c7dc8df', 't-mm-06-001', 'text', 'Make care of women your 1st concern', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bdf0ce9c', 't-mm-06-001', 'text', 'Treat them as individuals.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-12c7d104', 't-mm-06-001', 'text', 'Respect their dignity and not discriminate against them.', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1f632dea', 't-mm-06-001', 'text', 'Support and encourage the women to be involved in decisions about their treatment and care as far as they want (and are able) too.', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-82e3167e', 't-mm-06-001', 'text', 'Adults with capacity:', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-16d7b703', 't-mm-06-001', 'text', 'You must also consider:', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6693b494', 't-mm-06-001', 'text', 'Whether women lake of capacity is Temporary or permanent.', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f947dcee', 't-mm-06-001', 'text', 'Which procedure/ option would provide overall clinical benefit.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-04673f25', 't-mm-06-001', 'text', 'Which option, including the option not to treat, would be least restrictive for future choices.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f2ca9c82', 't-mm-06-001', 'text', 'Advance decision/  Advance directive:', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e8e8fa68', 't-mm-06-001', 'text', 'Reflects a pt’s wish to refuse a particlar type of medical treatment or care if they become unable to make or communicate decision themselves.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-07b3d3a4', 't-mm-06-001', 'text', 'If valid for current situation => must be respected.', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b126f602', 't-mm-06-001', 'text', 'Verbal:', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b32c9eca', 't-mm-06-001', 'text', 'Infront of chaperone.', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1587c4c1', 't-mm-06-001', 'text', 'Must be documented.', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66bbd408', 't-mm-06-001', 'text', 'Example:', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-844d1cbe', 't-mm-06-001', 'text', 'Breast examination.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1835dbe7', 't-mm-06-001', 'text', 'Presence of students during surgery.', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-85834fff', 't-mm-06-001', 'text', 'Emergency procedures – CS, Assisted vaginal delivery 1st and 2nd degree perineal tear (3rd and 4th written if time allows).', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c2dc7e93', 't-mm-06-001', 'text', 'Em – LSCS Assisted vaginal, 3rd/4th  degree => Better', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a7dbc0b9', 't-mm-06-001', 'text', 'To go for written if time allows.', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eba4b3cc', 't-mm-06-001', 'text', 'Written:', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-20bc201f', 't-mm-06-001', 'text', 'OPD procedures in Gynae.', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-943b8ffd', 't-mm-06-001', 'text', 'Any procedure under local, regional or GA.', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-de86a562', 't-mm-06-001', 'text', 'Multimedia Images:', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-784885eb', 't-mm-06-001', 'text', 'Laparoscopic findings, USG pictures, X – ray for teaching.', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6c0907df', 't-mm-06-001', 'text', 'Removal of tissue for research/ testing where samples are not anonymized.', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6dc24827', 't-mm-06-001', 'text', 'Example: Mrs X Histopath.', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0bab8e59', 't-mm-06-001', 'text', 'Analysis of fetus following fetal loss after 24weeks of gestation.', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cd7a4ecf', 't-mm-06-001', 'text', 'Storing gamets – legal advice HFEA & written Consent.', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a1820a72', 't-mm-06-001', 'text', 'Consent nota Needed:', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-32f02bb0', 't-mm-06-001', 'text', 'USG in pregnancy.', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6951b749', 't-mm-06-001', 'text', 'Images storing for pt record.', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-21e692c1', 't-mm-06-001', 'text', 'Specific Consent for removal of tissue for H/P is not required (unless anonymized and used in record & residual sample).', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d2c7b843', 't-mm-06-001', 'text', 'Retained tissues for education/ Teaching.', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ec1de7dc', 't-mm-06-001', 'text', 'Unexpected Pathology:', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0148df42', 't-mm-06-001', 'text', 'Unexpected pathology related to complaints.', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dfc1cbd8', 't-mm-06-001', 'text', 'Treatment can be performed (Appendicitis – I/O torsion).', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-10988d83', 't-mm-06-001', 'text', 'Complication of surgery that is life threatening proceed with corrective surgery.', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a5958c97', 't-mm-06-001', 'text', 'Unexpected pathology not related to complaint.', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8942ed60', 't-mm-06-001', 'text', 'Don’t proceed like pain RiF – operated for appendicitis, I/O ovarian cyst => don’t remove', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-72a4abf9', 't-mm-06-001', 'text', 'Unexpected pathology – Biopsy can be taken if it doesn’t upstage the disease.', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-454b7054', 't-mm-06-001', 'text', 'Unexpected Ectopic – remove.', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0c3d171d', 't-mm-06-001', 'text', 'Unexpected I/U pregnancy – reschedule operation.', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-03ad2571', 't-mm-06-001', 'text', 'Obstetrics:', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-58baa77b', 't-mm-06-001', 'text', 'During pain – no Consent.', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dd0b272a', 't-mm-06-001', 'text', 'In between contractions or epidural => can give Consent.', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-09524ffa', 't-mm-06-001', 'text', 'Consent for sterilization not be taken during labor or S/S.', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-60c21fc6', 't-mm-06-001', 'text', 'If already signed during antenatal Period => can be performed.', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3f81bae1', 't-mm-06-001', 'text', 'Gillick Competent:', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9d31bf5b', 't-mm-06-001', 'text', '< 16 years’ may wish to give their Consent for treatment without parent’s knowledge => mature Minor.', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1e4c7474', 't-mm-06-001', 'text', 'Refusal of Treatment: Overridden Parental Consent or court orders.', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-85e24a74', 't-mm-06-001', 'text', 'Professional Translator:', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d3e36b04', 't-mm-06-001', 'text', 'If Pt not knows English, but should not be a relative.', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ad5d7ed3', 't-mm-06-001', 'text', 'Gillick competent => TOP can be performed.', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6a34a528', 't-mm-06-001', 'text', 'Fraser law:', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ab3531a7', 't-mm-06-001', 'text', 'Covers Contracepation in mature minors.', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b5c2834a', 't-mm-06-001', 'text', 'Important Points:', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4e3ab1b1', 't-mm-06-001', 'text', 'All women age 18 or over => Capacity to give Consent.', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2b81598a', 't-mm-06-001', 'text', 'Pt can withdraw Consent @ any time if so, procedures should be stopped as soon as possible.', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9ec7389b', 't-mm-06-001', 'text', 'No body can Consent for a person who has capacity.', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-75dd18be', 't-mm-06-001', 'text', 'Consent does not expire.', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e3a8f3e0', 't-mm-06-001', 'text', 'Consent must be written only when the law require it.', 80) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c9774bcd', 't-mm-06-001', 'text', 'No place in law for next of kin to give Consent.', 81) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-34304784', 't-mm-06-001', 'text', 'Doctor must act only in best interest of women.', 82) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9783a487', 't-mm-06-001', 'text', 'Unconsious Pt:', 83) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b0b07134', 't-mm-06-001', 'text', 'Doctor in best interest.', 84) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ffd33b2e', 't-mm-06-001', 'text', 'Refusal of blood by Jehovah’s witness – don’t give blood.', 85) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a7853d7e', 't-mm-06-001', 'text', 'Fetus in context of Consent:', 86) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e8497c5f', 't-mm-06-001', 'text', 'Fetus has no rights.', 87) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
