INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d9da3c91', 't-mm-06-005', 'html', '<table><tbody><tr><td>NERVE</td><td>PROCEDURE</td><td>PRESENTATION</td></tr><tr><td>Femoral</td><td>TAH<br/>With retractor 8%.<br/>Without 1%.<br/>Improper lithotomy.</td><td>Loss of knee Jerk<br/>Sensory loss @ anterior and Medial thigh.<br/>Unable to climb Stairs.</td></tr><tr><td>Ilioinguinal, iliohypogastric 3.7%</td><td>Pfannenstiel incision 7%</td><td>Pain from scar to mons, labia, thigh</td></tr><tr><td>Genitofemoral</td><td>External Iliac node dissection</td><td>Same as ilioinguinal but towards femoral triangle instead of thigh</td></tr><tr><td>Lateral cutaneous Nerve of thigh</td><td>As (F) Nerve</td><td>Pain and paresthesia over lateral post and anterior thigh</td></tr><tr><td>Obturator nerve</td><td>TOT<br/>Pelvic flow repair<br/>Endometriosis</td><td>Medial thigh</td></tr><tr><td>Common peroneal</td><td>Sciatic notch</td><td>Foot drop</td></tr><tr><td>Tibial</td><td>Improper lithotomy</td><td>caves deformity</td></tr><tr><td>Pudendal</td><td>SSF</td><td>perineal pain on sitting sexual dysfunction.</td></tr><tr><td>Brachial plexus</td><td>Arm rest</td><td></td></tr><tr><td>Upper trunk</td><td>Hyperabduction</td><td>Erb</td></tr><tr><td>Lower trunk</td><td>Lateral placement of brace</td><td>Clump Kie’s + claw hand radial wrist drop</td></tr></tbody></table>', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
