INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7588dceb', 't-mm-06-009', 'text', 'Local Anaesthesia:', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f8a40e80', 't-mm-06-009', 'text', 'Not routinely given.', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bbfe474c', 't-mm-06-009', 'text', 'Used when there is need for cervical dilatation or use of speculum.', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-982a6abf', 't-mm-06-009', 'text', 'Types of local Anaesthesia:', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2cb91100', 't-mm-06-009', 'text', 'Short acting', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0638c73f', 't-mm-06-009', 'text', 'Example: mepivacaine, lidocaine and prilocaince require atleast 2 minutes.', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-602379e9', 't-mm-06-009', 'text', 'Long acting agents:', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3122637a', 't-mm-06-009', 'text', 'Example: bupivacain require at least 5 minutes to allow for onset of effect.', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2a9155d6', 't-mm-06-009', 'text', 'Cervical preparation before OPH:', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-377fa8ad', 't-mm-06-009', 'text', 'Not used routinely', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c444ac44', 't-mm-06-009', 'text', 'Vaginal prostalglandis – 12 hours before procedure', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6b7e40ec', 't-mm-06-009', 'text', 'Cervical dilators upto 6mm if needed.', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-658c12ff', 't-mm-06-009', 'text', 'Types of hysterscope:', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e5c0ca0b', 't-mm-06-009', 'text', '3.5mm or less in diameter should be used for diagnostic purpose.', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-75a1b4d3', 't-mm-06-009', 'text', 'Use the expandable outer working channels because they are associated with less pain.', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-87d57e80', 't-mm-06-009', 'text', 'Choice of hysteroscope depends on operator.', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ac82efbf', 't-mm-06-009', 'text', 'Distension media', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2a3207ef', 't-mm-06-009', 'text', 'Saline is recommended', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-99f26821', 't-mm-06-009', 'text', 'Reduced pain', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a093ed7e', 't-mm-06-009', 'text', 'Better view', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-43393a8b', 't-mm-06-009', 'text', 'Reduced vasovagal symptoms', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a52ef407', 't-mm-06-009', 'text', 'Less shoulder tip pain', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7fe58360', 't-mm-06-009', 'text', 'Effective in see and treat procedures.', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-744af1ca', 't-mm-06-009', 'text', 'Minimal risk with fluid overload', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-05feda28', 't-mm-06-009', 'text', 'Lesser electrosurgical complication.', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c41fb4d7', 't-mm-06-009', 'text', 'Saline should be instilled at lowest possible pressure.', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b2afaf59', 't-mm-06-009', 'text', 'Warm saline appropriately according to body temperature.', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4ed652f5', 't-mm-06-009', 'text', 'Vaginoscopy:', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-40aa6bd1', 't-mm-06-009', 'text', 'Also called ‘no touch’ approach.', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1465a242', 't-mm-06-009', 'text', 'It should be standard technique for OPH unless the use of vaginal spectrum is required.', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6d76561b', 't-mm-06-009', 'text', 'Useful in following patients.', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-25d2ded9', 't-mm-06-009', 'text', 'Nulliparous', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-77e55a7e', 't-mm-06-009', 'text', 'Sufferes of vaginismus', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e1e33be3', 't-mm-06-009', 'text', 'Virgo intacta', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ec21748a', 't-mm-06-009', 'text', 'Genital track atrophy.', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c0891198', 't-mm-06-009', 'text', 'Prevention of infection following OPH:', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aa249259', 't-mm-06-009', 'text', 'Antibiotics not routinely recommended', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d615c668', 't-mm-06-009', 'text', 'Must be given if suspicion of pyometra to prevet systematic infection', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0560d5dd', 't-mm-06-009', 'text', 'Delay OPH if evidance of genital infection.', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-53395aba', 't-mm-06-009', 'text', 'Documentation of OPH', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-81f91f5d', 't-mm-06-009', 'text', 'Related to findings:Impression & description of vulva, vagina, cervix and endometriumVisualization of both ostiaDetails of congenital anomaly of uterus adhesions, cervical niches, fibroids, polyps and its FIGO types, RPOCS.Uterocervical length when biopsy is taken or device is fitted.Related to findings:Impression & description of vulva, vagina, cervix and endometriumVisualization of both ostiaDetails of congenital anomaly of uterus adhesions, cervical niches, fibroids, polyps and its FIGO types, RPOCS.Uterocervical length when biopsy is taken or device is fitted.Related to technique:', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
