INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2a4bbb51', 't-mm-06-009', 'text', 'Hysteroscopy/ operative device used', 81) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
