INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-25d7eb5b', 't-mm-06-009', 'text', 'Local anaesthesia (Agent, dose, route).', 83) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
