INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-88a384bb', 't-mm-06-009', 'text', 'Biopsy performed.', 85) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6fed7e41', 't-mm-06-009', 'text', 'Operative procedure performed', 86) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bacc9429', 't-mm-06-009', 'text', 'Inhalational agents used', 87) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-67f5808d', 't-mm-06-009', 'text', 'Procedural success', 88) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2f9e030f', 't-mm-06-009', 'text', 'Complications', 89) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c5e603e2', 't-mm-06-009', 'text', 'Vasovagal reaction', 90) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fed4f28d', 't-mm-06-009', 'text', 'Uterine perforation', 91) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c829406a', 't-mm-06-009', 'text', 'Heavy bleeding.', 92) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-06-010', 'chap-mm-06-01', '10. STEPS OF ABDOMINAL HYSTRECTOMY', 'Detailed medical reference and study guide on 10. STEPS OF ABDOMINAL HYSTRECTOMY.', 10, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66a0220c', 't-mm-06-010', 'image', '/uploads/content-images/maternal_mind_book/image40.png', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6b4e4001', 't-mm-06-010', 'text', 'WHO checklist', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9fba5f22', 't-mm-06-010', 'text', 'Low transverse incision preferred', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-46ced163', 't-mm-06-010', 'text', 'Enter into the peritoneum high up', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b4319371', 't-mm-06-010', 'text', 'Pack abdominal organs, omentum and bowels', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b447eac9', 't-mm-06-010', 'text', 'Self-training retractor like Balfour', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bfc901cf', 't-mm-06-010', 'text', 'Straight clamps at cornu', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0e970feb', 't-mm-06-010', 'text', '2 curved clamps at round ligament mid position; clamp, cut and ligate; transfix to avoid slippage with vicryl 1', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5bd4c6cf', 't-mm-06-010', 'text', 'Underneath the round ligament, make a window in the avascular part of broad ligament (visualize ureter lying in the posterior fold of broad ligament or ovarian fossa), clamp, cut and ligate ovarian ligament, transfix to avoid slippage with vicryl 1.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-52ae4a8e', 't-mm-06-010', 'text', 'Separate bladder from the uterus and the cervix through Mayo Scissors', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-87da0891', 't-mm-06-010', 'text', 'Curved non-crushing clamps on uterine artery pedicle. Before that, visualize the ureter and keep them away from surgical field. Clamp, cut and ligate. Transfix to avoid slippage with vicryl 1', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-11690b3c', 't-mm-06-010', 'text', 'Straight clamps for cardinal and uterosacral ligaments. Clamp, cut and ligate. Transfix to avoid slippage with vicryl.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5b049a5a', 't-mm-06-010', 'text', 'Two curved clamps on either side of vagina. Take a stay suture on both angles. Cut with knife and hand over for histopathology.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3189cf31', 't-mm-06-010', 'text', 'To prevent vault, prolapse, tie vault, cardinal and uterosacral on each side', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-98201430', 't-mm-06-010', 'text', 'Close vault with locking/ oblique/ continuous/ interrupted sutures', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f5721435', 't-mm-06-010', 'text', 'Inspect vault and all pedicle. Complete swab count. Leave peritoneum unstitched to decrease postop morbidity and pain.', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7ba2ec1c', 't-mm-06-010', 'text', 'Close rectus sheath in a continuous manner', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9cf21f3d', 't-mm-06-010', 'text', 'Subcutaneous tissue closure if >2cm', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f7de6c61', 't-mm-06-010', 'text', 'Skin and subcuticular stitches.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-06-011', 'chap-mm-06-01', '11. STEPS OF VAGINAL HYSTERECTOMY', 'Detailed medical reference and study guide on 11. STEPS OF VAGINAL HYSTERECTOMY.', 11, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d065f4cc', 't-mm-06-011', 'text', '1. Apply valsellum to anterior and posterior lips of cervix', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-17379cc5', 't-mm-06-011', 'text', '2. Infiltrate with xylocaine 1:1,000 with adrenaline (inform the anaesthetist)', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f6c710d4', 't-mm-06-011', 'text', '3. Make circumferential incision around the internal cervical os', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-de1275be', 't-mm-06-011', 'text', '4. Push the bladder up anteriorly to expose the uterovesical peritoneum and the rectum posteriorly to expose the posterior peritoneum; incise the peritoneum and feel for the adnexa (to ensure there are no masses and there are no adhesions)', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8eb8d259', 't-mm-06-011', 'text', '5. Apply clamps to the transverse cervical ligaments (Mackenrodt''s ligaments), making sure that the bladder is pushed away to avoid the ureters. Divide ligaments close to the uterus and transfix with the end of the stich anchored to clamp', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3ef774e8', 't-mm-06-011', 'text', '6. Apply clamps to uterine vessels, divide and ligate carefully', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-07e89845', 't-mm-06-011', 'text', '7. Retrovert the uterus to expose the U-V peritoneum and then divide it', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cb7dbb24', 't-mm-06-011', 'text', '8. Apply clamps to the infundibulo-pelvic fold containing round ligament and fallopian tube, and divide and transfix', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3047f7a0', 't-mm-06-011', 'text', '9. Deliver the uterus out. Check the haemostasis of all the pedicles.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-45539ff6', 't-mm-06-011', 'text', '10. Identify peritoneum and anchor it with small forceps; close peritoneum with continuous suture (this step may be omitted and the peritoneum not closed)', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-97b1cf20', 't-mm-06-011', 'text', '11. Identify the angle of vagina and tie transverse ligaments to it. Close vagina with interrupted sutures', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-06-012', 'chap-mm-06-01', '12. STEPS OF EVACUATION', 'Detailed medical reference and study guide on 12. STEPS OF EVACUATION.', 12, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-33111871', 't-mm-06-012', 'text', 'Procedure step by step:', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1ff4e810', 't-mm-06-012', 'text', 'Perform safety and equipment check.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0d446065', 't-mm-06-012', 'text', 'Have the woman empty her bladder before entering the procedure room.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-94373f25', 't-mm-06-012', 'text', 'Initiate any intravenous painkiller and/ or Anxiolytic oral medication  should be used in advance of the procedure in order to perform D & E @ the time of their max effect', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8993335d', 't-mm-06-012', 'text', 'Perform bimanual exam to check uterine size & position as well as adequacy of cervical dilation. Remove and account for all osmotic dilators previously placed, if the cervix is not adequately prepared, give an additional dose of misopostal and place another set of dilators.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-00b259a8', 't-mm-06-012', 'text', 'Place speculum.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-53822b1d', 't-mm-06-012', 'text', 'Clean cervix with an antiseptic solution, such as providone-iodine (Betadine).', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-06e135b3', 't-mm-06-012', 'image', '/uploads/content-images/maternal_mind_book/image41.jpg', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4b35387e', 't-mm-06-012', 'text', 'Figure 1. Aspirate the arriotic fluid.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-07469550', 't-mm-06-012', 'image', '/uploads/content-images/maternal_mind_book/image41.jpg', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c33bc2bc', 't-mm-06-012', 'text', 'Figure 2. Open the forceps', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bfa3eb04', 't-mm-06-012', 'image', '/uploads/content-images/maternal_mind_book/image42.jpg', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a4617300', 't-mm-06-012', 'text', 'Figure 3. Pull the forcep handle down so graspers are in the anterior lower uterine segment.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3fabe17b', 't-mm-06-012', 'image', '/uploads/content-images/maternal_mind_book/image42.jpg', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96ccee47', 't-mm-06-012', 'text', 'Figure 4. Evacuate from the lowest section of the uterine cavity.', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e8b9dfe3', 't-mm-06-012', 'text', 'Perform para cervical block and place tenaculum.', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2b2ac1e0', 't-mm-06-012', 'text', 'Place traction on the tenaculum to bring cervix down the vagina.', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-633bc9e2', 't-mm-06-012', 'text', 'Ring forcep, sponge holding forceps, volsellum forceps can be used in place of a tenaculum for later gestations, if desired', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0b29e853', 't-mm-06-012', 'text', 'Recheck adequacy of dilation by attempting to pass the largest diameter dilator without using force.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a798e1fc', 't-mm-06-012', 'text', 'Mechanically dilute cervix, as needed, to achieve desired/necessary amount.', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-40e2f2bf', 't-mm-06-012', 'text', 'dilator need to reach the internal os without going higher into the uterus. touching the fundus with the dilator is painful for the woman and increases the risk of perforation.', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2554b7e7', 't-mm-06-012', 'text', 'Perform uterine aspiration with largest cannula available (12-16 mm) and separate the amniotic fluid (see figure 1). Either electric or manual vacuum aspiration can be used.', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1ea9f50a', 't-mm-06-012', 'text', 'Perform the suction as is done during a first trimester aspiration abortion, rotating the cannula during suction. If using MVA empty the aspirator when it is full and repeat as necessary. When nothing more can be suctioned, remove cannula from uterus.', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9b5f731a', 't-mm-06-012', 'text', 'For gestations up to 15 weeks, it may be possible to complete the abortion using aspiration only.', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-629322d4', 't-mm-06-012', 'text', 'Maintaining gentle traction on the tenacullum to straighten the cervical canal, pass the closed foreceps through the cervix in a vertical direction (the jaw of the bierer or Sopher forceps should open in an up-down direction, not horizontally). See fig 2.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d03a8f8a', 't-mm-06-012', 'text', 'As soon as the forceps pass through the internal os, gently open it as wide as possible. While opening the forceps, drop your hand and forceps in the direction of the floor to angle the jaws of the forceps into the anterior lower – uterine segment (see Figure 3).', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-02b90cc5', 't-mm-06-012', 'text', 'A mid trimester gravid uterus is usually positioned anteriorly, toward the anterior abdominal wall.', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-91c6ae35', 't-mm-06-012', 'text', 'To evacuate the tissue, close the forceps around the fetal tissue and rotated it 90 degrees to assist with disarticulation before withdrawing.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-65174218', 't-mm-06-012', 'text', 'Be careful not to grasp the myometrium with the forceps.', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f8319c24', 't-mm-06-012', 'text', 'Keep forceps within the lower to mid – uterine segment. There is usually no need to use the forceps near the fundus, which increases the risk of perforation (see Figure 4).', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9a15f15c', 't-mm-06-012', 'text', 'Repeat until fetal removal is completed as is the majority or all of the placenta.', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-df1f015a', 't-mm-06-012', 'text', 'attempt to remove tissues with each pass of the forceps.', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1eefd482', 't-mm-06-012', 'text', 'If you cannot locate and move the fetus/ fetal parts within 5 – 7 minutes, consider using ultrasound to visualize and direct the movement of the forceps.', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6a52731d', 't-mm-06-012', 'text', 'If the tissue has moved upwards to the fundus from the lower segment of the uterus, use suction to bring the fetus down within grasp of the forceps or consider removing the speculum and tenacullum and messaging the uterus. If dilated sufficiently to allow passage of part of the provider’s hand, the pregnancy can be repositioned internally. In the unlikely event that these maneuvers do not bring the tissue within reach of the forceps, administer misoprostal 400mcg (buccal) or high dose oxytocin (200 units in 500mL normal saline or lactated ringers and run at 50Ml/hour IV). The D&E procedure should be reattempted in 30 minutes to 3 hours, the woman should be observed during this time.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5878a82d', 't-mm-06-012', 'text', 'When all the fetal tissues is removed, perform suction aspiration to ensure no tissues are remaining.', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b1e5cd2d', 't-mm-06-012', 'text', 'Examine the fetal tissue to ensure that evacuation is complete:', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9e68b52f', 't-mm-06-012', 'text', 'Identify fetal parts (Thorax, spine, calvarium, all 4 extremities and placenta, for all procedures, 14 weeks’ and greater).', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9188dc9c', 't-mm-06-012', 'text', 'If it is unclear whether the evacuation is complete, an ultrasound or a digital exam of the uterine cavity may be used for confirmation.', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-06-013', 'chap-mm-06-01', '13. MVA', 'Detailed medical reference and study guide on 13. MVA.', 13, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-884c368c', 't-mm-06-013', 'text', 'Selection criteria of MVA:', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1c3264be', 't-mm-06-013', 'text', '1. Haemodynamically stable', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b781741e', 't-mm-06-013', 'text', '2. Parous women', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-298b8bf9', 't-mm-06-013', 'text', '3. Well-motivated nulliparous women who can tolerate speculum examination', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-65ab427b', 't-mm-06-013', 'text', '4. Ultrasound diagnosis of early fetal demise with crown-rump length <25 mm', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2594651b', 't-mm-06-013', 'text', '5. Ultrasound diagnosis of an incomplete miscarriage with retained products of conception measuring less than 5 cm (mean diameter).', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96ddaae2', 't-mm-06-013', 'text', '6. No clinical signs of infection (fever, offensive discharge or generalized lower abdominal pain).', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0ba29a0b', 't-mm-06-013', 'text', 'Women who are not suitable for outpatient MVA include those with:', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-616e13a7', 't-mm-06-013', 'text', '1.> 10-week period of gestation', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a5cf886e', 't-mm-06-013', 'text', '2. Panic attacks', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-55448052', 't-mm-06-013', 'text', '3. Cervical stenosis', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-209d87b0', 't-mm-06-013', 'text', '4. Fibroid uterus >12 weeks in size', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6a5ee0f2', 't-mm-06-013', 'text', '5. Uterine malformation', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-85432ad4', 't-mm-06-013', 'text', '6. Hemorrhagic disorder and treatment with anticoagulants', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c14c8fa3', 't-mm-06-013', 'text', '7. Allergy or contraindication to the use of misoprostol or to local anesthetic agents', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b2e0f834', 't-mm-06-013', 'text', '8. Postnatal retained products', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4de05ae7', 't-mm-06-013', 'text', '9. Uterine infection', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-24df71fd', 't-mm-06-013', 'text', '10. Inability to tolerate pelvic examination', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fffd4fa0', 't-mm-06-013', 'text', '11. Retained products more than 5cm.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-06-014', 'chap-mm-06-01', '14. STEPS OF ANTERIOR REPAIR', 'Detailed medical reference and study guide on 14. STEPS OF ANTERIOR REPAIR.', 14, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-91d290bd', 't-mm-06-014', 'text', 'Anterior Repair Steps:', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-211d1577', 't-mm-06-014', 'text', 'Before surgery the routine steps taken before any operative procedure should be carried out.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dca21392', 't-mm-06-014', 'text', 'Primary incision is full length of anterior vaginal wall, tented by four Allis clamps.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-05628184', 't-mm-06-014', 'image', '/uploads/content-images/maternal_mind_book/image43.emf', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a79510eb', 't-mm-06-014', 'text', 'Incision of inner surface of vaginal wall to separate viscovaginal connective tissues.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4b55fb88', 't-mm-06-014', 'image', '/uploads/content-images/maternal_mind_book/image44.emf', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b5924c50', 't-mm-06-014', 'text', 'Further separation of connective tissues and bladder from vaginal flap by rolling gauze-covered index finger from vaginal wall toward bladder.', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5f068dfc', 't-mm-06-014', 'image', '/uploads/content-images/maternal_mind_book/image45.jpg', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-840df15c', 't-mm-06-014', 'text', 'Sharp separation of bladder from vaginal apex.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d55836b4', 't-mm-06-014', 'image', '/uploads/content-images/maternal_mind_book/image45.jpg', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eeafa0dc', 't-mm-06-014', 'text', 'Separation of bladder pillars to promote bladder advancement', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-65e0647a', 't-mm-06-014', 'image', '/uploads/content-images/maternal_mind_book/image46.jpg', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6f87e982', 't-mm-06-014', 'text', 'Palpation of ureter', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b43096d3', 't-mm-06-014', 'image', '/uploads/content-images/maternal_mind_book/image46.jpg', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c370c62c', 't-mm-06-014', 'text', 'First plication suture at the urethrovesical angle. Arrows indicate the varying path of the imbrication sutures', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0c147708', 't-mm-06-014', 'image', '/uploads/content-images/maternal_mind_book/image47.jpg', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d79a0bfb', 't-mm-06-014', 'text', 'Only after the first layer of imbrication sutures is in place does blunt dissection extend further laterally, exposing denser layers of connective tissue.', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-181047cc', 't-mm-06-014', 'image', '/uploads/content-images/maternal_mind_book/image47.jpg', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c2cff14e', 't-mm-06-014', 'text', 'Additional layers of plication may be appropriate.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-58c6c451', 't-mm-06-014', 'image', '/uploads/content-images/maternal_mind_book/image48.jpg', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fc806576', 't-mm-06-014', 'text', 'Excision of redundant anterior vaginal wall', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-513ee905', 't-mm-06-014', 'image', '/uploads/content-images/maternal_mind_book/image48.jpg', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fa064832', 't-mm-06-014', 'text', 'The vaginal vault is pushed back to its normal location, allowing evaluation of vaginal length and caliber. Posterior rotation of the urethra as a result of tension of the anterior vaginal wall can be assessed at this point.', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-87164e57', 't-mm-06-014', 'image', '/uploads/content-images/maternal_mind_book/image49.jpg', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ac5c8e4a', 't-mm-06-014', 'text', 'Completion of anterior colporrhaphy with interrupted sutures of 2-0 polyglycolic material.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a9c24fda', 't-mm-06-014', 'text', 'Intra-abdominal pressure usually suffices to obliterate the space between the repaired vesicovaginal connective tissues and the vaginal.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-06-015', 'chap-mm-06-01', '15. STEPS OF POSTERIOR REPAIR', 'Detailed medical reference and study guide on 15. STEPS OF POSTERIOR REPAIR.', 15, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-90a8c969', 't-mm-06-015', 'text', 'Posterior repair steps:', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e11f2922', 't-mm-06-015', 'text', 'The patient is placed in the dorsal lithotomy position. The pelvis and large intestine are prepared for surgery.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2907673d', 't-mm-06-015', 'text', 'A bimanual examination under general anesthesia is performed to differentiate between an enterocele and a rectocele.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-55ed88d8', 't-mm-06-015', 'text', 'Observation of the perineal body is made to determine the extent of reconstruction needed', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b3fd7f28', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image50.jpg', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a31d30e5', 't-mm-06-015', 'text', 'The labia are retracted with interrupted sutures. The upper extent of the rectocele is identified. Allis clamps are applied to the posterior vaginal mucosa over this area. The clamps are elevated, creating a triangle.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ccf54faa', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image51.jpg', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6543dc52', 't-mm-06-015', 'text', 'Allis clamps are placed at the margins of the original hymen. An additional Allis clamp is placed in the midline at the top of the rectocele. A transverse incision is made at the posterior fourchette.A Kelly clamp is inserted under the posterior vaginal mucosa, dissecting the posterior mucosa off the perirectal fascia. An additional incision is made in the perineal body, removing a triangular piece of skin, outlined by the dotted line. This will expose the insertion of the bulbocavernosus muscle. Only the skin of the perineal body should be removed, and care should be taken not to remove the underlying superficial transverse perineal muscles.', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-97592a99', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image52.jpg', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1e2a1402', 't-mm-06-015', 'text', 'The vertical incision in the posterior vaginal mucosa has been made, and the edges are held with Allis clamps. The perirectal fascia is dissected off the posterior vaginal mucosa. The apex of the rectocele is held in an Allis clamp. The dissection of perirectal fascia off the vaginal mucosa is started with a scalpel but is completed with the handle of the scalpel or with scissors.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-12132ce7', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image53.jpg', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9d649b28', 't-mm-06-015', 'text', 'A finger is placed over the rectocele, pushing it into the rectum, thus revealing the margins of the levator ani muscles. Already, number 1synthetic absorbable suture is passed through the margin of the levator ani from the apex down to the posterior fourchette. Bydepressing the anterior rectal wall downward with one finger and elevating the previously placed suture, the surgeon sees the margin of the levator ani more clearly, and placement of sutures becomes easier.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a4b85471', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image53.jpg', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5f904793', 't-mm-06-015', 'text', 'After all levator ani sutures have been placed, they are progressively tied.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0a1e2868', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image54.jpg', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b56cacde', 't-mm-06-015', 'text', 'The excessive posterior vaginal mucosa has been trimmed away; the triangular defect in the perineal body can be seen. The insertion of the bulbocavernosus muscle is adjacent to the triangular defect in the perineal body.', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-25008354', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image54.jpg', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c02fb5c4', 't-mm-06-015', 'text', 'The perirectal fascia is closed with interrupted 0 synthetic absorbable suture in the midline', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1990a145', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image55.jpg', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-99055c6f', 't-mm-06-015', 'text', 'A synthetic absorbable suture is placed at the apex of the vaginal mucosa and tied (a).The tail of the suture is left for a length of 20 cm.The suture (b) is placed superficial to the tail of the suture (a).', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d7b99a2b', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image55.jpg', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6f86c299', 't-mm-06-015', 'text', 'The closure of the posterior vaginal wall is completed to the posterior fourchette. The former hymenal ring is reconstructed. The suture (b) is tied to the tail of the first suture (a) placed at the apex. The vaginal mucosa is approximated to the perirectal fascia to eliminate dead space', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1798b575', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image56.jpg', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f4fdc487', 't-mm-06-015', 'text', 'The same suture completes the closure of the perineal body. Several interrupted O synthetic absorbable sutures are placed in the insertions of the bulbocavernosus muscles to reconstruct the perineal body.', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-34c5b82f', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image57.jpg', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0097f91a', 't-mm-06-015', 'text', 'The posterior vaginal mucosa suture (b) is placed in the subcutaneous tissue of the perineal body. Note that the suture marked a is still left long for eventual tying.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cfadefe3', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image57.jpg', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1b574e04', 't-mm-06-015', 'text', 'The same suture (b) that completed the closure of the posterior vaginal wall is used to close the', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6121cff4', 't-mm-06-015', 'text', 'subcutaneous tissue and the insertions of the bulbocavernosus muscles.', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1c56891c', 't-mm-06-015', 'text', 'The suture marked a is the long end of the tie at the apex of the posterior vaginal mucosa incision', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-21031783', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image58.jpg', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c9468831', 't-mm-06-015', 'text', 'The subcuticular suture (b) is placed in the skin of the perineal body from the apex of the wound immediately above the anus to the posterior fourchette. At the posterior fourchette it is tied to suture a.', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f1786b83', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image58.jpg', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fd3f2a88', 't-mm-06-015', 'text', 'The completed operation is shown, with the rectocele reduced and the perineal body reconstructed. Vaginal packs are not required. Bladder catheterization is rarely indicated.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a2d789e4', 't-mm-06-015', 'image', '/uploads/content-images/maternal_mind_book/image59.jpg', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-06-016', 'chap-mm-06-01', '16.THE USE OF SURGICAL DRAINS', 'Detailed medical reference and study guide on 16.THE USE OF SURGICAL DRAINS.', 16, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d5a4c7e1', 't-mm-06-016', 'text', 'Indications:', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-324a0632', 't-mm-06-016', 'text', '1.To prevent fluid accumulation that can be the breeding ground for infection and dicomfort', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b5e12222', 't-mm-06-016', 'text', '2. To charactorize fluid', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dc6cbfbc', 't-mm-06-016', 'text', '3. To monitor leakage like serous/ frank blood, so that early detection of haemorrage can be done.', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9f256c10', 't-mm-06-016', 'text', '4. To promote tissue apposition', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-52d05ebc', 't-mm-06-016', 'text', '5. Where visceral repair has taken place to notice anastomotic leak earlier', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6dd57d84', 't-mm-06-016', 'text', '6. Prophylactic drain with the aim to reduce infection in clean wound is not indicated.', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-83f0e9ed', 't-mm-06-016', 'text', 'Complications of drains:', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3e614bf9', 't-mm-06-016', 'text', 'Infection', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0c6137bb', 't-mm-06-016', 'text', 'Bleeding', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0cbff543', 't-mm-06-016', 'text', 'Hernia', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-438d3f74', 't-mm-06-016', 'text', 'Kinking leeding to non fullfillment of purpose', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fbd3a647', 't-mm-06-016', 'text', 'Material of drains:', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1b5a12a4', 't-mm-06-016', 'text', 'Insert silastic material to reduce tissue reaction.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7be54835', 't-mm-06-016', 'text', 'Types:', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5ae94669', 't-mm-06-016', 'text', 'Collect fluid in bag or bottlePassiveActiveCollect fluid in bag or bottlePassiveActiveOpenClosed', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0ca91511', 't-mm-06-016', 'text', '- Open drains collect', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-06f38488', 't-mm-06-016', 'text', 'material into guaze', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-84a68aa5', 't-mm-06-016', 'text', 'pad or stoma bag.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-41d3a786', 't-mm-06-016', 'text', '- Usually not common', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-da22db7c', 't-mm-06-016', 'text', 'in gynaecology.', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5dc984f0', 't-mm-06-016', 'text', 'Closed Passive drains:', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ca768aed', 't-mm-06-016', 'text', 'Examples Robinsons or nasogastric tube', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1fb9e35a', 't-mm-06-016', 'text', 'Work by differential pressure between body cavities and exterior', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e0ba05e1', 't-mm-06-016', 'text', 'Closed Active Drains:', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-36abdb64', 't-mm-06-016', 'text', 'Also called suction drains', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-776a4ca2', 't-mm-06-016', 'text', 'Example radivac', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8248a79f', 't-mm-06-016', 'text', 'Valves prevent reflux of fluid back into wound', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2a9f74be', 't-mm-06-016', 'text', 'Can lead to tissue collapse around a drain that can obstruct drain orifices', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f3212739', 't-mm-06-016', 'text', 'Promote tissues apposition, leading to minimization of hematoma or seroma formation.', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-320fe58c', 't-mm-06-016', 'text', 'Suction force also keeps clear the drain from debris.', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-550da3a3', 't-mm-06-016', 'text', 'Location of drains in Gynaecology:', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9c958cd6', 't-mm-06-016', 'text', '1. Pelvis', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
