INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-85039f5f', 't-mm-06-018', 'text', 'Bleeding is caused by aberant vessel which can’t be identified surgically or AV malformation', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
