INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f3573649', 't-mm-06-018', 'text', 'Catheter is fed with radiological help, after insertion of cather, clotting agent is released for example coil, particles gel or foam to stop bleeding.', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
