INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-02e7088c', 't-mm-06-018', 'text', 'Interfere with cardiac functions especially    FDPs', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
