INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4a737a5c', 't-mm-06-018', 'text', 'Increased level:', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
