INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9e97acf5', 't-mm-06-018', 'text', '2. Platelets', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0c4d8cb6', 't-mm-06-018', 'text', 'Treatment:', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d3ebd143', 't-mm-06-018', 'text', '1. Treat the underlying cause, stop haemorrhage', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1d47b86b', 't-mm-06-018', 'text', '2. Correct clotting disorder', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3c197f04', 't-mm-06-018', 'text', 'FFP – most coagulaion factors are present but  low in  fibrinogen.', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
