INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3683e357', 't-mm-06-018', 'text', 'The amount and type of given product should be determind on the type of coagulopathy and by the haematologist', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aa3aff7d', 't-mm-06-018', 'text', 'Coagulopathy resolves in 24 – 48 hours while thrombocytopenia resolves within a week.', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9f95bf28', 't-mm-06-018', 'text', 'Rotational thromboelastometry (TEG/ROTEM)  test is used by some units to assess coagulation and fibrinolysis, it guides regarding transfusion therapy in patients with significant haemorrhage however reference ranges vary between pregnant and non pregnant population.', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c45dd260', 't-mm-06-018', 'text', 'Secondary haemorrhage:', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-01fc32d0', 't-mm-06-018', 'text', 'Occurs after 7 – 14 days.', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2d899053', 't-mm-06-018', 'text', 'More common in vaginal procedures', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-77d3dcd6', 't-mm-06-018', 'text', 'Has an infective aetiology', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-56f8d3be', 't-mm-06-018', 'text', 'Can be because of retained products of conception', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8a37e7c9', 't-mm-06-018', 'text', 'Treatment is antibiotics along with culture and sensitivity of infective agent', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-50db24a3', 't-mm-06-018', 'text', 'Correct the cause.', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-06-019', 'chap-mm-06-01', '17.2. HAEMATOMAS', 'Detailed medical reference and study guide on 17.2. HAEMATOMAS.', 19, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3a47f4e5', 't-mm-06-019', 'text', 'Hematoma is a bruise Collection of blood underneath the skin or with in a cavity.', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-48c8bff2', 't-mm-06-019', 'text', 'Assessment of risks and benefits of stopping or continuing antiplatelets like aspirin, clexane, warfarin or NOAC.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-71041129', 't-mm-06-019', 'text', 'Consult the concerned consultant if patient had heart problem for which she is taking anticoagulant.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0279819f', 't-mm-06-019', 'text', 'Wound Haematoma:', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-10444329', 't-mm-06-019', 'text', '1. Superficial hematoa underneath the skin', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0c40c855', 't-mm-06-019', 'text', '2. Can cause pain, super imposd infection and fever', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-00591c76', 't-mm-06-019', 'text', 'Treatment', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0ceac131', 't-mm-06-019', 'text', 'Treat underlying cause', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c65e8939', 't-mm-06-019', 'text', 'Most can be managed expectantly', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f5f755c1', 't-mm-06-019', 'text', 'Surgery is necessary in case of enlarging hematoma causing pain, discomfort and complication.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6f824fe4', 't-mm-06-019', 'text', 'Under anesthesia', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-83161617', 't-mm-06-019', 'text', 'Incision + Drainage + ligation of bleeding vessels.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-69a1352c', 't-mm-06-019', 'text', 'Consider antibiotics if necessary.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ee80f767', 't-mm-06-019', 'text', 'Vault Haematoma:', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e2a78a1d', 't-mm-06-019', 'text', 'Relatively common after hystrectomy 20%', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8678b95f', 't-mm-06-019', 'text', 'Majority treated by antibiotics alone.', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
