INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-00b98920', 't-mm-06-019', 'text', 'Persistent symptoms like pain', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-37ac427c', 't-mm-06-019', 'text', 'Large sized', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f914a994', 't-mm-06-019', 'text', 'Procedure:', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-44b1fe47', 't-mm-06-019', 'text', 'Approach vaginally (very less likely abdominal approach).', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bdfafdd5', 't-mm-06-019', 'text', 'Remove one or two sutures', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7752981b', 't-mm-06-019', 'text', 'Introduce finger, avoid instruments', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-37e31aff', 't-mm-06-019', 'text', 'Bimanual compression to expell hematoma', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-58ee8bb8', 't-mm-06-019', 'text', 'Meticulus examination to look for bleeding point, Mostly no cause is found', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b6a9f51e', 't-mm-06-019', 'text', 'Place a large bore or corrugated drain and fix it with vaginal mucousa with purse string sutures.', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9ee5cc1c', 't-mm-06-019', 'text', 'Close the vault if it was sutured continuosly in primary surgery.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-870b5321', 't-mm-06-019', 'text', 'Pack is not essential but provide additional haemostatic support in case of significant ozing.', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-38eae738', 't-mm-06-019', 'html', '<table><tbody><tr><td>Procedure</td><td>Hematoma</td></tr><tr><td>Episiotomy</td><td>Perineal haematoma</td></tr><tr><td>Keilland’s forceps</td><td>Broad ligament haematoma</td></tr><tr><td>Vaginal hystrectomy</td><td>Vault haematoma</td></tr><tr><td>Elective C/S</td><td>Wound haematoma</td></tr><tr><td>Sacrospinous fixation</td><td>Paravaginal haematoma</td></tr></tbody></table>', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7abbafbf', 't-mm-06-019', 'text', 'Key points about haematomas:', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ffdc6b13', 't-mm-06-019', 'text', 'Most of haematomas are managed conservatively', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a7b5951e', 't-mm-06-019', 'text', 'Risk of  stopping anticoagulation must be borne in mind as patients are @ risk of VTE', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d7ec74e8', 't-mm-06-019', 'text', 'Large hematomas can become infected', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-34bab6c5', 't-mm-06-019', 'text', 'Consider drains when hematomas are managed surgically', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-806e4e0e', 't-mm-06-019', 'text', 'Vault hematomas mostly does not indicte return to theatre', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-287fe806', 't-mm-06-019', 'text', 'Broad ligament hematomas must be considered when clinical findings are not in keeping with symptoms.', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
