INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f6cf4438', 't-mm-06-020', 'text', 'Can be managed conservatively with or without antibiotic cover and observation healing with secondary intention leads to hyper granulation, Hyper granulation and discomfort hyper granulation can be managed by using silver nitrate.', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
