INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d5183200', 't-mm-06-028', 'heading', '17.9.6. DUTY OF CANDOUR:', 101) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f0924aa3', 't-mm-06-028', 'text', 'Medical professionals have a duty to be open and honest with patients when things go wrong.', 102) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0c3a08a5', 't-mm-06-028', 'text', 'Health and social care Act 2008:', 103) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8cdcd5d3', 't-mm-06-028', 'text', '1. Regulation 20 is duty of candour', 104) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1d69a45a', 't-mm-06-028', 'text', '2. Intention is to ensure that providers are open and transparent with people who use services and other relevant persons in general in relation to care and treatment.', 105) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aaba610a', 't-mm-06-028', 'text', '3. It also sets out some specific requirements that providers must follow when things go wrong with care and treatment, providing reasonable support, providing truthful information and an apology when things go wrong', 106) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb84a41b', 't-mm-06-028', 'text', '4. The regulation applies to registered persons when they are carrying on regulated activity', 107) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d8b28740', 't-mm-06-028', 'text', '5. Breach in this duty can lead to prosecution by the care quality commission (CQC).', 108) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
