INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d61c4ac0', 't-mm-07-001', 'text', 'Thyroid peroxidase antibodies r associated with RPL, so work up is offered but thyroxine is not given in euthyroid women.', 119) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-22de0cdc', 't-mm-07-001', 'text', 'Subclinical Hypothyroidism has association with RPL.', 120) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-14c63865', 't-mm-07-001', 'text', 'Thyroxine supplementation:', 121) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f14cf400', 't-mm-07-001', 'text', 'Not recommended routinely with mild SCH (TSH >2.5).', 122) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1c4efb79', 't-mm-07-001', 'text', 'Consider Thyroxine if TSH > 4Miu/l', 123) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7add4124', 't-mm-07-001', 'text', 'regular TSH test from 7 – 9weeks, until 34 weeks is recommended in case of positive TPO antibodies and or/SCH because of risk of progression to overt hypothyroidism.', 124) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-467592e3', 't-mm-07-001', 'text', '9.Progesterone supplementation:', 125) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8a3f293c', 't-mm-07-001', 'text', 'RPL + Bleeding = Micronized progesterone is recommended 400mg, Plv, twice a day from bleeding till 16weeks).', 126) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
