INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-07-002', 'chap-mm-07-01', '2. ECTOPIC PREGNANCY', 'Detailed medical reference and study guide on 2. ECTOPIC PREGNANCY.', 2, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-89ac2817', 't-mm-07-002', 'heading', '3. DIAGNOSIS OF INTRAUTERINE AND ECTOPIC PREGNANCY', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f172a6e6', 't-mm-07-002', 'html', '<table><tbody><tr><td>Ectopic Pregnancy Incidence = 11/1000<br/>-  2 – 3% visiting EPAC<br/>-  Mortality   from 20% to 5%</td><td>Diagnostic criteria</td><td>Management</td><td>Follow Up</td></tr><tr><td>- Tubal Ectopic:</td><td>-  TVS: Tool of choice.<br/>Extra uterine Sac 20- 40%.Non cystic mass 50-60%.Sac with fetal content 15-20%.Extra uterine Sac 20- 40%.Non cystic mass 50-60%.Sac with fetal content 15-20%.<br/>Extra uterine Sac 20- 40%.<br/>Non cystic mass 50-60%.<br/>Sac with fetal content 15-20%.<br/>Extra uterine Sac 20- 40%.<br/>Non cystic mass 50-60%.<br/>Sac with fetal content 15-20%.<br/>TVS<br/>-  Free fluid in uterus 20%.<br/>-  Intradecidual / double decidual sign for intrauterine pregnancy.<br/>-  Free fluid:<br/>=> Anechoic.<br/>=> Echogenic<br/>In ruptured ectopic or leakage from fimbria, 28 – 56%.<br/>-  Mass moves separate to ovary.<br/>-  BHCG helpful in planning the management.</td><td>1. Systemic Methotrexate:<br/>65-95% success<br/>CRITERIA OF METHO<br/>-  Never given @ 1st visit<br/>-  B – HCG 1500 – 5000<br/>-  No pain<br/>-  I/U Gestation ruled out<br/>=> willing for F/U<br/>=> GS < 35mm with no FCA.<br/>Avoid:<br/>- alcohol & folate containing vitamins.<br/>Contraception:<br/>- for 3m`<br/>- 7% require surgical t/m.<br/>2. Surgical:<br/>- with pain – always surgical<br/>- laparoscopy – preferable<br/>=> salpingectomy<br/>preferable – 5%<br/>Recurrent Ectopic – 56%or 40% pregnancy<br/>=> Salpingotomy:<br/>- if fertility reducing factors are present<br/>- previous ectopic<br/>- Contralateral tubal damage.<br/>- previous Abdominal surgery.<br/>- Risk of persistent Trophoblasts.<br/>- follow up is needed<br/>- metho may be required<br/>in case of persistent disease 1/5.<br/>=> 8% ectopic<br/>=>60% pregnancy<br/>3. Expectant:<br/>-success 57 – 100%,<br/>- 29% required additional t/m.<br/>Indication:<br/>1. clinically stable.<br/>2. GS < 30mm.<br/>3. B – HCG <1500:<br/>Offer: B – HCG <1000<br/>Consider: B – HCG 1000-5000<br/>- Women consent<br/>-  50mg single dose.</td><td>B – HCG 4 – 7days<br/>in B – HCG <15%USG to rule out FCA, Free fluidAbsent2nd dose metho 3-27% (average 15% need 2nd dose of methotrexate.in B – HCG <15%USG to rule out FCA, Free fluidAbsent2nd dose metho 3-27% (average 15% need 2nd dose of methotrexate. In B - HCG  B – HCG weekly till <15IU/ml In B - HCG  B – HCG weekly till <15IU/ml<br/>in B – HCG <15%<br/>USG to rule out FCA, Free fluid<br/>Absent<br/>2nd dose metho 3-27% (average 15% need 2nd dose of methotrexate.<br/>in B – HCG <15%<br/>USG to rule out FCA, Free fluid<br/>Absent<br/>2nd dose metho 3-27% (average 15% need 2nd dose of methotrexate.<br/>In B - HCG<br/>B – HCG weekly till <15IU/ml<br/>In B - HCG<br/>B – HCG weekly till <15IU/ml<br/>UPT after 3weeks.<br/>Weekly B – HCG till normal.<br/>Repeat B – HCG 48 hours<br/>Weekly till B – HCG <20</td></tr><tr><td>Cervical Ectopic<br/>1%</td><td>- Empty uterus<br/>- Barrel shape Cervix<br/>- Sac below internal OS<br/>- Absence of sliding sign<br/>- Blood flow on Color Doppler<br/>B – HCG:<br/>- Single – HCG to diagnose.</td><td>Medical management with methotrexate:<br/>- Success rate with local/systemic metho is 91%<br/>- success rate decreases with beta HCG over 10000, positive fetal heart activity and gestational age >12 weeks<br/>Surgical management:<br/>- More failure, consider for women with life threatening bleeding, failed medical management or unstable patient.<br/>- Dilatation and curettage or hysteroscopic resection  with or without uterine artery embolization</td><td></td></tr><tr><td>Caesarian Scar ectopic: CSP<br/>- Incidence 1/2000<br/>- Recurrence 3.2%<br/>- 5% more if scar thickness is <5mm.<br/>Risk Factors:<br/>Previous c/section on breach or high uterine incision due to poorly formed lower segment<br/>Types:<br/>1. Endogenous progressing towards uterine cavity & reaching term but risk of PPH.<br/>2. Exogenous<br/>Progressing towards serosa – risk of rupture & hemoperitoneum.</td><td>TVS: 1st choice to diagnose<br/>- Empty uterine cavity & Cervical canal<br/>-  G.S / trophoblast mass @ scar site.<br/>-  Thin / absent myometrium between bladder & G.S.<br/>-  placental circulation on doppler<br/>- G.S/or trophoblast located at the level of internal OS<br/>13% misdiagnosed<br/>MRI 2nd choice,<br/>B – HCG No role in diagnosis<br/>-  single B – HCG as baseline for monitoring if conservative Mx is chosen.<br/>- If Advance GA then TVS combined with TAS.</td><td>Medical treatment<br/>Systemic or local metho:<br/>1. B - HCG <5000<br/>2. G.A <8weeks<br/>3. Hemodynamically stable with minimum or no Signs and symptoms.<br/>- Risk of Hge, retained POCS<br/>- May need suction evacuation after Metho.<br/>Surgical t/m: More effective in unstable patients.<br/>1.cervical dilatation and curettage under ultrasound guidance in case of endogenous CSP with myometrium thickness >2mm<br/>2 Hysteroscopic resection<br/>3. Laparotomy or laparoscopy<br/>In case of exogenous CSP or myometrial thickness of less than 2mm.<br/>4.Hysterectomy<br/>Last option<br/>Sequential management:<br/>Medical followed by surgical management:<br/>- Combined medical and surgical management<br/>- Expectant management is not recommended</td><td></td></tr><tr><td>Interstitial pregnancy 1 – 6%<br/>3D USG to rule out3D USG to rule outDID:<br/>3D USG to rule out<br/>3D USG to rule out<br/>- Angular<br/>- Early I/U</td><td>- Empty uterus<br/>- POC / Sac is located laterally in the intramural portion of the tube.<br/>- Surrounded by myometrium <5mm – all around<br/>- positive interstitial like sign<br/>- 80% sensitivity – 98% specificity.<br/>MRI – supplemental role.<br/>- Intact junctional zone<br/>B – HCG:<br/>Help in management<br/>repeat after 48 hrs.</td><td>- treatment is as for tubal ectopic pregnancy<br/>- Hysteroscopy resection under USG or laparoscopic Guidance.</td><td></td></tr><tr><td>Cornual pregnancy<br/>1 /76,000</td><td>1. single interstitial portion of tube in the body of uterus.<br/>2. POC are mobile & separate from uterus.<br/>3. Completely covered by myometrium.<br/>4. Vascular pedicle adjoining G.S to unicornate uterus.<br/>B – HCH help in management repeat after 48hours.</td><td>- Excision of rudimentary horn.<br/>- Laparoscopy preferred.</td><td></td></tr><tr><td>Ovarian Ectopic:<br/>D/D<br/>- Corpus Luteum<br/>- Tubal Ectopic<br/>- Ovarian Germ cell tumors.</td><td>No specific criteria.<br/>Negative sliding sign.<br/>Diagnosis:  On histopathology<br/>B – HCG: help in management repeat after 48hrs</td><td>No selection Criteria<br/>Surgery: laparoscopically<br/>t/m of choice.<br/>- wedge resection – preferred.<br/>- Evacuation of POCS – to avoid ovarian damage.<br/>- Oophorectomy – in case of heavy bleeding or concurrent ovarian pathology.<br/>Metho: 40% failure.</td><td></td></tr><tr><td>Abdominal<br/>Ectopic:<br/>1% of Ectopic pregnancies.<br/>Types:<br/>1. Early before 20weeks.<br/>2. Late after 20weeks.<br/>Mortality:<br/>- 7 Times of other ectopic.<br/>- 9 Times of I/U pregnancy.</td><td>1. Absence of Intra uterine G.S.<br/>2. Absence of adnexal mass.<br/>3. G.S surrounded by bowel loops.<br/>4. wide mobility to fluctuation of sac with TVS probe.<br/>5. No fistula<br/>6. No injury to tube/ovaries<br/>MRI: Adjunctive role.<br/>- Help in management.<br/>- Locate placenta & its relation with vital organs before t/m.<br/>Should be done in all cases.</td><td>Surgical t/m:<br/>Laparoscopy: early ectopic except where implantation don’t involve vascular area.<br/>Laparotomy: late ectopic<br/>placenta left in sites if attached e vital organs or vessels<br/>spontaneous resorption awaited.<br/>Leaving placenta in situ<br/>But mortality is lower than Removing placentaBut mortality is lower than Removing placenta- Risk of ileus<br/>But mortality is lower than Removing placenta<br/>But mortality is lower than Removing placenta<br/>- Intestinal<br/>obstruction<br/>- fistula formation<br/>- Peritonitis<br/>- Hemorrhage<br/>Metho:<br/>- Adjuvant therapy with surgery.<br/>- Local ± systemic metho.<br/>USG guided feticide.</td><td>angiographic embolization of vessels => can be offered as 1st line as it    es vacularity & haemorrhage.</td></tr><tr><td>Heterotopic pregnancy:<br/>Pt want pregnancy<br/>- Surgery<br/>Don’t want<br/>- Medical<br/>- KCL<br/>- Glucose<br/>- Metho</td><td>Suspected in:<br/>- Assisted reproduction.<br/>- I/U pregnancy + persistent pelvic pain,<br/>- Persistent    ed B – HCG after miscarriage or TOP.<br/>B – HCG:<br/>Limited value.<br/>No role.</td><td>Metho:<br/>If I/U pregnancy is non-viable.<br/>Women don’t wish to retain,<br/>Local injections:<br/>Of KCL or glucose with aspiration of G.S contents in stable pts.<br/>Surgical<br/>Unstable/stable pts.<br/>Expectant:<br/>Where USG findings r supportive of non-viable pregnancy</td><td></td></tr></tbody></table>', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
