INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-19d71653', 't-mm-07-004', 'text', 'Score:', 149) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e54a646b', 't-mm-07-004', 'text', 'Up to 6 – single Agent.', 150) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
