INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-930e6d5b', 't-mm-07-004', 'text', 'Followed by 6 days’ rest.', 152) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
