INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-57e194b1', 't-mm-08-008', 'html', '<table><tbody><tr><td></td><td>HTN<br/>HTN <160/110</td><td>Severe HTN<br/>B.P > 160/110</td><td>Pre eclampsia<br/>B.P < 160/110</td><td>Severe Eclampsia<br/>B.P > 160/110</td></tr><tr><td>Admission</td><td>* Not required</td><td>Admit till B.P < 160/110</td><td>Admit if clinical concerns.</td><td>Admit till B.P <160/110.</td></tr><tr><td>Anti-hypertensive</td><td>B.P > 140/90</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Target B.P</td><td>135/85 or less</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>B.P monitoring</td><td>1 – 2 times/ week<br/>(weekly)</td><td>Every 15 – 30 min till B.P <160/110</td><td>Twice/ thrice weekly (every 48 hours)</td><td>15 – 30 min till B.P <160/110 then 4 hourly.</td></tr><tr><td>Proteinuria</td><td>1 – 2/ week</td><td>Daily while admitted</td><td>Repeat if clinically indicated</td><td>If clinically indicated.</td></tr><tr><td>Blood Testing</td><td>Weekly</td><td>Weekly</td><td>twice/ week</td><td>thrice/ week</td></tr><tr><td>PIGE Testing</td><td>20 – 35 weeks</td><td>20 – 35 weeks</td><td></td><td></td></tr><tr><td>Fetal Assessment:</td></tr><tr><td>FHR Auscultation</td><td>Every visit</td><td>Every visit</td><td>Every visit</td><td>Every visit</td></tr><tr><td>CTG</td><td>If clinically indicated</td><td>@ diagnosis then if clinically indicated</td><td>@ diagnosis then if clinically indicated</td><td>@ diagnosis then if clinically indicated</td></tr><tr><td>USG</td><td>2 – 4 weeks</td><td>2 weeks</td><td>2 weeks</td><td>2 weeks</td></tr><tr><td>Timing of Birth: discussed below</td></tr><tr><td>Post Natal care</td><td>Ask about Epigastric pain and headache while checking B.P.</td></tr><tr><td>B.P monitoring</td><td></td><td></td><td></td></tr><tr><td>Daily for</td><td>2 days</td><td>2 days</td><td>On treatment:<br/>4 hourly during admission<br/>Every day or alternate days till 2weeks<br/>Without Treatment:<br/>4 hourly during admission<br/>Once for 3 – 5 days<br/>Alternate days till B.P is normal</td></tr><tr><td>Once for next</td><td>3 – 5 days</td><td>3 – 5 days</td><td></td></tr><tr><td>Once on day</td><td>15</td><td>15</td><td></td></tr><tr><td>Once in</td><td>6 – 8 weeks</td><td>6 – 8 weeks</td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td>Start Anti-Hypertensive if</td><td>B.P > 150/100</td><td>B.P > 150/100</td><td>B.P > 150/100<br/>B.P < 130/80<br/>*  48 – 72 hours after Birth.<br/>Normal => no need to repeat.<br/>U/A: 6 – 8 weeks => repeat 3m0 Postnatal.</td></tr><tr><td>Target B. P</td><td>B.P < 130/80</td><td>B.P < 130/80</td><td></td></tr><tr><td>Hematological Tests</td><td></td><td></td><td></td></tr></tbody></table>', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
