INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7ad80b0d', 't-mm-08-008', 'html', '<table><tbody><tr><td>Recurrence:</td><td>In current/ previous pregnancy</td></tr><tr><td>In future pregnancy</td><td>HTN</td><td>Pre-eclampsia</td><td>Gest HTN</td></tr><tr><td>HTN</td><td>21%</td><td>20%</td><td>22%</td></tr><tr><td>Pre-eclampsia</td><td>14%</td><td>- 16% overall - birth before 34 weeks 33%<br/>- after 34 – 37 weeks 23%.</td><td>7%</td></tr><tr><td>Gest HTN</td><td>9%</td><td>6 – 12%</td><td>11 – 15%</td></tr><tr><td>Chronic HTN</td><td>4%</td><td>2%</td><td>3%</td></tr></tbody></table>', 110) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
