INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2b8f8e02', 't-mm-08-011', 'text', 'Can be given if > 0.5IU/ml.', 86) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-81a5b382', 't-mm-08-011', 'text', 'Hemostatic defect corrected.', 87) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
