INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ab926c9b', 't-mm-08-011', 'text', 'Avoid.', 89) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c1bfabe5', 't-mm-08-011', 'text', 'I/M injection can be given where VWF activity and VIII levels > 0.5 IU/ml.', 90) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
