INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a1740d19', 't-mm-08-011', 'text', '3 days in SVD.', 93) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fef112f8', 't-mm-08-011', 'text', '5 days in C/S.', 94) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ba989211', 't-mm-08-011', 'text', 'Tranexamic acid 1g 3 – 4times/ day, 7 – 14days', 95) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d059605f', 't-mm-08-011', 'text', 'Sometimes 2 – 3 weeks or more.', 96) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
