INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3e976081', 't-mm-08-011', 'text', 'VWF concentrate required in type 3 for 3 weeks after delivery.', 98) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c3987986', 't-mm-08-011', 'text', 'Average time for PPH 10 – 20 days.', 99) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
