INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-22d50553', 't-mm-08-012', 'text', 'Homozygous 0.2 – 0.5%.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
