INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-34e194a3', 't-mm-08-012', 'text', 'XI, bleeding, tendency even with mild reduction.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
