INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ebd368c4', 't-mm-08-012', 'text', 'Booking, 3rd , prior to invasive procedure.', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-945fdba7', 't-mm-08-012', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aa3c4655', 't-mm-08-012', 'text', 'Levels don’t rise in pregnancy (usually).', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
