INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-878a8da9', 't-mm-08-012', 'text', 'Other compounding factors like VWF, Plt dysfunction.', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
