INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-58564c49', 't-mm-08-012', 'text', 'Minimal except homozygosity or compound heterozygote.', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-35ee5a04', 't-mm-08-012', 'text', 'No ICH, No need for PND.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
