INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b86b0cfb', 't-mm-08-012', 'text', 'Tranexamic Acid', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e11b1d59', 't-mm-08-012', 'text', 'Factor XI concentrate', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8a57b727', 't-mm-08-012', 'text', 'FFP', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f1070706', 't-mm-08-012', 'text', 'Tranexamic – never with factor XI concentrate => risk of thrombosis alone tranexamic acid is sufficient in most cases', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
