INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-25969b6f', 't-mm-08-012', 'text', 'Factor XI – concentrate; risk of thrombosis in factor XI inhibitors.', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-036bccea', 't-mm-08-012', 'text', 'rxIIa – can be used in inhibitors of XI', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fc1306e4', 't-mm-08-012', 'text', 'rxIIa use is off license, can be used carefully in low doses.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4f321f01', 't-mm-08-012', 'text', 'ANC, intrapartum and post-partum care:', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3606421d', 't-mm-08-012', 'text', 'factor XI or Tranexamic acid is not required antenatally unless an invasive procedure is undertaken or if there is bleeding following miscarriage or surgical procedure.', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e1ff6958', 't-mm-08-012', 'text', 'Delivery plan individualized', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-83b36336', 't-mm-08-012', 'text', 'Prophylactic factor XI replacement in homozygous or compound heterozygous, previous history of bleeding.', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-67e6f305', 't-mm-08-012', 'text', 'Central Neuraxial Anesthesia:', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bc440f8a', 't-mm-08-012', 'text', 'Don’t in women with low f – XI with bleeding phenotype.', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d9ca18cf', 't-mm-08-012', 'text', 'Phenotype is not clear.', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
