INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-08-013', 'chap-mm-08-01', '13.FIBRINOGEN DISORDERS', 'Detailed medical reference and study guide on 13.FIBRINOGEN DISORDERS.', 13, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
