INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6898af6a', 't-mm-08-013', 'text', 'Risks:', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4812665c', 't-mm-08-013', 'text', 'Afibrinogenemia –risk of ICH, PPH.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-50050235', 't-mm-08-013', 'text', 'Hypofibrinogenemia- dysfunction of coagulation – thrombosis and pregnancy loss.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-75dae532', 't-mm-08-013', 'text', 'Afibrinogenemia:', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f91a4c64', 't-mm-08-013', 'text', 'If fibrinogen < 0.3g/lit => prophylaxis with fibrinogen concentrate 50 – 100mg/kg – Twice/weeks, throughout the pregnancy', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
