INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7104b877', 't-mm-08-016', 'text', 'Spider nevi – 66% Caucasian, 11% black.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-49456bea', 't-mm-08-016', 'text', 'Pruritus- 18% with 80% recurrence.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c78d595f', 't-mm-08-016', 'text', 'Symmetrical lesion => endogenous cause.', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-84691dbe', 't-mm-08-016', 'html', '<table><tbody><tr><td>Dermatosis of  pregnancy</td><td>Affected area</td><td>Risk factors</td><td>Recurrence</td><td>Management</td><td>Pregnancy outcome</td></tr><tr><td>IHCP 0.7%</td><td>Scalp Anus, Vulva abdominal skin.</td><td>*Ethnicity: more in India,<br/>Pakistan.<br/>*Previous IHCP</td><td>60 – 70%</td><td>* Urso<br/>* Topical emollients.<br/>* Sedating anti histamine.<br/>* Water soluble vitamin K</td><td>Risk of:<br/>* IUD<br/>* Meconium<br/>* PPH.<br/>* Fetal distress.<br/>* C/S prematurity.</td></tr><tr><td>Atopic eruption of pregnancy:<br/>* Prurigo gestationis.<br/>* Prurigo Folliculitis.<br/>* Eczema of Pregnancy.<br/>* Nurse early onset Prurigo.<br/>Risk is 1/300</td><td>Erythematous/ excoriated<br/>nodules.<br/>Papules on<br/>Face, Neck, Chest<br/>Extensor surfaces.<br/>* Immune mediated.<br/>* Clinical diagnosis.</td><td>Family History</td><td>Limited data</td><td>* Topical emollients.<br/>* Anti pruritus.<br/>* Topical steroids<br/>* Anti Histamine, UV light.<br/>* 1% Menthol.<br/>* Benzoyl per oxide.<br/>* Erythromycin,<br/>* Zinc.</td><td>No Adverse effects.</td></tr><tr><td>* Polymorphic eruption of pregnancy PEP<br/>* 1/160 –1/300.<br/>*Pruritic, urticarial papules/ plaques of pregnancy.<br/>* Toxic erythema.<br/>* Nurse late onset.</td><td>Periumbilical sparing + sparing of palms, soles and face</td><td>PG, twins over distention.</td><td>Rarely occur</td><td>* Topical steroids (1st line)<br/>* Emollients.<br/>* Oral steroids.<br/>* Anti Histamine.</td><td>No adverse effect.</td></tr><tr><td>* Pemphigoid Gestationis<br/>* 1/700-1/50’000.<br/>* Herpes Gestationis.<br/>* Bullous pemphigoid.<br/>* Gestationis<br/>Pemphigoids.</td><td>* Bullous eruption.<br/>* Appears around umbilicus unlike PEP.<br/>* Mucosal sparing.<br/>* All over the body.<br/>* Biopsy necessary.<br/>* Two samples:<br/>1. Biopsy.<br/>2. Immune studies.<br/>* Flare @ time of delivery</td><td>Immunological HLA – DR3, DR4.</td><td>* Recurrence with earlier onset and increasing severity.<br/>* Recurrence with OCP and periods.</td><td>* Topical/ Oral steroid.<br/>* Anti Histamines<br/>* Antibiotics.<br/>* Immunosuppressive drugs.</td><td>* IUGR.<br/>* Pre – Term.<br/>* self-limiting.<br/>* Skin lesion in Neonates.</td></tr></tbody></table>', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ce0394c2', 't-mm-08-016', 'text', 'Table 33. DERMATOLOGICAL CONDITIONS OF PREGNANCY', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
