INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9c04cd34', 't-mm-08-021', 'text', 'IUD, Mirena, DMPA – not affected by Enzyme inducers, carbamazepine, topiramate, phenytoin, phenobarbital', 110) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
