INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-08-022', 'chap-mm-08-01', '22.CA BREAST IN PREGNANCY AND PREGNANCY FOLLOWING CA BREAST', 'Detailed medical reference and study guide on 22.CA BREAST IN PREGNANCY AND PREGNANCY FOLLOWING CA BREAST.', 22, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b4ac5133', 't-mm-08-022', 'text', '1 in 9 women has life time risk.', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0e5e44bb', 't-mm-08-022', 'text', 'Most common female cancer.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5ce426d4', 't-mm-08-022', 'text', 'Leading cause of death in between age 35 – 54 years.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0ef483ec', 't-mm-08-022', 'text', '15% diagnosed before 45 years.', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4e59fa5c', 't-mm-08-022', 'text', '10 – 20% cases associated with pregnancy or occur within 1 years after birth.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7ef29df0', 't-mm-08-022', 'text', '5 Years survival 80% <50 years of age.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-04523d84', 't-mm-08-022', 'text', 'CA Breast Diagnosed During Pregnancy:', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7258b924', 't-mm-08-022', 'text', 'Pregnancy itself don’t worse prognosis', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5a0fe426', 't-mm-08-022', 'text', 'Feeling of lump => refer to Breast specialist.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fab4d09b', 't-mm-08-022', 'text', 'Testing in conjunction with MDT team.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a0c3d1e8', 't-mm-08-022', 'text', 'Diagnosis:', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aacfbb1a', 't-mm-08-022', 'text', 'USG – 1st line.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d38b2598', 't-mm-08-022', 'text', 'Mammography:', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-171f530b', 't-mm-08-022', 'text', 'If cancer is confirmed, to assess the extent with shield.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4301ba44', 't-mm-08-022', 'text', 'Tissue Biopsy:', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7383b725', 't-mm-08-022', 'text', 'Not cytology because it is inconclusive in pregnancy due to normal proliferative changes.', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c074d1e9', 't-mm-08-022', 'text', 'H/P, receptor status, stage, Grade.', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5bf79f08', 't-mm-08-022', 'text', 'X – RAY chest and spine (bone involvement).', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bbc55499', 't-mm-08-022', 'text', 'liver USG – if needed.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-35f3440f', 't-mm-08-022', 'text', 'MRI with Gadolinium: done only if clinical concerns limited data on safety.', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c0f8bd74', 't-mm-08-022', 'text', 'Tumor makers – Not recommended – As they are misleading (CA 15-3, CA -125).', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-00afc807', 't-mm-08-022', 'text', 'CT, pelvic x - ray, NR as they have effect on baby.', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
