INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-03e71462', 't-mm-08-022', 'text', 'Wide local excision.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e3f62147', 't-mm-08-022', 'text', 'Sentinel node biopsy, if pre -op USG and needle biopsy has negative results then do S.N Biopsy.', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-91a06305', 't-mm-08-022', 'text', 'Avoid blue dye.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b3f445df', 't-mm-08-022', 'text', 'S.N biopsy => positive => axillary clearance.', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4908531b', 't-mm-08-022', 'text', 'MRM.', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3b0ffc8', 't-mm-08-022', 'text', 'Reconstruction is delayed till delivery.', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
