INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4345276d', 't-mm-08-022', 'text', 'If preservation of organ function is required like spinal cord compression by radio, then do with shield or after Iatrogenic delivery of baby.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
