INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4370f68d', 't-mm-08-022', 'text', '5HT3, Steroids => for emesis', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f2d0376a', 't-mm-08-022', 'text', 'Tamoxifen and trastuzumab (HER 2 new) contraindicated in pregnancy and lactation.', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-59409642', 't-mm-08-022', 'text', 'Birth:', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-53127fcd', 't-mm-08-022', 'text', 'MDT.', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f6a14151', 't-mm-08-022', 'text', 'Postpone delivery 2 – 3weeks after last chemo to avoid neutropenic crises.', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ee3afd6f', 't-mm-08-022', 'text', 'Lactation:', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-14742440', 't-mm-08-022', 'text', 'B.F on chemo is C/I – as it causes leukopenia & infection in neonates.', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-45e14dd0', 't-mm-08-022', 'text', 'Otherwise offered short duration in between chemo (14days after chemo).', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-88792edf', 't-mm-08-022', 'text', 'CC:', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3cd05710', 't-mm-08-022', 'text', 'Avoid hormonal CC => consider after 5 years free of recurrence.', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-64b8ccdc', 't-mm-08-022', 'text', 'Pregnancy Following CA – Breast:', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-013a5c2b', 't-mm-08-022', 'text', '<10% became pregnant following diagnosis of CA Breast:', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9ed35a60', 't-mm-08-022', 'text', 'Pre pregnancy:', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b05a2936', 't-mm-08-022', 'text', 'Consult:', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d6c2d0c4', 't-mm-08-022', 'text', 'Oncologist.', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4f8082b9', 't-mm-08-022', 'text', 'Surgeon.', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2c18205b', 't-mm-08-022', 'text', 'Obstetrician', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7f57bda4', 't-mm-08-022', 'text', 'Stop tamoxifen 3m0 before (washout period) long half-life.', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-873d58a5', 't-mm-08-022', 'text', 'CA with Mets => Avoid pregnancy as life expectancy is limited and treatment is compromised.', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e6a35fc9', 't-mm-08-022', 'text', 'Pregnancy don’t adversely affect long term survival.', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b4156f7f', 't-mm-08-022', 'text', 'Avoid pregnancy till 2 years after treatment (highest time for recurrence).', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-87c23574', 't-mm-08-022', 'text', 'Outcome of pregnancy after CA Breast No evidence available', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f13b85c9', 't-mm-08-022', 'text', 'Recommended tamoxifen treatment for CA Breast is 5 years.', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-110364e6', 't-mm-08-022', 'text', 'Ed risk of C/section.', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
