INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-94480da3', 't-mm-08-028', 'html', '<table><tbody><tr><td>Feature</td><td>HELLP</td><td>TTP/HUS</td><td>AFLP</td></tr><tr><td>Incidence</td><td>1/100<br/>10 – 30% of severe PE</td><td>1/25,000</td><td>3/100,000</td></tr><tr><td>Gestation</td><td>AP – 70%<br/>PP – 30%</td><td>TTP – 2nd, 3rd<br/>Hus – PP >75%</td><td>Biopsy shows tubular</td></tr><tr><td>Thrombocytopenia</td><td><10x109 – rare</td><td>Profound</td><td>Free fatty acid</td></tr><tr><td>LFT’S</td><td>transaminases</td><td>Normal transaminases<br/>Pre hepatic Bilirubin</td><td>Deposition</td></tr><tr><td>AKI</td><td>3 – 15%</td><td>30 – 80%</td><td>14%</td></tr><tr><td>Coagulopathy</td><td>20%</td><td>Elevated anti – Thrombin & Fibrinogen.</td><td>3.5% Require renal replacement<br/>- Low glucose<br/>- Raised ammonia<br/>Production - vomiting</td></tr><tr><td>ADAMTS - 13</td><td></td><td></td><td></td></tr><tr><td>complement</td><td>preset</td><td>Cause HUS<br/>Treatment:<br/>Eculizumab</td><td></td></tr></tbody></table>', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
