INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-853988a1', 't-mm-08-033', 'text', 'Fewer relapses and lower progression (Most relapses in 1st and 2nd ).', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
