INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e3ea6e38', 't-mm-08-033', 'text', 'A/N immunosuppression => spontaneous remission.', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
