INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-af331499', 't-mm-08-033', 'text', 'Pseudo relapse => flare up of all symptoms with greater intensity.', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c1bdaf19', 't-mm-08-033', 'text', 'B.F => reduce relapse 4-fold.', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e4d3825d', 't-mm-08-033', 'text', 'B.F =>   L.H =>   prolactin => anovulation =>   TNFα=>   CD4 cells.', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
