INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-be0b302c', 't-mm-08-034', 'html', '<table><tbody><tr><td>Lesions Above T4:<br/>Complete or partial<br/>paralysis of respiratory<br/>muscles.<br/>Difficultly initiation<br/>in B.F<br/>(Visual stimulation /<br/>I/V oxytocin).<br/>Lesions Above T6:<br/>Low baseline B.P.<br/>Low HR.<br/>Risk of Autonomic<br/>Dysreflexia: AD<br/>(emergency situation).<br/>Abnormal<br/>thermoregulation.<br/>No reactive shivering,<br/>sweating.<br/>Inadequate response<br/>to environmental<br/>temp change.<br/>Inflammation => febrile<br/>Response is<br/>Inadequate<br/>Above T10:<br/>Late pre – Term (15%)<br/>Unable to perceive labour pain.<br/>Unable to perceive FM.<br/>UTI.<br/>Above T12:<br/>malpresentation.<br/>Above L2 L4:<br/>- in adequate epidural Space.</td><td>Breathing more difficult during pregnancy.<br/>Resp function by vital capacity.<br/>Physiotherapy, continuous positive airway pressure CPAP, Mechanical ventilation.<br/>Vital capacity <12 – 15ml/kg => mechanical ventilation.<br/>Noxious stimuli => AD:<br/>Triggers<br/>Urinary: distention, calculi, blocked catheter, UTI.<br/>GI: Haemorrhoids, constipation, appendicitis,<br/>Skin: tight clothing, Blister, burns, ulcers.<br/>R.S: periods, intercourse.<br/>Others: DVT.<br/>S/S:<br/>Rise in B.P 20 – 40 diagnostic<br/>Nausea, vomiting, malaise, prickling sensation, thrombin headache, ringing in head.<br/>Sweating, blushing, piloerection, tremors, nasal congestion, increased spasm.<br/>Bradycardia, prolong PR internal AV Block disappearance of P WAVE, ventricular ECTOPIC BEATS.<br/>Fetal bradycardia.<br/>Treatment:<br/>Nifedipine S/L 10 – 40mg (1st line)<br/>(S/L or bite & swallow tablets).<br/>GTN patch/spray.<br/>Nitroglycerine.<br/>Labetalol<br/>Hydralazine<br/>Avoidance of triggers<br/>Hospital admission @ 36 + 6 weeks:<br/>CTG.<br/>U.C palpations every 4 hours.<br/>Manual perception of contraction.<br/>Bladder emptying and A/B for asymptomatic bacteriuria,<br/>ECV</td></tr></tbody></table>', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
