INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6ee17d1f', 't-mm-08-034', 'html', '<table><tbody><tr><td>system</td><td>Clinical Features</td><td>Management</td></tr><tr><td>Respiratory<br/>system</td><td>*   Breathing.<br/>*   Ability to cough.<br/>*    Bronchial secretions.<br/>*   Ventricular Perfusion miss match.<br/>*   Attacks of pneumonia.</td><td>- Physiotherapy.<br/>- CPAP.<br/>- Mechanical Ventilation.</td></tr><tr><td>CVS</td><td>*   Bradycardia 40 – 45<br/>*   Hypotension 80/50/</td><td>- Baseline recording of B.P & HR @ Booking & @ every AN visit.</td></tr><tr><td>Genitourinary</td><td>*   Risk of calculi:<br/>Urease producing bacterial infections.<br/>Immobilization.<br/>*   Risk of UTI:<br/>Long term catheter.<br/>Stasis and incontinence.<br/>*   Distended Bladder => trigger AD.</td><td>- Intermittent catheterization/ indwelling catheter/ Suprapubic.<br/>- suprapubic catheter => change before 24 hours of C/S.<br/>- keep bladder empty.</td></tr><tr><td>Bowels</td><td>*   Constipation<br/>*   Can trigger AD</td><td>- Fiber.<br/>- Timed bowel movements.<br/>- Laxative.<br/>- Gastro colic reflex utilization.<br/>- Digital evacuation.</td></tr><tr><td>Skin</td><td>*   Ulcers 6%.<br/>*   Atrophy.</td><td>- Skin Care.<br/>- Pressure reliving mattress.<br/>- Position change every 2 hours.</td></tr><tr><td>Bone</td><td>*   Osteoporosis</td><td></td></tr><tr><td>Endocrine</td><td>*   Risk of DM – 2.</td><td></td></tr><tr><td>Hematology</td><td>*   Normocytic, normochromic anemia.</td><td></td></tr><tr><td>Thrombosis</td><td>*   High risk in Acute SCI.</td><td>- score 1 for prophylaxis.</td></tr><tr><td>Psychological</td><td>*    mood disorders.</td><td></td></tr><tr><td>Neurological</td><td>*   Inability to respond appropriately<br/>To acute illness.</td><td></td></tr><tr><td>Neuromuscular</td><td>*   Spasticity.<br/>*   UMN – lesion.<br/>*   Below injury.<br/>*   12% worsening in pregnancy.</td><td>- Baclofen (intrathecal).<br/>- Oxybutynin.<br/>- Diazepam.</td></tr></tbody></table>', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
