INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-08-044', 'chap-mm-08-01', '38.1. MANAGEMENT OF HYPOTHYROIDISM AND RELATED DISORDERS', 'Detailed medical reference and study guide on 38.1. MANAGEMENT OF HYPOTHYROIDISM AND RELATED DISORDERS.', 44, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e1726dca', 't-mm-08-044', 'html', '<table><tbody><tr><td></td><td>OH<br/>Overt Hypothyroidism</td><td>SCH<br/>Sub – clinical Hypothyroidism</td><td>IH<br/>Isolated Hypothyroxinemia</td></tr><tr><td>Incidence</td><td>0.2 – 1%</td><td>2.2 – 10%</td><td>1.3 – 8%</td></tr><tr><td>Hormonal levels<br/>TSH<br/>fT4</td><td></td><td>Severe SCH TSH >10iu/ml<br/>(N)</td><td>N<br/><2.5 centile</td></tr><tr><td>Fetomaternal effects</td><td>Cognitive impairment<br/>Neuro –developmental delay<br/>Pre – term birth<br/>LBW</td><td>Pregnancy loss<br/>Pre – term birth<br/>LBW<br/>Neurological problems complications     es as TSH level      es >4.5 Iu/ml:<br/>Progression to OH 2 – 6%/ year progression is more if TPOAb are positive<br/>Pre – eclampsia<br/>Hypertension<br/>Placental abruption</td><td>Causes of IH:<br/>Obesity<br/>Iodine deficiency<br/>Iron deficiency<br/>Exposure to organochloride pesticides<br/>IH can cause placental Abruption.</td></tr><tr><td>Management:<br/>Pre – conception</td><td>Start/continue levothyroxine before pregnancy</td><td>Indication to start levothyroxine before pregnancy<br/>TSH > 10iu/L<br/>TPOAb positive</td><td>Refer to endocrinologist</td></tr><tr><td>Target TSH</td><td>< 2.5mu/L</td><td>< 2.5mu/L</td><td></td></tr><tr><td>Antenatal care<br/>Incremental doses in early pregnancy<br/>Need of incremental doses is @ around 5week so counsel the patient regarding self – increment.<br/>Newly diagnosed in pregnancy<br/>Ongoing monitoring in pregnancy<br/>40% need dose adjustment during pregnancy<br/>Aim of treatment</td><td>self-initiate an empirical     increase in dose of levothyroxine by 25 – 30% as soon as pregnancy is positive<br/>Double dose on two days of a week<br/>25ug/day increase if already taking dose <100ug/day<br/>50ug/day increase if already taking dose > 100ug/day.<br/>Start levothyroxine @ a dose of 1.6ug/kg per day.<br/>Repeat TFT in 4weeks after commencement of treatment.<br/>TSH and fT4 every 4 – 6weeks till 20 weeks then again @ 28 weeks.<br/>Keep TSH < 2.5mu/L and fT4 within normal trimester specific range. Purpose is<br/>To prevent transient abnormalities<br/>And prevent over treatment.</td><td>Severe SCH:<br/>Start levothyroxine @ dose 1.6ug/day<br/>Repeat TFT’S in 4 weeks.<br/>Mild – Mod SCH:<br/>(TSH < 10 MU/L)<br/>Start levothyroxine @ dose 1.0 – 1.2ug/kg/day<br/>OR<br/>Repeat TFT’s @ 4 – 6 weeks’ interval till 20 weeks and @ 28 weeks.<br/>4 – 6 weeks till 20 weeks then @ 28 weeks.<br/>TSH < 2.5mu/L</td><td>Levothyroxine is not recommended.<br/>Repeat TFT’s 4 – 6weeks after initial testing to ensure stability.</td></tr><tr><td>Post Natal<br/>Women taking levothyroxine pre – conceptionally<br/>Women not taking levothyroxine pre – conceptionally</td><td>Revert to pre – conception dose 2 weeks postpartum<br/>Stop and TFT’s 6 weeks postpartum</td><td>revert to pre – conception dose<br/>stop and TFT’S 6 weeks post-partum</td><td></td></tr></tbody></table>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-04715429', 't-mm-08-044', 'text', 'Table 36. MANAGEMENT OF HYPOTHYROIDISM AND RELATED DISORDERS', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
