INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-37bcc43a', 't-mm-08-045', 'text', 'These risks are directly related to severity of disease and duration of control in pregnancy.', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2334dee8', 't-mm-08-045', 'text', 'Optimal euthyroidism by treatment and antenatal care reduce obstetric risks except placental abruption.', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dcb79a8c', 't-mm-08-045', 'text', 'Pre – conceptional care:', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-25ac6f77', 't-mm-08-045', 'text', 'Pre – conceptional counselling is recommended in all women with hyperthyroidism in order to minimize adverse outcome.', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cac9d8c9', 't-mm-08-045', 'text', 'Discuss definitive treatment options', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d9ace0f0', 't-mm-08-045', 'text', 'SurgeryRadioactive Iodine - Definitive Treatment', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-28a61f0e', 't-mm-08-045', 'text', '1.Better option for              option.', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a5d23cb7', 't-mm-08-045', 'text', 'women with high            - Discuss with women', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3de5bd97', 't-mm-08-045', 'text', 'TSH receptor              with severe disease.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-639c93b0', 't-mm-08-045', 'text', 'antibiotics (TRAb)             -    es level of TRAb.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3ffbfb7d', 't-mm-08-045', 'text', '2.Definitive treatment', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-41f74159', 't-mm-08-045', 'text', 'option with lifelong            - Cause fetal thyrotoxi-', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bfaa5b9f', 't-mm-08-045', 'text', 'levothyroxine              cosis even maternal replacement.             thyroid level r normal', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f9cdc22b', 't-mm-08-045', 'text', 'Women with', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1107ccbd', 't-mm-08-045', 'text', 'Thyroidectomy follow guidelines on hypothyroidism in pregnancy', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-31e0eda1', 't-mm-08-045', 'text', '3.Discuss in women', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-87a6dd18', 't-mm-08-045', 'text', 'with severe disease', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a7180862', 't-mm-08-045', 'text', 'Cure is immediate', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-60441661', 't-mm-08-045', 'text', 'Discuss Adverse effects of Thyroid drugs:', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e8e2b757', 't-mm-08-045', 'text', 'Thioamides are main stay of treatment', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d6124033', 't-mm-08-045', 'text', 'Carbimazole CMZ – 20mg', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-85a37a2b', 't-mm-08-045', 'text', 'Methimazole MMI – 15mg', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5fe5d430', 't-mm-08-045', 'text', 'Propylthiouracil PTU', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-31a0b1cb', 't-mm-08-045', 'text', 'Minor adverse effects 3 – 5%', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b0a97bf8', 't-mm-08-045', 'text', 'Skin rash', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7e5a9054', 't-mm-08-045', 'text', 'Serious adverse effects:', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-85d79eeb', 't-mm-08-045', 'text', 'Liver failure 0.1% with PTU', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-29f1a5e4', 't-mm-08-045', 'text', 'Agranulocytosis 0.15% with either drug', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-121f2c7c', 't-mm-08-045', 'text', 'Potential teratogenic effects 2 – 4%', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-134b172f', 't-mm-08-045', 'text', 'CMZ and MMI cause:', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-69e74843', 't-mm-08-045', 'text', 'Embryopathy – dysmorphic features, aplasia cutis, choanal and esophageal atresia, abdominal wall defects, urinary and eye abnormalities, USD', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4cfb2883', 't-mm-08-045', 'text', 'More teratogenic effects if exposed during', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4ddfb742', 't-mm-08-045', 'text', '6 – 10 weeks of gestation.', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-444d1efc', 't-mm-08-045', 'text', 'PTU causes', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8730b54c', 't-mm-08-045', 'text', 'Less severe and potentially resolvable birth defects like 2 – 3% face and neck cysts', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-15237ea3', 't-mm-08-045', 'text', 'Urinary tract abnormalities.', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e6de47bd', 't-mm-08-045', 'text', 'Discontinuation of Drugs:', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ccb630ea', 't-mm-08-045', 'text', 'Discontinuation should be weighed against risk of hyperthyroidism flare in periconception period that has greatest effect on pregnancy.', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e854bd04', 't-mm-08-045', 'text', 'Switching of Drug:', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c71a3d98', 't-mm-08-045', 'text', 'Switch to PTU in preference to CMZ in lowest effective dose, keep fT4 in the upper half of reference range.', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6e11d9a5', 't-mm-08-045', 'text', 'Discuss effective contraception:', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3042571', 't-mm-08-045', 'text', 'Avoid pregnancy in:', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-68d4c943', 't-mm-08-045', 'text', 'Active, severe disease', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8271c5c4', 't-mm-08-045', 'text', '6 months’ post radiotherapy', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-43d332d7', 't-mm-08-045', 'text', '6 months’ post-surgery', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8279cc44', 't-mm-08-045', 'text', 'High level of TRAb especially if more than 3 times, as it causes fetal thyrotoxicosis', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1a1df3a1', 't-mm-08-045', 'text', 'At least 2 normal range fT4 levels @ least 3 months apart.', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-026b5bf1', 't-mm-08-045', 'text', 'Antenatal care:', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1aaa495f', 't-mm-08-045', 'text', 'Discontinuation of Drugs:', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2722b261', 't-mm-08-045', 'text', 'If women are euthyroid for > 6m0 on lower doses of anti – thyroid – CMZ < 10mg/day', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7683e64a', 't-mm-08-045', 'text', 'PTU < 200mg/day discontinue medicine before period of teratogenicity and gestational thyrotoxicosis i-e., 6 – 10weeks.', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e8b7066b', 't-mm-08-045', 'text', 'Switching of drugs during pregnancy', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-18fdbc3d', 't-mm-08-045', 'text', 'Switch to PTU before 10weeks', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7b03794b', 't-mm-08-045', 'text', 'Advised dose is 1:20 CMZ 10mg: PTU 200mg', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-176ab908', 't-mm-08-045', 'text', 'No benefit of switching after 10weeks.', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-53936b59', 't-mm-08-045', 'text', 'Switch to CMZ after 20 weeks because of risk of hepatotoxicity with PTU', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-29d27d3d', 't-mm-08-045', 'text', 'Recommended dose is 20: 1 PTU 200mg to target serum fT4 @ upper half of pregnancy specific range or total T4 @ 1 – 1.5 TIMES THE UPPER LIMIT OF non – pregnant reference range to minimize risk of fetal hypothyroidism.', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6362faa2', 't-mm-08-045', 'text', 'Monitoring of Thyroid function tests:', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0749fef2', 't-mm-08-045', 'text', 'Stable Thyroid function', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ffad1580', 't-mm-08-045', 'text', '2 – 4 weeks in 1st half of pregnancy', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-50e62911', 't-mm-08-045', 'text', '4 – 8 weekly after 20 weeks.', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-44a12230', 't-mm-08-045', 'text', 'Dose adjustment, switching or unstable thyroid function test – every 2 weeks.', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7def15a4', 't-mm-08-045', 'text', 'Dose titration should target fT4. It should never be based on TSH levels that may be low and fT3 or total T3 has no role', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-82e74a77', 't-mm-08-045', 'text', 'Stopping drug on normal fT4, measure fT4 2 – 4weekly on two consecutive occasions then monitor less frequently I – e., 4 – 8weekly.', 80) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d315051e', 't-mm-08-045', 'text', 'TRAb undetected or low at conception monitor TFT’s every 4 weeks until mid-trimester then 4 – 8 weeks after 20 weeks as in stable thyroid function tests', 81) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-29a3bef2', 't-mm-08-045', 'text', 'TRAb in all patients with hyperthyroidism in 1st trimester even definitive treatment has taken if positive then further monitoring @ 20 weeks and 28 weeks.', 82) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d87207f3', 't-mm-08-045', 'text', 'Toxic nodular goiter = more frequent monitoring as it is associated with fetal hypothyroidism due to lack of stimulation by TRAb so it is treated with lowest doses and keeping fT4 in upper limit of normal pregnancy range.', 83) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9ece8de1', 't-mm-08-045', 'text', 'Fetal monitoring:', 84) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-00041794', 't-mm-08-045', 'text', 'Anomaly scan if on anti – thyroid drugs – not all the anomalies are detected on USG.', 85) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e5757304', 't-mm-08-045', 'text', 'Serial fetal biometry and umbilical artery Doppler @ monthly intervals from 26 – 28weeks in following patients.', 86) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f7c665c0', 't-mm-08-045', 'text', 'Uncontrolled Graves’ dx requiring anti – thyroid drugs.', 87) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-892d3eda', 't-mm-08-045', 'text', 'TRAb 3 times above normal level', 88) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eeb57934', 't-mm-08-045', 'text', '2 – 4 weekly FHR auscultation to check fetal tachycardia if FHR > 170bpm for 10min then start surveillance earlier I – e., from 20 weeks', 89) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0a179363', 't-mm-08-045', 'text', 'Birth:', 90) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-814a9a37', 't-mm-08-045', 'text', 'According to obstetric indication', 91) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f9b6e340', 't-mm-08-045', 'text', 'Fetomaternal monitoring also depends on obstetric problems.', 92) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb5abc68', 't-mm-08-045', 'text', 'Block and replace regimens:', 93) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e1921b7e', 't-mm-08-045', 'text', 'Not recommended in hyperthyroidism due to increased Fetomaternal risk. Anti-thyroid cross placenta more effectively than levothyroxine and can cause fetal hypothyroidism and its sequalae.', 94) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-46d8c32c', 't-mm-08-045', 'text', 'Only indication is isolated fetal hyperthyroidism.', 95) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0aaefd1d', 't-mm-08-045', 'text', 'Antenatal Thyroidectomy:', 96) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9f67b5fd', 't-mm-08-045', 'text', 'Potential compromise of airway', 97) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-98ca7d05', 't-mm-08-045', 'text', 'Done in 2nd trimester', 98) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8b294b95', 't-mm-08-045', 'text', 'After 22 weeks’ risk of pre – term', 99) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-42fb72bf', 't-mm-08-045', 'text', 'Close peri – op monitoring of fT4 and calcium is needed to minimize risk', 100) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-54ede3d0', 't-mm-08-045', 'text', 'B – Adrenergic blocking agents like propranolol can be used temporarily to control hyperthyroid symptoms in lowest effective doses and for short duration to minimize the risk of SGA.', 101) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e56a2d89', 't-mm-08-045', 'text', 'Neonatal Monitoring:', 102) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a5fdc102', 't-mm-08-045', 'text', 'TFT’s @ birth and @ 1 – 2weeks after birth in following:', 103) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-02ded3ff', 't-mm-08-045', 'text', 'If mother has taken Anti – thyroid drugs during pregnancy for Graves’ dx', 104) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-02b00553', 't-mm-08-045', 'text', 'Ed TRAb in mother during pregnancy.', 105) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d19a2598', 't-mm-08-045', 'image', '/uploads/content-images/maternal_mind_book/image106.emf', 106) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-325e81a8', 't-mm-08-045', 'text', 'Differences between Gestational transient Thyrotoxicosis GTT and Graves’ hyperthyroid disease:', 107) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
