INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ab032279', 't-mm-08-047', 'html', '<table><tbody><tr><td>Features</td><td>Graves’ disease</td><td>PPT</td></tr><tr><td>1. Thyrotoxicosis symptoms moss commonly @</td><td>6m0 PP</td><td>3m0 PP</td></tr><tr><td>2. Ophthalmopathy</td><td>Present</td><td>Absent</td></tr><tr><td>3. TRAb</td><td>Present</td><td>Absent</td></tr><tr><td>4. Large goiter with bruit</td><td>Present</td><td>--</td></tr><tr><td>5. Ratio of T4:T3</td><td>--</td><td>RAISED</td></tr><tr><td>6. Uptake of radioactive isotopes</td><td></td><td>Low</td></tr><tr><td>7. USG</td><td>Diffuse hypoechoic and heterogeneous texture, increased    blood flow</td><td>Non – homogenous hypoechogenic texture, reduced    blood flow</td></tr><tr><td>8. Histopathology</td><td>- Patchy infiltrate<br/>- Follicular cell hyperplasia</td><td>Lymphocytic infiltrate is diffuse</td></tr></tbody></table>', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
