INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e254ebef', 't-mm-09-006', 'text', 'Treat for G negative bacteria.', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cbdcc0af', 't-mm-09-006', 'text', 'Artesunate I/V 2.4mg/kg @ 0, 12, 24hours’ stat dose (drugs of choice any Gestation, then daily till patient is stable).', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2e3d396c', 't-mm-09-006', 'text', 'Quinine I/V 20mg/ kg in 5% D/W over 4 hours. Then 100mg/kg every 8 hours then oral when Pt can swallow.', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e0d7f831', 't-mm-09-006', 'text', 'Uncomplicated:', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f626aa53', 't-mm-09-006', 'text', 'Admit in ward', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-409a776b', 't-mm-09-006', 'text', '<2% parasitemia', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d9fb763c', 't-mm-09-006', 'text', 'Mortality 0.1%', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-58811cf3', 't-mm-09-006', 'text', 'Quinine 600mg 8 hourly + clindamycin 450mg 8 hourly (before 13 weeks drug of choice).', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-93972e8b', 't-mm-09-006', 'text', 'OR', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e73f769b', 't-mm-09-006', 'text', 'Raiment 4-tab, B.D for 3days.', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-923f812b', 't-mm-09-006', 'text', 'OR', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1287c587', 't-mm-09-006', 'text', 'Proguanil + Atovaquone (malarone) 4 doses daily – 3 days.', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-82f68d31', 't-mm-09-006', 'text', 'Some important points about Malaria:', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1f693276', 't-mm-09-006', 'text', 'Expert advice (especially recurrent & severe).', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-779010ec', 't-mm-09-006', 'text', 'Rapid detection negative in low parasitemia & P – vivax.', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2478e3a8', 't-mm-09-006', 'text', 'Gold std microscopy thin/thick film.', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-67f3cb94', 't-mm-09-006', 'text', 'Rapid detection followed by microscopy (Number of infected cells, species, stage).', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d768619b', 't-mm-09-006', 'text', 'Premunition: Natural immunity acquired against malaria.', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-026f438a', 't-mm-09-006', 'text', 'Low premunition – 90% with low premunition develop anemia.', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c7bf2b60', 't-mm-09-006', 'text', 'UK population low premonition.', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-df58338c', 't-mm-09-006', 'text', 'Relapses – due to planta sequestration:', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e7e42261', 't-mm-09-006', 'text', '25 – 42 days’ average, relapse time', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d6b48f47', 't-mm-09-006', 'text', '85 days after quinine.', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6b671160', 't-mm-09-006', 'text', '98 days after Artesunate.', 80) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cc684509', 't-mm-09-006', 'text', '63 days with artemether, lumefantrine', 81) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f8da129a', 't-mm-09-006', 'text', 'Weekly films – reduces mortality due to recurrence.', 82) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9ece4f08', 't-mm-09-006', 'text', 'treatment of recurrence => artesunate 84% success. Artesunate 100mg/ day for 7 days + clindamycin 45mg TDS – 7 days (WHO recommendation for relapse).', 83) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
