INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ba9ae63a', 't-mm-09-006', 'text', 'Inform womenregarding S/S ofmalaria in Baby.', 124) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-534427b6', 't-mm-09-006', 'text', '=> All Neonates of mother who had malaria inpregnancy had blood films @birth & weeklyblood films for28 days.', 125) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
