INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1c6863ad', 't-mm-09-007', 'text', 'Shorten II0 stage if hypoxic/ exhausted.', 88) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f2f36388', 't-mm-09-007', 'text', 'Obstetrician involvement.', 89) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ae9ed61f', 't-mm-09-007', 'text', 'Water birth:', 90) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3c169b24', 't-mm-09-007', 'text', 'Asymptomatic can have water birth', 91) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-533331a4', 't-mm-09-007', 'text', 'Cough, fever, feeling unwell avoid', 92) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5697beb8', 't-mm-09-007', 'text', 'Transmission – unknown in water.', 93) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c045bf69', 't-mm-09-007', 'text', 'PPE less effective when wet.', 94) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d1d7846c', 't-mm-09-007', 'text', 'Analgesia:', 95) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-784b272d', 't-mm-09-007', 'text', 'Entonox with mask can be given', 96) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6e0ac167', 't-mm-09-007', 'text', 'Epidural – informed discussion.', 97) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f1482b14', 't-mm-09-007', 'text', 'Positive elective procedures @ end of list.', 98) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-144a5568', 't-mm-09-007', 'text', 'Emergency c/s of positive COVID woman is done in 2nd theatre followed by full cleaning.', 99) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9c62b160', 't-mm-09-007', 'text', 'PNC:', 100) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-da5b7fd9', 't-mm-09-007', 'text', 'B.F is safe even confirmed COVID.', 101) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7d437041', 't-mm-09-007', 'text', 'Rooming in.', 102) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-24b64407', 't-mm-09-007', 'text', 'Kangaroo Mother care can be done', 103) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9ae73134', 't-mm-09-007', 'text', 'Deterioration of COVID in pregnancy:', 104) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c35f18ed', 't-mm-09-007', 'text', 'Consider bacterial infection if TLC is increasing', 105) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb81aa82', 't-mm-09-007', 'text', 'Don’t assume pyrexia as COVID.', 106) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-465895e6', 't-mm-09-007', 'text', 'Consider other possibilities.', 107) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8f4b57bc', 't-mm-09-007', 'text', 'Inpatient criteria:', 108) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7c8c570b', 't-mm-09-007', 'text', 'One of the following:', 109) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8a4d2e4b', 't-mm-09-007', 'text', 'Loss of smell.', 110) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d53d8a53', 't-mm-09-007', 'text', 'Clinical/ Radiological pneumonia.', 111) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bc1452bb', 't-mm-09-007', 'text', 'ARDS.', 112) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a555a3f7', 't-mm-09-007', 'text', 'Fever > 37.8 + cough or nasal discharge/ cough or SOB or sore throat or sneezing wheezing.', 113) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66be4ade', 't-mm-09-007', 'text', 'X – ray, CT:', 114) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d69ca52e', 't-mm-09-007', 'text', 'Chest pain, worsening hypoxia, RR > 22.', 115) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5a59a5b1', 't-mm-09-007', 'text', 'Consider pulmonary embolism/ Heart Failure.', 116) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-25ab8e06', 't-mm-09-007', 'text', 'Treatment of deteriorating COVID:', 117) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-01316946', 't-mm-09-007', 'text', 'Warning signs Escalate urgently:', 118) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8b8556dc', 't-mm-09-007', 'text', 'O2 requirement above 40%.', 119) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9036a9f7', 't-mm-09-007', 'text', 'RR > 30.', 120) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c9f6bd84', 't-mm-09-007', 'text', 'oliguria', 121) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9d1c1de5', 't-mm-09-007', 'text', 'AKI', 122) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-15ee6262', 't-mm-09-007', 'text', 'Drowsiness even O2 sat are normal.', 123) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96e87808', 't-mm-09-007', 'text', 'Fluid balance – given in boluses 250 – 500ml – assess fluid overload.', 124) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-061cd5bc', 't-mm-09-007', 'text', 'Keep low threshold for antibiotics.', 125) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e1e32d55', 't-mm-09-007', 'text', 'MDT', 126) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-808ce19a', 't-mm-09-007', 'text', 'Physician.', 127) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b6062735', 't-mm-09-007', 'text', 'Obstetrician + midwife.', 128) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-49a3d7ae', 't-mm-09-007', 'text', 'Anesthetist.', 129) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-41d010d0', 't-mm-09-007', 'text', 'Neonatologist.', 130) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c89999bf', 't-mm-09-007', 'text', 'VTE – thrombocytopenia < 50 => stop aspirin & LMWH + seek neonatologist opinion.', 131) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-55a40bfc', 't-mm-09-007', 'text', 'Steroids:', 132) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7205a9f5', 't-mm-09-007', 'text', 'Prednisolone – 40mg OD orally for 10days or during Hospital admission whichever is sooner.', 133) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f4171ea3', 't-mm-09-007', 'text', 'Hydrocortisone – 8mg B.D I/v.', 134) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-26d4cbba', 't-mm-09-007', 'text', 'Consider antiviral remdesivir.', 135) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0665d215', 't-mm-09-007', 'text', 'Feto maternal assessment and plan of delivery if required.', 136) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d01283b6', 't-mm-09-007', 'text', 'Steroid + Mgso4 for PTB => should not delay.', 137) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b8fc34b6', 't-mm-09-007', 'text', 'Young women can compensate for deteriorating respiratory function and have normal O2 saturation. They collapse suddenly.', 138) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-418e3821', 't-mm-09-007', 'text', 'Vaccination is safe and recommended', 139) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7d876d87', 't-mm-09-007', 'text', 'Acute COVID – 19 care pathways', 140) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5631a80a', 't-mm-09-007', 'image', '/uploads/content-images/maternal_mind_book/image117.png', 141) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
