INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e894f80e', 't-mm-09-009', 'text', 'Within 2 days of birth.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5b2d85a7', 't-mm-09-009', 'text', 'Acquired from placenta.', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-48952b38', 't-mm-09-009', 'text', 'Presents with septicemia and meningitis.', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d5d26c0e', 't-mm-09-009', 'text', 'Late onset:', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
