INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7d06b306', 't-mm-09-009', 'text', 'Acquired during child birth through birth canal.', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4bdc1d4a', 't-mm-09-009', 'text', 'Presents with meningitis.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f939e50c', 't-mm-09-009', 'text', 'Diagnosis:', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5bd1584a', 't-mm-09-009', 'text', 'Mother: blood culture, gram staining.', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ba5c6cf1', 't-mm-09-009', 'text', 'Baby: urine, amniotic fluid', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-89babc87', 't-mm-09-009', 'text', 'Culture', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cf5252df', 't-mm-09-009', 'text', 'Difficult to isolate from tissues.', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-26e121c5', 't-mm-09-009', 'text', 'Can be isolated from body fluids.', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7f033c8f', 't-mm-09-009', 'text', 'Treatment:', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-794d4e5b', 't-mm-09-009', 'text', 'I/V ampicillin + gentamycin.', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fbdcc660', 't-mm-09-009', 'text', 'If allergic => Then trimethoprim/ sulfamethoxazole or Erythromycin.', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-33651ecb', 't-mm-09-009', 'text', 'Avoid cheese, don’t reheat left over food.', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
