INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b89e83f2', 't-mm-09-015', 'text', 'Points to be noted in History:', 112) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2af0ea3b', 't-mm-09-015', 'html', '<table><tbody><tr><td>History</td><td>Symptoms/ features.</td><td>Organism suspected</td></tr><tr><td>Febrile illness.</td><td>Chills, Myalgia rigors.</td><td>Wound/Rash => staphylococcus, streptococcus.<br/>UTI/ Catheterization => Gram positive.<br/>Flue => influenza.<br/>Foreign travel => SARS – COV-2, Adenovirus, Malaria, Homorganic fever.</td></tr><tr><td>Contact with GAS</td><td>Tonsillitis, impetigo.<br/>Cellulitis, vomiting.<br/>Rapid deterioration.<br/>Severe pain</td><td>GAS</td></tr><tr><td>Skin infection or contact with boil/ Abscess.</td><td>Abscess, mastitis.<br/>Infected Scars.<br/>Purulent discharge.</td><td>PVL producing staph aureus.</td></tr><tr><td>Dysuria flank pain fever</td><td>Dysuria suggesting UTI</td><td></td></tr><tr><td>Urinary retention</td><td>Acute retention.<br/>Vulval/ sacral Pain.</td><td>HSV.</td></tr><tr><td>I/V misuse.</td><td>Vasculitis lesion.<br/>Endocarditis.</td><td>GAS.<br/>PVL producing s. Aureus.<br/>HIV, HBV, HCV.</td></tr><tr><td>Gastroenteritis.</td><td>Diarrhea<br/>Vomiting</td><td>Salmonella.<br/>Campylobacter (crampy abdominal Pain).<br/>Norovirus.<br/>Early toxic shock (staph and Strep exotoxins act as antitoxins).<br/>C – difficile (if recent A/B).</td></tr><tr><td>Zoonotic infectious.</td><td>Using unpasteurized milk.<br/>Under cooked meat.<br/>Exposure to animal diarrhea.<br/>Contact with birthing animals.<br/>Feeding lambs.<br/>Bird contact.</td><td>Salmonella.<br/>Campylobacter<br/>Listeria.<br/>C – difficile.</td></tr><tr><td>Haemorrhagic rash / purpa.</td><td></td><td>Meningococcal.<br/>Pneumonia.<br/>GAS.</td></tr></tbody></table>', 113) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d1e8c853', 't-mm-09-015', 'text', 'Rule out Allergies to A/B:', 114) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2bd332fc', 't-mm-09-015', 'text', 'Careful history Nausea/ Vomiting => intolerance not allergy.', 115) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b2636f08', 't-mm-09-015', 'text', 'Mild rash with penicillin => 1 – 3% are allergic to cephalosporins/ Cross reaction.', 116) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4ff83ee3', 't-mm-09-015', 'text', 'Anaphylaxis with penicillin => Avoid', 117) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1850f362', 't-mm-09-015', 'text', '- Cephalosporin.', 118) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-36bb2389', 't-mm-09-015', 'text', '- carbapenem.', 119) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3b3d6186', 't-mm-09-015', 'text', 'Discuss: infection specialist.', 120) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-97e85756', 't-mm-09-015', 'text', 'Alterative: Erythromycin, clindamycin, vancomycin.', 121) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4e157f19', 't-mm-09-015', 'text', 'Potential sites outside the Genital Track & their Presentation:', 122) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cf777338', 't-mm-09-015', 'html', '<table><tbody><tr><td>Site</td><td>Diseases</td><td>Clinical Features</td></tr><tr><td>Head</td><td>Meningitis.<br/>Meninges encephalitis</td><td>Photophobia.<br/>Neck stiffness.<br/>Altered conscious status.<br/>Delirium.<br/>Focal neurological seizers.</td></tr><tr><td>ENT</td><td>Otitis media<br/>Sinusitis.<br/>Pharyngitis.<br/>Laryngitis</td><td>Earache.<br/>Muffled hearing.<br/>Purulent nasal discharge.<br/>Fascial pain.<br/>Hoarse voice.<br/>Headache.<br/>Lymphadenopathy.<br/>Sore throat.</td></tr><tr><td>Chest</td><td>Pneumonia</td><td>Cough with sputum.<br/>Chest pain.<br/>Hypoxia.</td></tr><tr><td>Hepatic Biliary</td><td>Cholecystitis.<br/>Cholangitis Pancreatitis.</td><td>Rt upper quadrant pain.<br/>Murphy’s sign positive<br/>Pain radiates to back.</td></tr><tr><td>Abdomen</td><td>Gastroenteritis<br/>Appendicitis<br/>Bowel perfection.</td><td>Diarrhea.<br/>Vomiting.<br/>MC Burney sign +.<br/>Atypical presentation.<br/>Acute abdomen.</td></tr><tr><td>Breast</td><td>Mastitis<br/>Abscess<br/>Necrotizing Fasciitis</td><td>Pain.<br/>Burning.<br/>Inflammation in breast.</td></tr><tr><td>Urinary tract</td><td>UTI pyelonephritis<br/>Herpes</td><td>Dysuria, loin pain.<br/>Hematoma.<br/>Urinary retention.</td></tr><tr><td>Reginal anesthesia related infection</td><td>Meningitis.<br/>Spinal abscess</td><td>Headache.<br/>Focal neurology.<br/>Photophobia.<br/>Back pain<br/>permanent spinal cord or cauda equina damage.</td></tr><tr><td>Wond infection</td><td>C – section<br/>Episiotomy wound.<br/>VTE.<br/>I/V cannula site.</td><td>Skin and soft tissue infections.</td></tr><tr><td>Necrotizing fasciitis</td><td>N. F</td><td>Agonizing pain requiring increasing analgesia.<br/>Initially no obvious signs.<br/>Later may have blisters and bruises.</td></tr></tbody></table>', 123) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-219188db', 't-mm-09-015', 'text', 'Table 37. Potential sites outside the Genital Track & their Presentation:', 124) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b1efb131', 't-mm-09-015', 'text', 'Management:', 125) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7e7f2feb', 't-mm-09-015', 'text', 'MDT:', 126) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fe95b86f', 't-mm-09-015', 'text', 'Senior obstetrician', 127) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-11f261c8', 't-mm-09-015', 'text', 'Senior anesthetistwithin 1 hour', 128) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-59701ead', 't-mm-09-015', 'text', 'Senior Midwife', 129) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-554d78eb', 't-mm-09-015', 'text', 'Expert MDT:', 130) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-11e7f811', 't-mm-09-015', 'text', 'urgently if sepsis not responding to initial management.', 131) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-19386776', 't-mm-09-015', 'text', 'Critical care Team:', 132) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c181f737', 't-mm-09-015', 'text', 'Urgent referral in severe or rapidly deteriorating cases of sepsis.', 133) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fcffc555', 't-mm-09-015', 'text', 'Indications for Transfer to ICU:', 134) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-31329360', 't-mm-09-015', 'text', 'CVS:', 135) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-922d26c6', 't-mm-09-015', 'text', 'Hypotension < 90 mmHg systolic.', 136) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3d9263c2', 't-mm-09-015', 'text', 'Lactate > 4 mmol/lit persistent despite fluids resuscitation.', 137) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0656997e', 't-mm-09-015', 'text', 'Suggesting need for vasopressor/ inotropic support.', 138) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4384b566', 't-mm-09-015', 'text', 'Respiratory:', 139) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-258ab7a7', 't-mm-09-015', 'text', 'Pulmonary edema.', 140) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-67fd52b9', 't-mm-09-015', 'text', 'Need for mechanical ventilation.', 141) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d73d9808', 't-mm-09-015', 'text', 'Need for airway protection.', 142) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-27763b15', 't-mm-09-015', 'text', 'Renal:', 143) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c3688c32', 't-mm-09-015', 'text', 'Renal replacement Therapy.', 144) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-003e8c7d', 't-mm-09-015', 'text', 'Neurological:', 145) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-42712f0a', 't-mm-09-015', 'text', 'Conscious level.', 146) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-46a9e6dd', 't-mm-09-015', 'text', 'Miscellaneous:', 147) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3ad78ff8', 't-mm-09-015', 'text', 'MOD', 148) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-832ecd39', 't-mm-09-015', 'text', 'Uncorrected acidosis.', 149) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e7e46b8c', 't-mm-09-015', 'text', 'Hypothermia.', 150) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c4bb5808', 't-mm-09-015', 'text', 'Surviving sepsis campaign Hour – 1 Bundle of care:', 151) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e21e9735', 't-mm-09-015', 'text', 'Measure lactate. (Re measure if > 2mmol/ lit within 1 hour).', 152) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-92ba30e1', 't-mm-09-015', 'text', 'Obtain blood cultures.', 153) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5b9ae3ff', 't-mm-09-015', 'text', 'Broad spectrum antibiotics.', 154) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3bcb71de', 't-mm-09-015', 'text', 'I/V fluids 30ml/kg crystalloids if lactate > 4.', 155) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-de45be30', 't-mm-09-015', 'text', 'Apply vasopressors if hypotension after fluid resuscitation to maintain B.P MAP > 65mnHg.', 156) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-83de072d', 't-mm-09-015', 'text', 'Antibiotics:', 157) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6856c27c', 't-mm-09-015', 'text', 'I/V Antibiotics within 1 hour in women @ high risk of sepsis or septic shock.', 158) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c020a981', 't-mm-09-015', 'text', 'Use of sepsis bundle improve compliance with urgent management.', 159) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a37e5aa8', 't-mm-09-015', 'text', 'Early fluid resuscitation of crystalloids with immediate bolus of 500ml in women with hypotension and lactate > 4mmol, urine output be strictly monitored with urometer – 1 hourly.', 160) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f95f092d', 't-mm-09-015', 'text', 'Choice of A/B depends upon local epidemiology.', 161) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-00c6e34b', 't-mm-09-015', 'text', 'Where sensitivity not known = piperacillin/ tazobactam or Meropenem (for G – negative) plus clindamycin (for G – positive + Anaerobes) provide very broad cover.', 162) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9e823cc4', 't-mm-09-015', 'text', 'Vancomycin is advisable in case of MRSA.', 163) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5099c6a9', 't-mm-09-015', 'text', 'Switch to specific antibiotics in case availability of culture reports.', 164) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-18ddde46', 't-mm-09-015', 'text', 'Add I/V Acyclovir 500mg TDS, as part of 2nd line A/B in case of maternal deterioration with 1st line cover.', 165) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-606197c1', 't-mm-09-015', 'text', 'Pyrexia in labor > 380C or high => GBS prophylaxis.', 166) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-84538a35', 't-mm-09-015', 'text', 'Consider VTE propylene in sepsis.', 167) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-84967e64', 't-mm-09-015', 'text', 'Necrotizing Fasciitis:', 168) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ec42f2dd', 't-mm-09-015', 'text', 'Post birth wound can lead to serious abdominal or perineal N.F.', 169) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3006a4b3', 't-mm-09-015', 'text', 'Infection causing necrosis of superficial and deep and sub cutaneous tissues.', 170) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-303e0a0e', 't-mm-09-015', 'text', '1.8/1000 C/section can lead to N.F.', 171) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6a34cc87', 't-mm-09-015', 'text', 'Rapid for by GAS.', 172) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d7dfd641', 't-mm-09-015', 'text', 'Spread is hematogenous or direct.', 173) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b6b480e0', 't-mm-09-015', 'text', 'Visible signs are in later stages.', 174) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d9514ef5', 't-mm-09-015', 'text', 'Require increasing analgesic.', 175) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dcb48540', 't-mm-09-015', 'text', 'increasing and out of proportion pain due to edema and thrombosis of arterial supply to nerves leading to increasing demand of analgesia.', 176) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-40c21c92', 't-mm-09-015', 'text', 'Obvious signs are later – bruises, Blisters.', 177) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bdf0e4b8', 't-mm-09-015', 'text', 'Urgent involvement of plastic surgeon, intensivist, and infection specialist.', 178) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-540208e0', 't-mm-09-015', 'text', 'Treatment:', 179) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-464ccc80', 't-mm-09-015', 'text', 'Piperacillin – tazobactam', 180) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-69f7a930', 't-mm-09-015', 'text', 'OR          + clindamycin + Meropenem                       vanco in case of', 181) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-20704cd8', 't-mm-09-015', 'text', 'MRSA.', 182) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c7bb3664', 't-mm-09-015', 'text', 'Clindamycin => switch off exotoxin.', 183) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8b7c52ea', 't-mm-09-015', 'text', 'MRSA => vancomycin should be added.', 184) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-815ccec8', 't-mm-09-015', 'text', 'Streptococcal Toxic Shock Syndrome < 50% pts have classical sunburn rash.', 185) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1fa77353', 't-mm-09-015', 'text', 'Staph TSS => 100% sun burn rash.', 186) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8aec398b', 't-mm-09-015', 'text', 'Resistance to these A/B or allergies => consult infection specialist.', 187) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-336fd952', 't-mm-09-015', 'text', '(P – T – O)', 188) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-538af738', 't-mm-09-015', 'text', 'Table 38. Important points regarding Antibiotics:', 189) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-82088baf', 't-mm-09-015', 'html', '<table><tbody><tr><td></td><td>Spectrum</td><td>Points</td></tr><tr><td>Co – amoxiclav</td><td>No activity against MRSA or Pseudomonas Active against most streptococci, staphylococci (MSSA) anaerobes and many Gram negatives</td><td>Concern about an increase in the risk of necrotizing enterocolitis in babies exposed to co-amoxiclav in utero</td></tr><tr><td>Metronidazole</td><td>Only covers anaerobes</td><td>Unnecessary if using clindamycin and piperacillin-tazobactam as each covers anaerobes well<br/>Used with e.g. cefotaxime as intrapartum prophylaxis for suspected chorioamnionitis if non-severe penicillin allergy</td></tr><tr><td>Clindamycin</td><td>covers most GAS (>89%) ; GBS (67%) so should no longer be used for GBS prophylaxis , Covers most staphylococci, including<br/>many MRSA. and anaerobes Switches off exotoxin production<br/>Not renally excreted or nephrotoxic</td><td>Associated with increased risk of Clostridium difficile superinfection</td></tr><tr><td>Piperacillin – tazobactam.</td><td>Spectrum same as co-amoxiclav, but also many Gram positive and Gram-negative organisms, including pseudomonas<br/>No activity against MRSA<br/>Renal sparing (in contrast to aminoglycosides)<br/>Poor activity against ESBL, producing coliforms</td><td>Avoid in beta-lactam allergy Very poor CSF penetration</td></tr><tr><td>Cephalosporins e.g. ceftriaxone.</td><td>No activity against ESBL producing coliforms, pseudomonas or MRSA<br/>Cover beta-haemolytic streptococci including GAS and GBS (but not enterococci)</td><td>Should not be used if severe beta-lactam allergy Increased risk of C. difficle</td></tr><tr><td>Carbapenems</td><td>Very broad empirical cover, most Gram-negatives (including most ESBL-producers, anaerobes) Covers most Gram positives except MRSA CPE are resistant.</td><td>Not for severe beta-lactam allergy With moderate beta-lactam allergy <1% cross reaction<br/>Excellent penetration including CSF</td></tr><tr><td>Gentamicin</td><td>Mainly Gram negative cover (including most pseudomonas)<br/>No streptococcal, or anerobic cover</td><td>Inactivated in pus/anaerobic conditions Nephrotoxic and ototoxic, so usually limited where possible to a stat dose for sepsis. (For endocarditis a lower dose is given twice daily. and then serum levels must be monitored)</td></tr><tr><td>Vancomycin</td><td>Covers MRSA. Recommended option in severe penicillin allergy for GBS prophylaxis.<br/>No cover for Gram negatives.<br/>Not absorbed orally, so always given intravenously unless treating C.difficile infection.</td><td>Serum levels need to be monitored due to the potential for renal and ototoxicity.<br/>Too rapid infusion can cause "red man syndrome" due to histamine release.</td></tr></tbody></table>', 190) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4d29cfeb', 't-mm-09-015', 'text', 'Spectra of Antibiotics:', 191) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
