INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8c66b9b7', 't-mm-09-015', 'text', 'Role of immunoglobulins:', 194) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d32525e9', 't-mm-09-015', 'text', 'I/V immunoglobulins should be considering as part of treatment for G positive and Toxic Shock Syndrome when other measure are failing.', 195) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-80501b93', 't-mm-09-015', 'text', 'Not effective for G negative or sepsis in general.', 196) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f93649c3', 't-mm-09-015', 'text', 'Limited use in sickest women', 197) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e392115b', 't-mm-09-015', 'text', 'Use in critical care setting.', 198) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-98c8c74b', 't-mm-09-015', 'text', 'Use where blood warning device available.', 199) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
