INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d90eb69c', 't-mm-09-015', 'text', 'Risk of neonatal encephalopathy and CP is    ed in case of I/U infection.', 211) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-61e16435', 't-mm-09-015', 'text', 'Neonatal Care:', 212) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ebbf82d0', 't-mm-09-015', 'text', 'Babies of women treated for sepsis during labor or within 24 hours before or after birth should be assessed for neonatal infection.', 213) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0b83f3e0', 't-mm-09-015', 'text', 'If either women or baby is infected with GAS disease in post – partum period, both should be treated with Antibiotics.', 214) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-888d0707', 't-mm-09-015', 'text', 'Infection control strategies:', 215) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d752f5ac', 't-mm-09-015', 'text', 'All women after birth should be informed about signs and symptoms of genital tract infection, (written + verbal) + guidance regarding hygiene, hand washing & seeking help when feel unwell.', 216) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-70d89e22', 't-mm-09-015', 'text', 'All women identified with GAS infection during pregnancy should be aggressively treated.', 217) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d74a25bf', 't-mm-09-015', 'text', 'All close contact with GAS infected women should seek medical advice & if symptoms develops should be treated with A/B.', 218) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3d66c2fd', 't-mm-09-015', 'text', 'All healthcare professionals who are exposed to respiratory secretions of GAS infected women should be considered for A/B.', 219) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5716a1f5', 't-mm-09-015', 'text', 'Women with GAS infected should be cared by barrier nursing including clothing, masks, limited mobility.', 220) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4a2a68c8', 't-mm-09-015', 'text', 'Early investigations if suspected', 221) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fe3f732e', 't-mm-09-015', 'text', 'Take into account the normal physiological changes in labor like    ed HR', 222) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-92479753', 't-mm-09-015', 'text', 'Recognize that sepsis in labor has higher risk of illness or death.', 223) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
