INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f97978fe', 't-mm-09-016', 'text', 'No need of fasting B.A (Bile Acids)', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
