INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2e8ac281', 't-mm-09-016', 'text', 'Co – morbidities present.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
