INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9254e60d', 't-mm-09-016', 'text', 'Malabsorption of Vitamin K 1%.', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c161ae85', 't-mm-09-016', 'text', 'Fetal Risks:', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-be42acc4', 't-mm-09-016', 'text', 'Still birth – depends upon levels of B.A (No association with ALT).', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ca416e4c', 't-mm-09-016', 'text', '19 – 39 mmol/lit = No additional risk of S.B.', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
