INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9493c617', 't-mm-09-016', 'text', 'Pregnancy', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5f9f349f', 't-mm-09-016', 'text', 'Raised Bile Acid cause anoxia due to arrhythmia or placental vascular spasm.', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
