INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3d5c414b', 't-mm-09-016', 'text', 'CTG or USG => don’t predict or prevent S.B.', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
