INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-04579ebd', 't-mm-09-016', 'text', 'Fetus don’t have IUGR or Placental insufficiency.', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
