INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fe65188d', 't-mm-09-016', 'text', 'Chlorpheniramine @ night – can be used but effectiveness is uncertain.', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
