INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-54ed5490', 't-mm-09-016', 'text', 'No effect on itching.', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
