INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b2dbb5ca', 't-mm-09-016', 'text', 'Vitamin K indicated if there is', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
