INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-011afc60', 't-mm-09-018', 'text', 'Has association severe/ critical women should be offered USG Biometry & further monitoring accordingly.', 83) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-09226393', 't-mm-09-018', 'text', 'Bleeding in pregnancy except to due to previa has association with FGR/ SGA.', 84) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
