INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4f9a37b6', 't-mm-09-018', 'text', 'Raised α FP Associations with FGR/SGA', 91) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1dbac546', 't-mm-09-018', 'text', '(above 2 MOM)So, Additional', 92) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7257d616', 't-mm-09-018', 'text', 'Raised inhibinsurveillance is', 93) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c4b991c2', 't-mm-09-018', 'text', '(above 2 MOM)recommended.', 94) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7e475424', 't-mm-09-018', 'text', 'Low PPAP – A => Association with still birth.', 95) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3201097f', 't-mm-09-018', 'text', 'β – HCG (above 4 MOM) no association with SGA.', 96) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-03125384', 't-mm-09-018', 'text', 'So, no additional surveillance should be done.', 97) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1cbb1c0b', 't-mm-09-018', 'text', 'Prevention of FGR:', 98) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4495ac41', 't-mm-09-018', 'text', 'Reduce smoking – Recommended.', 99) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2232fab2', 't-mm-09-018', 'text', 'All women who smoke should be assessed by co levels.', 100) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e32177b3', 't-mm-09-018', 'text', 'Ensure in house treatment from + tobacco dependence advisor.', 101) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-07f7ffd6', 't-mm-09-018', 'text', 'Use opt out referral process.', 102) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5bcb75b2', 't-mm-09-018', 'text', 'Vitamin D 10mg throughout pregnancy Recommended uncertain role.', 103) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3a95dfd', 't-mm-09-018', 'text', 'Folic Acid 400mg pre conception & 1st  recommended.', 104) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-284a4c52', 't-mm-09-018', 'image', '/uploads/content-images/maternal_mind_book/image127.emf', 105) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ffb57fe2', 't-mm-09-018', 'text', 'Prevent other pregnancy complications.', 106) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-be9021a4', 't-mm-09-018', 'text', 'Balanced energy/ protein supplementation:', 107) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fcbc39e5', 't-mm-09-018', 'text', 'birth weight.', 108) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b7f4b679', 't-mm-09-018', 'text', 'Role is not clear.', 109) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-09ad7377', 't-mm-09-018', 'text', 'Omega 3 long chain poly un saturated fatty acid – No effect.', 110) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eb49aff9', 't-mm-09-018', 'text', 'Minerals, micronutrients & vitamins – not clear.', 111) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-160cbbda', 't-mm-09-018', 'text', 'Calcium supplementation reduces pre – Eclampsia but FGR association not clear.', 112) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96bc751e', 't-mm-09-018', 'text', 'Aspirin 150mg recommended', 113) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-45452929', 't-mm-09-018', 'text', 'Between 12 – 36 + 6 weeks to those women who are at risk of pre – eclampsia & placental dysfunction.', 114) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b8371d0f', 't-mm-09-018', 'text', 'It reduces their chance of developing SGA / FGR.', 115) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-353b493c', 't-mm-09-018', 'text', '150mg OD @ night.', 116) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-57085eca', 't-mm-09-018', 'text', 'LMWH – not recommended.', 117) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c5d0dd47', 't-mm-09-018', 'text', 'Surveillance tools for FGR:', 118) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b8f816df', 't-mm-09-018', 'text', 'Symphisio fundal height SFH:', 119) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1046916c', 't-mm-09-018', 'text', 'Routinely offered after 24 weeks.', 120) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-05cc0841', 't-mm-09-018', 'text', 'SFH < 10th centile => Refer for USG.', 121) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d0153ffb', 't-mm-09-018', 'text', 'Serial SFH more informative.', 122) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9d3ae93c', 't-mm-09-018', 'text', 'Plot serial SFH on growth charts.', 123) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-43341c6a', 't-mm-09-018', 'text', '3 types of growth charts population base, standard & customized.', 124) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7ab338ee', 't-mm-09-018', 'text', 'Customized charts improve detection.', 125) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c5e2ac81', 't-mm-09-018', 'text', 'USG – core component of FGR surveillance.', 126) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-300186ed', 't-mm-09-018', 'text', 'Routine USG for AC/EFW don’t improve outcome.', 127) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-258d324d', 't-mm-09-018', 'text', 'Fetal size is measured by AC or EFW. AC is superior but inferior to combined measurement leading to EFW.', 128) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-691523da', 't-mm-09-018', 'text', 'EFW is measured by fetal parameters like FL, AC, HC.', 129) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b310b6cd', 't-mm-09-018', 'text', 'Fetal size should be measured @ least 3 – weeks by headlock formula, in SGA every 2 weeks.', 130) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2f369b38', 't-mm-09-018', 'text', 'Plotting of EFW should be done on reference chart to determine centile.', 131) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-07cd07e6', 't-mm-09-018', 'text', 'Universal growth harts should be adjusted according to local data.', 132) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6d0498bb', 't-mm-09-018', 'text', 'Amniotic fluid estimation either by, SDP (2 – 8cm), or AFI (5 – 25cm).', 133) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b7956b93', 't-mm-09-018', 'text', 'Uterine Artery Doppler:', 134) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dcdf4c8c', 't-mm-09-018', 'text', 'Predictive value of abnormal uterine artery Doppler is limited.', 135) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-137fc659', 't-mm-09-018', 'text', 'Can be used along mid trimester anomaly scan (18 – 24 + 6 weeks) to determine abnormal placentation & therefore risk of early onset FGR also & early onset pre – Eclampsia.', 136) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f28ed787', 't-mm-09-018', 'text', 'Also help in determining growth surveillance pathway.', 137) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ea424621', 't-mm-09-018', 'text', 'Assessment of uterine Artery Pulsatility index is recommended.', 138) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b884907f', 't-mm-09-018', 'text', 'Assessment of uterine notching is not recommended as it is a qualitative assessment and it is common to have notching in 1st  43% notching in 2nd  has similar sensitivity to PI.', 139) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-589170c0', 't-mm-09-018', 'image', '/uploads/content-images/maternal_mind_book/image128.emf', 140) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-235e0089', 't-mm-09-018', 'image', '/uploads/content-images/maternal_mind_book/image129.emf', 141) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9a9187c8', 't-mm-09-018', 'text', 'Uterine artery Doppler in 3rd  helps in determining whether FGR is due to abnormal placentation & it has moderate role in predicting adverse outcome for SGA.', 142) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3c7cd377', 't-mm-09-018', 'image', '/uploads/content-images/maternal_mind_book/image129.emf', 143) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-19e1368e', 't-mm-09-018', 'text', 'placental biomarkers.', 144) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d728dde1', 't-mm-09-018', 'text', 'Improve diagnostic of USG for SGA & SB.', 145) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5653c3af', 't-mm-09-018', 'text', 'placental growth factor PIGF. & soluble fms – like tyrosine kinase (s – flt) are recommended for diagnostic of pre – Eclampsia and placental dysfunction. But these are not recommended in non – hypertensive FGR diagnosis.', 146) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-19302fe7', 't-mm-09-018', 'text', 'More useful in 3rd placental .', 147) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f5b4af9a', 't-mm-09-018', 'image', '/uploads/content-images/maternal_mind_book/image129.emf', 148) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4a03d76b', 't-mm-09-018', 'text', 'Placental morphology/ Biometry.', 149) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7955245f', 't-mm-09-018', 'text', 'Under research.', 150) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8e90f37f', 't-mm-09-018', 'text', 'Doppler Studies.', 151) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fdf03112', 't-mm-09-018', 'text', 'Umbilical Artery Doppler:', 152) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d0bd2d27', 't-mm-09-018', 'text', 'In all growth restricted pregnancies.', 153) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ce943a98', 't-mm-09-018', 'text', 'Reduces hospital admissions, neonatal mortality and pre – Term birth.', 154) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5462b72b', 't-mm-09-018', 'text', 'Abnormal can be defined as PI above 95th centile, absent diabolic flow reverse flow.', 155) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-85343779', 't-mm-09-018', 'text', 'Ductus venous Doppler:', 156) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5139ff8b', 't-mm-09-018', 'text', 'Done if absent/ Reverse umbilical artery Doppler.', 157) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3a73ba47', 't-mm-09-018', 'text', 'In pre – Term FGR.', 158) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-acd35a8a', 't-mm-09-018', 'text', 'Can be defined as raised PIV above 95th centile (pre – critical) or reverse wave (critical).', 159) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-94fbb7e5', 't-mm-09-018', 'text', 'Cerebral Doppler:', 160) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d8cb0df7', 't-mm-09-018', 'text', 'Abnormal MCA CPR/ UCR can inform monitoring strategies but don’t determine timing of birth before 37 weeks, but after 37 weeks it ca guide about timing of birth.', 161) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-507e4699', 't-mm-09-018', 'text', 'Table 39. Risk assessment for FGR and their referral Pathway:', 162) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ea3403d0', 't-mm-09-018', 'html', '<table><tbody><tr><td>Risk assessment<br/>@ Booking.<br/>@ Mid trimester anomaly scan.</td><td>Screening for early onset FGR & triage pathway.</td><td>Screening/ surveillance pathway for FGR.</td><td>Reassess @ 28 weeks & after any antenatal admission.<br/>Assess for serial complications developing in pregnancy.<br/>E.g.,<br/>* Hypertensive disorders.<br/>* Significant bleeding.<br/>Serial USG from diagnosis till delivery.</td></tr><tr><td>Low Risk => no RF</td><td>Anomaly scan & EFW > 10th centile.</td><td>Serial SFH monitoring.</td><td></td></tr><tr><td>Moderate Risk:<br/>Obstetric History:<br/>Previous SGA.<br/>Previous SB + appropriate for gestational age birth weight<br/>Current Factor:<br/>Current smoker<br/>Drugs misuse.<br/>Age > 40 @ booking.<br/>BMI < 18.5 & other features.<br/>e.g., eating disorder, bowel disorders causing weight loss.<br/>Gastric bypass (even with normal BMI).<br/>Previous PTB/ 2nd  miscarriage (placental mediated).</td><td>* Anomaly Scan & EFW > 10th centile.<br/>* Require one off SFH @ 28/ 40 weeks.<br/>* Assess women with moderate risk for abnormal placentation and start aspirin.</td><td>* Serial USG from 32 weeks.<br/>* Every 4 weeks till delivery.</td><td></td></tr><tr><td>High Risk:<br/>Medical conditions:CKD<br/>HTN<br/>SLE<br/>APLS</td><td>Consider aspirin 150 mg @ night < 16 weeks as appropriate<br/>1. previous HTN<br/>2. previous FGR <3rd centile or ,10th centile born before 34 weeks</td><td>Normal uterine artery Doppler & EFW > 10th centile.<br/>Uterine artery DopplerUterine artery Doppler(N) uterine artery Doppler & EFW < 10th centile.<br/>Uterine artery Doppler<br/>Uterine artery Doppler<br/>Abnormal uterine artery Doppler & EFW > 10th centile.<br/>Abnormal uterine artery Doppler & EFW < 10th centile.</td><td>Serial user from 32 weeks every 2 – 4 weeks till delivery.<br/>Serial USG from 26 – 28 weeks till delivery.<br/>Serial USG from 28 weeks every 2 – 4 weeks till delivery.<br/>Refer to FMU</td><td></td></tr><tr><td>Complex cardiac discase.<br/>Obstetric History:<br/>Previous FGR.<br/>HTN in previous pregnancy.<br/>Previous SGA SB.<br/>Current Pregnancy:<br/>PAPPA < 5th centile.<br/>Inhibin (2nd ) > 2 MOM.<br/>Alpha FP (2nd  ) >2 MOM.<br/>Echogenic bowel.<br/>Significant bleeding.<br/>EFW < 10th centile.<br/>Single umbilical artery.</td><td></td><td></td><td></td><td></td></tr><tr><td>Others:<br/>Large Fibroids.<br/>BMI > 35.<br/>Congenital uterine Anomalies.</td><td>Anomaly scan & EFW > 10th centile.</td><td>Serial USG from 28 weeks in women with congenital uterine anomalies till delivery.<br/>* Serial USG from 32 weeks in women with large fibroids and high BMI.</td><td></td></tr></tbody></table>', 163) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3c0033eb', 't-mm-09-018', 'text', 'Early FGR up to 32 weeks:* EFWfortnightly.* U/A Doppler weekly.Early FGR up to 32 weeks:* EFWfortnightly.* U/A Doppler weekly.a.24 – 35 + 6weeks.b.26 – 28 + 6weeks.c.29 – 31 + 6weeks.d.32 – 33 + 6weeks.34 – 36 + 6weeks.a.24 – 35 + 6weeks.b.26 – 28 + 6weeks.c.29 – 31 + 6weeks.d.32 – 33 + 6weeks.34 – 36 + 6weeks.Individualized care.Deliver if:A – wave absent on DV.STV < 2.6ms on CCTG.Deliver if:A – wave absent on DV.STV < 3ms on CCTG.Delivery if:A – wave absent on DV.STV < 3.5ms on CCTG.Individualized care.Deliver if:A – wave absent on DV.STV < 2.6ms on CCTG.Deliver if:A – wave absent on DV.STV < 3ms on CCTG.Delivery if:A – wave absent on DV.STV < 3.5ms on CCTG.AEDF or REDF in umbilical arteryMonitor @ least twice weekly with CCTG and/or DV DopplerAEDF or REDF in umbilical arteryMonitor @ least twice weekly with CCTG and/or DV DopplerManagement of FGR:', 164) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-98f591ef', 't-mm-09-018', 'text', 'FGR 32 – 36 + 6weeks.* EFW - fortnightly.* U/A Doppler – weekly.FGR 32 – 36 + 6weeks.* EFW - fortnightly.* U/A Doppler – weekly.Delivery if:STV < 4.5ms.AEDE.Delivery by 36 – 36 + 6weeks if PI > 95th centile on UADDelivery if:STV < 4.5ms.AEDE.Delivery by 36 – 36 + 6weeks if PI > 95th centile on UADUmbilical artery Doppler PI > 95th centileMonitor @ least twice weekly CCTG.Umbilical artery Doppler PI > 95th centileMonitor @ least twice weekly CCTG.', 165) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cb626c05', 't-mm-09-018', 'text', 'Deliver if:AC/EFW < 3rd centile by 37 + weeks.When FGR can’t be excluded.Any signs of centile redistribution.STV < 4.5.AREDF.Deliver if:SGA by 39 + 0 weeks.STV < 4.5.AREDFDeliver all SGA till 39 + 6 weeks.Deliver if:AC/EFW < 3rd centile by 37 + weeks.When FGR can’t be excluded.Any signs of centile redistribution.STV < 4.5.AREDF.Deliver if:SGA by 39 + 0 weeks.STV < 4.5.AREDFDeliver all SGA till 39 + 6 weeks.37 – 38 + 6weeks.> 39 weeks.37 – 38 + 6weeks.> 39 weeks.SGA Term 37 weeks onwards:* EFW - fortnightly.* UAD weekly.SGA Term 37 weeks onwards:* EFW - fortnightly.* UAD weekly.', 166) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-057cf320', 't-mm-09-018', 'text', 'AEDF on UAD in Early FGR:', 167) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7cc840ca', 't-mm-09-018', 'text', 'Try to prolong till 34 weeks.', 168) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-680b870f', 't-mm-09-018', 'text', 'Deliver by 34 weeks.', 169) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
