INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-05be407b', 't-mm-09-018', 'text', 'Try to prolong till 32 weeks.', 172) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
