INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-64109896', 't-mm-09-018', 'text', 'EFW < 10th centile + abnormal uterine artery Doppler.', 177) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-878a788a', 't-mm-09-018', 'text', 'Invasive testing:', 178) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eb229d22', 't-mm-09-018', 'text', 'Severe SGA + structural anomalies (offered).', 179) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fca809f7', 't-mm-09-018', 'text', 'SGA + structurally normal features before 23 weeks + normal uterine artery Doppler (considered).', 180) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-90843dcf', 't-mm-09-018', 'text', 'Analysis includes:', 181) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aae54cb1', 't-mm-09-018', 'text', 'Micro array to detect micro insertions & micro deletions.', 182) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-93063c84', 't-mm-09-018', 'text', 'Pre – natal exome sequencing should only be considered in cases with multi system abnormalities or isolated short long bones.', 183) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a1b42230', 't-mm-09-018', 'text', 'Serological Screening of Infections:', 184) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d2ec4107', 't-mm-09-018', 'text', 'Incidence of FGR due to infections is 5%.', 185) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a33f8c5f', 't-mm-09-018', 'text', 'Causative Agents:', 186) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eca78b0d', 't-mm-09-018', 'text', 'CMV, toxoplasmosis, malaria, syphilis', 187) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e19e64fb', 't-mm-09-018', 'text', 'Full TORCH screening is not recommended', 188) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-46bf2533', 't-mm-09-018', 'text', 'Testing should be based on presentation and history.', 189) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-85bdd46a', 't-mm-09-018', 'text', 'CMV: Testing should be offered in severe SGA.', 190) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-39ae1cf0', 't-mm-09-018', 'text', 'Malaria: offered to those who have travelled in endemic areas. It is a significant cause of PTB and LBW.', 191) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-42fa1f41', 't-mm-09-018', 'text', 'Zika Virus: FGR is seen in 10% of infected women and is femur sparing pattern of FGR testing is offered to high-risk population.', 192) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2512e228', 't-mm-09-018', 'text', 'Treatment or interventions for FGR:', 193) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-73d78e82', 't-mm-09-018', 'text', 'No proven intervention except birth of baby.', 194) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
