INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f3ef481e', 't-mm-09-018', 'text', 'Phosphodiesterase 5 inhibitors – no proven role.', 196) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
