INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-63ea2c6d', 't-mm-09-018', 'text', 'Reduces neonatal death, RDS and perinatal death.', 205) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-62a91a0d', 't-mm-09-018', 'text', 'Effective between 48 hours to 7 days of administration.', 206) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9b78649c', 't-mm-09-018', 'text', 'MgSO4 – offer @ 24 – 29 + 6 weeks, consider @ 30 – 33 + 6 weeks reduces neurological developmental abnormalities.', 207) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
