INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0e4c5c34', 't-mm-09-019', 'text', 'Maternal age > 35.', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-91087cc1', 't-mm-09-019', 'text', 'Maternal age < 20.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-190fe199', 't-mm-09-019', 'text', 'Black, Asian and non-white women.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ddccdf3b', 't-mm-09-019', 'text', 'Previous SB.', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5d01235a', 't-mm-09-019', 'text', 'Previous adverse pregnancy outcome like PTB, pre – Eclampsia, FGR.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0e9baa2e', 't-mm-09-019', 'text', 'Multiple pregnancy.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b0eb1301', 't-mm-09-019', 'text', 'Low education', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a398a663', 't-mm-09-019', 'text', 'RFM.', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-93f42384', 't-mm-09-019', 'text', 'Thyroid disease.', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-55f07ece', 't-mm-09-019', 'text', 'Thrombophilia.', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8cabc767', 't-mm-09-019', 'text', 'Malaria infection.', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2d0b7e9d', 't-mm-09-019', 'text', 'COVID 19 infection.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-412242d6', 't-mm-09-019', 'text', 'Cholestasis.', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e7bffa00', 't-mm-09-019', 'text', 'SLE, APLS.', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-065ca812', 't-mm-09-019', 'text', 'Renal disease.', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8c599acc', 't-mm-09-019', 'text', 'Modifiable Recurrent Factor:', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-750f9f09', 't-mm-09-019', 'text', 'Preexisting HTN.', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7a837ec4', 't-mm-09-019', 'text', 'Obesity/ overweight/ weight gain.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6d301fd9', 't-mm-09-019', 'text', 'Smoking > 10 cigarette/ day.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1f86b869', 't-mm-09-019', 'text', 'Alcohol use.', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e3a9b229', 't-mm-09-019', 'text', 'Illicit drug use.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-41261733', 't-mm-09-019', 'text', 'Going to sleep supine.', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f786f860', 't-mm-09-019', 'text', 'Living in area of deprivation.', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-30a8d658', 't-mm-09-019', 'text', 'Diagnosis:', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5c42fbb9', 't-mm-09-019', 'text', 'USG:', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9a316350', 't-mm-09-019', 'text', 'Gold standard for diagnosis.', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-347e3237', 't-mm-09-019', 'text', 'Should be available at all times.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb91fd67', 't-mm-09-019', 'text', '2nd opinion should be obtained for diagnosis.', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-06b0a049', 't-mm-09-019', 'text', 'Real time features that can be seen on USG are collapse of fetal skull with overlapping, hydrops, maceration, intra fetal Gas.', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ac051e1c', 't-mm-09-019', 'text', 'Occult placental abruption can be identified in up to 15% of cases on USG. Sometimes even large abruption can be missed.', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a5085778', 't-mm-09-019', 'text', 'Auscultation of fetal heats can’t be used to diagnose IUFD.', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bb4b9454', 't-mm-09-019', 'text', 'Reduced/ Absent fetal movements:', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bc155f1d', 't-mm-09-019', 'text', 'Can’t be used to diagnose IUFD.', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7857b8b9', 't-mm-09-019', 'text', 'Can help women to seek help.', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-35a426b5', 't-mm-09-019', 'text', 'Sometimes women feel passive movement after IUFD, she should be informed about and repeat another USG if women want.', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c21ae752', 't-mm-09-019', 'text', 'Communication with Patient & Family after diagnosis of IUFD:', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6374162f', 't-mm-09-019', 'text', 'Appropriate place for discussion.', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4fe2fcbc', 't-mm-09-019', 'text', 'Offer companion if she is alone.', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1521c1b7', 't-mm-09-019', 'text', 'Clear information, avoid jargons, take help of professional interpreter if needed.', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d0850839', 't-mm-09-019', 'text', 'Give time to family and women to absorb any news.', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5cdf614b', 't-mm-09-019', 'text', 'Keep empathetic approach.', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5c921705', 't-mm-09-019', 'text', 'Offer bereavement counselling.', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-702ca4dd', 't-mm-09-019', 'text', 'Connect with SANS – (support group).', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b5ace914', 't-mm-09-019', 'text', 'Give privacy ad time to women and family.', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-40319d03', 't-mm-09-019', 'text', 'Address all the concerns of women ad family.', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-725cde84', 't-mm-09-019', 'text', 'Discussion of birth plan in detail. If she wants time, then offer her time for decision making.', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-80e6828a', 't-mm-09-019', 'text', 'All staff should be knowing about IUFD and should be sensitive to sounds that can be upsetting.', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ec0ba7bf', 't-mm-09-019', 'text', 'Continuity of care giver should be ensured.', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7b65ae4e', 't-mm-09-019', 'text', 'Recommendations for MOD & timing:', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ef50e36b', 't-mm-09-019', 'text', 'Mode of birth should be informed decision between parent’s and experienced obstetrician; Detailed discussion should be carried out between vaginal birth vs C – section.', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4247cb7a', 't-mm-09-019', 'text', 'IUFD is not contraindication to pool birth under suitable circumstances.', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-63e65a13', 't-mm-09-019', 'text', 'Options for Birth:', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3b8279c', 't-mm-09-019', 'text', 'Spontaneous Vaginal Birth:', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-47cff218', 't-mm-09-019', 'text', 'Vaginal birth is recommended for most of women.', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5fed0b2c', 't-mm-09-019', 'text', 'Quick recovery.', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e0eca50e', 't-mm-09-019', 'text', 'Less hospital stay.', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8bd9298f', 't-mm-09-019', 'text', 'Risk of vaginal/ perineal trauma.', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4d266649', 't-mm-09-019', 'text', 'Need for instrumental birth or C/section.', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4c7eca18', 't-mm-09-019', 'text', 'Immediate induction:', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3b2966ae', 't-mm-09-019', 'text', 'In women who are severely un well or at high risk of deterioration like pre – Eclampsia, sepsis placental abruption, ruptured membranes (unless C/section indicated).', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-28b88ca3', 't-mm-09-019', 'text', 'Postmortem is more informative.', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4f6fb08c', 't-mm-09-019', 'text', '90% women deliver within 24 hours of indication.', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c66f7d18', 't-mm-09-019', 'text', 'Delayed induction:', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-80df28ce', 't-mm-09-019', 'text', 'Offered in women who are physically well, with intact membranes and no lab evidence of DIC.', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4beeddb7', 't-mm-09-019', 'text', 'No physical harm for short delay like 48 hours.', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-690f5bca', 't-mm-09-019', 'text', 'Physical harm and anxiety if prolong delay is there like more than 48 hours.', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a8b772fb', 't-mm-09-019', 'text', 'Risk of DIC 10% within 4 hours.', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-faae9f42', 't-mm-09-019', 'text', 'Testing of DIC is offered if delayed delivery is planned more than 48 hours.', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c770c808', 't-mm-09-019', 'text', 'Diagnostic value of postmortem examination is lost in delayed delivery and baby’s appearance may be deteriorated.', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b09b2dfd', 't-mm-09-019', 'text', 'If delayed delivery is planned, then women should be given 24 hours contact no for information and support.', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb3c2271', 't-mm-09-019', 'text', 'Women should also be explained about sign and symptoms of complication.', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-80326dcb', 't-mm-09-019', 'text', 'C – Section:', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e39dfeaf', 't-mm-09-019', 'text', 'Less perineal trauma, pelvic organ prolapses and incontinence.', 80) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-337fdefa', 't-mm-09-019', 'text', 'More risks associated with fertility, future pregnancies and surgical morbidity.', 81) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dafa905a', 't-mm-09-019', 'text', 'Induction of labor:', 82) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-892c1684', 't-mm-09-019', 'text', '1st line: Misoprostol + Mifepristone.', 83) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-595d6dde', 't-mm-09-019', 'text', 'MISO is preferred over prostaglandin E2.', 84) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bc25eb62', 't-mm-09-019', 'text', 'Vaginal misoprostol equally effective as oral but less side effects.', 85) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-53360e2a', 't-mm-09-019', 'text', 'MISO along with Mifepristone – reduced birth interval.', 86) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5f810cd1', 't-mm-09-019', 'text', 'Doses:', 87) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-338adc2a', 't-mm-09-019', 'text', 'Mifepristone = 200mg.', 88) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-62d18851', 't-mm-09-019', 'text', 'Misoprostol=as given in table', 89) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-321faecc', 't-mm-09-019', 'html', '<table><tbody><tr><td>Weeks</td><td>Dose</td><td>Route</td><td>Interval</td></tr><tr><td>24 – 24+6 weeks</td><td>400ug</td><td>Buccal/ sublingual/ vaginal, oral.</td><td>Every 3 hours</td></tr><tr><td>25 – 27+6 weeks</td><td>200ug</td><td>Buccal / sublingual/ vaginal, oral.</td><td>Every 4 hours.</td></tr><tr><td>28 weeks onwards</td><td>25 – 500ug</td><td>Buccal / sublingual/ vaginal, oral.</td><td>Every 2 hours.</td></tr></tbody></table>', 90) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-73260bea', 't-mm-09-019', 'text', 'IOL in women with C – Section:', 91) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8853be8c', 't-mm-09-019', 'text', 'Discussion of potential benefits and harm should be undertaken by experienced obstetrician.', 92) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5257ca77', 't-mm-09-019', 'text', 'Close monitoring for scar rupture.', 93) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5f877d12', 't-mm-09-019', 'text', 'Oxytocin augmentation can be used for VBAC, but decision by experienced obstetrician or consultant.', 94) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0d3297a5', 't-mm-09-019', 'text', 'Misoprostol can be used for IOL in women with C – section.', 95) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e1bd0477', 't-mm-09-019', 'text', 'Dose is same up to 27 + 6 weeks as in un scared uterus.', 96) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6d751b17', 't-mm-09-019', 'text', 'Dose after 28 weeks – insufficient evidence.', 97) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-610ad7be', 't-mm-09-019', 'text', 'Women with 2 scar or atypical scar – safety is unknown.', 98) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0ff45ea7', 't-mm-09-019', 'text', 'Previous 1 C/section 2 – 3 times risk of rupture.', 99) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a9bdf48f', 't-mm-09-019', 'text', 'Previous 2 – no evidence available.', 100) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3965c64c', 't-mm-09-019', 'text', 'Previous 3 – not recommended ordinarily.', 101) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d08148d6', 't-mm-09-019', 'text', 'Uterine Rupture:', 102) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5087a722', 't-mm-09-019', 'text', 'S/S:', 103) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1b698c80', 't-mm-09-019', 'text', 'Maternal tachycardia.', 104) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
