INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-40276e4c', 't-mm-09-019', 'text', 'Anti D as soon as possible to women with negative blood group.', 166) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-21ad84a1', 't-mm-09-019', 'text', 'Keilhauer test in all women to detect amount of FMH.', 167) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-380deeac', 't-mm-09-019', 'text', 'In large FMH, anti D dose according to Keilhauer test and repeat test after 48 hours to ensure fetal red cells have cleared.', 168) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-289b30f7', 't-mm-09-019', 'text', 'Anti D should be given within 72 hours’ maximum up to 10 days.', 169) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
