INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7aabcf28', 't-mm-09-019', 'text', 'Legal requirement for medical certification:', 229) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-77f68d68', 't-mm-09-019', 'text', 'Still birth must be medically certified by fully registered doctor or midwife, who was present at birth or examined the baby after birth.', 230) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d2cf5462', 't-mm-09-019', 'text', 'HM coroner must be contacted if there is doubt about status of birth. Babies born later than 24 weeks who are known to have died before 24 weeks, do not have to be registered.', 231) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1aee768a', 't-mm-09-019', 'text', 'The baby can be registered as indeterminate sex awaiting further tests.', 232) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6867c05a', 't-mm-09-019', 'text', 'Parents are responsible in law for registration of baby’s birth but can delegate task to health care professional.', 233) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-26b2d722', 't-mm-09-019', 'text', 'Burial, Spiritual Guidance & Remembrance:', 234) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-87f670d2', 't-mm-09-019', 'text', 'Burial should be by parents but can delegate to hospital services after filling the form.', 235) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4b7348f5', 't-mm-09-019', 'text', 'Parents should be provided proper guidance regarding Cremation.', 236) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
