INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b43b0f33', 't-mm-09-025', 'text', 'Hemodynamic instability.', 97) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4736bdf5', 't-mm-09-025', 'text', 'Fetal compromise.', 98) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-062396eb', 't-mm-09-025', 'text', 'Senior obstetrician should involve in decision making regarding tocolysis', 99) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7b501551', 't-mm-09-025', 'text', 'C/I:', 100) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6c714c2f', 't-mm-09-025', 'text', 'Abruption is an absolute contraindication.', 101) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-decdd5af', 't-mm-09-025', 'text', 'Mild APH + Previa is a relative contraindication.', 102) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f422f4e6', 't-mm-09-025', 'text', 'ANC:', 103) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2ba2e2ff', 't-mm-09-025', 'text', 'Switch to “High Risk” – obstetric led Care', 104) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f8a78742', 't-mm-09-025', 'text', 'serial growth Scan till its prove normal.', 105) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ab7e955a', 't-mm-09-025', 'text', 'Birth:', 106) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-14b7fe83', 't-mm-09-025', 'text', 'Expectant – CTG (N), Hemodynamically stable, Pre – Term.', 107) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-072b4737', 't-mm-09-025', 'text', 'Expedite – abnormal CTG=> emergency C/S.', 108) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-49d85c77', 't-mm-09-025', 'text', 'IUD – deliver immediately, C/S may be required.', 109) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb9d3096', 't-mm-09-025', 'text', 'Unexplained APH with no Fetomaternal compromise => senior obstetrician should decide regarding MOD & TOD.', 110) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a62011fc', 't-mm-09-025', 'text', 'Fetal monitoring : by CEFM', 111) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-00b08ca4', 't-mm-09-025', 'text', 'Anesthesia:', 112) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bf000767', 't-mm-09-025', 'text', 'Regional – recommended until no C/I.', 113) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1197e02b', 't-mm-09-025', 'text', 'General => if Fetomaternal condition is compromised.', 114) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f96cefee', 't-mm-09-025', 'text', 'Stable mother but fetal compromise regional is preferred.', 115) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4ac10d38', 't-mm-09-025', 'text', 'Unstable mother GA is preferred to facilitate Resuscitation.', 116) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3aec8fcb', 't-mm-09-025', 'text', 'Active 3rd stage of labor is recommended.', 117) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e6df0e50', 't-mm-09-025', 'text', 'Ergometrine if no HTN.', 118) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c420ab34', 't-mm-09-025', 'text', 'Anti D + FMH by Kleihauer is recommended.', 119) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9b639b10', 't-mm-09-025', 'text', 'Recurrent APH – repeat Anti D after 6 weeks.', 120) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3877e88b', 't-mm-09-025', 'text', 'Pts on warfarin/ heparin – No more doses.', 121) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66ef8d08', 't-mm-09-025', 'text', 'Further doses after consultation with medical staff & detailed assessment @ hospital.', 122) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-42c81c1b', 't-mm-09-025', 'text', 'Neonatal Management – Risk of fetal anemia – May need Transfusion.', 123) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ab2df2ef', 't-mm-09-025', 'text', 'Major/ Massive => senior pediatrician/ neonatologists.', 124) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5b24dc13', 't-mm-09-025', 'text', 'Minor => pediatric support only.', 125) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6e5518fb', 't-mm-09-025', 'text', 'Abruption/ Vasa previa => senior pediatrician / Neonatologist => may need tx.', 126) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f3fba3db', 't-mm-09-025', 'text', 'Anterior placenta => experienced pediatrician / Neonatologist.', 127) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-29a76ef1', 't-mm-09-025', 'text', 'APH @ 24 – 26 weeks:', 128) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c4b4655c', 't-mm-09-025', 'text', 'Mother is priority.', 129) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-07ecf473', 't-mm-09-025', 'text', 'Senior pediatrician / Neonatologist should involve in counselling.', 130) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-74cbaddf', 't-mm-09-025', 'text', 'Conservative treatment if mother is stable.', 131) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aa2e0d9f', 't-mm-09-025', 'text', 'Post – Natal F/U:', 132) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ca4bdcd1', 't-mm-09-025', 'text', '4 – 6 weeks.', 133) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
