INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3b96aba4', 't-mm-09-027', 'text', 'Primigravida – 10 appointments/ visits.', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d2d7d9e4', 't-mm-09-027', 'text', 'Multigravida – 7 appointments/visits.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-40a92d7a', 't-mm-09-027', 'html', '<table><tbody><tr><td>Time of appointment</td><td>Objective</td></tr><tr><td>1st contact with health care professional</td><td>Information giving<br/>Folic acid till 12 weeks of pregnancy, 400µg daily.<br/>Food hygiene.<br/>Life style – (smoking cessation, recreational drug use, alcohol abuse.<br/>AN screening, risk/benefits.<br/>Discuss issues.<br/>Ask questions.</td></tr><tr><td>Booking by 10 weeks</td><td>Information giving regarding<br/>How baby develops<br/>Nutrition, diet including vitamin D 10mg/ day.<br/>Exercise, including Pelvic floor.<br/>Antenatal screening.<br/>Pregnancy care pathway.<br/>Place of birth, Breast feeding.<br/>AN classes.<br/>Maternity benefits.<br/>Screening Tests:<br/>1. Blood group + Antibodies.<br/>2. Screening for Hemoglobinopathies.<br/>Offer to all.<br/>Types of screening depends upon prevalence:<br/>High > 1.5/10,000 high performance chromatography.<br/>Less < 1.5/ 10,000.<br/>Family origin Questionnaire.<br/>High risk                                                                          low risk<br/>High performance<br/>chromatography<br/>MCV < 27 => High performance liquid chromatography<br/>Female carrier => check partner status.<br/>Heel prick => neonate.<br/>3. Anemia, Hep B, HIV, syphilis.<br/>4. Asymptomatic bacteriuria.<br/>5. Chlamydia – no test but information given if age is < 25 years.<br/>6. Dating scan, 10 – 13+6 weeks (CRL up to 84mm, then HC).<br/>7. Height, weight, BMI, B.P, proteinuria, risk factor for PTE, GDM.<br/>8. Screening for down to all women.<br/>Combined: 11 – 13+6 weeks.<br/>Tripple/ Quadruple: after 15 weeks.<br/>9. Identify genital mutation.<br/>10. Ask about past/ present mental health illness, depression.<br/>11. Occupation – identify occupational hazards.<br/>12. Support @ home – rule out domestic abuse, deprivation.</td></tr><tr><td>@ 16 weeks</td><td>Discuss and preview results of screening.<br/>Reassess plan and pattern of care.<br/>Investigate, Hb < 11 and give iron.<br/>B.P, proteinuria.<br/>Give information, discussion.</td></tr><tr><td>18 – 20 weeks.</td><td>Anomaly Scan & its purpose (NT >6mm, 2 or more soft markers).<br/>Reproductive choices.<br/>Referral to FMUReferral to FMUPrepare pts for (treatment, disability, TOP).<br/>Referral to FMU<br/>Referral to FMU<br/>4 camber view of heart & outflow track routinely.</td></tr><tr><td>25 weeks.</td><td>Only Nulliparous<br/>SFH.<br/>B.P, proteinuria<br/>Discussion, information.</td></tr><tr><td>28 weeks</td><td>2nd screen for:<br/>Anemia.<br/>Atypical Ab.<br/>Anti D prophylaxis.<br/>SFH plotting.<br/>B.P proteinuria.<br/>Information, discussion.</td></tr><tr><td>31 weeks.</td><td>Nulliparous B.P, proteinuria.<br/>SFH, plot.<br/>Information + discussion.<br/>Review screening tests done @ 28 weeks.<br/>Replan care pathway if any problem detected</td></tr><tr><td>34 weeks</td><td>Information, discussion.<br/>Prepare for birth including pain & birth plan, coping with pain.<br/>Recognition of active labor.<br/>2nd dose Anti D.<br/>B.P, proteinuria.<br/>SFH plot.<br/>Review screening tests @ 28 weeks</td></tr><tr><td>36 weeks</td><td>Information, discussion.<br/>B.F information.<br/>Care of new born.<br/>Vitamin K prophylaxis + Neonatal screening.<br/>Post – natal care.<br/>Baby blue awareness & post – natal depression.<br/>Check:<br/>B.P, protein uria, SFH.<br/>Baby position – Breach => offer ECV.</td></tr><tr><td>38 weeks</td><td>B.P, proteinuria.<br/>SFH.<br/>Information, Discussion.</td></tr><tr><td>40 weeks</td><td>Nulliparous<br/>B.P, SFH, information, Discussion</td></tr><tr><td>41 weeks</td><td>Membrane sweep<br/>IOL – offer.<br/>B.P, proteinuria, SFH, information, discussion.</td></tr></tbody></table>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
