INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8631147e', 't-mm-09-028', 'html', '<table><tbody><tr><td>Vaccines</td><td>Indications</td></tr><tr><td>Hep A</td><td>1.  Long term liver disease.<br/>Hemophilia.<br/>Poor sanitary condition.<br/>Living near to sewage.<br/>Living with primates.<br/>Drug abusers.</td></tr><tr><td>Hep B</td><td>1. Sex workers.<br/>2. Living with Hep B positive.<br/>3. Drug abusers.<br/>4. Multiple sex partners.<br/>5. Regular transfusions.<br/>6. Liver disease or CKD.<br/>7. Travelling to endemic areas.</td></tr><tr><td>Meningococcal</td><td>1. Asplenia.<br/>2. Immune suppression.<br/>3. Complement deficiency.<br/>4. High risk endemics travel.<br/>5. University students < 25 years of age<br/>6. Contact with infected individuals.</td></tr><tr><td>Pneumococcal</td><td>1. Asplenia.<br/>2. SCD.<br/>3. Splenectomy.<br/>4. HIV.</td></tr><tr><td>Typhoid</td><td>1. Travel to endemics.</td></tr><tr><td>Rabies</td><td>- Post exposure prophylaxis recommended<br/>- Pre – exposure prophylaxis – where risk of exposure to rabies is substantial.</td></tr><tr><td>Yellow fever</td><td>- High case fatality.<br/>- Given when travel is un avoidable.</td></tr></tbody></table>', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c49b409f', 't-mm-09-028', 'text', 'Breast Feeding: after vaccination', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f699e496', 't-mm-09-028', 'text', 'Not C/I not any precautions.', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-09-029', 'chap-mm-09-01', '16. ANC OF SINGLETON PREGNANCY CONCEIVED USING ART', 'Detailed medical reference and study guide on 16. ANC OF SINGLETON PREGNANCY CONCEIVED USING ART.', 29, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5e17bb9a', 't-mm-09-029', 'html', '<table><tbody><tr><td>Condition</td><td>Incidence</td><td>Recommendations</td></tr><tr><td>OHSS<br/>Risk of VTE<br/>PIH<br/>PTL</td><td>Mild – 33%.<br/>Mod – severe 3.1 – 8%.<br/>Risk of VTE = 0.7 – 10%.<br/>Upper body & arterial system after resolution of OHSS.</td><td>Establish evidence based local protocols.<br/>Admission to nominated centers.<br/>Reporting to HEFA severe & critical.</td></tr><tr><td>Miscarriages</td><td>15 – 20%</td><td>Manage as spontaneous miscarriage.<br/>Women should have access to specialist counselor before, during & after ART.</td></tr><tr><td>Ectopic</td><td>1.4%</td><td>Same as miscarriage<br/>Careful inspection of adnexa on USG.<br/>Be mindful of heterotopic pregnancy</td></tr><tr><td>PIH – more if<br/>Age > 35 years<br/>BMI > 30.<br/>PCOS<br/>Multiple pregnancy</td><td>2% more than natural conception<br/>More in egg donation.<br/>Sperm donation or<br/>Embryo donation.</td><td>Risk assessment @ booking.<br/>Aspirin 75mg from 12 weeks if risk Factor positive (not on basis of ART).</td></tr><tr><td>GDM – more in PCOS</td><td>1%</td><td>ART not an indication of OGTT</td></tr><tr><td>VTE</td><td>Highest in 1st</td><td>Alone ART is not an indication for prophylaxis.<br/>Risk assessment.</td></tr><tr><td>Subclinical hypothyroidism</td><td></td><td>Treatment of subclinical hypo    es risk of miscarriage in ART pregnancies (limited evidence).</td></tr><tr><td>Fetal complications</td></tr><tr><td>Structural Anomalies</td><td>30 – 40%     risk</td><td></td></tr><tr><td>Oligospermia => Autosomal translocation or inversion 4.6 – 13.7%<br/>Microdeletion = 5 – 15%.</td><td>Absolute risk<br/>More in ICSI 6.5 – 7%</td><td>No additional surveillance.</td></tr><tr><td>IUGR:<br/>ART minor risk Factor for SGA</td><td></td><td>No additional surveillance.</td></tr><tr><td>S. B</td><td>2.4-fold</td><td>Delivery @ Term IOL or C/Section</td></tr><tr><td>PTL</td><td>11.2% iatrogenic</td><td>No additional surveillance.</td></tr><tr><td>Placental complications</td></tr><tr><td>Placenta Previa</td><td>More in blastocyst stage Transfer than @ cleavage stage.</td><td>No additional surveillance</td></tr><tr><td>Placenta Accreta</td><td></td><td>No additional surveillance</td></tr><tr><td>Abruption</td><td></td><td>No additional surveillance</td></tr><tr><td>Vasa Previa</td><td></td><td>If low lying placenta @ anomaly scan than TVS with Doppler to rule out Vasa Previa should be under taken.</td></tr></tbody></table>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d77b9c3c', 't-mm-09-029', 'text', 'Table 41. ANC OF SINGLETON PREGNANCY CONCEIVED USING ART', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
