INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-339f0037', 't-mm-09-030', 'html', '<table><tbody><tr><td>Gestational age</td><td>< 50mGy<br/>< 5 Rad</td><td>50 – 100 mGy<br/>5 – 10 Rad</td><td>>100mGy<br/>>Rad</td><td>Estimated threshold dose.</td></tr><tr><td>0 – 2</td><td>No effect</td><td>No effect</td><td>No effect</td><td>50 – 100mGy</td></tr><tr><td>3 – 4</td><td>No effect</td><td>No effect</td><td>Spontaneous miscarriage</td><td>200mGy</td></tr><tr><td>5 – 10</td><td>No effect</td><td>No effect</td><td>Congenital anomaly (skeletal, Ophthalmic Genital tract)<br/>FGR</td><td>200 – 250</td></tr><tr><td>11 – 17</td><td>No effect</td><td>No effect</td><td>-    IQ or Retardation.<br/>-  Microcephaly (dose dependent).</td><td>60 – 310<br/>200</td></tr><tr><td>18 – 27</td><td>No effect</td><td>No effect</td><td>IQ    - not at diagnostic doses</td><td></td></tr><tr><td>> 27</td><td>No effect</td><td>No effect</td><td>Not applicable @ discharge medicine.</td><td></td></tr></tbody></table>', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
