INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7addaea3', 't-mm-09-030', 'html', '<table><tbody><tr><td>Very low dose - < 0.1mGy<br/>Cx spine x – ray (two view)<br/>CXR (two view)<br/>X ray extremities<br/>Mamogram two view.<br/>Head & neck CT.</td><td>< 0.001<br/>0.0005 – 0.1.<br/>< 0.001<br/>0.001– 0.01.<br/>0.001– 0.01.</td></tr><tr><td>Low – moderate dose – 0.01 – 10mGy<br/>Abdominal x – ray<br/>Lumber spine<br/>CT chest or pulmonary angiography<br/>Technetium as bone scintigraphy<br/>Pulmonary digital subtraction angiogram<br/>CT – pelvimetry</td><td>0.1 – 3.0<br/>1 – 10<br/>0.1 – 0.5<br/>4 – 5<br/>0.5<br/>< 1</td></tr><tr><td>Higher doses – 10 – 50mGy<br/>Abdominal – CT<br/>Pelvic CT.<br/>F – FDG PET/ CT whole body</td><td>1.3 – 35.<br/>10 – 50.<br/>10 – 50.</td></tr></tbody></table>', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
