INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5dde95e1', 't-mm-09-030', 'text', 'More effect if exposure exceeds 60 min.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bfbfc218', 't-mm-09-030', 'text', 'MRI:', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-84de18c8', 't-mm-09-030', 'text', 'Challenging in obstetrics – to perform and interpret due to fetal movements, MRI better than USG, Safe at any Gestation.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8452a1f7', 't-mm-09-030', 'text', 'Gadolinium contrast:', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-680954b5', 't-mm-09-030', 'text', 'Improve imaging – crosses placenta and fetal circulation and excreted in amniotic fluid => risk of fibrosis in nephrogenic system (not) statistically significant.', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-17edc752', 't-mm-09-030', 'text', 'Risk of SB and neonatal death.', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-33df3e4e', 't-mm-09-030', 'text', 'Risk of rheumatological, inflammatory skin diseases.', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-41613f56', 't-mm-09-030', 'text', 'Avoid – Gadolinium in pregnancy.', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-afd87d8f', 't-mm-09-030', 'text', 'Nuclear imaging:', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3af76f7', 't-mm-09-030', 'text', 'Thyroid scan, bone scan, Renal scan, V/P scan.', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f4c7f695', 't-mm-09-030', 'text', 'Most commonly use “isotope – tech 99)', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-833843f4', 't-mm-09-030', 'text', 'Gamma rays emitted t/2 = 6 hours.', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-58543648', 't-mm-09-030', 'text', '“rad iodine 13” t/2 = 8 days.', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e1218828', 't-mm-09-030', 'text', 'Cause fetal hypothyroidism in 10 – 12 weeks.', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f8ab8e96', 't-mm-09-030', 'text', '“F – FDG” in PET CT.', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-609a5f81', 't-mm-09-030', 'text', 'Avoid – Rad Iodine in pregnancy', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e9fdc9c3', 't-mm-09-030', 'text', 'Tech 99 & F – FDG can be used => in thyroid scan use Tech 99 in place of radio Iodine.', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5be7450b', 't-mm-09-030', 'text', 'V/P Scan/ CTPA:', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c326988e', 't-mm-09-030', 'html', '<table><tbody><tr><td>Parameter</td><td>CTPA</td><td>V/P scan</td></tr><tr><td>Availability</td><td>more</td><td>less</td></tr><tr><td>Fetal radiation exposure</td><td></td><td>- Childhood cancers.</td></tr><tr><td>Identification of pathology.</td><td>more   pneumonia 5-7%.<br/>Pulmonary edema 2-6%.</td><td>Limited.</td></tr><tr><td>CA breast</td><td>20mGy<br/>10mGy before Age 35    es<br/>CA breast 13.6%.</td><td>none</td></tr></tbody></table>', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
