INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b7a7df06', 't-mm-09-031', 'text', 'Spontaneous conception 61%.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-807b78eb', 't-mm-09-031', 'text', 'Time from surgery to conception 31m0.', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5c6f6c3c', 't-mm-09-031', 'text', 'Live birth 62%.', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cf4d7490', 't-mm-09-031', 'text', 'Miscarriages:', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d2d6522f', 't-mm-09-031', 'text', '1st  16% (15 – 20%) normal pregnancies.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d29633ac', 't-mm-09-031', 'image', '/uploads/content-images/maternal_mind_book/image139.emf', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e6ef4056', 't-mm-09-031', 'text', '2nd  7% (4%).', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ca907ae9', 't-mm-09-031', 'image', '/uploads/content-images/maternal_mind_book/image140.emf', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-669522ba', 't-mm-09-031', 'text', 'Term delivery 54.8%.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e1ad5726', 't-mm-09-031', 'text', 'Pre – Term 30 – 40% up to (45%).', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ef409628', 't-mm-09-031', 'text', 'More cervix is excised => more risk of PTL', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-728f15bd', 't-mm-09-031', 'text', '> 10mm – risk of PTL.', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-123c53de', 't-mm-09-031', 'text', 'Contraception:', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ab2046af', 't-mm-09-031', 'text', 'POP – ineffective due to loss of CX and mucous plug.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-55ea6781', 't-mm-09-031', 'text', 'IUCD – difficulty in insertion due to isthmic stenosis (insertion of foleyscatheter for 3days after surgery).', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5e422ceb', 't-mm-09-031', 'text', 'COC, implants, - UKMEC (2).', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9a60edcf', 't-mm-09-031', 'text', 'Interval 2 – 3m0 between surgery and pregnancy =>   risk of PTL.', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c78851b4', 't-mm-09-031', 'text', '6m0 C/C is recommended after surgery.', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-77c3b450', 't-mm-09-031', 'text', 'ANC:', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3255cc6a', 't-mm-09-031', 'text', 'MDT – consultant led care.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b0678774', 't-mm-09-031', 'text', 'Vaginal progesterone, 200mg, B.D, 12 – 36weeks.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-148e7967', 't-mm-09-031', 'text', 'Fortnightly serial scan of isthmic length by expert.', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bd402b52', 't-mm-09-031', 'text', 'No need of another cerclage.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6cf5cbf4', 't-mm-09-031', 'text', 'Urine examination and vaginal swabs for culture and sensitivity booking then @ 16 – 24 weeks. Repeat tests if clinically indicated.', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c20efa12', 't-mm-09-031', 'text', 'Antibiotic cover if infection noted.', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2a294497', 't-mm-09-031', 'text', 'Avoid vaginal examination – unnecessary.', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8dcb6e5a', 't-mm-09-031', 'text', 'Avoid sexual inter course from 20 weeks as it    es infections.', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bb128329', 't-mm-09-031', 'text', 'Avoid exercise, weight lifting in 2nd .', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-302c1ae7', 't-mm-09-031', 'image', '/uploads/content-images/maternal_mind_book/image141.emf', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d68ca8ff', 't-mm-09-031', 'text', 'Avoid elective dental work in pregnancy as it    es PTL.', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-acde0f0f', 't-mm-09-031', 'text', 'A/B + steroids if PPROM.', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1c1b484b', 't-mm-09-031', 'text', 'EL – ISCS @ 37 weeks.', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d3371f9f', 't-mm-09-031', 'text', 'Planned + Pre labour C/S is recommended', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-16ebf1e9', 't-mm-09-031', 'text', 'Lower segment not formed so upper segment c section', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
