INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-92384fd3', 't-mm-09-032', 'text', 'Clause E – termination of abnormal fetus.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bd5fb30d', 't-mm-09-032', 'text', 'MFPR:', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c4aa5214', 't-mm-09-032', 'text', 'Clause C – Termination of 1 or 2 normal Fetus.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b267fa2c', 't-mm-09-032', 'text', 'Pre – requisites:', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4c78c579', 't-mm-09-032', 'text', 'Should be in fetal medicine unit.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5c34d85e', 't-mm-09-032', 'text', 'Assessment:', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ff1d2fb2', 't-mm-09-032', 'text', 'Chorionicity before 14 weeks.', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e83146cc', 't-mm-09-032', 'text', 'Documentation/ labelling of position, size Chorionicity, placental location and anatomic features.', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0f48b31e', 't-mm-09-032', 'text', 'All women with triplets or higher order pregnancies are offered MFPR.', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8f3a8a81', 't-mm-09-032', 'text', 'Referral within 5 days of request.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6def62b5', 't-mm-09-032', 'text', 'Reduction before 16 weeks (11 – 14weeks) is offered.', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bc2c8a53', 't-mm-09-032', 'text', 'Procedures that are independent of Chorionicity', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7a4769fc', 't-mm-09-032', 'text', '[1st   ST]', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6e040c10', 't-mm-09-032', 'image', '/uploads/content-images/maternal_mind_book/image142.emf', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-16d4ca81', 't-mm-09-032', 'text', 'MFPR or ST.', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e5c58466', 't-mm-09-032', 'text', 'Between 11 – 14 weeks – 2 reasons:', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ec347c1d', 't-mm-09-032', 'text', 'Spontaneous miscarriages have occurred.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2b4d982c', 't-mm-09-032', 'text', 'Anatomical survey is done including NT.', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5ec52485', 't-mm-09-032', 'text', 'Injection of 15% kcl, Intracardiac, 0.5 – 2ml till Asystole is confirmed.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6b3400d4', 't-mm-09-032', 'text', 'Choice of embryo depends on:', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1e61f122', 't-mm-09-032', 'text', 'NT.', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9f7e5395', 't-mm-09-032', 'text', 'CRL – small twin.', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2bec6e75', 't-mm-09-032', 'text', 'Location of sac.', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b7fceb0d', 't-mm-09-032', 'text', 'Markers of aneuploidy.', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-24f7339c', 't-mm-09-032', 'text', 'Technically approach able and furthest away from CX', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8094b586', 't-mm-09-032', 'text', '[3rd  ST', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1fe88f6b', 't-mm-09-032', 'image', '/uploads/content-images/maternal_mind_book/image142.emf', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dff75785', 't-mm-09-032', 'text', 'Don’t do MFPR after 16 weeks, only ST in 3rd', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3a60d94', 't-mm-09-032', 'image', '/uploads/content-images/maternal_mind_book/image142.emf', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2c1cc318', 't-mm-09-032', 'text', 'Safest time is after 32 weeks – less chance of miscarriage and PTL (severe).', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66fea8ba', 't-mm-09-032', 'text', 'Prophylactic steroid before 32 weeks.', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d777be0d', 't-mm-09-032', 'text', 'Intracardiac injection of KCL (5 – 10ml) or lidocaine (10 – 30ml) 1%.', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0fd2ebfa', 't-mm-09-032', 'text', 'Repeat diagnosis if differentiating features are absent.', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aebcdc8c', 't-mm-09-032', 'text', '[Diagnosis and termination by same specialist]', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-306550aa', 't-mm-09-032', 'text', 'Procedures for monochorionic fetuses:', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-267f1498', 't-mm-09-032', 'text', 'Radiofrequency ablation:', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-402145ef', 't-mm-09-032', 'text', 'RFA 15 – 27weeks.', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c17c01f1', 't-mm-09-032', 'text', '17G RFA needle @ I/fetal portion of cord.', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-44a98e3c', 't-mm-09-032', 'text', 'Energy applied @ RFA needle till temperature of 1100 for 3 min.', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-79e67fc7', 't-mm-09-032', 'text', 'Done for MCDA twins for anomaly or SGA.', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-805d2164', 't-mm-09-032', 'text', 'Procedure of choice in MFPR @ earlier gestations. Also, for ST in Acardiac twin in TRAP.', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-57c428f0', 't-mm-09-032', 'text', 'Bipolar diathermy cord coagulation:', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0520ef84', 't-mm-09-032', 'text', '18 – 27 weeks.', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eb56813b', 't-mm-09-032', 'text', 'Intra Amniotic 2.7mm or 3.3mm S/C port is placed under L/A.', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d7577ca1', 't-mm-09-032', 'text', '30 – 50 w diathermy for 60 sec till no flow in cord', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-941cf500', 't-mm-09-032', 'text', 'Cord should be < 12mm.', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-024ffff3', 't-mm-09-032', 'text', 'Intra Fetal laser ablation:', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e5349c47', 't-mm-09-032', 'text', 'Intra-abdominal aortopelvic vessels.', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-35b5f94a', 't-mm-09-032', 'text', 'ND – Yag laser.', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e9d69688', 't-mm-09-032', 'text', 'When free loop of cord is not visible like TRAP.', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6dab25a5', 't-mm-09-032', 'text', 'Suture Ligation – after 26 weeks:', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4f34bab2', 't-mm-09-032', 'text', 'When cord is thick for RFA or diathermy or ablation.', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
