INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-256350aa', 't-mm-09-033', 'text', 'Risks:', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8cb4a721', 't-mm-09-033', 'text', 'Hypoglycemia to neonate', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d8ee44c8', 't-mm-09-033', 'text', 'Potential developmental delay', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e293e43e', 't-mm-09-033', 'text', 'Steroid talk:', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f3138ace', 't-mm-09-033', 'text', 'Discussion before offering or considering steroid.', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b2ef0eda', 't-mm-09-033', 'text', 'Should involve women in discussion', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c802148f', 't-mm-09-033', 'text', 'Informed decision of women should be there', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-391a9213', 't-mm-09-033', 'text', 'It is Gestation related', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-51fb837d', 't-mm-09-033', 'text', 'Discussion should be based on following points', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7041eeb7', 't-mm-09-033', 'text', 'Table 42. ANTENATAL CORTICOSTEROID', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-354fb547', 't-mm-09-033', 'html', '<table><tbody><tr><td>Gestation</td><td>Benefits</td><td>Risks</td><td>Uncertainties</td></tr><tr><td>22 – 34+6 weeks</td><td>Highly likely:<br/>NND<br/>Perinatal death<br/>RDS<br/>Likely<br/>Interventricular haemorrhage<br/>Developmental delay<br/>Benefits are more if birth occurs 24 – 48 hours after treatment<br/>Respiratory morbidity reduction is likely if birth occurs within 7 days of treatment.</td><td>Likely:<br/>Affect maternal OGTT up to 5 days<br/>Birth weight if birth occurs after 7 days.<br/>May:<br/>Psychiatric diagnosis and Behavioral problem in children</td><td>Long term harms<br/>Risks/ benefits in multiple pregnancies.</td></tr><tr><td>35 – 36+6 weeks</td><td>Likely:<br/>Respiratory support</td><td>Likely:<br/>Neonatal hypoglycemia<br/>May    :<br/>Psychiatric and behavioral diagnosis</td><td>Benefits are unlikely if birth is after 7 days.</td></tr><tr><td>Planned C/S<br/>@ 37 – 39weeks</td><td>May    :<br/>NNU admission with respiratory morbidity</td><td>May   :<br/>Educational attainment @ school</td><td>Reduction in:<br/>RDS<br/>TTN<br/>Overall NNU admission<br/>Short term hypoglycemia<br/>Benefits are unlikely if birth occurs after 7 days.</td></tr><tr><td>Rescue course if treatment >7 days</td><td>Likely    :<br/>Need for respiratory support</td><td>Likely    :<br/>Birth weight<br/>Head circumference<br/>Length<br/>Neonatal B.P</td><td>Dose dependent effects.</td></tr></tbody></table>', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-048cf63f', 't-mm-09-033', 'text', 'Recommendations of Steroids:', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4639a668', 't-mm-09-033', 'html', '<table><tbody><tr><td>Before 24 weeks</td><td>Discuss</td></tr><tr><td>24 – 34+6 weeks where preterm is anticipated</td><td>Discuss and offer</td></tr><tr><td>35 – 36+6</td><td>Consider the balance of risks and benefits</td></tr><tr><td>Twins and triplets</td><td>Targeted steroid same as singleton<br/>Only targeted used</td></tr><tr><td>Diabetes Mellitus</td><td>Not a contraindication<br/>Additional insulin and close monitoring<br/>Steroid discussion with women or her carer @ 37 – 38+6 weeks about the risk and benefits, corticosteroids are associated with neonatal hypoglycemia.</td></tr><tr><td>Hypertension</td><td>Offer after discussion in case of planned early birth<br/>Offer to SGA, FGR babies if birth is expected earlier but inform regarding lack of evidence.</td></tr><tr><td>PPROM</td><td>Offer if birth is expected to be preterm<br/>Limited evidence to recommend repeat courses, however further courses may reduce need for neonatal respiratory support.</td></tr></tbody></table>', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1b94ad0a', 't-mm-09-033', 'text', 'Dose and route of Steroids:', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6843b459', 't-mm-09-033', 'text', 'Dexamethasone Phosphate, I/M:', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bf5b4cf6', 't-mm-09-033', 'text', '24 mg', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c03bd71d', 't-mm-09-033', 'text', '2 doses4 doses', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ae2fdd95', 't-mm-09-033', 'text', '12 mg6 mg', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c3e07a11', 't-mm-09-033', 'text', '24 hours apart12 hours apart', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-68aaaa88', 't-mm-09-033', 'text', 'Betamethasone sodium Phosphate/ Acetate mix, I/M:', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7a3c6f55', 't-mm-09-033', 'text', '24mg total', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e0f9c5ce', 't-mm-09-033', 'text', '2 doses', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f9902dde', 't-mm-09-033', 'text', '24 hours apart', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0dc70011', 't-mm-09-033', 'text', 'How long after Administration is a course more effective:', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2af754e2', 't-mm-09-033', 'text', 'After 48 hours of dose, Neonatal death is reduced.', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f84da847', 't-mm-09-033', 'text', 'After 24 hours of 1st dose, benefits seen', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d11ef356', 't-mm-09-033', 'text', 'Most effective in reducing RDS if birth occurs between 24 hours to 7 days of 2nd dose.', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c8839eb5', 't-mm-09-033', 'text', 'Contraindications of Steroid:', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3180ad57', 't-mm-09-033', 'text', 'Systemic infections', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0eac7f4f', 't-mm-09-033', 'text', 'In case of serious concerns, birth should not be delayed to administer steroid.', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a823973c', 't-mm-09-033', 'text', 'Repeat Course of Steroids:', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d2cfa899', 't-mm-09-033', 'text', 'No reduction in serious morbidity or long-term benefits to babies instead risk of low birth weight and reduced length', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b47f1d4e', 't-mm-09-033', 'text', 'Limited evidence to recommend repeat course of steroid.', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1ca599b2', 't-mm-09-033', 'text', 'Repeat course reduce need for neonatal respiratory support', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5528614a', 't-mm-09-033', 'text', 'Repeat courses should not exceed three.', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-09-034', 'chap-mm-09-01', '21. CERVICAL CERCLAGE', 'Detailed medical reference and study guide on 21. CERVICAL CERCLAGE.', 34, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-43d066f0', 't-mm-09-034', 'text', 'Definitions:', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b9e2f1ba', 't-mm-09-034', 'text', 'History indicated Cerclage:', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3ba4efd', 't-mm-09-034', 'text', 'Cerclage as a result of factors in a women’s obstetric or gyaecological history which     the risk of spontaneous 2nd  loss or preterm birth.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4036d59d', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c593d9d6', 't-mm-09-034', 'text', 'Prophylactic cerclage', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-015d2679', 't-mm-09-034', 'text', 'Offer @ 11 – 14 weeks.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-41f9f3b8', 't-mm-09-034', 'text', 'Ultrasound indicated cerclage:', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-08b7f916', 't-mm-09-034', 'text', 'Cerclage is inserted as a therapeutic measure in cases of cervical length shortening seen on transvaginal ultrasound.', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e6967b99', 't-mm-09-034', 'text', 'Prophylactic length is measured between 14 – 24 weeks by TVS and with an empty bladder', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-57d74b03', 't-mm-09-034', 'text', 'Done if cervical length is <25m @ gestation <24 weeks.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d410e7ae', 't-mm-09-034', 'text', 'Emergency cerclage/ Physical exam indicated cerclage:', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-87d6acbc', 't-mm-09-034', 'text', 'Insertion of cerclage as salvage measure in case of premature cervical dilatation with exposed fetal membranes in vagina', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ca9a8dd5', 't-mm-09-034', 'text', 'Pt can present with vaginal discharge, bleeding or sensation of pressure', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a2dd9794', 't-mm-09-034', 'text', 'Can be applied up to 27+6 weeks', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9ee280c2', 't-mm-09-034', 'text', 'Types of Cerclage:', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bc8f32c4', 't-mm-09-034', 'text', 'Transvaginal (McDonald):', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-534f1d36', 't-mm-09-034', 'text', 'Suture placed @ cervical isthmus junction without bladder mobilization.', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c29b2b0b', 't-mm-09-034', 'text', 'High transvaginal cerclage (Shirodkar)', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4d242854', 't-mm-09-034', 'text', 'Purse string suture placed following bladder mobilization, to allow insertion above the level of cardinal ligaments.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-44f32a4c', 't-mm-09-034', 'text', 'Transabdominal Cerclage:', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-567a2251', 't-mm-09-034', 'text', 'Suture performed via laparotomy or laparoscopy, placing the suture @ cervico isthmic junction.', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dda4a0c8', 't-mm-09-034', 'text', 'Occlusion Cerclage:', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-19d36ec0', 't-mm-09-034', 'text', 'Occlusion of external OS by placement of a continuous non-absorbable suture.', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-18bdda83', 't-mm-09-034', 'text', 'Purpose is the retention of mucus plug.', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4c1a77c3', 't-mm-09-034', 'text', 'Recommendations of Cervical Cerclage:', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-84f7eb44', 't-mm-09-034', 'text', 'History indicated', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-27f7aba8', 't-mm-09-034', 'text', '3 or more preterm birth or 2nd  miscarriages.', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8750b396', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-43182510', 't-mm-09-034', 'text', 'It reduces perinatal death', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3056588c', 't-mm-09-034', 'text', 'No benefit of this cerclage to those who has previous cervical surgery or uterine anomalies', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-574ec7fd', 't-mm-09-034', 'text', 'It is unknown that the characteristics of previous events are helpful or not (painless dilatation, rupture of membranes, prior cervical surgery).', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-31e42084', 't-mm-09-034', 'text', 'Ultrasound indicated:', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-80650dc7', 't-mm-09-034', 'text', 'Not affected to those who has incidental short length in late 2nd  without risk factors.', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-26b8ab9f', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b6ff76c9', 't-mm-09-034', 'text', 'Offered to those who had one or more preterm birth or 2nd loss along with cervical length <25mm measured @ <24weeks.', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5e278631', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e923481d', 't-mm-09-034', 'text', 'Not offered to those who has cervical funneling without short cervical length <25mm', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ec25ba51', 't-mm-09-034', 'text', 'USG surveillance of cervical length is offered to those who have previous preterm birth or 2nd  loss, by TVS with empty bladder and @ 16 – 24weeks, every 2 – 4weeks.', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7c24fe47', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e0a68ad0', 't-mm-09-034', 'text', 'Other women where cervical length need to be measured are either high risk or intermediate risk.', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4c99f013', 't-mm-09-034', 'text', 'High Risk:', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0173e6e3', 't-mm-09-034', 'text', 'Previous PPROM < 34 weeks', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e86f3b7e', 't-mm-09-034', 'text', 'Previous use of cerclage', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-716316ee', 't-mm-09-034', 'text', 'Known uterine variant', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8a295676', 't-mm-09-034', 'text', 'Intrauterine adhesions', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-17a2fe30', 't-mm-09-034', 'text', 'History of trachelectomy', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b7e4b41c', 't-mm-09-034', 'text', 'Intermediate Risk:', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f97b5969', 't-mm-09-034', 'text', 'Previous C/S at full dilatation', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-189ee75b', 't-mm-09-034', 'text', 'LLETZ with excision depth >1cm, more', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9a213027', 't-mm-09-034', 'text', 'than 1 procedure or more than 1 cone biopsy.', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e68139fd', 't-mm-09-034', 'text', 'Multiple Pregnancy:', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8c3c3db3', 't-mm-09-034', 'text', 'not offered either cerclage', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-48944a0c', 't-mm-09-034', 'text', 'Raised BMI:', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b0f57d41', 't-mm-09-034', 'text', 'BMI >25, cerclage is effective in those who has cervical length <25mm', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1e19b1bf', 't-mm-09-034', 'text', 'Transabdominal Cervical Cerclage:', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ffb42683', 't-mm-09-034', 'text', 'Consider and discuss in women with failed or unsuccessful transvaginal cerclage', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dac2dc45', 't-mm-09-034', 'text', 'Can be performed pre conceptually or in early pregnancy. Pre conceptually performed cerclage is more effective than antenatal cerclage. It is not associated with subfertility', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b37d4d7c', 't-mm-09-034', 'text', 'Can be performed laparoscopically', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b7885efb', 't-mm-09-034', 'text', 'Laparoscopy should be considered where possible as it has fewer complication.', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b15eb959', 't-mm-09-034', 'text', 'In case of delayed miscarriage or fetal death, decision of TOP is difficult up to 18 weeks suction curettage or dilatation and curettage can be performed via stitch.', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9743da39', 't-mm-09-034', 'text', '>18 weeks, stitch can be opened via posterior colpotomy. Failed colpotomy can led to hysterotomy or C/S. decision should be aided by senior obstetrician.', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dafbafbe', 't-mm-09-034', 'text', 'Emergency Cerclage:', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4fc9f20f', 't-mm-09-034', 'text', 'Individualized decision by taking into account the risks and benefits.', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bdf83330', 't-mm-09-034', 'text', 'Women’s decision should be aided by senior obstetrician', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6422b379', 't-mm-09-034', 'text', 'It can prolong pregnancy up to 34 weeks', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e940ba85', 't-mm-09-034', 'text', 'It can reduce chance of birth by 2-fold before 34 weeks.', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-caf23507', 't-mm-09-034', 'text', 'Advanced dilatation of cervix > 4cm or membrane prolapse beyond external os appears to be associated with higher cerclage failure.', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eefa687e', 't-mm-09-034', 'text', 'Not justified beyond 24 weeks due to', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e072ba03', 't-mm-09-034', 'text', 'potential risk of iatrogenic membrane rupture and subsequent preterm.', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f2294aee', 't-mm-09-034', 'text', 'Contraindications of cerclage:', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b437cba8', 't-mm-09-034', 'text', '1. active preterm labour', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5b6b6f24', 't-mm-09-034', 'text', '2. clinical Chorioamnionitis', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f592543e', 't-mm-09-034', 'text', '3. continuing vaginal bleeding.', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-069e3d36', 't-mm-09-034', 'heading', '4. PPROM', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3b3f855d', 't-mm-09-034', 'text', '5. Evidence of fetal defects', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e23d357d', 't-mm-09-034', 'text', '6. Lethal fetal defects', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d65d681c', 't-mm-09-034', 'text', '7. Fetal death', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2c1fcef2', 't-mm-09-034', 'text', 'Risk of cervical cerclage:', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-30d67a40', 't-mm-09-034', 'text', 'Small risk of intraoperative bladder damage, cervical trauma, membrane rupture, bleeding.', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6975318d', 't-mm-09-034', 'text', 'Cervical trauma/ laceration in case of labour with suture in place.', 80) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ca8eaf95', 't-mm-09-034', 'text', 'High vaginal cerclage needs anaesthesia for insertion and removal.', 81) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-171bd71e', 't-mm-09-034', 'text', 'No association with PPROM, Chorioamnionitis IOL or C/S (except Emergency cerclage).', 82) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d34a1629', 't-mm-09-034', 'text', 'No association with preterm birth or 2nd  loss (except emergency cerclage).', 83) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-845cc00c', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 84) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ecf00e92', 't-mm-09-034', 'text', 'Risks and benefits should be discussed with women, both verbal and written information should be given before insertion of cerclage.', 85) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-551f9d7b', 't-mm-09-034', 'text', 'Investigation before cerclage insertion:', 86) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b79d655e', 't-mm-09-034', 'text', '1. History indicated cerclage.', 87) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6ddc7ead', 't-mm-09-034', 'text', '1st  USG', 88) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-668ad006', 't-mm-09-034', 'image', '/uploads/content-images/maternal_mind_book/image143.emf', 89) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3357cc06', 't-mm-09-034', 'text', 'Aneuploidy screening', 90) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-16720396', 't-mm-09-034', 'heading', '2. USG indicated or emergency cerclage anomaly scan.', 91) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2a004adc', 't-mm-09-034', 'heading', '3. CRP + TLC count if clinical picture exists.', 92) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3836683f', 't-mm-09-034', 'text', 'TLC cut off <14,000/micro liter', 93) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1931fbb8', 't-mm-09-034', 'text', 'CRP cut off <4 mg/dl', 94) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ba60ce66', 't-mm-09-034', 'text', '4. Amniocentesis', 95) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c4d3354b', 't-mm-09-034', 'text', '- Not before ultrasound or history indicated cerclage', 96) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2b313225', 't-mm-09-034', 'text', '- Can be done before emergency cerclage in cases where there is clinical suspicion of Intra amniotic infection.', 97) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3e39c4e2', 't-mm-09-034', 'text', '5. Amnioreduction', 98) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4ea5340b', 't-mm-09-034', 'text', '- No data exists', 99) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-133288db', 't-mm-09-034', 'text', '6. Genital Screening', 100) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-87dafa30', 't-mm-09-034', 'text', '- Not undertaken routinely', 101) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-704a3d11', 't-mm-09-034', 'text', 'Operative issues:', 102) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4a563f03', 't-mm-09-034', 'text', 'Can be performed safely as day case procedure', 103) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d011587d', 't-mm-09-034', 'text', 'Tocolysis:', 104) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-df99b25a', 't-mm-09-034', 'text', 'Consider on individual basis', 105) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-37bfceef', 't-mm-09-034', 'text', 'Not routinely', 106) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-58680aee', 't-mm-09-034', 'text', 'Antibiotics before cerclage', 107) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7151f0f9', 't-mm-09-034', 'text', 'Surgeon’s choice', 108) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9cd5c194', 't-mm-09-034', 'text', 'Anaesthesia', 109) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2a50caaa', 't-mm-09-034', 'text', 'Decision by operating team along with women', 110) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-79be914a', 't-mm-09-034', 'text', 'Suture material', 111) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5d95e0e7', 't-mm-09-034', 'text', 'Non absorbable suture, surgeon’s discretion.', 112) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-01a95bdc', 't-mm-09-034', 'text', 'Type of cerclage:', 113) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5759a45e', 't-mm-09-034', 'text', 'Depends on surgeon’s choice', 114) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-049d685c', 't-mm-09-034', 'text', 'High/ low cerclage has similar outcome.', 115) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-184297c4', 't-mm-09-034', 'text', 'Try to place suture in cervix as high as possible', 116) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-929371f0', 't-mm-09-034', 'text', 'No difference between two possible string or single suture. It’s surgeon’s discretion.', 117) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ae42a0c0', 't-mm-09-034', 'text', 'Occlusion suture in addition to primary suture not applied routinely', 118) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d2f16a9c', 't-mm-09-034', 'text', 'Bed Rest:', 119) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5ee4300c', 't-mm-09-034', 'text', 'Not recommended routinely', 120) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a9405035', 't-mm-09-034', 'text', 'Sexual intercourse:', 121) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c2da8185', 't-mm-09-034', 'text', 'Abstinence not recommended routinely.', 122) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-99d75589', 't-mm-09-034', 'text', 'Post cerclage serial USG for cervical length:', 123) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6658b4e4', 't-mm-09-034', 'text', 'Not done routinely', 124) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7cc73323', 't-mm-09-034', 'text', 'Selected USG indicated cerclage cases to offer timely steroid and in utero transfer.', 125) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f41ea7a7', 't-mm-09-034', 'text', 'Fetal fibronectin:', 126) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7b6a5e95', 't-mm-09-034', 'text', 'Not recommended routinely', 127) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8c86bc6d', 't-mm-09-034', 'text', 'High negative predictive value can reassure the women.', 128) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-53659f93', 't-mm-09-034', 'text', 'Progesterone supplementation:', 129) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6872c74b', 't-mm-09-034', 'text', 'Not recommended routinely', 130) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-87cfc375', 't-mm-09-034', 'text', 'Arabian pessary or progesterone', 131) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-04321082', 't-mm-09-034', 'text', 'None of them is more effective than cerclage', 132) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-447baa1b', 't-mm-09-034', 'text', 'Removal of Cerclage:', 133) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-29901a0c', 't-mm-09-034', 'text', '1. @ 36+1 – 37weeks before labour', 134) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-161b38dd', 't-mm-09-034', 'text', '2. Women presenting in active labour, remove cerclage to prevent cervical trauma.', 135) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fd031f84', 't-mm-09-034', 'text', '3. Abdominal cerclage need not to be removed. Deliver by C/S and leave cerclage in place.', 136) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f4b0a7ee', 't-mm-09-034', 'text', 'PPROM and Cerclage removal:', 137) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6f33da11', 't-mm-09-034', 'text', 'PPROM between 24 – 34 weeks + No infections => Delayed removal by 48 hours.', 138) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8d49d033', 't-mm-09-034', 'text', 'Delayed removal until labour ensures or birth indicated is associated with an     risk of maternal/fetal sepsis and is not recommended.', 139) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5aab4d8c', 't-mm-09-034', 'heading', 'LABOUR AND DELIVERY', 140) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c65faddb', 't-mm-09-034', 'text', 'LABOUR AND DELIVERY:', 141) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO books (id, title, description, is_published, "order") VALUES ('book-mm-10', 'LABOUR AND DELIVERY', 'Comprehensive OB-GYN study module covering LABOUR AND DELIVERY.', true, 10) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO chapters (id, book_id, title, description, "order", is_published) VALUES ('chap-mm-10-01', 'book-mm-10', 'LABOUR AND DELIVERY Core Topics', 'Core topics for LABOUR AND DELIVERY', 1, true) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, is_published=true;
