INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0b26d72f', 't-mm-10-002', 'text', 'Birth in Obstetric unit.', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-42294f32', 't-mm-10-002', 'text', 'There is   ed risk for women or baby during or shortly after labor', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eff7e1e3', 't-mm-10-002', 'text', 'Table 43: Medical conditions requiring birth in obstetric unit', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-04793675', 't-mm-10-002', 'html', '<table><tbody><tr><td>Disease area</td><td>Medical condition</td></tr><tr><td>Cardiovascular</td><td>Confirmed cardiac disease<br/>Hypertensive disorders</td></tr><tr><td>Respiratory</td><td>Asthma requiring an increase in treatment or hospital treatment<br/>Cystic fibrosis</td></tr><tr><td>Haematological</td><td>Haemoglobinopathies, such as sickle-cell disease, beta- thalassemia major<br/>History of thromboembolic disorders<br/>Immune thrombocytopenia purpura or other platelet disorder or platelet count below 100×109/liter<br/>Von Willebrand''s disease<br/>Bleeding disorder in the woman or unborn baby<br/>Atypical antibodies which carry a risk of haemolytic disease of the newborn</td></tr><tr><td>Endocrine</td><td>Hyperthyroidism<br/>Diabetes needing medication</td></tr><tr><td>Infective</td><td>Hepatitis B or C with abnormal liver function tests<br/>Toxoplasmosis – women receiving treatment<br/>Current active infection of chicken pox, rubella or genital herpes in the woman or baby<br/>Tuberculosis under treatment</td></tr><tr><td>Immune</td><td>Systemic lupus erythematosus<br/>Scleroderma</td></tr><tr><td>Renal</td><td>Abnormal renal function<br/>Renal disease requiring supervision by a renal specialist</td></tr><tr><td>Neurological</td><td>Epilepsy<br/>Myasthenia gravis<br/>Previous cerebrovascular accident</td></tr><tr><td>Gastrointestinal</td><td>Liver disease associated with current abnormal liver function tests</td></tr><tr><td>Psychiatric</td><td>Psychiatric disorder requiring current inpatient care</td></tr></tbody></table>', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6b6542ad', 't-mm-10-002', 'text', 'Table 44 Other factors indicating increased risk and suggesting planned birth at an obstetric unit', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3aae98f8', 't-mm-10-002', 'html', '<table><tbody><tr><td>Factor</td><td>Additional information</td></tr><tr><td>Previous complications</td><td>• Unexplained stillbirth or neonatal death, or previous death related to intrapartum difficulty<br/>• Previous baby with neonatal encephalopathy<br/>• Pre-eclampsia requiring preterm birth<br/>• Placental abruption with adverse outcome<br/>• Eclampsia<br/>• Uterine rupture<br/>• Primary postpartum haemorrhage requiring additional treatment or blood transfusion<br/>• Caesarean birth<br/>• Shoulder dystocia</td></tr><tr><td>Current pregnancy</td><td>• Multiple birth<br/>• Placenta previa<br/>• Pre-eclampsia or pregnancy-induced hypertension<br/>• Preterm labour or preterm prelabour rupture of membranes<br/>• Placental abruption<br/>• Anaemia – hemoglobins less than 85 g/liter at onset of labour<br/>• Confirmed intrauterine death<br/>• Substance misuse<br/>• Alcohol dependency requiring assessment or treatment<br/>• Gestational diabetes needing medication<br/>• Malpresentation – breech or transverse lie<br/>• Recurrent antepartum haemorrhage<br/>• Small for gestational age in this pregnancy (less than third centile or reduced growth velocity on ultrasound as defined in the NHS Saving babies lives version 3)<br/>• Abnormal fetal heart rate, umbilical or fetal doppler studies<br/>• Ultrasound diagnosis of oligo- or polyhydramnios</td></tr><tr><td>Previous gynaecological history</td><td>• Myomectomy<br/>• Hysterotomy</td></tr></tbody></table>', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b11b3212', 't-mm-10-002', 'text', 'Individualized assessment in Birth Planning', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-16524911', 't-mm-10-002', 'text', 'History not itself a reason for advising birth in an obstetric unit but indicate that further consideration of birth setting may be needed.', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cbb7a315', 't-mm-10-002', 'text', 'Table 45. Medical conditions indicating individual assessment is needed when planning place of birth', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-115b1360', 't-mm-10-002', 'html', '<table><tbody><tr><td>Disease area</td><td>Medical condition</td></tr><tr><td>Cardiovascular</td><td>Cardiac disease without intrapartum implications</td></tr><tr><td>Disease area</td><td>Medical condition</td></tr><tr><td>Haematological</td><td>Atypical antibodies not putting the baby at risk of haemolytic disease<br/>Sickle-cell trait<br/>Thalassemia trait<br/>Anaemia – hemoglobin 85 to 105 g/liters at onset of labour</td></tr><tr><td>Endocrine</td><td>Unstable hypothyroidism such that a change in treatment is needed</td></tr><tr><td>Infective</td><td>Group B streptococcus where intrapartum intravenous antibiotics are recommended<br/>Hepatitis B or C with normal liver function tests (as baby will need paediatric review after birth)<br/>Carrier of or infected with HIV</td></tr><tr><td>Immune</td><td>Non-specific connective tissue disorders</td></tr><tr><td>Skeletal/ Neurological</td><td>Spinal abnormalities<br/>Previous fractured pelvis<br/>Neurological deficits</td></tr><tr><td>Gastrointestinal</td><td>Liver disease without current abnormal liver function<br/>Crohn''s disease<br/>Ulcerative colitis</td></tr></tbody></table>', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6ff6b9a8', 't-mm-10-002', 'text', 'Table 46. Other factors to take into account when planning place of birth', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-be43d966', 't-mm-10-002', 'html', '<table><tbody><tr><td>Factor</td><td>Additional information</td></tr><tr><td>Previous complications</td><td>Stillbirth or neonatal death with a known non-recurrent cause<br/>Pre-eclampsia developing at term<br/>Placental abruption with good outcome<br/>History of previous baby more than 4.5 kg<br/>Extensive vaginal, cervical, or third- or fourth-degree perineal trauma<br/>Retained placenta needing manual removal in theatre<br/>Previous term baby with jaundice requiring exchange transfusion<br/>Major gynaecological surgery</td></tr><tr><td>Current pregnancy</td><td>Antepartum bleeding of unknown origin (single episode after 24 weeks of pregnancy)<br/>Body mass index (BMI) at booking (see the section on impact of BMI on choice of place of birth)<br/>Blood pressure of 140 mmHg systolic or 90 mmHg diastolic or more on 2 occasions<br/>Clinical or ultrasound suspicion of macrosomia<br/>Induction of labour<br/>Grand multiparity (parity 4 or more)<br/>Recreational drug use<br/>Under current outpatient psychiatric care<br/>Age 40 or over at booking<br/>Fibroids<br/>Fetal abnormality</td></tr></tbody></table>', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cae31c77', 't-mm-10-002', 'text', 'Care during labor:', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
