INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-878126d8', 't-mm-10-003', 'text', 'More effective pain relief', 85) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
