INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ce46686b', 't-mm-10-003', 'text', 'No long-term backache', 87) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b6cb83c7', 't-mm-10-003', 'text', 'No prolonged 1st stage.', 88) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
