INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7a0184f1', 't-mm-10-003', 'text', 'ed chance of headache', 93) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ba1c1738', 't-mm-10-003', 'text', 'Care and observation with regional analgesia:', 94) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c8012248', 't-mm-10-003', 'text', 'I/V line', 95) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2273a35e', 't-mm-10-003', 'text', 'Pre – loading and maintenance fluids not required with low dose epidural or combined spinal – epidural', 96) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-60420bc2', 't-mm-10-003', 'text', 'Monitor B.P every 5 min for 15 min after loading dose and maintenance doses (10ml or above)', 97) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a10887d3', 't-mm-10-003', 'text', 'Talk to anesthetist if not pain free after 30min of dose', 98) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0456259e', 't-mm-10-003', 'text', 'Assess sensory block level 1 hourly.', 99) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d5615335', 't-mm-10-003', 'text', 'Assess motor block 1 hourly by asking to do straight leg raise. If she is unable to raise leg, ask anesthetist to review.', 100) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-773f5919', 't-mm-10-003', 'text', 'Adapt position whatever she likes except lying flat on her back.', 101) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c18153ed', 't-mm-10-003', 'text', 'Mobilize if can', 102) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2d51c0a1', 't-mm-10-003', 'text', 'Delayed pushing for 1 hours in multi and 1 hour in primigravida after full dilatation unless she has an urge to actively push. After this time encourage woman to actively push during contraction.', 103) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a536e115', 't-mm-10-003', 'text', 'No oxytocin routinely', 104) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-16325552', 't-mm-10-003', 'text', 'cCTG for 30min after loading dose as well as after each bolus of 10ml or above.', 105) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-51f7bcd2', 't-mm-10-003', 'text', 'Continue regional analgesia until completion of 3rd stage of labor or perineal tear repair.', 106) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bd3a5ffb', 't-mm-10-003', 'text', 'Establishing and Maintaining Regional Analgesia:', 107) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-91bd5a4d', 't-mm-10-003', 'text', 'Use either epidural or combined spinal – epidural analgesia for establishing regional analgesia in labour', 108) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b0a5d2de', 't-mm-10-003', 'text', 'If rapid analgesia is needed use CSE', 109) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4382313d', 't-mm-10-003', 'text', 'Establish CSE with bupivacaine and fentanyl', 110) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-39e0cb08', 't-mm-10-003', 'text', 'Establish epidural analgesia with a low concentration local anesthetic and fentanyl solution – administer test dose initially to ensure that in-advertent intrathecal or intra vascular placement of epidural catheter has not occurred.', 111) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f2e282e3', 't-mm-10-003', 'text', 'Maintenance dose should be low concentration solution. 0.0625% to 0.125%', 112) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-62d9359c', 't-mm-10-003', 'text', 'Bupivacaine combined with 2-3 micrograms per ml fentanyl.', 113) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0f21391c', 't-mm-10-003', 'text', 'Bupivacaine or equivalent can be used as local anesthetic component of solution.', 114) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4a34cb97', 't-mm-10-003', 'text', 'Patient controlled epidural analgesia can be used by trained healthcare professional for maintenance.', 115) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c8f6a3f5', 't-mm-10-003', 'text', 'Don’t use high concentration solution of local anesthetic 0.25% or above routinely either for establishment or maintenance.', 116) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0d92d34e', 't-mm-10-003', 'text', 'PROM:', 117) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-af9d6a3a', 't-mm-10-003', 'text', 'Advice women to call midwife immediately on phone.', 118) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-28d2f735', 't-mm-10-003', 'text', 'Immediate review of a women if risk factor present.', 119) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
