INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ac09032d', 't-mm-10-003', 'text', 'Immediate review of women with PROM', 131) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5ce23849', 't-mm-10-003', 'text', 'Above risk factor present', 132) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5dacb8fc', 't-mm-10-003', 'text', 'Women have any concern', 133) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b24c476b', 't-mm-10-003', 'text', 'Women want IOL', 134) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7fffd283', 't-mm-10-003', 'text', 'Something changed.', 135) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f684169d', 't-mm-10-003', 'text', 'Home review by Midwife:', 136) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-957258f6', 't-mm-10-003', 'text', 'If no risk factor', 137) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bc3d0641', 't-mm-10-003', 'text', 'Women want to wait for spontaneous onset of labour', 138) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4f96d930', 't-mm-10-003', 'text', 'Don’t offer speculum examination if it is certain that membranes have ruptured.', 139) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b88fdea3', 't-mm-10-003', 'text', 'Offer speculum examination if diagnosis is not clear', 140) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eb0e5b2f', 't-mm-10-003', 'text', 'Don’t offer digital examination in the absence of contractions.', 141) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2e813eae', 't-mm-10-003', 'text', '60% women with PROM go into labour in 24 hours', 142) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ff828a5f', 't-mm-10-003', 'text', 'Neonatal risk with PROM 1% rather 0.5% with intact membranes.', 143) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0404684f', 't-mm-10-003', 'text', 'Discuss benefits and risks of expectant management vs IOL', 144) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-10fa29f8', 't-mm-10-003', 'text', 'If women choses expectant management', 145) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-18544112', 't-mm-10-003', 'text', 'No need of vaginal swab and CRP', 146) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0c3dc43c', 't-mm-10-003', 'text', 'Temp recording 4 hourly during walking hour and report immediately if change happens.', 147) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e77659e3', 't-mm-10-003', 'text', 'Any change in color and smell of vaginal discharge do report immediately', 148) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e1ef59b7', 't-mm-10-003', 'text', 'Can take shower or bath', 149) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a7974853', 't-mm-10-003', 'text', 'Avoid sexual intercourse –    risk of infection.', 150) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e7ee5fc1', 't-mm-10-003', 'text', 'FM and FHR @ initial visit and then every 24 hours till in labor. Advice women to report immediately if there is RFM.', 151) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-21e070a0', 't-mm-10-003', 'text', 'If labour is not started after 24 hours of PROM, advice women to give birth in alongside midwifery unit or obstetric unit because there is risk of neonatal complication and maternal infection. She is also advised to stay at least for 12 hours after birth.', 152) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7fbd7f3f', 't-mm-10-003', 'text', 'If women are GBS positive at any stage of this pregnancy or had baby with GBS infection, offer immediate birth along with IPA prophylaxis.', 153) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-10-004', 'chap-mm-10-01', '1.3.1ST STAGE OF LABOR', 'Detailed medical reference and study guide on 1.3.1ST STAGE OF LABOR.', 4, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
