INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dfb214be', 't-mm-10-004', 'text', 'Primigravida, 8 – 18 hours, 2nd gravida onwards 5 – 12 hours.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
