INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-23cbb958', 't-mm-10-004', 'text', 'PPI don’t offer routinely', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-10142d61', 't-mm-10-004', 'text', 'PPI offer to those who received opioids or going to have C/S.', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d9f86bf7', 't-mm-10-004', 'text', 'Drink to thirst, isotonic fluids more beneficial than water.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3c2e540', 't-mm-10-004', 'text', 'Can take light diet unless received opioids or going to have C/S.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-70f98af8', 't-mm-10-004', 'text', 'Don’t routinely perform amniotomy + oxytocin', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9d1d3d76', 't-mm-10-004', 'text', 'Don’t offer clinical intervention if labor is progressive.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-40c03c2f', 't-mm-10-004', 'text', 'Observations during 1st Stage:', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96cb6e4a', 't-mm-10-004', 'text', 'TempB.PR/RVaginal examinationBladder care1.Fluid balance – intake/ output2.Frequency of passing urine3.Inability to pass urineSensationPresentabsentCheck fluid balanceIf fluid balance normal or on oxytocin, then insert CatheterTempB.PR/RVaginal examinationBladder care1.Fluid balance – intake/ output2.Frequency of passing urine3.Inability to pass urineSensationPresentabsentCheck fluid balanceIf fluid balance normal or on oxytocin, then insert CatheterHRAll observations if women have complications or being transferred to other birth setting.HRAll observations if women have complications or being transferred to other birth setting.½ hourly  1 hourly4 hourly', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-18632204', 't-mm-10-004', 'text', 'Contraction frequency', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3b217e63', 't-mm-10-004', 'text', 'Delay in 1st stage of labor is suspected when:', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-62a1b64c', 't-mm-10-004', 'text', 'Cervical dilatation < 2cm in 4 hours.', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-082b9594', 't-mm-10-004', 'text', 'Descent and rotation of baby’s head is delayed', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9c7f6b96', 't-mm-10-004', 'text', 'Change in strength, duration and frequency of contraction.', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d93e577c', 't-mm-10-004', 'text', 'Full assessment by knowing parity, uterine contraction, cervical dilation and rate of change, station and position of presenting part.', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3cbcc327', 't-mm-10-004', 'text', 'Offer support and effective pain relief', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8b2f8dc2', 't-mm-10-004', 'text', 'Repeat examination after 2 hours', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4adc11ea', 't-mm-10-004', 'text', 'Suspect delay if dilation < 1 cm', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-81ae4b04', 't-mm-10-004', 'text', 'Offer amniotomy', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-30dbf1ca', 't-mm-10-004', 'text', 'Explain procedure', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-282299b1', 't-mm-10-004', 'text', 'Advice that it will shorten labor by an hour.', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a737b3fb', 't-mm-10-004', 'text', 'Repeat examination after 2 hours', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5fdc1b35', 't-mm-10-004', 'text', 'Shift to obstetric unit by following principles of transferDetailed and full assessment by obstetrician including abdominal examination and consideration of oxytocinCommence oxytocin infusion if Women agreeContractions are inadequateFollow protocols of oxytocin administrationsRepeat examination after 4 hours.Progress > 2cmprogress < 2cmContinue careobstetric review to                                                                                assess for C/SShift to obstetric unit by following principles of transferDetailed and full assessment by obstetrician including abdominal examination and consideration of oxytocinCommence oxytocin infusion if Women agreeContractions are inadequateFollow protocols of oxytocin administrationsRepeat examination after 4 hours.Progress > 2cmprogress < 2cmContinue careobstetric review to                                                                                assess for C/SNormal progressno progress, Confirm Delay', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9a2dc3ff', 't-mm-10-004', 'text', 'Continue care and support', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-25df180a', 't-mm-10-004', 'text', 'Protocols of Oxytocin Administrations:', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-263cf97c', 't-mm-10-004', 'text', 'Start after discussion with women, stop whenever she wants.', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-57b9625c', 't-mm-10-004', 'text', 'Effective analgesia i.e., epidural', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0b17b256', 't-mm-10-004', 'text', 'In Obstetric led units after obstetrician’s advice', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-00bad718', 't-mm-10-004', 'text', 'CTG', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4720e198', 't-mm-10-004', 'text', 'Monitor fluid balance', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f9fcb45c', 't-mm-10-004', 'text', 'No, I/V fluid routinely except patient is not drinking or dehydrated or hypotensive', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-04ea8659', 't-mm-10-004', 'text', 'Incremental doses not less than 30 min, till 3 – 4 contractions in 10 minutes.', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8ef72bab', 't-mm-10-004', 'text', 'Stop oxytocin:', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2b24bc16', 't-mm-10-004', 'text', 'Contractions > 4 in 10 minutes.', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f3fb8c66', 't-mm-10-004', 'text', 'Abnormal CTG', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
