INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f8ff322d', 't-mm-10-005', 'text', 'FHR – every 5 min for 1 min after contraction abdominal examination – for frequency, strength and duration of contractions.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
