INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f9728250', 't-mm-10-005', 'text', 'She can opt for position whatever she finds comfortable except lying on her back', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
