INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-613ef753', 't-mm-10-005', 'text', 'Upright position and keeping mobile may be beneficial as it reduces FHR abnormalities, episiotomy rate and improve her birthing.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
