INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4099323d', 't-mm-10-005', 'text', 'spontaneous pushing may shorten 2nd stage as compare to directed pushing.', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
