INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-778c5ded', 't-mm-10-005', 'text', 'Delayed directed pushing by 1 hour after full dilatation reduces risk or forceps or ventouse deliveryDelayed directed pushing by 1 hour after full dilation may shorten active 2nd stage of labor.Delayed directed pushing by 1 hour after full dilatation reduces risk or forceps or ventouse deliveryDelayed directed pushing by 1 hour after full dilation may shorten active 2nd stage of labor.NulliparousMultiparous', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
