INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-179bc1c4', 't-mm-10-006', 'text', 'Outcome of Active and passive 3rd stage:', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d72f53a8', 't-mm-10-006', 'html', '<table><tbody><tr><td>Outcome</td><td>Active management</td><td>Passive/ Physiological management</td></tr><tr><td>Haemorrhage of > 500ml</td><td>68/1000</td><td>188/1000</td></tr><tr><td>Haemorrhage of > 1 lit</td><td>13/1000</td><td>29/1000</td></tr><tr><td>Need for blood Transfusion</td><td>13/1000</td><td>35/1000</td></tr><tr><td>Postpartum anemia Hb < 9g/dl</td><td>30/1000</td><td>60/1000</td></tr><tr><td>Need for uterotonics</td><td>47/1000</td><td>247/1000</td></tr><tr><td>Nausea, vomiting, headache, hypertension, readmission for bleeding</td><td>186/1000</td><td>90/1000</td></tr></tbody></table>', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-04a40453', 't-mm-10-006', 'text', 'Similar Outcomes in both managements:', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
