INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7f453cba', 't-mm-10-006', 'text', '2. Oxytocin I/V, 5 units over 2 – 3min, If women have received oxytocin in 1st or 2nd stage', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f3371293', 't-mm-10-006', 'text', '3. Oxytocin plus ergometrine I/M 5 units   + 500mg', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
