INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-56059c9e', 't-mm-10-008', 'html', '<table><tbody><tr><td>Uterotonic used in the third stage of labour as prophylaxis</td><td>Suggested first-line treatment of postpartum haemorrhage</td><td>Suggested second-line treatment of postpartum haemorrhage</td><td>Additional treatments that can be offered, depending on clinical need</td></tr><tr><td>No uterotonic used – physiological management</td><td>Oxytocin plus ergometrine by intramuscular injection (if contraindicated, give carboprost), or<br/>Oxytocin infusion as soon as intravenous access is available</td><td>Carboprost intramuscular injection</td><td>Carboprost intramuscular injection (can be repeated at intervals not less than<br/>15 minutes up to a maximum of 8 doses), or<br/>Misoprostol 800 micrograms sublingually or rectally (may be used earlier if intravenous route not available)</td></tr><tr><td>Oxytocin alone</td><td>Ergometrine intramuscular injection (if contraindicated give carboprost), or<br/>Oxytocin infusion as soon as intravenous access is available</td><td>Carboprost intramuscular injection</td><td>Carboprost intramuscular injection (can be repeated at intervals not less than<br/>15 minutes up to a maximum of 8 doses), or<br/>Misoprostol 800 micrograms sublingually or rectally (may be used earlier if intravenous route not available)</td></tr><tr><td>Oxytocin plus ergometrine</td><td>Carboprost intramuscular injection, or<br/>Oxytocin infusion as soon as intravenous access is available</td><td>Repeat carboprost after<br/>15 minutes</td><td>Carboprost intramuscular injection (can be repeated at intervals not less than<br/>15 minutes up to a maximum of 8 doses), or<br/>Misoprostol 800 micrograms sublingually or rectally (may be used earlier if intravenous route not available)</td></tr><tr><td>Carbetocin</td><td>Ergometrine intramuscular injection</td><td>Carboprost intramuscular injection</td><td>Carboprost intramuscular injection (can be repeated at intervals not less than<br/>15 minutes up to a maximum of 8 doses), or<br/>Misoprostol 800 micrograms sublingually or rectally</td></tr></tbody></table>', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-458fea91', 't-mm-10-008', 'text', 'Repeat dose of ergometrine or combination of oxytocin and ergometrine may be given if other medicines are not available like home birth', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7e2625ad', 't-mm-10-008', 'text', 'Oxytocin onset of action 2 .5min', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5370e167', 't-mm-10-008', 'text', 'Effect lasts for 30min.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-11caa04d', 't-mm-10-008', 'text', 'Ergometrine onset of action 7 min', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e5b6b55e', 't-mm-10-008', 'text', 'Effect lasts for 3 hours.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-03eb9e0e', 't-mm-10-008', 'text', 'Management Algorithm:', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a032a61b', 't-mm-10-008', 'text', 'Follow GTG', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bb4044f0', 't-mm-10-008', 'text', 'As described in post-partum hemorrhage, (Postpartum module)', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-10-009', 'chap-mm-10-01', '1.8. CARE OF THE WOMEN AFTER BIRTH', 'Detailed medical reference and study guide on 1.8. CARE OF THE WOMEN AFTER BIRTH.', 9, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
