INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9db96ec4', 't-mm-10-009', 'text', 'Uterine contractions and lochia', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f410fce8', 't-mm-10-009', 'text', 'Examine placenta and membranes for', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b64973b5', 't-mm-10-009', 'text', 'condition structure, cord vessels and completeness.', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4c88535d', 't-mm-10-009', 'text', 'Early assessment of emotional state and psychological impact of birth', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fd20d5a8', 't-mm-10-009', 'text', 'Voiding of bladder, after 6 hours if voiding has not happened and bladder is palpable – catheterize and transfer to obstetric unit.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7fca1cd6', 't-mm-10-009', 'text', 'Any concern in above observations', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bfe2c707', 't-mm-10-009', 'text', 'Transfer to obstetric unit by following full protocols of transfer.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0d2fef61', 't-mm-10-009', 'text', 'If women have regional analgesia or anesthesia, perform straight leg sign. If she can’t raise straight leg after 4 hours of last dose, then take urgent review from anesthetist.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-10-010', 'chap-mm-10-01', '2.NEONATAL CARE AND RESUSCITATION', 'Detailed medical reference and study guide on 2.NEONATAL CARE AND RESUSCITATION.', 10, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e1d5848e', 't-mm-10-010', 'text', 'Care of the new born Baby:', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-335856f0', 't-mm-10-010', 'text', 'Record APGR score routinely @ 1 min and 5 min.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1771bf28', 't-mm-10-010', 'image', '/uploads/content-images/maternal_mind_book/image144.jpeg', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-43801f6c', 't-mm-10-010', 'text', 'For central oxygenation look inside the mouth at mucous membranes and tongue', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f8b3cc95', 't-mm-10-010', 'text', 'For peripheral oxygenation look at the color of the nail bed.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96c92930', 't-mm-10-010', 'text', 'Record time from birth to the onset of regular breathing pattern.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5492de71', 't-mm-10-010', 'text', 'Don’t take paired cord blood routinely for blood gas analysis.', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-caa109ed', 't-mm-10-010', 'text', 'Send paired cord blood sample if baby is born in poor condition', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-11fd048b', 't-mm-10-010', 'text', 'Encourage skin to skin contact of baby with mother or her birth companion.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f7494e79', 't-mm-10-010', 'text', 'Keep baby warm and dry', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ccbd2a3f', 't-mm-10-010', 'text', 'Avoid airway blockage while skin to skin contact by maintaining proper head position.', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a969abcd', 't-mm-10-010', 'text', 'Initiate breast feeding as soon as possible.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-85cc1281', 't-mm-10-010', 'text', 'Record head circumference and birth weight after 1-hour skin to skin contact and plot on centile chart.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5bca6ee5', 't-mm-10-010', 'text', 'Initial examination to detect minor physical abnormality.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ffe03257', 't-mm-10-010', 'text', 'SSRI and SNRI pose risk of persistent pulmonary hypertension of newborn and also cause neonatal withdrawal symptoms. Therefore, take extra care of those women who are taking SSRI & SNR', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2fb4806f', 't-mm-10-010', 'text', 'Neonatal Resuscitation Algorythm:', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6d4c6e8e', 't-mm-10-010', 'image', '/uploads/content-images/maternal_mind_book/image145.bin', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0d6550ae', 't-mm-10-010', 'text', 'Care of baby with meconium:', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ab868c32', 't-mm-10-010', 'text', 'Don’t do suction of airway before birth of shoulders and trunk.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-471b34b1', 't-mm-10-010', 'text', 'Don’t suction baby’s upper airways if baby has normal respiration, Heart rate and tone.', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-01fbc7c5', 't-mm-10-010', 'text', 'Don’t intubate if baby has normal respiration, Heart rate and tone.', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-33496bc8', 't-mm-10-010', 'text', 'If HR, Respiration and tone Abnormal', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a618837a', 't-mm-10-010', 'text', 'Follow guidelines on Neonatal Resuscitation.', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66d0b10a', 't-mm-10-010', 'text', 'Observation of baby with Meconium:', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-12901d03', 't-mm-10-010', 'text', 'Significant MeconiumNon-Significant Meconium', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-06f83dbb', 't-mm-10-010', 'text', '- Closely observe in', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-877219aa', 't-mm-10-010', 'text', 'Unit where neonatologist- Observing @ 1 hour &', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2861c68f', 't-mm-10-010', 'text', 'Is present2 hours.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-25936d44', 't-mm-10-010', 'text', '- Perform observations @- @ all birth settings', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ec8324d3', 't-mm-10-010', 'text', '1 hour and', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b57c39bb', 't-mm-10-010', 'text', '2 hours', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b4422ca7', 't-mm-10-010', 'text', 'Then 2 hourly till 12 hours', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c7541dfc', 't-mm-10-010', 'text', 'Assessment by neonatologist if:', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-527260ea', 't-mm-10-010', 'text', 'RR > 60min', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4334001e', 't-mm-10-010', 'text', 'Presence of grunting', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0f4d0b6e', 't-mm-10-010', 'text', 'HR < 100/min or > 160/min', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6cffc41b', 't-mm-10-010', 'text', 'Capillary refill time > 3 sec', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f6e387fa', 't-mm-10-010', 'text', 'Body temp of 380C or above, or 37.50C on 2 readings 15 – 30min apart.', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-55587306', 't-mm-10-010', 'text', 'SPo2 < 95%.', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2d4b496b', 't-mm-10-010', 'text', 'Central cyanosis', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1ffb0e77', 't-mm-10-010', 'text', 'Care of baby born to woman with PROM > 24 hours:', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ab647d21', 't-mm-10-010', 'text', 'Temperature', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-719879e5', 't-mm-10-010', 'text', 'HR', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-475182b3', 't-mm-10-010', 'text', 'RR', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-93da5c9c', 't-mm-10-010', 'text', 'Respiratory grunting', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b14b6724', 't-mm-10-010', 'text', 'Subcostal recession', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fe885287', 't-mm-10-010', 'text', 'Central cyanosis', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-16cca8f7', 't-mm-10-010', 'text', 'Skin perfusion by capillary refill time', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-edbc1194', 't-mm-10-010', 'text', 'Floppiness', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fa331108', 't-mm-10-010', 'text', 'Concerns regarding general wellbeing and feeding.', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-15a97139', 't-mm-10-010', 'text', 'Ay concern arises in above observations, call neonatologists for observation.', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-70ff21ed', 't-mm-10-010', 'text', 'No need of antibiotics routinely', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6740672e', 't-mm-10-010', 'text', 'No need of antibiotics either woman or baby if no signs of infections even if PROM > 24 hours.', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0984d8af', 't-mm-10-010', 'text', 'Consider Antibiotics to mother or baby if there is evidence of infection.', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1bce1d1f', 't-mm-10-010', 'text', 'Advise woman to inform healthcare professionals immediately if she has any concern regarding baby’s wellness during 5 days’ and particularly 12 hours after birth.', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dd67b747', 't-mm-10-010', 'text', 'Referral to neonatal care specialist immediately:', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9dcf07b8', 't-mm-10-010', 'text', 'Baby with symptoms/ signs of sepsis', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f1056d01', 't-mm-10-010', 'text', 'Baby born to mother who has evidence of chorioamnionitis.', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-10-011', 'chap-mm-10-01', '3.INTRAPARTUM CARE OF WOMAN WITH EXISTING MEDICAL CONDITIONS AND OBSTETRIC COMPLICATIONS', 'Detailed medical reference and study guide on 3.INTRAPARTUM CARE OF WOMAN WITH EXISTING MEDICAL CONDITIONS AND OBSTETRIC COMPLICATIONS.', 11, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bb806170', 't-mm-10-011', 'text', 'All women with medical disorders should have personalized intrapartum care plan along with contingency plan.', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-58521312', 't-mm-10-011', 'text', 'Care plan should be formulated in MDT, in discussion with women and her companion.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
