d><td>Fontan circulation.<br/>If otherwise the patient is well</td><td>Severe mitral stenosis<br/>Severe symptomatic</td><td></td><td></td></tr><tr><td></td><td></td><td>ectopic beats, isolated</td><td></td><td>Aorta <45 mm in bicuspid</td><td>and the cardiac condition</td><td>aortic stenosis</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td>aortic valve pathology</td><td>uncomplicated</td><td>Systemic right ventricle</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td>Repaired coarctation</td><td>Unrepaired cyanotic heart</td><td>with moderate or</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td>Atrioventricular septal defect</td><td>disease<br/>Other complex heart disease</td><td>severely decreased ven- tricular function</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>Moderate mitral stenosis</td><td>Severe aortic dilatation<br/>(>45 mm in Marfan syn-</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>Severe asymptomatic aortic</td><td>drome or other HTAD,</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>stenosis</td><td>>50 mm in bicuspid</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>Moderate aortic dilatation</td><td>aortic valve, Turner syn-</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>(40–45 mm in Marfan syn-</td><td>drome ASI >25 mm/m2,</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>drome or other HTAD;</td><td>tetralogy of Fallot >50</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>45–50 mm in bicuspid aortic</td><td>mm)</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>valve, Turner syndrome ASI</td><td>Vascular Ehlers–Danlos</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>20–25 mm/m2, tetralogy of<br/>Fallot <50 mm)</td><td>Severe (re)coarctation</td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>Ventricular tachycardia</td><td>Fontan with any<br/>complication</td><td></td><td></td></tr><tr><td></td><td>Risk</td><td>No detectable increased</td><td>Small increased risk of</td><td>Intermediate increased risk</td><td>Significantly increased risk of</td><td>Extremely high risk of</td><td></td></tr><tr><td></td><td></td><td>risk of maternal mortality</td><td>maternal mortality or</td><td>of maternal mortality or</td><td>maternal mortality or severe</td><td>maternal mortality or</td><td></td></tr><tr><td></td><td></td><td>and no/mild increased</td><td>moderate increase in</td><td>moderate to severe</td><td>morbidity</td><td>severe morbidity</td><td></td></tr><tr><td></td><td></td><td>risk in morbidity</td><td>morbidity</td><td>increase in morbidity</td><td></td><td></td><td></td></tr><tr><td></td><td>Maternal cardiac</td><td>2.5–5%</td><td>5.7–10.5%</td><td>10–19%</td><td>19–27%</td><td>40–100%</td><td></td></tr><tr><td></td><td>event rate</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Counselling</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes: expert counselling</td><td>Yes: pregnancy contraindicated</td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>required</td><td>: if pregnancy</td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td>occurs, termination</td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td>should be discussed</td><td></td></tr><tr><td></td><td>Care during</td><td>Local hospital</td><td>Local hospital</td><td>Referral hospital</td><td>Expert centre for pregnancy</td><td>Expert centre for pregnancy</td><td></td></tr><tr><td></td><td>pregnancy</td><td></td><td></td><td></td><td>and cardiac disease</td><td>and cardiac</td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td>disease</td><td></td></tr><tr><td></td><td>Minimal follow-up</td><td>Once or twice</td><td>Once per trimester</td><td>Bimonthly</td><td>Monthly or bimonthly</td><td>Monthly</td><td></td></tr><tr><td></td><td>visits during</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>pregnancy</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Location of delivery</td><td>Local hospital</td><td>Local hospital</td><td>Referral hospital</td><td>Expert centre for pregnancy</td><td>Expert centre for pregnancy</td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>and cardiac disease</td><td>and cardiac</td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td>disease</td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td>ASI = aortic size index; EF = ejection fraction; HTAD = heritable thoracic aortic disease; mWHO = modified World Health Organization classification; NYHA = New York Heart Association; WHO = World Health Organization.</td></tr></tbody></table>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6cd2d6dd', 't-mm-10-012', 'text', 'Table 48. Modified World Health Organization classification of maternal cardiovascular risk', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9cd34807', 't-mm-10-012', 'text', 'Assessment of women with heart disease', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-26d6ac79', 't-mm-10-012', 'text', 'Comprehensive clinical assessment including history and physical examination.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-85aa4fb0', 't-mm-10-012', 'text', 'mWHO classification of risk (Table)', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0e595f3f', 't-mm-10-012', 'text', 'NYHA functional class', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eb4a41dd', 't-mm-10-012', 'text', 'Investigations same as non-pregnant.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-121cf94b', 't-mm-10-012', 'text', 'Mechanical heart valves on anticoagulants', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-33fd3ee5', 't-mm-10-012', 'text', 'Involve hematologist in MDT', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e9cbff2b', 't-mm-10-012', 'text', 'Individualized anticoagulation depending on their current treatment.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dc9951f0', 't-mm-10-012', 'text', 'Switching of Warfarin:', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9c795e3c', 't-mm-10-012', 'text', '1. Antenatal – LMWH by 36 weeks.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-76e29ce3', 't-mm-10-012', 'text', 'Or before planned birth.', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4de5b735', 't-mm-10-012', 'text', 'Steps:', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2ab1a857', 't-mm-10-012', 'text', '1) Stop warfarin', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-717d57db', 't-mm-10-012', 'text', '2) Start LMWH after 24 hours', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-770e4ab5', 't-mm-10-012', 'text', 'Dose according to recent weight', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6536b433', 't-mm-10-012', 'text', 'Twice daily regimen.', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-67b71fc1', 't-mm-10-012', 'text', '3) Dose of LMWH according to anti – xa levels.', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-471db9b2', 't-mm-10-012', 'text', 'Anti – xa daily after LMWH dose', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-76ae467e', 't-mm-10-012', 'text', 'After 3 – 4hours of dose', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-72ef28c0', 't-mm-10-012', 'text', 'Aiming 1 – 1.2IU/ml', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b1cb7dc2', 't-mm-10-012', 'text', 'Till target is achieved.', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0a84aae2', 't-mm-10-012', 'text', '4) Weekly anti – xa, once anti – xa target is achieved.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1d1dcca4', 't-mm-10-012', 'text', '2. Women with Planned C/S:', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66dca856', 't-mm-10-012', 'text', '1) Stop before 24 hours of C/S', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8a63c878', 't-mm-10-012', 'text', '- C/S as near to 24 hours as possible but not later than 30 hours.', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0eba81d1', 't-mm-10-012', 'text', '2) Switch to I/V ufH (unfractionated heparin)', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8d83a880', 't-mm-10-012', 'text', '- Maintain APTT twice of control', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5b277d90', 't-mm-10-012', 'text', '- Stop ufH 4 – 6 hours before C/S', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-49caf862', 't-mm-10-012', 'text', '3. Women with Planned IOL:', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ac19116f', 't-mm-10-012', 'text', 'Senior obstetrician should be involved to decided when to stop LMWH or ufH in order to minimize risk of maternal haemorrhage or valve thrombosis and enable women for option of regional analgesia.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0a551079', 't-mm-10-012', 'text', '1) LMWH 12 hourly, aiming birth close to 12 hours after stopping.', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8b7ae300', 't-mm-10-012', 'text', '-Stop LMWH 12 hours before birth.', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0fbaa442', 't-mm-10-012', 'text', '2) UfH every 4 – 6 hours, aiming birth close to 4 – 6 hours after stopping.', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0b69510a', 't-mm-10-012', 'text', '-Stop ufH 4 – 6 hours before birth.', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-18e5493a', 't-mm-10-012', 'text', '4.  Women who presents in established labor:', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-150856b6', 't-mm-10-012', 'text', '- Consult hematologist', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c67f22b6', 't-mm-10-012', 'text', '- Immediately INR', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7199e269', 't-mm-10-012', 'text', '- No anticoagulant before assessment by an obstetrician', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-83137f64', 't-mm-10-012', 'text', '- Obstetrician review within 2 hours.', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-70c83041', 't-mm-10-012', 'text', '- Consider reversal of anticoagulation', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9f2cbb03', 't-mm-10-012', 'text', '5. Postpartum Period:', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4b02fc99', 't-mm-10-012', 'text', '- Review by obstetrician and anesthetist within 3 – 4 hours.', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7ba716a2', 't-mm-10-012', 'text', '- Restart therapeutic LMWH or ufH within 4 – 6 hours after birth.', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-42f52b68', 't-mm-10-012', 'text', '- Women @ risk of postpartum hemorrhage consider following options till hourly review indicate that therapeutic anticoagulation can be re – established.', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bf35358d', 't-mm-10-012', 'text', '1) Prophylactic dose of LMWH', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c5000a8d', 't-mm-10-012', 'text', '2) No LMWH', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7eb8ae72', 't-mm-10-012', 'text', '- Restart warfarin 7 days after birth according to MDT care plan.', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4947ffde', 't-mm-10-012', 'text', 'Mode of Birth for women with heart disease:', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7a759ce9', 't-mm-10-012', 'text', 'Develop individualized birth plan covering all 3 stages of labor after MDT discussion', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5ac98dbe', 't-mm-10-012', 'text', 'Mechanical heart valves – offer planed birth either C/S or IOL', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cbb17b5e', 't-mm-10-012', 'text', 'Pulmonary hypertension – manage pregnancy and birth in collaboration with a specialist pulmonary hypertension center.', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d2e66d37', 't-mm-10-012', 'text', 'Planned C/S indications:', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-571e7824', 't-mm-10-012', 'text', 'Any high risk of aortic disease.', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-435eceee', 't-mm-10-012', 'text', 'Pulmonary hypertension', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3000d053', 't-mm-10-012', 'text', 'NYHA class III OR IV', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-525f5e53', 't-mm-10-012', 'text', 'There should be an individualized emergency care plan in case these patients (with planned C/S) present in labor or new symptoms or with obstetric complications.', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5c38c4ba', 't-mm-10-012', 'text', 'Fluid Management for women with heart disease:', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2c24339e', 't-mm-10-012', 'text', 'MDT decision', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2dee5e7a', 't-mm-10-012', 'text', 'MDT should include cardiologist with expertise in managing heart disease in pregnancy.', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-23399cdc', 't-mm-10-012', 'text', 'MDT fluid management discussion should include:', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-03ef79e2', 't-mm-10-012', 'text', '1. How condition affects fluid balance.', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-593187d2', 't-mm-10-012', 'text', '2. Optimum fluid balance', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8f8b4610', 't-mm-10-012', 'text', '3. How optimum fluid balance is achieved', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-83acffb4', 't-mm-10-012', 'text', '4. Plans for monitoring and risk assessment.', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-31224adb', 't-mm-10-012', 'text', 'Conditions where fluid balance is critical to cardiac functions.', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-59dfb5ee', 't-mm-10-012', 'text', '1. Stenotic lesions of left heart like MS, AS', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-feb5b3d8', 't-mm-10-012', 'text', '2. Hypertrophic cardiomyopathy', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bb8999aa', 't-mm-10-012', 'text', '3. Cardiomyopathy with systolic dysfunction', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5938b25b', 't-mm-10-012', 'text', '4. Pulmonary arterial hypertension', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6b2a592b', 't-mm-10-012', 'text', '5. Univentricular circulation like Fontan', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d08e6e58', 't-mm-10-012', 'heading', '6. NYHA class IV', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-02d21ef6', 't-mm-10-012', 'text', 'Monitoring of Fluid Balance in ICU:', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8b1f6eed', 't-mm-10-012', 'text', 'In above patients 1 hourly intake/ output monitoring should be done with at least 4 hourly assessments by a senior clinician.', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8f066aca', 't-mm-10-012', 'text', '1 hourly monitoring of pulse, B.P, RR and SPo2', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a13cba56', 't-mm-10-012', 'text', 'ECG and Pulse oximetry continuously', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0a81c3c8', 't-mm-10-012', 'text', 'Intra – arterial pressure continuously', 80) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9092a33f', 't-mm-10-012', 'text', 'Serial Echocardiography or Cardiac Output, Monitoring with non-invasive technique.', 81) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4e9370d5', 't-mm-10-012', 'text', 'Heart Failure:', 82) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c523d470', 't-mm-10-012', 'text', 'Suspect Heart Failure in Intrapartum Period:', 83) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5f3f884a', 't-mm-10-012', 'text', 'Symptoms:', 84) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fab662cc', 't-mm-10-012', 'text', '1. Breathlessness when lying down or @ rest', 85) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-652f96e1', 't-mm-10-012', 'text', '2. Unexplained productive cough with frothy pink sputum.', 86) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-36959e56', 't-mm-10-012', 'heading', '3. PND – being woken from sleep by severe breathlessness and coughing', 87) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5ac1d46f', 't-mm-10-012', 'text', 'Signs:', 88) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-671138c6', 't-mm-10-012', 'text', '1. Pale, Sweaty, Agitated with cool peripheries', 89) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e343a9b7', 't-mm-10-012', 'heading', '2. HR > 110 /min', 90) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0dfc9713', 't-mm-10-012', 'heading', '3. RR > 20/ min', 91) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f6e5d6c8', 't-mm-10-012', 'text', '4. Hypotension systolic B.P < 100mmHg', 92) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a94e1d46', 't-mm-10-012', 'text', '5. SPo2 < 95% on air.', 93) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d921bcf0', 't-mm-10-012', 'text', '6. Raised IVP', 94) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d25fd52d', 't-mm-10-012', 'text', '7. Added murmurs or heart sounds', 95) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2d1b8271', 't-mm-10-012', 'text', '8. Reduced air entry, basal crackles or wheeze on listening to chest.', 96) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8a9cebab', 't-mm-10-012', 'text', 'investigations:', 97) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-03ef072f', 't-mm-10-012', 'text', 'in patients with suspicion of heart failure', 98) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-76aa1693', 't-mm-10-012', 'text', '1. Establish peripheral venous access and send urea, Electrolytes and CBC.', 99) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f18e8775', 't-mm-10-012', 'text', '2. Arterial blood gases', 100) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c3a3dca2', 't-mm-10-012', 'heading', '3. ECG', 101) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9f9f6a65', 't-mm-10-012', 'text', '4. Chest x – ray.', 102) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4401fd4f', 't-mm-10-012', 'text', 'Management:', 103) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4d9d47b9', 't-mm-10-012', 'text', 'Senior review without delay if heart failure is suspected.', 104) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-506417e1', 't-mm-10-012', 'text', 'If suspicion of heart failure in intrapartum period can’t be rule out by above investigations.', 105) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c9470cfb', 't-mm-10-012', 'text', '1. Review by cardiologist.', 106) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aa8f1e6a', 't-mm-10-012', 'text', '2. Transthoracic echocardiogram', 107) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-81d0f517', 't-mm-10-012', 'text', '3. Measurement of NT – Pro BNP', 108) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-64b934c3', 't-mm-10-012', 'text', '(N – Terminal pro brain natriuretic peptide)', 109) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-970a6f7c', 't-mm-10-012', 'text', 'Consider early birth in women with heart failure due to cardiomyopathy depending upon severity.', 110) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-507ac560', 't-mm-10-012', 'text', 'If suspicion persists after birth, consider continued involvement of a cardiologist.', 111) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d7349af0', 't-mm-10-012', 'text', 'Anesthesia and analgesia for women with heart disease:', 112) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bbaeec8b', 't-mm-10-012', 'text', 'During pregnancy prepare a plan of anesthesia and analgesia involving MDT', 113) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5e5fa0c8', 't-mm-10-012', 'text', 'm WHO 1 Same option as healthy women.', 114) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9d8f9c13', 't-mm-10-012', 'text', 'm WHO 2', 115) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-991f4da7', 't-mm-10-012', 'text', 'm WHO 3- Regional anaesthesia unless it is contraindicated.', 116) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ed5ceb76', 't-mm-10-012', 'text', 'm WHO 4- Combined sequential spinal - epidural technique improvescardio-vascular stability.', 117) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ed311855', 't-mm-10-012', 'text', 'Offer intrapartum monitoring of heart and circulation to all women.', 118) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a20d0cf3', 't-mm-10-012', 'text', 'Continuous invasive intra-arterial pressure monitoring like CVP and advance cardiac output monitoring.', 119) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4162c8ec', 't-mm-10-012', 'text', 'Offer low dose epidural because it is less likely to cause cardiac instability.', 120) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-47e3960c', 't-mm-10-012', 'text', 'Stopping and re Starting LMWH in women with regional Anaesthesia:', 121) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9850adb8', 't-mm-10-012', 'html', '<table><tbody><tr><td></td><td>Prophylactic dose</td><td>Therapeutic dose</td></tr><tr><td>Last dose</td><td>12 hours before sitting</td><td>24 hours before sitting</td></tr><tr><td>Further dose</td><td>4 hours after sitting epidural or spinal</td><td>Don’t give once catheter is inside</td></tr><tr><td>Restart</td><td>4 hours after removal</td><td>12 hours after removal</td></tr></tbody></table>', 122) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f91ba07a', 't-mm-10-012', 'text', '3rd stage of labour in women with heart disease:', 123) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2844dc77', 't-mm-10-012', 'text', 'Individualized plan in discussion with MDT', 124) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4605110c', 't-mm-10-012', 'text', 'Consider including cardiologist.', 125) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-024a5ea4', 't-mm-10-012', 'text', 'm WHO – 1 = Low risk – consider options as normal women.', 126) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d3549042', 't-mm-10-012', 'text', 'm WHO – 2 = Active management of 3rd stage of labor.', 127) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d80c6805', 't-mm-10-012', 'text', 'Table 49. m WHO – 3 & m WHO – 4:', 128) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cbbe9e98', 't-mm-10-012', 'html', '<table><tbody><tr><td>Condition</td><td>First-line uterotonic</td><td>Second-line uterotonic</td><td>Drugs to avoid because of potential harm</td></tr><tr><td>Significant aortopathy<br/>Marfan syndrome and<br/>Loyes–Dietz with aortic<br/>dilatation >40 mm<br/>Bicuspid aortopathy and<br/>aortic dilatation >45 mm<br/>Previous aortic<br/>dissection<br/>Turner syndrome and<br/>aortic size index<br/>>25 cm/m2</td><td>Oxytocin</td><td>Misoprostol<br/>Carboprost</td><td>Ergometrine (because of risk<br/>of hypertension-induced<br/>aortic dissection or rupture)</td></tr><tr><td>Limited or fixed low<br/>cardiac output, or<br/>preload-dependent<br/>circulation<br/>Severe systemic<br/>ventricular dysfunction<br/>(ejection fraction <30%)<br/>Severe valvular stenosis<br/>Hypertrophic<br/>cardiomyopathy with<br/>diastolic dysfunction or<br/>significant outflow tract<br/>obstruction<br/>Fontan circulation<br/>Cyanotic heart disease</td><td>Slow infusion of<br/>oxytocin to<br/>avoid sudden<br/>haemodynamic<br/>change</td><td>Misoprostol<br/>Carboprost</td><td>Long-acting oxytocin<br/>analogues and ergometrine<br/>(because of risk of<br/>hypertension-induced heart<br/>failure)</td></tr><tr><td>Pulmonary arterial<br/>hypertension</td><td>Oxytocin</td><td>misoprostol</td><td>Ergometrine, Carboprost and<br/>long-acting oxytocin<br/>analogues (because of risk of<br/>worsening pulmonary<br/>hypertension)</td></tr><tr><td>Coronary artery disease</td><td>Oxytocin</td><td>misoprostol</td><td>Ergometrine (because of risk<br/>of coronary ischemia)</td></tr></tbody></table>', 129) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-10-013', 'chap-mm-10-01', '3.2.ASTHMA', 'Detailed medical reference and study guide on 3.2.ASTHMA.', 13, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-10-014', 'chap-mm-10-01', '3.3.WOMAN ON LONG TERM SYSTEMIC STEROIDS', 'Detailed medical reference and study guide on 3.3.WOMAN ON LONG TERM SYSTEMIC STEROIDS.', 14, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f781b557', 't-mm-10-014', 'text', 'Stress Dose Steroids:', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bfdefdda', 't-mm-10-014', 'text', 'Women with adrenal insufficiency', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fada0243', 't-mm-10-014', 'text', 'Taking long term steroid', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5ceace65', 't-mm-10-014', 'text', 'Prednisolone 5mg daily or more for > 3 months.', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6a7356ca', 't-mm-10-014', 'text', 'Continue regular oral steroid.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4771f50d', 't-mm-10-014', 'text', 'Give stress steroids', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3389467c', 't-mm-10-014', 'text', '1. In Labour:', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-69626677', 't-mm-10-014', 'text', 'Hydrocortisone 50mg I/V or I/m', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-879cc582', 't-mm-10-014', 'text', 'Every 6 hours till delivery', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d89af5fb', 't-mm-10-014', 'text', 'And 6 hours after birth.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
