INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-18d0f880', 't-mm-10-015', 'html', '<table><tbody><tr><td>Maternal platelet count</td><td>Maternal care</td></tr><tr><td>Platelet count<br/>above 80×109/l</td><td>Treat the woman as healthy for the purpose of considering<br/>regional analgesia and anaesthesia</td></tr><tr><td>Platelet count 50 to<br/>80×109/l</td><td>Before considering regional analgesia and anaesthesia, take into<br/>account:<br/>• clinical history<br/>• the woman''s preferences<br/>• Anaesthetic expertise</td></tr><tr><td>Platelet count<br/>below 50×109/l</td><td>Avoid regional analgesia and anaesthesia under most circumstances</td></tr></tbody></table>', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
