INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-04a6a98e', 't-mm-10-019', 'text', 'Table 50. Routine maternal observations for women in labour with fever, suspected sepsis, sepsis or intrapartum haemorrhage:', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3f3d1abf', 't-mm-10-019', 'html', '<table><tbody><tr><td>Maternal observations</td><td>Fever</td><td>Suspected sepsis – concern insufficient for antibiotic treatment</td><td>Sepsis or suspected sepsis – on antibiotic treatment</td><td>Intrapartum haemorrhage</td></tr><tr><td>Pulse</td><td>Hourly</td><td>Hourly</td><td>Continuous, or at least every 30 minutes</td><td>At least hourly</td></tr><tr><td>Blood pressure</td><td>4-hourly, and hourly in the second stage</td><td>4-hourly, and hourly in the second stage</td><td>Continuous, or at least every 30 minutes</td><td>At least 4-hourly, and at least hourly in the second stage</td></tr><tr><td>Respiratory rate</td><td>4-hourly</td><td>4-hourly</td><td>Continuous, or at least every 30 minutes</td><td>At least 4-hourly</td></tr><tr><td>Temperature</td><td>Hourly</td><td>Hourly</td><td>Hourly</td><td>At least 4-hourly</td></tr><tr><td>Level of consciousness (AVPU)</td><td>Hourly</td><td>Hourly</td><td>Every 30 minutes</td><td>Hourly</td></tr><tr><td>Oxygen saturation</td><td>4-hourly</td><td>4-hourly</td><td>Continuous, or at least every 30 minutes</td><td>At least 4-hourly</td></tr><tr><td>Urine</td><td>Record output</td><td>Record output</td><td>Record output, hourly if catheterized</td><td>Record output, hourly if catheterized</td></tr></tbody></table>', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
