INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5f901738', 't-mm-10-023', 'text', 'Serious risk to baby in vaginal birth', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fcfa8e51', 't-mm-10-023', 'text', 'Benefits of C/S in reducing the risk to baby are greater in early labor', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8d7e658b', 't-mm-10-023', 'text', 'Empower her to make a choice between continuing labor and C/S', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-10-024', 'chap-mm-10-01', '3.13.LARGE FOR GESTATIONAL AGE BABIES', 'Detailed medical reference and study guide on 3.13.LARGE FOR GESTATIONAL AGE BABIES.', 24, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1720cc28', 't-mm-10-024', 'text', 'Discuss:', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-76a5b9f2', 't-mm-10-024', 'text', 'Suspicion of LGA IS UNCERTAIN until baby is born', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e9041cc4', 't-mm-10-024', 'text', 'Risk and benefits of vaginal birth VS C/S', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cdcd03c0', 't-mm-10-024', 'text', 'Higher chances of maternal problems in C/S', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e30b03d1', 't-mm-10-024', 'text', 'Higher chances of risks to baby as well as to mother with vaginal birth', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d9fd363e', 't-mm-10-024', 'text', 'In vaginal birth there is a risk of shoulder dystocia, brachial plexus injury, instrumental birth and perineal trauma.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-440af075', 't-mm-10-024', 'text', 'Offer a choice to continue labor or C/S.', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-10-025', 'chap-mm-10-01', '3.14.WOMEN WITH NO ANTENATAL CARE', 'Detailed medical reference and study guide on 3.14.WOMEN WITH NO ANTENATAL CARE.', 25, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
