INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-93692038', 't-mm-10-025', 'text', 'Arrange interpreter if needed and encourage her to speak language whatever she is comfortable, Interpreter must be professional', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
