INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1b0672e9', 't-mm-10-025', 'text', 'Random blood glucose', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6b4c07f3', 't-mm-10-025', 'text', 'Asymptomatic bacteriuria', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f84b8164', 't-mm-10-025', 'text', 'HIV, HeP B and syphilis', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c483622e', 't-mm-10-025', 'text', 'Offer rapid HIV testing to women who are at risk of infection like suspected sexual abuse, I/V drugs abusers or immigrant of high prevalence', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8640b838', 't-mm-10-025', 'text', 'Explain to women that when and why information regarding her pregnancy may need to be shared with other agencies.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-132abbc2', 't-mm-10-025', 'text', 'Safeguarding concerns => refer to safeguarding services', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-76564890', 't-mm-10-025', 'text', 'Inform to healthcare professionals such as GP, Health visitors and paedriatic teams and social care professionals.', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-10-026', 'chap-mm-10-01', '3.15.  PREVIOUS C/S', 'Detailed medical reference and study guide on 3.15.  PREVIOUS C/S.', 26, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c0100e6d', 't-mm-10-026', 'text', 'Discuss:', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0b85702c', 't-mm-10-026', 'text', 'Risks and benefits of VBAC vs C/S', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b1d7d2e6', 't-mm-10-026', 'text', 'Vaginal birth is associated with a small chance of uterine rupture instrumental birth.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-84bd1a8e', 't-mm-10-026', 'text', 'Emergency C/S has higher chance of heavy', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-264f8f03', 't-mm-10-026', 'text', 'bleeding needing blood transfusion, infection, Complications in future pregnancies, longer hospital stay.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-119ae2ea', 't-mm-10-026', 'text', 'Little difference of outcome of baby in VBAC vs C/S', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b3329a85', 't-mm-10-026', 'text', 'Support full range of analgesia', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a5fb1572', 't-mm-10-026', 'text', 'Regional analgesia increases chances of instrumental birth but reduces chances of another C/S', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5cb53bd6', 't-mm-10-026', 'text', 'No need of continuous CTG and routine amniotomy.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-10-027', 'chap-mm-10-01', '3.16. LABOR AFTER 42 WEEKS OF PREGNANCY', 'Detailed medical reference and study guide on 3.16. LABOR AFTER 42 WEEKS OF PREGNANCY.', 27, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-800c7d0a', 't-mm-10-027', 'text', 'Offer continuous CTG', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6a85d2b7', 't-mm-10-027', 'text', 'Support her decisions.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-10-028', 'chap-mm-10-01', '4. FETAL MONITORING DURING LABOUR', 'Detailed medical reference and study guide on 4. FETAL MONITORING DURING LABOUR.', 28, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d9ba0818', 't-mm-10-028', 'text', 'FHR monitoring is a guidance tool on fetal condition and not a diagnostic test.', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0407393f', 't-mm-10-028', 'text', 'Findings of FHR monitoring should be assessed along with clinical picture', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1cfc3ce9', 't-mm-10-028', 'text', 'Decisions are based on clinical picture along with FHR monitoring but never alone on FHR findings.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7632cb3f', 't-mm-10-028', 'text', 'Women’s decision should be respected', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a6c5ba41', 't-mm-10-028', 'text', 'Maintain one to one support', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-271944c5', 't-mm-10-028', 'text', 'Increased intervention with continuous CTG as compared to intermittent auscultation.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6d91d72e', 't-mm-10-028', 'text', 'Initial assessment during labour:', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2e017423', 't-mm-10-028', 'text', 'Assessment of risks', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9a02308c', 't-mm-10-028', 'text', 'Review ANC record', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-30f32cc2', 't-mm-10-028', 'text', 'Women’s preferences and method of fetal assessment discussed with her during antenatal period.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-44b7e3fd', 't-mm-10-028', 'text', 'Discuss with women that risk assessment is a continuous process so, FHR monitoring tool may change during the course of labour.', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ed8ed98a', 't-mm-10-028', 'text', 'Intermittent Auscultation – IA:', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-05c5611d', 't-mm-10-028', 'text', 'Offer to low risk women', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9c60a261', 't-mm-10-028', 'text', 'Use either pinard stethoscope or Doppler USG', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-acb5b4a1', 't-mm-10-028', 'text', 'Carry out Intermittent Auscultation after a palpated contraction', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4d57e173', 't-mm-10-028', 'text', 'For 1 min', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f35a818e', 't-mm-10-028', 'text', 'Every 15 min in 1st stage and every 5 min in 2nd stage', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-481e2d3e', 't-mm-10-028', 'text', 'Record o Partogram as single rate', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0f63eb71', 't-mm-10-028', 'text', 'Record accelerations and decelerations if heard.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-deb593be', 't-mm-10-028', 'text', 'Palpate maternal pulse and record 1 hourly and more oftenly if there are any concerns.', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-becba7aa', 't-mm-10-028', 'text', 'Ensure differentiation between the maternal and fetal heartbeat.', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e02ee3d2', 't-mm-10-028', 'text', 'No fetal heart beat => urgent real time USG assessment.', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-90448999', 't-mm-10-028', 'text', 'Concerns about differentiating between fetal and maternal heart rates => seek help and consider changing the method of FHR monitoring.', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8fefc49f', 't-mm-10-028', 'text', 'In 2nd stage it is easier to mistakenly auscultate maternal rather than FHR', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e646e8ee', 't-mm-10-028', 'text', 'IA', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8124a037', 't-mm-10-028', 'text', 'No concernsContinue IANo concernsContinue IA', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a28d6daf', 't-mm-10-028', 'text', '20 beats    in FHR on Partogram', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-59b1d54c', 't-mm-10-028', 'text', 'FHR more from start of labor', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a67dcb0e', 't-mm-10-028', 'text', 'Decelerations', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4416b745', 't-mm-10-028', 'text', 'IA more frequently (carry out IA after 3 consecutive contractions)', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-56bf24e1', 't-mm-10-028', 'text', 'Carry out full review.', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
