INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a20d836f', 't-mm-10-028', 'text', 'Women want cCTG- Continue cCTG', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dfb5f9d4', 't-mm-10-028', 'text', '- Review clinically', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ba7308ba', 't-mm-10-028', 'text', 'Continue cCTG', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-af620f77', 't-mm-10-028', 'text', 'Continuous Cardiotocography – cCTG:', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8c7c4148', 't-mm-10-028', 'text', 'Use the following advice only in labour and not in antenatal period', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b37b585d', 't-mm-10-028', 'text', 'While interpreting how baby is copying with labour take in to account fetal, maternal and labour factors along with CTG', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b983e371', 't-mm-10-028', 'text', 'Low threshold for escalation in presence of antenatal and intrapartum risk factors.', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d49a1fb6', 't-mm-10-028', 'text', 'Indications of CTG', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5505af4b', 't-mm-10-028', 'text', '3. Ongoing risk Assessment3. Ongoing risk Assessment2. MDT Decision2. MDT Decision', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
