INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f0116d38', 't-mm-10-028', 'text', 'Features of CTG:', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66121c60', 't-mm-10-028', 'text', 'Contractions – by tocodynamometer', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-61a5373c', 't-mm-10-028', 'text', 'Base line FHR', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-81dbf720', 't-mm-10-028', 'text', 'Variability', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-853c4bb5', 't-mm-10-028', 'text', 'Decelerations.', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-288d369e', 't-mm-10-028', 'image', '/uploads/content-images/maternal_mind_book/image146.png', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-adcd3ccc', 't-mm-10-028', 'image', '/uploads/content-images/maternal_mind_book/image146.png', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1b994328', 't-mm-10-028', 'text', '1.2.3.4. 1.2.3.4.', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7ecdf51e', 't-mm-10-028', 'text', 'WhiteAmberRedWhiteAmberRed', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-809d8d88', 't-mm-10-028', 'text', 'Important Consideration while Reviewing CTG:', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e75e5618', 't-mm-10-028', 'text', 'Evaluate changes on trace over time', 67) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2e8c9818', 't-mm-10-028', 'text', 'Document any change from previous review', 68) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7fb71362', 't-mm-10-028', 'text', 'Review changes alongside existing or new intrapartum risk factors', 69) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9d22f821', 't-mm-10-028', 'text', 'Think about possible reason for any change and take into account whole clinical picture in formulating ongoing care.', 70) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9a5432c5', 't-mm-10-028', 'text', 'Normal CTG trace indicate that baby is coping well with labour', 71) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-526add79', 't-mm-10-028', 'text', 'Changes to FHR during labour are common and don’t necessarily cause concern, however they may represent fetal compromise.', 72) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-51ca969d', 't-mm-10-028', 'text', 'If CTG trace changes or is not normal there will be less certainly about the condition of the baby', 73) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-70d97b8a', 't-mm-10-028', 'text', 'Accelerations:', 74) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9961c4e6', 't-mm-10-028', 'text', 'Transient    in FHR of 15bpm or more lasting 15 sec or more', 75) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8ec0de0f', 't-mm-10-028', 'text', 'Presence of accelerations even with reduced variability is reassuring.', 76) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3d60172a', 't-mm-10-028', 'text', 'Absence of accelerations on an otherwise normal CTG trace does not indicate fetal acidosis.', 77) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-45d3ee4b', 't-mm-10-028', 'text', 'Categorization of CTG traces:', 78) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f0caeabd', 't-mm-10-028', 'text', 'Normal', 79) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f68767ce', 't-mm-10-028', 'text', 'No amber or no red feature', 80) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-68ca54e7', 't-mm-10-028', 'text', 'All 4 features are white.', 81) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e9749801', 't-mm-10-028', 'text', 'Suspicious:', 82) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e3644aaa', 't-mm-10-028', 'text', 'Any 1 feature amber', 83) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2519e18f', 't-mm-10-028', 'text', 'Pathological', 84) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96afbe59', 't-mm-10-028', 'text', 'Any feature red or', 85) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b8e20f51', 't-mm-10-028', 'text', '2 or more features are amber.', 86) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3a50e16c', 't-mm-10-028', 'text', 'Special consideration for CTG traces in 2nd stage of labour:', 87) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-074e3c90', 't-mm-10-028', 'text', 'Interpretation more challenging in 2nd stage', 88) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-08a91ad9', 't-mm-10-028', 'text', 'Keep low threshold for seeking 2nd opinion', 89) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dded1e32', 't-mm-10-028', 'text', 'Differentiate FHR from MHR every 5 min', 90) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a5c36324', 't-mm-10-028', 'text', 'Consider scalp electrode if there is concern', 91) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-69d98510', 't-mm-10-028', 'text', 'about confusing FHR and MHR.', 92) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6c6db40e', 't-mm-10-028', 'text', 'Accelerations are most likely to be maternal pulse', 93) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f292583a', 't-mm-10-028', 'text', 'If there are deceleration, look for other signs of hypoxia like   in baseline FHR or reduction in variability.', 94) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9788a1be', 't-mm-10-028', 'text', 'Hypoxia is more common and more rapid in active 2nd stage', 95) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f2d20463', 't-mm-10-028', 'text', 'FHR > 20bPm from baseline or more from start of labour is labelled as red feature in active.', 96) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-86d6ccf6', 't-mm-10-028', 'text', 'CTG concern in 2nd stage.', 97) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8872a16b', 't-mm-10-028', 'text', 'Obtain obstetric review', 98) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-617d15fa', 't-mm-10-028', 'text', 'Discourage Pushing', 99) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3ec5072c', 't-mm-10-028', 'text', 'Discontinue oxytocin infusion unless birth is imminent', 100) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-24438b17', 't-mm-10-028', 'text', 'Agree and document CTG trace.', 101) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-09a74e93', 't-mm-10-028', 'text', 'Management of Abnormal CTG Trace:', 102) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e4d0a957', 't-mm-10-028', 'text', 'Suspicious CTG:', 103) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-45466db6', 't-mm-10-028', 'text', '1.No other concerning risk Factor:', 104) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bfdec802', 't-mm-10-028', 'text', 'Full assessment of clinical picture', 105) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-51df0b59', 't-mm-10-028', 'text', 'Under take conservative measures.', 106) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-46a822b0', 't-mm-10-028', 'text', '2.Other concerning risk factor like sepsis, meconium, slow progress.', 107) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d8740193', 't-mm-10-028', 'text', 'Full assessment of clinical picture', 108) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b836a893', 't-mm-10-028', 'text', 'Conservative measures', 109) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96464238', 't-mm-10-028', 'text', 'Urgent review by an obstetrician or a senior midwife', 110) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f8855e23', 't-mm-10-028', 'text', 'Consider', 111) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9c344a8b', 't-mm-10-028', 'text', 'Fetal scalp stimulation', 112) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ef04c543', 't-mm-10-028', 'text', 'Expedite the birth.', 113) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66ae9414', 't-mm-10-028', 'text', 'Pathological CTG:', 114) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-df5af504', 't-mm-10-028', 'text', 'Urgent review by an obstetrician or senior midwife.', 115) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cd8ff42d', 't-mm-10-028', 'text', 'Exclude acute events', 116) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-edd8944e', 't-mm-10-028', 'text', 'Cord prolapses', 117) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-22a613a6', 't-mm-10-028', 'text', 'Abruption', 118) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96b07909', 't-mm-10-028', 'text', 'Rupture', 119) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-49768a80', 't-mm-10-028', 'text', 'Full assessment', 120) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-564a6cef', 't-mm-10-028', 'text', 'Undertake conservative measures', 121) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c8f2184b', 't-mm-10-028', 'text', 'Still pathological after conservative measures', 122) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7972bd7f', 't-mm-10-028', 'text', 'Obtain further urgent review', 123) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-389cd846', 't-mm-10-028', 'text', 'Evaluate whole clinical picture', 124) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
