INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-862ee14c', 't-mm-10-036', 'html', '<table><tbody><tr><td></td><td>Vacuum</td><td>Forceps</td><td>Sequential</td></tr><tr><td>Episiotomy</td><td>50 – 60</td><td>90%</td><td></td></tr><tr><td>VV tear</td><td>10%</td><td>20 %</td><td></td></tr><tr><td>OASI</td><td>1 – 4%</td><td>8 – 12%</td><td>17.4%</td></tr><tr><td>PPH</td><td>10 – 40%</td><td>10 – 40%</td><td></td></tr><tr><td>Incontinence</td><td>Common @ 6 weeks improve with time</td></tr></tbody></table>', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4d0ba062', 't-mm-10-036', 'text', 'Fetal Outcomes:', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66db91de', 't-mm-10-036', 'html', '<table><tbody><tr><td></td><td>Vacuum</td><td>Forceps</td><td>Sequential</td></tr><tr><td>Cephal haematoma</td><td>1 – 12%</td><td>__</td><td></td></tr><tr><td>Facial/ Scalp laceration</td><td>10%</td><td>10%</td><td></td></tr><tr><td>Retinal Haemorrhage</td><td>17 – 38%</td><td>Less than vacuum</td><td></td></tr><tr><td>Jaundice</td><td>5 – 15%</td><td>5 – 15%</td><td></td></tr><tr><td>Subgaleal Haemorrhage</td><td>3 – 6/1000</td><td>__</td><td></td></tr><tr><td>ICH / Subdural</td><td>5-15/10,000</td><td>5-15/10,000</td><td>2 – 3 times more</td></tr><tr><td>Cervical spine injury</td><td>__</td><td>Rare due to Kelland</td><td></td></tr><tr><td>Skull fracture</td><td>__</td><td>Rare</td><td></td></tr><tr><td>Fascial Nerve pulse</td><td>__</td><td>Rare</td><td></td></tr><tr><td>Fetal death</td><td>Very rare</td><td>Very rare</td><td></td></tr></tbody></table>', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-51783454', 't-mm-10-036', 'text', 'Malpractice litigation – failure to discontinue', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
