INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f7e0de04', 't-mm-10-038', 'text', 'CPR less effective if GA > 20 weeksCPR less effective if GA > 20 weeks- 30 compressions @ 100-120/min- Depress 5 – 6cm @ center of chest- Ventilations = 2 breaths @ 10/minUntil: defibrillator/ monitor is attached- 30 compressions @ 100-120/min- Depress 5 – 6cm @ center of chest- Ventilations = 2 breaths @ 10/minUntil: defibrillator/ monitor is attached', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
