INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e18596f3', 't-mm-10-038', 'text', 'During CPR:- Establish I/V line- High flow O2- intubate & then continuous chest compression- Correct reversible cause- Adrenaline every 3-5min- Consider – Amiodarone, Atropine, Mg.During CPR:- Establish I/V line- High flow O2- intubate & then continuous chest compression- Correct reversible cause- Adrenaline every 3-5min- Consider – Amiodarone, Atropine, Mg.Antiarrhythmic Drugs:After 3 DC Shock Amiodarone 1st dose 300mg bolus2nd dose 150mgIf not available give lidocaine1st dose 1-1.5mg/kg2nd dose: 0.5-0.75mg/kgAfter 5th DC ShockAmiodarone 150mgAntiarrhythmic Drugs:After 3 DC Shock Amiodarone 1st dose 300mg bolus2nd dose 150mgIf not available give lidocaine1st dose 1-1.5mg/kg2nd dose: 0.5-0.75mg/kgAfter 5th DC ShockAmiodarone 150mg', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
