INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2c55bc02', 't-mm-10-038', 'text', 'Vasovagal & epilepsy => commonest cause of collapse.', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb463794', 't-mm-10-038', 'text', 'Manual uterine displacement or left lateral tilt', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ee091416', 't-mm-10-038', 'text', 'Perimortem C/S', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ce679947', 't-mm-10-038', 'text', 'If >20 weeks', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-894995b3', 't-mm-10-038', 'text', 'Aim for uterine evacuation within 5 min', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-82eed758', 't-mm-10-038', 'text', 'No response despite correct performance of CPR within 4 min', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a905c073', 't-mm-10-038', 'text', 'Achieved within 5 min', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9db797ac', 't-mm-10-038', 'text', '69% infant survival', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-25f5bf40', 't-mm-10-038', 'text', 'Hypoxic brain damage of neonate if perimortem C/S performed after 6min.', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-48003550', 't-mm-10-038', 'text', 'Cardiac arrest 50% survival of mother.', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d80fbc6e', 't-mm-10-038', 'text', '54% survived until discharge', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7b608c29', 't-mm-10-038', 'text', '42% with mod – good Neurological outcomes.', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f2ce2cbb', 't-mm-10-038', 'text', 'More favorable outcome when CPR performed within 10min.', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fa405860', 't-mm-10-038', 'text', 'Post Collapse managementPost Collapse management', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b383ef76', 't-mm-10-038', 'text', 'Patient AliveYESNOContinue treatment of underlying- Inform coroner or prosecutorcause of collapsefiscal inform MBRRACEtransfer to appropriate clinicalcare setting HDUAccurate documentationDebrief patient and relative Offer staff debrief and supportReview case through clinical governance processPatient AliveYESNOContinue treatment of underlying- Inform coroner or prosecutorcause of collapsefiscal inform MBRRACEtransfer to appropriate clinicalcare setting HDUAccurate documentationDebrief patient and relative Offer staff debrief and supportReview case through clinical governance process', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eed66648', 't-mm-10-038', 'text', 'Table 51. Physiological and physical changes in Pregnancy:', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9e1cb537', 't-mm-10-038', 'html', '<table><tbody><tr><td>System</td><td>Change in pregnancy</td><td>Impact on resuscitation</td></tr><tr><td>CVS:<br/>Plasma volume<br/>HR<br/>Cardiac output<br/>Uterine blood flow<br/>Systemic vascular resistance<br/>Arterial B.P<br/>Venous return</td><td>By up to 50%<br/>By 15 – 20 bpm<br/>By 40% but    by gravid uterus 30 – 40%<br/>10% of co<br/>By 10 – 15 mmhg<br/>By presence of uterus 60%</td><td>Dilution Anemia<br/>O2 carrying capacity<br/>CPR circulation demands<br/>Sequences blood during CPR<br/>Sequences blood during CPR<br/>Reserve<br/>CPR circulation demands<br/>reserve</td></tr><tr><td>Respiratory system:<br/>RR<br/>O2 consumption<br/>Residual capacity<br/>Arterial PCo2<br/>Laryngeal edema</td><td>By 20%<br/>By 25%</td><td>Buffering capacity, acidosis<br/>Hypoxia develops quickly<br/>Hypoxia when apnea<br/>Buffering capacity acidosis more likely<br/>Difficult intubation</td></tr><tr><td>Other changes:<br/>Gastric mortality<br/>Lower esophageal sphincter<br/>Uterus<br/>Weight</td><td>Relaxed<br/>Enlarged</td><td>Aspiration risk<br/>Early intubation with cuffed and tubes, laryngeal airway cause trauma and bleeding.<br/>Diaphragmatic splinting ventilation difficult<br/>intubation difficult.</td></tr></tbody></table>', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d26eb4cb', 't-mm-10-038', 'text', 'Identification of impending Collapse:', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0170b3b5', 't-mm-10-038', 'text', 'Obstetric MEW score chart – all women under observation to allow early recognition.', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-95605145', 't-mm-10-038', 'text', 'Miss unwell women', 59) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5268531f', 't-mm-10-038', 'text', 'Causes of collapse and their management (4T,4H):', 60) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b884d631', 't-mm-10-038', 'text', 'VTE – most common cause of maternal death', 61) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3db681a', 't-mm-10-038', 'text', 'Haemorrhage 6/1000, among most common causes of direct maternal death.', 62) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ea92872d', 't-mm-10-038', 'text', 'AF embolism', 63) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-76b25888', 't-mm-10-038', 'text', '1.7/100,000, Mortality 67/1000', 64) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ddf7a7f4', 't-mm-10-038', 'text', 'Presents during labour, birth or within 30 min of birth.', 65) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bd8ca565', 't-mm-10-038', 'text', 'Collapse, Hypotension, Respiratory distress, Hypoxia.', 66) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
