INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-10-039', 'chap-mm-10-01', '15.PERIMORTEM C/S', 'Detailed medical reference and study guide on 15.PERIMORTEM C/S.', 39, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
