INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ccbb4719', 't-mm-10-039', 'text', 'Infant survival after PMCS = 69% Maternal survival 54%, 78% survive with moderate impaired neurological functions.', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
