INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-11-008', 'chap-mm-11-01', '6.2.PERINATAL MENTAL HEALTH SERVICES', 'Detailed medical reference and study guide on 6.2.PERINATAL MENTAL HEALTH SERVICES.', 8, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8301e47a', 't-mm-11-008', 'text', '1. Specialist perinatal mental health services', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4ee4d7f7', 't-mm-11-008', 'text', 'Specialist perinatal mental health services (PMHS) are concerned with the prevention, detection and management of mental health problems that can complicate pregnancy and the postnatal period.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dd8ffe32', 't-mm-11-008', 'text', 'This includes offering pre-conception counselling, caring for women with new-onset or pre-existing moderate to severe mental illness, as well as caring for women with a history of illness who are currently well but who are at high risk of serious mental illness during the perinatal period.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-702257a9', 't-mm-11-008', 'text', 'Promoting the emotional and physical well-being and healthy development of babies and infants, through supporting a secure and attuned relationship with their parents, is central to the care provided by a specialist PMHS.', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a2489a58', 't-mm-11-008', 'text', 'Specialist perinatal mental health services include specialist community perinatal mental health teams and MBUs.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-18d2949e', 't-mm-11-008', 'text', 'Specialist community perinatal mental health teams have the dual role of assessing and treating severe and moderate mental illness with additional complex psychosocial needs or comorbid conditions, as well as assessing and actively supporting the mother-infant relationship.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1192d3e7', 't-mm-11-008', 'text', 'Women who need admission in late pregnancy or the postpartum period should be admitted to specialist mother and baby units which are designed and resourced to safely meet the physical and mental health needs of both mother and infant.', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-277cbec9', 't-mm-11-008', 'text', 'Each specialist perinatal mental health service should be part of a managed clinical network.', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e4817b0b', 't-mm-11-008', 'text', 'Perinatal mental health problems include a range of disorders and severities, which present in a variety of health settings and are managed by multiple services.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0475e0be', 't-mm-11-008', 'text', 'Some of these services are specifically designed to meet the needs of pregnant and postpartum women and their infants, others care for them as part of a general service.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96197f9d', 't-mm-11-008', 'text', 'a. Service provided by specialist mental health include:', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6ee40a11', 't-mm-11-008', 'text', 'specialist community perinatal mental health teams (PMHTs)', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4deeb665', 't-mm-11-008', 'text', 'specialist in-patient mother and baby units (MBUs)', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f7274581', 't-mm-11-008', 'text', 'adult mental health services (including community and in-patient services and psychological therapy services).', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-10f080c6', 't-mm-11-008', 'text', 'Child and adolescent mental health services (CAMHS)', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0c26d395', 't-mm-11-008', 'text', 'parent-infant mental health services', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-61f850eb', 't-mm-11-008', 'text', 'primary psychological services', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ab1453a2', 't-mm-11-008', 'text', 'general practitioners (GPs)', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4cdf87be', 't-mm-11-008', 'text', 'health visitors and the extended primary care team', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0632436c', 't-mm-11-008', 'text', 'Children’s services and social care organizations', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-335fe777', 't-mm-11-008', 'text', 'voluntary/third sector and peer support organizations.', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d7be1c42', 't-mm-11-008', 'text', 'b. Indication of referral', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-75aa7fb1', 't-mm-11-008', 'text', 'Refer to a secondary mental health service (preferably a specialist perinatal mental health service) for assessment and treatment, all women who:', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-00203178', 't-mm-11-008', 'text', 'have or are suspected to have severe mental illness', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e3dd4611', 't-mm-11-008', 'text', 'have any history of severe mental illness (during pregnancy or the postnatal period or at any other time).', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-53ec1f25', 't-mm-11-008', 'text', 'If a woman has any past or present severe mental illness or there is a family history of severe perinatal mental illness in a first-degree relative, be alert for possible symptoms of postpartum psychosis in the first 2 weeks after childbirth.', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a658f67a', 't-mm-11-008', 'text', 'If a woman has sudden onset of symptoms suggesting postpartum psychosis, refer her to a secondary mental health service (preferably a specialist perinatal mental health service) for immediate assessment (within 4 hours of referral).', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e7941f80', 't-mm-11-008', 'text', 'Services provided by specialist community perinatal mental health team:', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c0c003e4', 't-mm-11-008', 'text', 'A good specialist community perinatal mental health team will be a member of the Perinatal Mental Health Services. It will assess and manage women with moderate to severe mental illness in the community, who cannot be appropriately treated by primary care services. Responsibilities include:', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d3376560', 't-mm-11-008', 'text', 'assessment and care for pregnant and postnatal women with moderate to severe mental disorder who require secondary care mental health services.', 30) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c796825e', 't-mm-11-008', 'text', 'provide pre-conception advice to women who are at high risk of early post-partum major mental illness', 31) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bf4c1a7f', 't-mm-11-008', 'text', 'assess and proactively care for women who are well but who are at high risk of a severe postnatal illness', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-44e33074', 't-mm-11-008', 'text', 'assess the mother-infant relationship and infant development in the context of maternal mental disorder', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-940e2c64', 't-mm-11-008', 'text', 'prioritize the management of women on leave, or recently discharged, from MBU care.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2773f22b', 't-mm-11-008', 'text', 'Provide a range of evidence-based psychological, pharmacological and psychosocial interventions that are adapted for the perinatal period to treat maternal mental health problems and support the mother-infant relationship, promoting the best outcomes for infant development', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-50c17966', 't-mm-11-008', 'text', 'respond in a timely manner and have the capacity to deal with crises and emergencies and assess patients in a variety of settings, including their homes, maternity hospitals and out-patient clinics', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1df171b7', 't-mm-11-008', 'text', 'MBU:', 37) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6acb48f0', 't-mm-11-008', 'text', 'Services Provided by MBU', 38) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6038077e', 't-mm-11-008', 'text', 'assessment and care for women in late pregnancy and postnatal women (to 12 months) with mental disorder who require in-patient care, accompanied by their infants', 39) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b3c79d40', 't-mm-11-008', 'text', 'provide care across the range of conditions.', 40) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e95b854b', 't-mm-11-008', 'text', 'be able to respond in a timely manner which takes into account the maternity context, needs of the developing infant and alterations to presentations brought about by the perinatal period', 41) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-62a05ebd', 't-mm-11-008', 'text', 'ensure that the infant’s health, care and developmental needs are fully met', 42) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-02af48d1', 't-mm-11-008', 'text', 'assess the mother-infant relationship and infant development in the context of maternal mental disorder', 43) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c5cdd667', 't-mm-11-008', 'text', 'provide a range of evidence-based psychological, pharmacological and psychosocial interventions that are adapted for the perinatal period to treat maternal mental health problems and support the mother-infant relationship', 44) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-97ea2be2', 't-mm-11-008', 'text', 'offer timely, equitable and comprehensive access such that mothers are not admitted to general adult wards without their baby.', 45) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b9a071ea', 't-mm-11-008', 'text', 'be closely integrated with specialist community perinatal and outreach teams to promote early discharge and continuity of care', 46) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb50ce9a', 't-mm-11-008', 'text', 'provide advice, support and signposting to partners of women under the care of the service, who may themselves have mental health difficulties, and support the development of the father/partner-infant relationship.', 47) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-526ad068', 't-mm-11-008', 'text', 'b. Indications of admission', 48) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ce86dd86', 't-mm-11-008', 'text', '1. Rapidly changing mental state', 49) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9ccee6c0', 't-mm-11-008', 'text', '2. Suicidal ideation (particularly of a violent nature)', 50) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-edb99791', 't-mm-11-008', 'text', '3. Pervasive guilt or hopelessness', 51) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d3c49a10', 't-mm-11-008', 'text', '4. Significant estrangement from the infant.', 52) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e59401e2', 't-mm-11-008', 'text', '5. New or persistent beliefs of inadequacy as a mother.', 53) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-74b5b1e0', 't-mm-11-008', 'text', 'Parent – infant Mental health services:', 54) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-84d545e0', 't-mm-11-008', 'text', 'Services provided:', 55) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d313a694', 't-mm-11-008', 'text', 'provide therapeutic interventions for parent-infant relationships in pregnancy and the early years.', 56) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5d51969e', 't-mm-11-008', 'text', 'Good quality parent-infant mental health services should be multidisciplinary teams with expertise in supporting mothers and fathers/ partners/other carers to develop sensitive and attuned relationships with their babies, infants and toddlers, including in the antenatal period.', 57) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-805817bb', 't-mm-11-008', 'text', 'offer direct support to parents and carers using a variety of evidence-based therapeutic parent-infant interventions', 58) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-11-009', 'chap-mm-11-01', '6.3.BABY BLUES', 'Detailed medical reference and study guide on 6.3.BABY BLUES.', 9, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
