INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7daa538b', 't-mm-11-009', 'text', '3 – 10 days after birth, peaking on 5th day.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
