INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d0e7f5b0', 't-mm-11-009', 'text', 'No Suicidal thought', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3a8bbfb', 't-mm-11-009', 'text', 'No worthlessness or hopelessness.', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
