INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0b43a086', 't-mm-11-009', 'text', 'Self – limiting in 48hours', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
