INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-11-010', 'chap-mm-11-01', '6.4.DEPRESSION', 'Detailed medical reference and study guide on 6.4.DEPRESSION.', 10, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cba1912d', 't-mm-11-010', 'text', 'During pregnancy 12%', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7696b750', 't-mm-11-010', 'text', '3 months PP = 13%', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-99131376', 't-mm-11-010', 'text', '1-year after delivery = 15 – 20%', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3838b66', 't-mm-11-010', 'text', 'Past history and FH    es risk 42%', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-250e2343', 't-mm-11-010', 'text', 'Bipolar depression – risk of psychosis.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-07921876', 't-mm-11-010', 'text', 'Diagnostic key words:', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d7867741', 't-mm-11-010', 'text', 'Lack of interest in friends, life, baby', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb27690b', 't-mm-11-010', 'text', 'Persistent sadness low mood', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-13622a69', 't-mm-11-010', 'text', 'Don’t improve but worse with time', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
