INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-11-017', 'chap-mm-11-01', '7.POST PARTUM CONTRACEPTION', 'Detailed medical reference and study guide on 7.POST PARTUM CONTRACEPTION.', 17, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-46ec5a4f', 't-mm-11-017', 'text', 'Less than six weeks postpartum', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6280996f', 't-mm-11-017', 'text', 'Postpartum women who are < 48 hours postpartum can use Cu-IUDs (MEC Category 1).', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fbbc3511', 't-mm-11-017', 'text', 'Breastfeeding women who are < 48 hours postpartum can generally use LNG-IUDs (MEC Category 2).', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-07940174', 't-mm-11-017', 'text', 'Breastfeeding women who are < 6 weeks postpartum can generally use POPs and LNG and ETG implants (MEC Category 2).', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b5815b7d', 't-mm-11-017', 'text', 'Breastfeeding women who are ≥ 4 weeks postpartum can use the progesterone vaginal rings without restrictions (MEC Category 1)', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-59d5e9d2', 't-mm-11-017', 'text', 'Postpartum women who are ≥ 4 weeks postpartum can use Cu-IUDs and LNG-IUDs without restriction (MEC Category 1).', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e515cc74', 't-mm-11-017', 'text', 'Postpartum women who are ≥ 21 days to 42 days postpartum without other risk factors for venous thromboembolism (VTE) can generally use CHCs (MEC Category 3).', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-729cfd20', 't-mm-11-017', 'text', 'Six weeks to less than six months postpartum', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a3b6da22', 't-mm-11-017', 'text', 'Breastfeeding women who are ≥ 6 weeks to < 6 months postpartum can use POPs, POIs, and LNG and ETG implants without restriction (MEC Category 1).', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5d3dc4a0', 't-mm-11-017', 'text', 'Postpartum women who are > 42 days postpartum can use CHCs without restriction (MEC Category 1).', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e5f6a623', 't-mm-11-017', 'text', 'Recommendations against some contraceptive methods', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0dc19398', 't-mm-11-017', 'text', 'Postpartum women who are ≥ 48 hours to < 4 weeks postpartum generally should not have an LNG-IUD inserted (MEC Category 3).', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-453e39c2', 't-mm-11-017', 'text', 'Breastfeeding women who are < 6 weeks postpartum generally should not use POIs (depot medroxyprogesterone acetate or norethisterone enanthate) (MEC Category 3).', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb8d4450', 't-mm-11-017', 'text', 'Breastfeeding women < 6 weeks postpartum should not use CHCs (MEC Category 4).', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-beec9cb1', 't-mm-11-017', 'text', 'Breastfeeding women ≥ 6 weeks to < 6 months postpartum generally should not use CHCs (MEC Category 3).', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ab7e325d', 't-mm-11-017', 'text', 'Postpartum women who are < 21 days postpartum and do not have other risk factors for VTE generally should not use CHCs (MEC Category 3).', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-60a5fc49', 't-mm-11-017', 'text', 'Postpartum women who are < 21 days postpartum with other risk factors for VTE should not use CHCs (MEC Category 4).', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a2e0f0d6', 't-mm-11-017', 'text', 'Postpartum women who are ≥ 21 days to 42 days postpartum with other risk factors for VTE generally should not use CHC (MEC Category 3).', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-31fe0a30', 't-mm-11-017', 'text', 'Recommendations on emergency contraception', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0acdbf74', 't-mm-11-017', 'text', 'Breastfeeding women can use LNG for emergency contraceptive pills (ECPs) without restriction (MEC Category 1).', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-902fa5d4', 't-mm-11-017', 'text', 'Women who are breastfeeding can generally use ulipristal acetate for ECPs (MEC Category 2).', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
