INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5c911595', 't-mm-11-019', 'text', 'Includes case base discussions and problem-based discussions', 32) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5990379e', 't-mm-11-019', 'text', '1-minute preceptor:', 33) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fd2752d0', 't-mm-11-019', 'text', 'This is a ﬁve-step process that can be carried out in minutes 15 with the purpose of structuring teaching opportunities that arise in the clinical environment. This is an example of a teaching method that demands a good rapport between the teacher and the learner(s). The teacher must make the learner feel secure and allow the voicing of opinions, whether they are correct or in correct.', 34) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0eba2e5b', 't-mm-11-019', 'text', 'The ﬁve steps are:', 35) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6cc4c0c0', 't-mm-11-019', 'text', 'commitment', 36) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
