INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-664548f3', 't-mm-12-002', 'text', 'NOTES:', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2a52677d', 't-mm-12-002', 'text', 'Non-technical skills for surgeons This is the cognitive and interpersonal skills, e.g. to see and making leadership team working. The tool provides a framework and terminology for giving feedback under the following headings. Situational Awareness, Decision Making, Communication, Teamwork, Leadership', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e79705d2', 't-mm-12-002', 'text', 'Norm reference assessment:', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cd938dd7', 't-mm-12-002', 'text', 'A norm-referenced assessment is a type of standardized test that ranks test-takers against a peer group (norm group)', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-26ff407a', 't-mm-12-002', 'text', 'Students are compared to each other', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-87dbba5a', 't-mm-12-002', 'text', 'Fixed no of students fail each year', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fa10b3cb', 't-mm-12-002', 'text', 'Candidates ability influence standard', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fd3b8db9', 't-mm-12-002', 'text', 'Standards are not known in advance', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-202e875d', 't-mm-12-002', 'text', 'Criterion reference standard', 27) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3d6cf36f', 't-mm-12-002', 'text', 'evaluates a student''s knowledge and skills against fixed, predetermined standards or learning objectives, rather than comparing them to peers.', 28) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-841d1bc7', 't-mm-12-002', 'text', 'Failure rates vary', 29) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-12-003', 'chap-mm-12-01', '4. ARCP', 'Detailed medical reference and study guide on 4. ARCP.', 3, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a875efe5', 't-mm-12-003', 'text', 'Is formal meeting, there will be at least 3 panel members who are appointed by theDeanery''s specialty training committee.”Either your postgraduate dean or training program director will be on the panel.The panel will review the evidence on your portfolio including workplace-based assessments, audits and projects', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-da700c2f', 't-mm-12-003', 'text', 'ARCPP Outcomes: Outcome 1:', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dec546c2', 't-mm-12-003', 'text', 'Evidence is satisfactory, indicating successful transition into the next training year', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dcc1b8ec', 't-mm-12-003', 'text', 'Outcome 2:', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ff5ca806', 't-mm-12-003', 'text', 'If there are any deficiencies in training areas of poor performance the panel will', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-66f56014', 't-mm-12-003', 'text', 'recommend outcome 2, which is a recommendation for targeted training to help address the issue.  If you complete this targeted training successfully there’ll, be no delay to CCT', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-93746690', 't-mm-12-003', 'text', 'Outcome 3:', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-783e7142', 't-mm-12-003', 'text', 'if 2 panel identifies that you need a formal additional Period of training they will  recommend an outcome 3', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9d6cb413', 't-mm-12-003', 'text', 'Outcome 4:', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0daecc85', 't-mm-12-003', 'text', 'if there is insufficient and sustained lack of progress despite having up to a year the |panel will recommend outcome 4 and release you from the training program', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-12-004', 'chap-mm-12-01', '5.APPRAISAL AND REVALIDATION', 'Detailed medical reference and study guide on 5.APPRAISAL AND REVALIDATION.', 4, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-35a0f0fd', 't-mm-12-004', 'text', 'Appraisal and assessment are often confused but are quite different processes. Each has a different role for training and should be kept separate whenever possible.', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9ee39682', 't-mm-12-004', 'text', 'Appraisal assists learning informally:', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9feca620', 't-mm-12-004', 'text', 'primarily intended for the appraise', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e437fada', 't-mm-12-004', 'text', 'encourages open informal dialogue', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-47b18f58', 't-mm-12-004', 'text', 'establishes learning goals and suggestions on how to achieve these', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2b8e96b2', 't-mm-12-004', 'text', 'addresses the concerns supportively', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-486f179a', 't-mm-12-004', 'text', 'guides the appraise throughout the year.', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cdb004db', 't-mm-12-004', 'text', 'Assessment formally tests learning has been achieved:', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7fce8ee4', 't-mm-12-004', 'text', 'tests that competencies have been met against a predetermined (minimum) standard', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-57ded3b9', 't-mm-12-004', 'text', 'required for continued safe practice, progression to the next stage of training and a license to work independently in the form of ARCP or ''exit interview''.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-321d931a', 't-mm-12-004', 'text', 'In practice, appraisal includes some element of assessment, as it is important that clinical standards are maintained throughout the year so as to maintain patient safety. The educational supervisor (appraiser/trainer) is responsible for ensuring that a trainee does not cause harm.', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-29e942fa', 't-mm-12-004', 'text', 'Revalidation', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-54f28a12', 't-mm-12-004', 'text', 'is a process of relicensing that allows continuation in clinical practice. This applies to all doctors, specialist trainees and certified specialists.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1927269b', 't-mm-12-004', 'text', 'It aims to ensure quality improvement in patient care through personal and professional development.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6ba4a5d5', 't-mm-12-004', 'text', 'Revalidation sets out to:', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b88ff26b', 't-mm-12-004', 'text', 'assure patients and public, employers and other health care professionals that licensed doctors are up to date and fit to practice', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-924db9c5', 't-mm-12-004', 'text', 'test concordance with principles and values set out in Good Medical Practice', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-231baa69', 't-mm-12-004', 'text', 'evaluate revalidation portfolio of supporting information over a five-year cycle.', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fb7c2aa7', 't-mm-12-004', 'text', 'Appraisal for revalidation aims to enable doctors to:', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-09ba0aea', 't-mm-12-004', 'text', 'discuss their practice and performance with their appraiser in order to demonstrate that they continue to meet the principles and values set out in Good Medical Practice  and thus to inform the responsible officer’s revalidation recommendation to the GMC', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-820d8e70', 't-mm-12-004', 'text', 'enhance the quality of their professional work by planning their professional development', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cefd3701', 't-mm-12-004', 'text', 'consider their own needs in planning their professional development', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e9f1c507', 't-mm-12-004', 'text', 'ensure that they are working productively and in line with the priorities and requirements of the organization they practice in.', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c9986e3d', 't-mm-12-004', 'text', 'Most doctors should have no difficulty in demonstrating that they are up to date and fit to practice and should spend almost all their time discussing their continuing professional development and how to improve the quality of their practice by reflecting on their work, challenges, achievements and aspirations and deciding where it is most appropriate to focus their efforts in the coming year.', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8bc67054', 't-mm-12-004', 'text', 'The Education Cycle', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9c73a492', 't-mm-12-004', 'text', 'The cycle for learning and self-development starts with the appraisal and is completed by assessment of progress, which then feeds back into planning for the next phase', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-12-005', 'chap-mm-12-01', '6.REFLECTION', 'Detailed medical reference and study guide on 6.REFLECTION.', 5, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
