INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b43d87b3', 't-mm-12-005', 'text', 'Kolb’s reflective practice', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
