INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-13-001', 'chap-mm-13-01', '1. WHAT IS CLINICAL GOVERNANCE?', 'Detailed medical reference and study guide on 1. WHAT IS CLINICAL GOVERNANCE?.', 1, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8008203a', 't-mm-13-001', 'text', 'CLINICAL GOVERNANCE:', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a7a9d017', 't-mm-13-001', 'heading', '1. CLINICAL GOVERNANCE', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-baae48a7', 't-mm-13-001', 'text', 'Clinical Governance is defined as a framework through which NHS organizations are accountable for continuously improving the quality of the services and safeguarding standards of the care by creating an environment in which excellence in the clinical care will flourish.', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-18235a48', 't-mm-13-001', 'text', 'Traditionally, clinical governance has been described using 7 key pillars:', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-87544339', 't-mm-13-001', 'text', 'clinical effectiveness and research', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-394c74f2', 't-mm-13-001', 'text', 'clinical audit', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a058a5ad', 't-mm-13-001', 'text', 'risk management', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-95a0d293', 't-mm-13-001', 'text', 'education and training', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c978f7cf', 't-mm-13-001', 'text', 'patient and public involvement (PPI)', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5f824c78', 't-mm-13-001', 'text', 'information management', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bf3740a8', 't-mm-13-001', 'text', 'staff management.', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9fc35a35', 't-mm-13-001', 'text', 'The various elements of clinical governance, when brought together, acquire the ability to improve the efficiency of systems', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-155c9437', 't-mm-13-001', 'image', '/uploads/content-images/maternal_mind_book/image161.jpg', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-13-002', 'chap-mm-13-01', '2. CLINICAL EFFECTIVENESS', 'Detailed medical reference and study guide on 2. CLINICAL EFFECTIVENESS.', 2, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-117f60ac', 't-mm-13-002', 'text', '3.AUDIT    Dr. Ambreen Yasin', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2090894a', 't-mm-13-002', 'text', 'means ensuring that everything you do is designed to provide the best outcomes for patients ensuring that the right person does:', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-18e304bd', 't-mm-13-002', 'text', 'The right thing (evidence-based practice)', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-048a9142', 't-mm-13-002', 'text', 'In the right way (skills and competence)', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ed08de6b', 't-mm-13-002', 'text', 'At the right time (providing treatment/services when the patient needs them)', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3dd1dcfa', 't-mm-13-002', 'text', 'In the right place (location of treatment/services)', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bc453899', 't-mm-13-002', 'text', 'With the right result (clinical effectiveness/maximizing health gain).', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-bb731e9b', 't-mm-13-002', 'text', 'The best available evidence, clinical skills and patient preferences are combined to achieve optimal processes and outcomes.', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b2433032', 't-mm-13-002', 'text', 'In practice, it means:', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-74552bf2', 't-mm-13-002', 'text', 'Adopting an evidence-based approach in the management of patient (evidence from randomized controlled trials, meta-analysis and systematic reviews)', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6acf9151', 't-mm-13-002', 'text', 'Changing practice, developing new protocols or guidelines based on experience and evidence if current practice is inadequate', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6324cd42', 't-mm-13-002', 'text', 'Implementing NICE guidelines, National Service Frameworks and other national standards to ensure optimal care - these should be appropriately disseminated and implemented in clinical practice, and compliance can be monitored by means of clinical audit', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6f7d1526', 't-mm-13-002', 'text', 'Clinical audit can be seen as a tool for driving clinical effectiveness.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-615bebc8', 't-mm-13-002', 'text', 'But clinical effectiveness also needs to encompass broader, qualitative aspects of care:', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8ea99fcf', 't-mm-13-002', 'text', 'Holistic care', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9ef0e9d1', 't-mm-13-002', 'text', 'Continuity of care', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9a26b367', 't-mm-13-002', 'text', 'sensitivity to the personal needs of the patient.', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3fd89021', 't-mm-13-002', 'text', 'Understanding these aspects of patient care forces us to recognize the diversity of patients. Not just in terms of gender, ethnicity or sexuality but also capacity, social background and acknowledging previous experiences. This enables us to personalize care and integrate clinical effectiveness with patients'' previous experiences. This is the basis of person-center care (''what matters to you'' rather than ''what’s the matter with you''). Clinical governance therefore needs to foster and promote this side of care as integral to the improvement of services and is likely to achieve better outcomes.  Ultimately therapies are only of value if patients accept and believe in them. Finding the right prompts is the key to reaching an agreement with patients and is most likely to result in successful therapies.', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-13-003', 'chap-mm-13-01', '3. CLINICAL AUDIT', 'Detailed medical reference and study guide on 3. CLINICAL AUDIT.', 3, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-47f346d3', 't-mm-13-003', 'text', 'is defined by ''a quality improvement process that seeks to improve patient care and outcomes through systematic review of care against explicit criteria and the implementation of change''.', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f5590b2f', 't-mm-13-003', 'text', 'The aim of audit is to ensure clinical practice is continuously monitored and that deficiencies in relation to set standards of care are remedied.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ebcff9b0', 't-mm-13-003', 'text', 'Criterion-based clinical audits assess local clinical performance against agreed standards, implement changes to clinical practice in order to enhance performance, and then reassess performance. This is a cyclical quality improvement process. Clinical audit usually assesses one or more of the following domains:', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-471f329e', 't-mm-13-003', 'text', 'Structure (organization or provision) of care', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-90d4ddcf', 't-mm-13-003', 'text', 'Process of care', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cec8781c', 't-mm-13-003', 'text', 'Outcome of care.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cd3d8f77', 't-mm-13-003', 'text', 'The audit cycle', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8da6e759', 't-mm-13-003', 'text', 'Audit can be considered to have five principal steps, commonly referred to as the audit cycle', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fdb0def2', 't-mm-13-003', 'text', '1. Selection of a topic', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3a5d39c7', 't-mm-13-003', 'text', '2. Identification of an appropriate standard', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d390b85f', 't-mm-13-003', 'text', '3. Data collection to assess performance against the prespecified standard', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1a41c061', 't-mm-13-003', 'text', '4. Implementation of changes to improve care if necessary', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0a1b12e8', 't-mm-13-003', 'text', '5. Data collection for a second, or subsequent, time to determine whether care has improved.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-41d1f5cd', 't-mm-13-003', 'text', 'Audit projects require a multidisciplinary approach with the involvement of stakeholders (including consumers or users of the service provided) and the local audit department at the planning stage. Good planning and resources are also necessary to ensure its success.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4065ab76', 't-mm-13-003', 'image', '/uploads/content-images/maternal_mind_book/image162.jpeg', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-13-004', 'chap-mm-13-01', '4. RISK MANAGEMENT', 'Detailed medical reference and study guide on 4. RISK MANAGEMENT.', 4, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-01618305', 't-mm-13-004', 'text', 'Healthcare is considered to be the most complex industry in the world. Despite major efforts, acute admission to hospital still retains a 10% chance of an adverse event. There remains a magnitude of difference in the reliability of healthcare processes when compared to processes within the airline industry or nuclear industry.', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6826a44c', 't-mm-13-004', 'text', 'Risk is the uncertainty surrounding events and their outcomes. All our activities carry some risk and risk is inherent in every activity.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-24d5e931', 't-mm-13-004', 'html', '<table><tbody><tr><th>Questions addressed by risk management</th></tr><tr><th>Question</th><th>Answer</th></tr><tr><td>What could go (or went) wrong?</td><td>Risk identification</td></tr><tr><td>What are the chances of it going wrong and what would be the impact?</td><td>Risk analysis and evaluation</td></tr><tr><td>What can we do to minimise the chance of this happening or to mitigate damage when it has gone wrong?</td><td>Risk treatment - the cost of prevention is compared with the cost of getting it wrong</td></tr><tr><td>What can we learn from things that have gone wrong?</td><td>Risk control; sharing and learning</td></tr></tbody></table>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-31751691', 't-mm-13-004', 'text', 'Basic questions addressed by risk management:', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2cfa2f1c', 't-mm-13-004', 'text', 'There is no clear demarcation between clinical (e.g. medication error) and non-clinical (e.g. falls off a trolley) risk management and it is preferable to take a holistic view of patient safety. However, strategies to prevent errors happening again may have the same or different pathways.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-46531120', 't-mm-13-004', 'text', 'This remains a basic framework to begin examination of an incident. Typically, actions should be considered across 3 levels.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-171c59ae', 't-mm-13-004', 'text', 'How engaged are you in your unit''s risk management program', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a40bfdff', 't-mm-13-004', 'text', 'How many patient safety incidents have you been involved with in the last 6 months?', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8d3f3dc3', 't-mm-13-004', 'text', 'In how many of these incidents did you complete an incident form? What happened to the form and what feedback did you receive?', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a692ee7d', 't-mm-13-004', 'text', 'Risk register', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2473ac4a', 't-mm-13-004', 'text', '1.All risks should have an action plan', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-536319e2', 't-mm-13-004', 'text', '2.Each unit should have risk register best in electronic form', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-65e873b6', 't-mm-13-004', 'text', '3.Shortage of staff and equipment must be mentioned in register before starting the shift', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7d412d4e', 't-mm-13-004', 'text', 'Root cause analysis:', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0d201578', 't-mm-13-004', 'text', '1.identify incident and take decision to investigate', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-96dab93f', 't-mm-13-004', 'text', '2.select members of investigation team', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dc63e437', 't-mm-13-004', 'text', '3.gather data (record, interview, protocols)', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-08b855c6', 't-mm-13-004', 'text', '4.determine chronology of incidents', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-60b607ba', 't-mm-13-004', 'text', '5.identify care delivery problems (unsafe act, failure to act, incorrect decision)', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a5266938', 't-mm-13-004', 'text', '6.identify contributing factors (lack of supervision, inadequate training)', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c8b6efb0', 't-mm-13-004', 'text', '7.device an action plan', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-332c4070', 't-mm-13-004', 'image', '/uploads/content-images/maternal_mind_book/image163.png', 22) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-92ea9a3d', 't-mm-13-004', 'text', 'Incident reporting  indication:', 23) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2e6ff6a4', 't-mm-13-004', 'text', 'Gynaecology:', 24) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6ef62b84', 't-mm-13-004', 'image', '/uploads/content-images/maternal_mind_book/image164.jpg', 25) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fd2b8dca', 't-mm-13-004', 'text', 'Obstetrics:', 26) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
