INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-13-006', 'chap-mm-13-01', '6. MATERNITY DASHBOARD', 'Detailed medical reference and study guide on 6. MATERNITY DASHBOARD.', 6, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c71c9569', 't-mm-13-006', 'text', 'Benchmarking is defined as a setting standard and they are compared with the performance and it can be monitored via clinical indicators.', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ac3c3f1c', 't-mm-13-006', 'text', 'Maternity Dashboard is a tool that can be employed to monitor the implementation of principles of the clinical governance on the ground.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-876ba6a4', 't-mm-13-006', 'text', 'It can be used to benchmark the activity and monitor the performance against the standards agreed locally for the maternity unit on a monthly basis', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7c10fcf2', 't-mm-13-006', 'text', 'Principles of the CAR Dashboard, which provides contemporary information about the amount of fuel in the tank, speed, state of the battery, temperature of the engine, so that appropriate action can be taken before the car breaks or slows down.', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c11e5c9e', 't-mm-13-006', 'text', 'Contemporary information about resources, clinical activity, risk management issues, user views, and so on, thus enabling early identification of the deviation from agreed goals and initiating timely and appropriate action to be taken to avoid patient safety incidents and to improve clinical care.', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-471fb103', 't-mm-13-006', 'text', 'Individual maternity units should set local thresholds for each of the parameters monitored, as well as upper and lower threshold.', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-def66c8e', 't-mm-13-006', 'text', 'The goal is to use a traffic light system,', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3acfca98', 't-mm-13-006', 'text', 'green when the goals are met (within the lower threshold)', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dd0d4ee2', 't-mm-13-006', 'text', 'amber when the goals are not met (above the lower threshold but still within the upper threshold.) It indicates action is needed if one has to avoid entering the red zone.', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0535b030', 't-mm-13-006', 'text', 'Red when the upper threshold is breached, here it requires immediate action from the highest level to maintain safety and restore the quality.', 10) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b4ae4e46', 't-mm-13-006', 'text', 'Parameters to be included are clinical activity, workforce, clinical outcome, risk incidents, complaints, or the patient satisfaction surveys.', 11) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f01f0f9f', 't-mm-13-006', 'text', 'Responsibilities for filling the maternity dashboard.', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fad16bf4', 't-mm-13-006', 'text', 'The primary objective is maternity dashboard is to ensure continuous improvement in the clinical care with clearly defined mechanisms and named individual responsible identified to deal with these issues as they arise.', 13) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-58be5ac5', 't-mm-13-006', 'text', 'The score card also provides information to establish trends such as increase in the number of caesarean sections requires an input from obstetrician, labour ward, clinical lead, third and the fourth degree, perineal tears, patient complaints.', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-505c33ca', 't-mm-13-006', 'text', 'Since it is important for someone with a clinical risk perspective to be responsible for maternity dashboard, such a person could be the risk manager, lead midwife for the risk working closely with the lead consultant for the labour ward. It is also shared with consumer representative in the Labor Board Forum and maternity Services liaison committees.', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-51ce03a3', 't-mm-13-006', 'text', 'Advantages and the disadvantages of Maternity Dashboard.', 16) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-44b9a29c', 't-mm-13-006', 'text', 'It improved the overall quality of care by informing the health providers about the performance', 17) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-74e876e3', 't-mm-13-006', 'text', 'to stimulate the comparisons between other maternity units to identify the areas for the further improvement.', 18) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dde228f8', 't-mm-13-006', 'text', 'It helped to understand how processes for delivering the health care services are designed to meet patient quality and operational requirements, including the best practice requirements.', 19) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-aac52e59', 't-mm-13-006', 'text', 'Helped to design and deliver the processes are coordinated and tested to ensure the smooth delivery of maternity care.', 20) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ab63eb11', 't-mm-13-006', 'text', 'The only disadvantage is that we consider it as another paper exercise. To avoid this pitfall, it is important to modify the Maternity Dashboard to suit local needs.', 21) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
